#[derive(Clone, Copy, Debug, PartialEq)]
pub enum BikeSteeringRegularizationMode {
    Curvature,
    RawDelta,
}

impl BikeSteeringRegularizationMode {
    fn from_request(request: &MintimeSolveRequestV1) -> Self {
        if mintime_option_bool(request, "legacy_raw_delta_regularization").unwrap_or(false) {
            return Self::RawDelta;
        }
        match mintime_option_str(request, "steering_regularization")
            .or_else(|| mintime_option_str(request, "bike_steering_regularization"))
            .map(|value| value.trim().to_ascii_lowercase())
            .as_deref()
        {
            Some("raw_delta" | "legacy_raw_delta" | "delta") => Self::RawDelta,
            Some("curvature" | "tan_delta_over_wheelbase" | "tan_delta_per_wheelbase") | None => {
                Self::Curvature
            }
            Some(_) => Self::Curvature,
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Curvature => "tan_delta_over_wheelbase",
            Self::RawDelta => "raw_delta_legacy",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct BikeMintimeObjectiveWeights {
    pub penalty_delta: f64,
    pub penalty_f: f64,
    pub penalty_delta_dd: f64,
    pub penalty_f_dd: f64,
    pub penalty_phi_cmd_dd: f64,
    pub penalty_n: f64,
    pub penalty_xi: f64,
    pub penalty_lean_equilibrium: f64,
    pub penalty_roll_tau: f64,
    pub penalty_roll_tau_rate: f64,
    pub penalty_ay_rate: f64,
    pub penalty_phi_eq_rate: f64,
    pub penalty_v1_delta_accel: f64,
    pub penalty_v1_delta_jerk: f64,
    pub penalty_v1_steering_torque_rate: f64,
    pub steering_regularization: BikeSteeringRegularizationMode,
}

impl Default for BikeMintimeObjectiveWeights {
    fn default() -> Self {
        Self {
            penalty_delta: 10.0,
            penalty_f: 0.01,
            penalty_delta_dd: 0.0,
            penalty_f_dd: 0.0,
            penalty_phi_cmd_dd: 0.0,
            penalty_n: 0.0,
            penalty_xi: 0.0,
            penalty_lean_equilibrium: 0.005,
            penalty_roll_tau: 0.001,
            penalty_roll_tau_rate: 0.0,
            penalty_ay_rate: 0.0,
            penalty_phi_eq_rate: 0.0,
            penalty_v1_delta_accel: 0.0,
            penalty_v1_delta_jerk: 0.0,
            penalty_v1_steering_torque_rate: 0.0,
            steering_regularization: BikeSteeringRegularizationMode::Curvature,
        }
    }
}

impl BikeMintimeObjectiveWeights {
    #[must_use]
    pub fn from_request(request: &MintimeSolveRequestV1) -> Self {
        Self {
            penalty_delta: mintime_option_or_profile_f64(request, "penalty_delta").unwrap_or(10.0),
            penalty_f: mintime_option_or_profile_f64(request, "penalty_F").unwrap_or(0.01),
            penalty_delta_dd: mintime_option_or_profile_f64(request, "penalty_delta_dd")
                .unwrap_or(0.0),
            penalty_f_dd: mintime_option_or_profile_f64(request, "penalty_f_dd").unwrap_or(0.0),
            penalty_phi_cmd_dd: mintime_option_or_profile_f64(request, "penalty_phi_cmd_dd")
                .unwrap_or(0.0),
            penalty_n: mintime_option_or_profile_f64(request, "penalty_n").unwrap_or(0.0),
            penalty_xi: mintime_option_or_profile_f64(request, "penalty_xi").unwrap_or(0.0),
            penalty_lean_equilibrium: mintime_option_or_profile_f64(
                request,
                "penalty_lean_equilibrium",
            )
            .unwrap_or(0.005),
            penalty_roll_tau: mintime_option_or_profile_f64(request, "penalty_roll_tau")
                .unwrap_or(0.001),
            penalty_roll_tau_rate: mintime_option_or_profile_f64(request, "penalty_roll_tau_rate")
                .unwrap_or(0.0),
            penalty_ay_rate: mintime_option_or_profile_f64(request, "penalty_ay_rate")
                .unwrap_or(0.0),
            penalty_phi_eq_rate: mintime_option_or_profile_f64(request, "penalty_phi_eq_rate")
                .unwrap_or(0.0),
            penalty_v1_delta_accel: mintime_option_or_profile_f64(
                request,
                "penalty_v1_delta_accel",
            )
            .or_else(|| mintime_option_or_profile_f64(request, "penalty_delta_accel"))
            .unwrap_or(0.0),
            penalty_v1_delta_jerk: mintime_option_or_profile_f64(request, "penalty_v1_delta_jerk")
                .or_else(|| mintime_option_or_profile_f64(request, "penalty_delta_jerk"))
                .unwrap_or(0.0),
            penalty_v1_steering_torque_rate: mintime_option_or_profile_f64(
                request,
                "penalty_v1_steering_torque_rate",
            )
            .or_else(|| mintime_option_or_profile_f64(request, "penalty_steering_torque_rate"))
            .unwrap_or(0.0),
            steering_regularization: BikeSteeringRegularizationMode::from_request(request),
        }
    }
}

