#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum BikeModelVersion {
    V0_5,
    V1Experimental,
}

impl BikeModelVersion {
    fn from_request(request: &MintimeSolveRequestV1) -> Result<Self, SolverApiError> {
        let raw = mintime_option_str(request, "bike_model_version")
            .or_else(|| {
                request
                    .vehicle_dynamics_profile
                    .string_param("bike_model_version")
            })
            .or_else(|| mintime_option_str(request, "model_version"))
            .or_else(|| {
                request
                    .vehicle_dynamics_profile
                    .string_param("model_version")
            })
            .unwrap_or(Self::V0_5.as_str());
        Self::parse(raw).map_err(|message| SolverApiError::new("solve.invalidRequest", message))
    }

    fn parse(raw: &str) -> Result<Self, String> {
        match raw.trim().to_ascii_lowercase().as_str() {
            "v0_5" | "v0.5" | "v05" | "bike_single_track_lean_v2" => Ok(Self::V0_5),
            "v1_experimental" | "v1" | "countersteer_v1" | "bike_countersteer_lean_v1" => {
                Ok(Self::V1Experimental)
            }
            other => Err(format!(
                "unsupported bike_model_version: {other}; expected v0_5 or v1_experimental"
            )),
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::V0_5 => "v0_5",
            Self::V1Experimental => "v1_experimental",
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum BikeV1SeedSource {
    Current,
    Point,
    PointPhaseAdvance,
    MaterializedFullStateControl,
    BikeV0_5,
    LateApex67_72,
    LateApex143_150,
    CombinedLateApex,
}

impl BikeV1SeedSource {
    fn from_request(request: &MintimeSolveRequestV1) -> Result<Self, SolverApiError> {
        let raw = mintime_option_str(request, "v1_seed_source")
            .or_else(|| mintime_option_str(request, "bike_v1_seed_source"))
            .or_else(|| mintime_option_str(request, "seed_source"))
            .unwrap_or(Self::Current.as_str());
        Self::parse(raw).map_err(|message| SolverApiError::new("solve.invalidRequest", message))
    }

    fn parse(raw: &str) -> Result<Self, String> {
        match raw.trim().to_ascii_lowercase().as_str() {
            "current" | "curvature" | "curvature_aware" => Ok(Self::Current),
            "point" | "point_seed" | "point_based" => Ok(Self::Point),
            "point_phase_advance" | "point_preview" | "point_lookahead" => {
                Ok(Self::PointPhaseAdvance)
            }
            "materialized_full_state_control" | "materialized_seed" | "full_state_control" => {
                Ok(Self::MaterializedFullStateControl)
            }
            "bike_v0_5" | "v0_5" | "v05" => Ok(Self::BikeV0_5),
            "late_apex_67_72" | "local_late_apex_67_72" => Ok(Self::LateApex67_72),
            "late_apex_143_150" | "local_late_apex_143_150" => Ok(Self::LateApex143_150),
            "combined_late_apex" | "late_apex_combined" | "local_late_apex" => {
                Ok(Self::CombinedLateApex)
            }
            other => Err(format!(
                "unsupported v1_seed_source: {other}; point warm-up was removed; expected current, point, point_phase_advance, materialized_full_state_control, bike_v0_5, late_apex_67_72, late_apex_143_150, or combined_late_apex"
            )),
        }
    }

    fn as_str(&self) -> &'static str {
        match self {
            Self::Current => "current",
            Self::Point => "point",
            Self::PointPhaseAdvance => "point_phase_advance",
            Self::MaterializedFullStateControl => "materialized_full_state_control",
            Self::BikeV0_5 => "bike_v0_5",
            Self::LateApex67_72 => "late_apex_67_72",
            Self::LateApex143_150 => "late_apex_143_150",
            Self::CombinedLateApex => "combined_late_apex",
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum BikeV1SeedStateSource {
    ReferenceCurvature,
    SeedPathCurvature,
    SeedPathYawReferenceLean,
    SmoothedSeedPathCurvature,
    PreviewCurvature,
}

impl BikeV1SeedStateSource {
    fn from_request(request: &MintimeSolveRequestV1) -> Result<Self, SolverApiError> {
        let raw = mintime_option_str(request, "v1_seed_state_source")
            .or_else(|| mintime_option_str(request, "bike_v1_seed_state_source"))
            .unwrap_or(Self::ReferenceCurvature.as_str());
        Self::parse(raw).map_err(|message| SolverApiError::new("solve.invalidRequest", message))
    }

    fn parse(raw: &str) -> Result<Self, String> {
        match raw.trim().to_ascii_lowercase().as_str() {
            "reference_curvature" | "reference" | "ref" | "default" | "existing" => {
                Ok(Self::ReferenceCurvature)
            }
            "seed_path_curvature" | "seed_path" | "path_curvature" | "projected_path" => {
                Ok(Self::SeedPathCurvature)
            }
            "seed_path_yaw_reference_lean" | "seed_yaw_ref_lean" | "seed_omega_ref_phi_delta" => {
                Ok(Self::SeedPathYawReferenceLean)
            }
            "smoothed_seed_path_curvature" | "smoothed_seed_path" | "smooth_seed_path" => {
                Ok(Self::SmoothedSeedPathCurvature)
            }
            "preview_curvature" | "preview" | "lookahead" => Ok(Self::PreviewCurvature),
            other => Err(format!(
                "unsupported v1_seed_state_source: {other}; expected reference_curvature, seed_path_curvature, seed_path_yaw_reference_lean, smoothed_seed_path_curvature, or preview_curvature"
            )),
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::ReferenceCurvature => "reference_curvature",
            Self::SeedPathCurvature => "seed_path_curvature",
            Self::SeedPathYawReferenceLean => "seed_path_yaw_reference_lean",
            Self::SmoothedSeedPathCurvature => "smoothed_seed_path_curvature",
            Self::PreviewCurvature => "preview_curvature",
        }
    }

    fn collocation_source_mode(self) -> &'static str {
        match self {
            Self::ReferenceCurvature => "patched_from_station_values_reference_collocation_kappa",
            Self::SeedPathCurvature => "patched_from_station_values_seed_path_curvature",
            Self::SeedPathYawReferenceLean => {
                "patched_from_station_values_seed_path_yaw_reference_lean"
            }
            Self::SmoothedSeedPathCurvature => {
                "patched_from_station_values_smoothed_seed_path_curvature"
            }
            Self::PreviewCurvature => "patched_from_station_values_preview_curvature",
        }
    }

    fn uses_seed_path_geometry(self) -> bool {
        !matches!(self, Self::ReferenceCurvature)
    }
}

