#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum BikeV1BasinTrustMode {
    Off,
    VHeading,
    VHeadingN,
    VHeadingNOmegaZ,
}

impl BikeV1BasinTrustMode {
    fn parse(raw: &str) -> Result<Self, String> {
        match raw.trim().to_ascii_lowercase().as_str() {
            "" | "off" | "none" | "false" | "disabled" => Ok(Self::Off),
            "v_heading" | "speed_heading" | "v_xi" | "v_xi_beta" => Ok(Self::VHeading),
            "v_heading_n" | "speed_heading_n" | "v_xi_n" | "v_xi_beta_n" => {
                Ok(Self::VHeadingN)
            }
            "v_heading_n_omega"
            | "v_heading_n_omega_z"
            | "speed_heading_n_omega"
            | "speed_heading_n_omega_z" => Ok(Self::VHeadingNOmegaZ),
            other => Err(format!(
                "unsupported debug_v1_basin_trust_mode: {other}; expected off, v_heading, v_heading_n, or v_heading_n_omega"
            )),
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Off => "off",
            Self::VHeading => "v_heading",
            Self::VHeadingN => "v_heading_n",
            Self::VHeadingNOmegaZ => "v_heading_n_omega",
        }
    }

    fn is_enabled(self) -> bool {
        !matches!(self, Self::Off)
    }

    fn component_count(self) -> usize {
        match self {
            Self::Off => 0,
            Self::VHeading => 2,
            Self::VHeadingN => 3,
            Self::VHeadingNOmegaZ => 4,
        }
    }

    fn includes_n(self) -> bool {
        matches!(self, Self::VHeadingN | Self::VHeadingNOmegaZ)
    }

    fn includes_omega_z(self) -> bool {
        matches!(self, Self::VHeadingNOmegaZ)
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum BikeV1ControlLowFrequencyMode {
    Off,
    SteeringTorque,
    Longitudinal,
    All,
}

impl BikeV1ControlLowFrequencyMode {
    fn parse(raw: &str) -> Result<Self, String> {
        match raw.trim().to_ascii_lowercase().as_str() {
            "" | "off" | "none" | "false" | "disabled" => Ok(Self::Off),
            "steering"
            | "steering_torque"
            | "steering_torque_lowfreq"
            | "torque"
            | "torque_lowfreq" => Ok(Self::SteeringTorque),
            "longitudinal"
            | "drive_brake"
            | "drive_brake_lowfreq"
            | "f_long"
            | "force"
            | "force_lowfreq" => Ok(Self::Longitudinal),
            "all" | "control" | "controls" | "combined" | "combined_control" => Ok(Self::All),
            other => Err(format!(
                "unsupported debug_v1_control_lowfreq_mode: {other}; expected off, steering_torque, longitudinal, or all"
            )),
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Off => "off",
            Self::SteeringTorque => "steering_torque",
            Self::Longitudinal => "longitudinal",
            Self::All => "all",
        }
    }

    fn is_enabled(self) -> bool {
        !matches!(self, Self::Off)
    }

    fn includes_control(self, control_index: usize) -> bool {
        match self {
            Self::Off => false,
            Self::SteeringTorque => control_index == V1_CONTROL_STEERING_TORQUE_NM,
            Self::Longitudinal => {
                control_index == V1_CONTROL_F_DRIVE_N || control_index == V1_CONTROL_F_BRAKE_N
            }
            Self::All => {
                control_index == V1_CONTROL_STEERING_TORQUE_NM
                    || control_index == V1_CONTROL_F_DRIVE_N
                    || control_index == V1_CONTROL_F_BRAKE_N
            }
        }
    }
}

