#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum BikeV1SteeringActuatorMode {
    Torque,
    DeltaCmdFirstOrder,
    Sr3NormalizedTorque,
    Sr3DeltaAccel,
}

impl BikeV1SteeringActuatorMode {
    fn parse(raw: &str) -> Result<Self, String> {
        match raw.trim().to_ascii_lowercase().as_str() {
            "" | "torque" | "default" | "off" | "none" => Ok(Self::Torque),
            "delta_cmd_first_order"
            | "delta_cmd"
            | "delta-command"
            | "first_order_delta_cmd"
            | "lc2_delta_cmd" => Ok(Self::DeltaCmdFirstOrder),
            "sr3_normalized_torque"
            | "normalized_torque"
            | "normalized_actual_torque"
            | "sr3_torque" => Ok(Self::Sr3NormalizedTorque),
            "sr3_delta_accel"
            | "delta_accel_coordinate"
            | "delta_accel"
            | "steering_accel_coordinate" => Ok(Self::Sr3DeltaAccel),
            other => Err(format!(
                "unsupported moto_v1_steering_mode/debug_v1_steering_actuator_mode: {other}; expected torque, delta_cmd_first_order, sr3_normalized_torque, or sr3_delta_accel"
            )),
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Torque => "torque",
            Self::DeltaCmdFirstOrder => "delta_cmd_first_order",
            Self::Sr3NormalizedTorque => "sr3_normalized_torque",
            Self::Sr3DeltaAccel => "sr3_delta_accel",
        }
    }

    fn uses_delta_cmd(self) -> bool {
        matches!(self, Self::DeltaCmdFirstOrder)
    }

    fn uses_sr3_actual_steering_authority(self) -> bool {
        matches!(self, Self::Sr3NormalizedTorque | Self::Sr3DeltaAccel)
    }

    fn steering_coordinate(self) -> &'static str {
        match self {
            Self::Torque => "torque_nm",
            Self::DeltaCmdFirstOrder => "delta_command_rad",
            Self::Sr3NormalizedTorque => "normalized_torque",
            Self::Sr3DeltaAccel => "normalized_delta_accel",
        }
    }

    fn normalized_control(self, params: BikeCountersteerLeanParamsV1, raw_control: f64) -> f64 {
        match self {
            Self::Torque => raw_control / params.steering_torque_max_nm.max(1.0),
            Self::DeltaCmdFirstOrder => {
                raw_control / params.base.steering_angle_max_rad.max(1.0e-9)
            }
            Self::Sr3NormalizedTorque | Self::Sr3DeltaAccel => raw_control,
        }
    }

    fn physical_input_torque_nm(
        self,
        params: BikeCountersteerLeanParamsV1,
        raw_control: f64,
    ) -> Option<f64> {
        match self {
            Self::Torque => Some(raw_control),
            Self::Sr3NormalizedTorque => Some(raw_control * params.steering_torque_max_nm.max(1.0)),
            Self::DeltaCmdFirstOrder | Self::Sr3DeltaAccel => None,
        }
    }

    fn uses_debug_steering_dynamics(self) -> bool {
        self.uses_delta_cmd() || self.uses_sr3_actual_steering_authority()
    }
}

