    fn basin_ipopt_iteration_snapshot_json(
        &self,
        snapshot: &BikeV1IpoptIterationSnapshot,
    ) -> JsonValue {
        let mut entries = vec![
            (
                "iteration".to_owned(),
                JsonValue::Integer(snapshot.iteration as i64),
            ),
            (
                "alg_mod".to_owned(),
                JsonValue::Integer(snapshot.alg_mod as i64),
            ),
            ("obj_value".to_owned(), json_number(snapshot.obj_value)),
            ("inf_pr".to_owned(), json_number(snapshot.inf_pr)),
            ("inf_du".to_owned(), json_number(snapshot.inf_du)),
            ("mu".to_owned(), json_number(snapshot.mu)),
            ("d_norm".to_owned(), json_number(snapshot.d_norm)),
            (
                "regularization_size".to_owned(),
                json_number(snapshot.regularization_size),
            ),
            ("alpha_du".to_owned(), json_number(snapshot.alpha_du)),
            ("alpha_pr".to_owned(), json_number(snapshot.alpha_pr)),
            (
                "ls_trials".to_owned(),
                JsonValue::Integer(snapshot.ls_trials as i64),
            ),
            (
                "current_iterate_available".to_owned(),
                JsonValue::Bool(snapshot.current_iterate_available),
            ),
            (
                "current_violations_available".to_owned(),
                JsonValue::Bool(snapshot.current_violations_available),
            ),
        ];
        if snapshot.current_iterate_available {
            entries.push((
                "snapshot".to_owned(),
                self.basin_snapshot_json(&format!("ipopt_iter{}", snapshot.iteration), &snapshot.x),
            ));
            entries.push((
                "constraint_values_by_sector_family".to_owned(),
                self.basin_constraint_signal_by_sector_family_json(&snapshot.g),
            ));
            entries.push((
                "constraint_multipliers_by_sector_family".to_owned(),
                self.basin_constraint_signal_by_sector_family_json(&snapshot.lambda),
            ));
            entries.push((
                "jacobian_transpose_lambda_by_sector_family_variable".to_owned(),
                self.basin_jacobian_transpose_lambda_by_sector_family_json(
                    &snapshot.x,
                    &snapshot.lambda,
                ),
            ));
        }
        if snapshot.current_violations_available {
            entries.push((
                "constraint_violation_by_sector_family".to_owned(),
                self.basin_constraint_signal_by_sector_family_json(
                    &snapshot.nlp_constraint_violation,
                ),
            ));
            entries.push((
                "constraint_complementarity_by_sector_family".to_owned(),
                self.basin_constraint_signal_by_sector_family_json(&snapshot.compl_g),
            ));
            entries.push((
                "variable_signals_by_sector_family".to_owned(),
                self.basin_variable_signal_by_sector_family_json(&[
                    ("z_l", &snapshot.z_l),
                    ("z_u", &snapshot.z_u),
                    ("x_l_violation", &snapshot.x_l_violation),
                    ("x_u_violation", &snapshot.x_u_violation),
                    ("compl_x_l", &snapshot.compl_x_l),
                    ("compl_x_u", &snapshot.compl_x_u),
                    ("grad_lag_x", &snapshot.grad_lag_x),
                ]),
            ));
        }
        JsonValue::Object(entries)
    }

    fn basin_final_multipliers_json(
        &self,
        x: &[f64],
        multipliers: Option<&BikeV1IpoptFinalMultipliers>,
    ) -> JsonValue {
        let Some(multipliers) = multipliers else {
            return JsonValue::Object(vec![
                ("available".to_owned(), JsonValue::Bool(false)),
                (
                    "note".to_owned(),
                    "Ipopt final multipliers were not captured.".into(),
                ),
            ]);
        };
        JsonValue::Object(vec![
            ("available".to_owned(), JsonValue::Bool(true)),
            (
                "note".to_owned(),
                "Raw Ipopt TNLP multipliers for the scaled V1 NLP. Use as active-pressure diagnostics, not physical-unit forces.".into(),
            ),
            (
                "constraint_multipliers_by_sector_family".to_owned(),
                self.basin_constraint_signal_by_sector_family_json(&multipliers.mult_g),
            ),
            (
                "variable_bound_multipliers_by_sector_family".to_owned(),
                self.basin_variable_signal_by_sector_family_json(&[
                    ("mult_x_l", &multipliers.mult_x_l),
                    ("mult_x_u", &multipliers.mult_x_u),
                ]),
            ),
            (
                "slip_angle_bound_telemetry".to_owned(),
                self.basin_slip_angle_bound_telemetry_json(x, &multipliers.mult_g),
            ),
        ])
    }

    /// Exports raw Ipopt multiplier pressure and physical distance to each
    /// pre-peak slip bound. This is diagnostic-only: the multiplier scale is
    /// Ipopt/TNLP-specific and must not be treated as a physical force.
    fn basin_slip_angle_bound_telemetry_json(&self, x: &[f64], multipliers: &[f64]) -> JsonValue {
        if multipliers.len() != self.rows.len() {
            return JsonValue::Object(vec![
                ("available".to_owned(), JsonValue::Bool(false)),
                (
                    "reason".to_owned(),
                    "constraint multiplier length does not match V1 row count".into(),
                ),
            ]);
        }

        let mut rows = Vec::new();
        let mut by_axle: BTreeMap<&'static str, (usize, usize, f64, f64)> = BTreeMap::new();
        for (row_index, row) in self.rows.iter().enumerate() {
            let BikeV1ExperimentalConstraintRow::SlipAngle { sample, axle } = *row else {
                continue;
            };
            let value = self.constraint_value(x, *row).unwrap_or(f64::NAN);
            let lower = self.constraint_lower_bounds[row_index];
            let upper = self.constraint_upper_bounds[row_index];
            let limit = upper.abs().max(lower.abs()).max(1e-12);
            let normalized_abs_alpha = value.abs() / limit;
            let near_bound = normalized_abs_alpha >= 0.999;
            let lambda = multipliers[row_index];
            let active_side = if lambda > 0.0 {
                "upper"
            } else if lambda < 0.0 {
                "lower"
            } else {
                "inactive"
            };
            let aggregate = by_axle.entry(axle).or_insert((0, 0, 0.0, 0.0));
            aggregate.0 += 1;
            aggregate.1 += usize::from(near_bound);
            aggregate.2 += lambda.abs();
            aggregate.3 = aggregate.3.max(lambda.abs());
            rows.push(JsonValue::Object(vec![
                ("row_index".to_owned(), JsonValue::Integer(row_index as i64)),
                (
                    "interval".to_owned(),
                    JsonValue::Integer(sample.interval() as i64),
                ),
                ("sample".to_owned(), sample.label().into()),
                ("axle".to_owned(), axle.into()),
                ("alpha_rad".to_owned(), json_f64_or_string(value)),
                ("lower_rad".to_owned(), json_f64_or_string(lower)),
                ("upper_rad".to_owned(), json_f64_or_string(upper)),
                (
                    "abs_alpha_over_limit".to_owned(),
                    json_f64_or_string(normalized_abs_alpha),
                ),
                ("near_bound".to_owned(), JsonValue::Bool(near_bound)),
                (
                    "raw_ipopt_multiplier".to_owned(),
                    json_f64_or_string(lambda),
                ),
                (
                    "raw_ipopt_multiplier_abs".to_owned(),
                    json_f64_or_string(lambda.abs()),
                ),
                (
                    "active_side_from_multiplier_sign".to_owned(),
                    active_side.into(),
                ),
            ]));
        }

        JsonValue::Object(vec![
            ("available".to_owned(), JsonValue::Bool(true)),
            (
                "note".to_owned(),
                "Raw final Ipopt mult_g values plus physical slip-bound proximity. Positive/negative multiplier sign denotes upper/lower pressure under the TNLP convention; compare relatively between like runs.".into(),
            ),
            (
                "by_axle".to_owned(),
                JsonValue::Array(
                    by_axle
                        .into_iter()
                        .map(|(axle, (count, near_count, lambda_abs_sum, lambda_abs_max))| {
                            JsonValue::Object(vec![
                                ("axle".to_owned(), axle.into()),
                                ("row_count".to_owned(), JsonValue::Integer(count as i64)),
                                ("near_bound_count".to_owned(), JsonValue::Integer(near_count as i64)),
                                (
                                    "near_bound_fraction".to_owned(),
                                    json_number(near_count as f64 / count.max(1) as f64),
                                ),
                                ("raw_multiplier_abs_sum".to_owned(), json_number(lambda_abs_sum)),
                                ("raw_multiplier_abs_max".to_owned(), json_number(lambda_abs_max)),
                            ])
                        })
                        .collect(),
                ),
            ),
            ("rows".to_owned(), JsonValue::Array(rows)),
        ])
    }

    fn basin_constraint_signal_by_sector_family_json(&self, values: &[f64]) -> JsonValue {
        if values.len() != self.rows.len() {
            return JsonValue::Object(vec![
                ("available".to_owned(), JsonValue::Bool(false)),
                (
                    "reason".to_owned(),
                    format!(
                        "constraint signal length {} does not match row count {}",
                        values.len(),
                        self.rows.len()
                    )
                    .into(),
                ),
            ]);
        }
        let mut stats: BTreeMap<(usize, &'static str), BikeV1BasinSignalStats> = BTreeMap::new();
        for (row_index, (row, value)) in self.rows.iter().zip(values.iter()).enumerate() {
            let Some(interval) = self.basin_row_interval(*row) else {
                continue;
            };
            let label = row.label();
            let bucket = stats.entry((interval, row.family())).or_default();
            bike_v1_add_basin_signal(bucket, row_index, &label, *value);
        }
        JsonValue::Array(
            stats
                .into_iter()
                .map(|((interval, family), stats)| {
                    let mut entry = bike_v1_basin_signal_stats_json(stats);
                    if let JsonValue::Object(fields) = &mut entry {
                        fields.insert(0, ("family".to_owned(), family.into()));
                        fields.insert(
                            0,
                            ("interval".to_owned(), JsonValue::Integer(interval as i64)),
                        );
                    }
                    entry
                })
                .collect(),
        )
    }

    fn basin_variable_signal_by_sector_family_json(
        &self,
        signals: &[(&'static str, &[f64])],
    ) -> JsonValue {
        let variable_count = self.decision_layout.dimensions.decision_variable_count();
        let mut stats: BTreeMap<(usize, &'static str, &'static str), BikeV1BasinSignalStats> =
            BTreeMap::new();
        for (signal_name, values) in signals {
            if values.len() != variable_count {
                continue;
            }
            for (variable_index, value) in values.iter().enumerate() {
                let Some((interval, family, label)) =
                    self.basin_variable_interval_family_label(variable_index)
                else {
                    continue;
                };
                let bucket = stats.entry((interval, family, *signal_name)).or_default();
                bike_v1_add_basin_signal(bucket, variable_index, &label, *value);
            }
        }
        JsonValue::Array(
            stats
                .into_iter()
                .map(|((interval, family, signal), stats)| {
                    let mut entry = bike_v1_basin_signal_stats_json(stats);
                    if let JsonValue::Object(fields) = &mut entry {
                        fields.insert(0, ("signal".to_owned(), signal.into()));
                        fields.insert(0, ("variable_family".to_owned(), family.into()));
                        fields.insert(
                            0,
                            ("interval".to_owned(), JsonValue::Integer(interval as i64)),
                        );
                    }
                    entry
                })
                .collect(),
        )
    }

    fn basin_decision_delta_by_sector_family_json(
        &self,
        transition: &str,
        left_x: &[f64],
        right_x: &[f64],
    ) -> JsonValue {
        let variable_count = self.decision_layout.dimensions.decision_variable_count();
        if left_x.len() != variable_count || right_x.len() != variable_count {
            return JsonValue::Object(vec![
                ("available".to_owned(), JsonValue::Bool(false)),
                (
                    "reason".to_owned(),
                    format!(
                        "decision lengths left={} right={} expected={}",
                        left_x.len(),
                        right_x.len(),
                        variable_count
                    )
                    .into(),
                ),
            ]);
        }
        let mut stats: BTreeMap<(usize, &'static str), BikeV1BasinSignalStats> = BTreeMap::new();
        for variable_index in 0..variable_count {
            let Some((interval, family, label)) =
                self.basin_variable_interval_family_label(variable_index)
            else {
                continue;
            };
            let delta = right_x[variable_index] - left_x[variable_index];
            let bucket = stats.entry((interval, family)).or_default();
            bike_v1_add_basin_signal(bucket, variable_index, &label, delta);
        }
        JsonValue::Object(vec![
            ("available".to_owned(), JsonValue::Bool(true)),
            ("transition".to_owned(), transition.into()),
            (
                "rows".to_owned(),
                JsonValue::Array(
                    stats
                        .into_iter()
                        .map(|((interval, family), stats)| {
                            let mut entry = bike_v1_basin_signal_stats_json(stats);
                            if let JsonValue::Object(fields) = &mut entry {
                                fields.insert(0, ("variable_family".to_owned(), family.into()));
                                fields.insert(
                                    0,
                                    ("interval".to_owned(), JsonValue::Integer(interval as i64)),
                                );
                            }
                            entry
                        })
                        .collect(),
                ),
            ),
        ])
    }

    fn basin_sector_samples_json(&self, x: &[f64], interval: usize) -> JsonValue {
        let mut samples = Vec::with_capacity(self.decision_layout.collocation_degree + 2);
        samples.push(self.basin_sample_json(
            x,
            "interval_start",
            BikeV1ExperimentalSample::IntervalStart { interval },
        ));
        for point in 0..self.decision_layout.collocation_degree {
            samples.push(self.basin_sample_json(
                x,
                "collocation",
                BikeV1ExperimentalSample::Collocation { interval, point },
            ));
        }
        samples.push(self.basin_sample_json(
            x,
            "interval_end",
            BikeV1ExperimentalSample::Station { interval },
        ));
        JsonValue::Array(samples)
    }

    fn basin_sample_json(
        &self,
        x: &[f64],
        role: &str,
        sample: BikeV1ExperimentalSample,
    ) -> JsonValue {
        let (state, control, kappa_1pm) = self.sample_state_control_kappa(x, sample);
        let dynamics = self.sample_dynamics(x, sample);
        let front_kamm = bike_v1_kamm_for_axle(
            self.feedback_params(),
            dynamics.tire_forces,
            "front",
            self.options.load_sensitive_kamm_denominator,
        );
        let rear_kamm = bike_v1_kamm_for_axle(
            self.feedback_params(),
            dynamics.tire_forces,
            "rear",
            self.options.load_sensitive_kamm_denominator,
        );
        let r_omega_radps = state.omega_z_radps - state.v_mps * kappa_1pm;
        let phi_eq_rad = bike_v1_seed_phi_from_kappa(self.params, kappa_1pm, state.v_mps);
        let delta_eq_rad = bike_v1_seed_delta_from_kappa(self.params, kappa_1pm);
        JsonValue::Object(vec![
            ("role".to_owned(), role.into()),
            ("sample".to_owned(), sample.json()),
            ("v_mps".to_owned(), json_number(state.v_mps)),
            ("n_m".to_owned(), json_number(state.n_m)),
            ("xi_rad".to_owned(), json_number(state.xi_rad)),
            ("beta_rad".to_owned(), json_number(state.beta_rad)),
            (
                "heading_relative_rad".to_owned(),
                json_number(state.xi_rad + state.beta_rad),
            ),
            ("omega_z_radps".to_owned(), json_number(state.omega_z_radps)),
            ("phi_rad".to_owned(), json_number(state.phi_rad)),
            ("phi_dot_radps".to_owned(), json_number(state.phi_dot_radps)),
            ("delta_rad".to_owned(), json_number(state.delta_rad)),
            (
                "delta_dot_radps".to_owned(),
                json_number(state.delta_dot_radps),
            ),
            ("kappa_1pm".to_owned(), json_number(kappa_1pm)),
            ("ax_mps2".to_owned(), json_number(dynamics.ax_mps2)),
            ("ay_mps2".to_owned(), json_number(dynamics.ay_mps2)),
            ("r_omega_radps".to_owned(), json_number(r_omega_radps)),
            ("phi_eq_rad".to_owned(), json_number(phi_eq_rad)),
            (
                "r_phi_rad".to_owned(),
                json_number(state.phi_rad - phi_eq_rad),
            ),
            ("delta_eq_rad".to_owned(), json_number(delta_eq_rad)),
            (
                "r_delta_rad".to_owned(),
                json_number(state.delta_rad - delta_eq_rad),
            ),
            ("front_kamm".to_owned(), json_number(front_kamm)),
            ("rear_kamm".to_owned(), json_number(rear_kamm)),
            (
                "max_kamm".to_owned(),
                json_number(front_kamm.max(rear_kamm)),
            ),
            (
                "front_normal_load_n".to_owned(),
                json_number(dynamics.tire_forces.fz_front_n),
            ),
            (
                "rear_normal_load_n".to_owned(),
                json_number(dynamics.tire_forces.fz_rear_n),
            ),
            (
                "alpha_front_rad".to_owned(),
                json_number(dynamics.tire_forces.alpha_front_rad),
            ),
            (
                "alpha_rear_rad".to_owned(),
                json_number(dynamics.tire_forces.alpha_rear_rad),
            ),
            ("f_drive_n".to_owned(), json_number(control.f_drive_n)),
            ("f_brake_n".to_owned(), json_number(control.f_brake_n)),
            (
                "steering_torque_nm".to_owned(),
                json_number(dynamics.steering_input_torque_nm),
            ),
            (
                "steering_control_raw".to_owned(),
                json_number(control.steering_torque_nm),
            ),
            (
                "steering_control_normalized".to_owned(),
                json_number(
                    self.options
                        .debug_v1_steering_actuator_mode
                        .normalized_control(self.params, control.steering_torque_nm),
                ),
            ),
            (
                "steering_input_torque_nm".to_owned(),
                json_number(dynamics.steering_input_torque_nm),
            ),
            (
                "steering_net_torque_nm".to_owned(),
                json_number(dynamics.steering_net_torque_nm),
            ),
            ("sigma_dt_ds".to_owned(), json_number(dynamics.sigma_dt_ds)),
        ])
    }

    fn basin_sector_scalar_metrics(
        &self,
        x: &[f64],
        interval: usize,
    ) -> BTreeMap<&'static str, f64> {
        let mut metrics = BTreeMap::new();
        let mut count = 0.0;
        let mut sum_v = 0.0;
        let mut min_v = f64::INFINITY;
        let mut max_v = f64::NEG_INFINITY;
        let mut min_n = f64::INFINITY;
        let mut max_n = f64::NEG_INFINITY;
        let mut max_abs_heading = 0.0_f64;
        let mut max_abs_xi = 0.0_f64;
        let mut max_abs_beta = 0.0_f64;
        let mut max_abs_delta = 0.0_f64;
        let mut max_abs_ay = 0.0_f64;
        let mut max_abs_ax = 0.0_f64;
        let mut max_kamm = 0.0_f64;
        let mut max_abs_slip = 0.0_f64;
        let mut max_abs_steering_torque = 0.0_f64;
        let mut max_abs_drive = 0.0_f64;
        let mut max_abs_brake = 0.0_f64;
        let mut max_abs_r_omega = 0.0_f64;
        let mut max_abs_r_phi = 0.0_f64;
        let mut max_abs_r_delta = 0.0_f64;
        let mut sum_sq_r_omega = 0.0_f64;
        let mut sum_sq_r_phi = 0.0_f64;
        let mut sum_sq_r_delta = 0.0_f64;

        let mut visit = |sample: BikeV1ExperimentalSample| {
            let (state, control, kappa_1pm) = self.sample_state_control_kappa(x, sample);
            let dynamics = self.sample_dynamics(x, sample);
            let front_kamm = bike_v1_kamm_for_axle(
                self.params,
                dynamics.tire_forces,
                "front",
                self.options.load_sensitive_kamm_denominator,
            );
            let rear_kamm = bike_v1_kamm_for_axle(
                self.params,
                dynamics.tire_forces,
                "rear",
                self.options.load_sensitive_kamm_denominator,
            );
            count += 1.0;
            sum_v += state.v_mps;
            min_v = min_v.min(state.v_mps);
            max_v = max_v.max(state.v_mps);
            min_n = min_n.min(state.n_m);
            max_n = max_n.max(state.n_m);
            max_abs_heading = max_abs_heading.max((state.xi_rad + state.beta_rad).abs());
            max_abs_xi = max_abs_xi.max(state.xi_rad.abs());
            max_abs_beta = max_abs_beta.max(state.beta_rad.abs());
            max_abs_delta = max_abs_delta.max(state.delta_rad.abs());
            max_abs_ay = max_abs_ay.max(dynamics.ay_mps2.abs());
            max_abs_ax = max_abs_ax.max(dynamics.ax_mps2.abs());
            max_kamm = max_kamm.max(front_kamm.max(rear_kamm));
            max_abs_slip = max_abs_slip
                .max(dynamics.tire_forces.alpha_front_rad.abs())
                .max(dynamics.tire_forces.alpha_rear_rad.abs());
            max_abs_steering_torque =
                max_abs_steering_torque.max(dynamics.steering_input_torque_nm.abs());
            max_abs_drive = max_abs_drive.max(control.f_drive_n.abs());
            max_abs_brake = max_abs_brake.max(control.f_brake_n.abs());
            let r_omega = state.omega_z_radps - state.v_mps * kappa_1pm;
            let phi_eq = bike_v1_seed_phi_from_kappa(self.params, kappa_1pm, state.v_mps);
            let delta_eq = bike_v1_seed_delta_from_kappa(self.params, kappa_1pm);
            let r_phi = state.phi_rad - phi_eq;
            let r_delta = state.delta_rad - delta_eq;
            max_abs_r_omega = max_abs_r_omega.max(r_omega.abs());
            max_abs_r_phi = max_abs_r_phi.max(r_phi.abs());
            max_abs_r_delta = max_abs_r_delta.max(r_delta.abs());
            sum_sq_r_omega += r_omega * r_omega;
            sum_sq_r_phi += r_phi * r_phi;
            sum_sq_r_delta += r_delta * r_delta;
        };

        visit(BikeV1ExperimentalSample::IntervalStart { interval });
        for point in 0..self.decision_layout.collocation_degree {
            visit(BikeV1ExperimentalSample::Collocation { interval, point });
        }
        visit(BikeV1ExperimentalSample::Station { interval });

        metrics.insert("sample_count", count);
        metrics.insert("min_v_mps", min_v);
        metrics.insert("max_v_mps", max_v);
        metrics.insert(
            "mean_v_mps",
            if count > 0.0 { sum_v / count } else { f64::NAN },
        );
        metrics.insert("min_n_m", min_n);
        metrics.insert("max_n_m", max_n);
        metrics.insert("width_span_m", max_n - min_n);
        metrics.insert("max_abs_heading_relative_rad", max_abs_heading);
        metrics.insert("max_abs_xi_rad", max_abs_xi);
        metrics.insert("max_abs_beta_rad", max_abs_beta);
        metrics.insert("max_abs_delta_rad", max_abs_delta);
        metrics.insert("max_abs_ay_mps2", max_abs_ay);
        metrics.insert("max_abs_ax_mps2", max_abs_ax);
        metrics.insert("max_kamm", max_kamm);
        metrics.insert("max_abs_slip_rad", max_abs_slip);
        metrics.insert("max_abs_steering_torque_nm", max_abs_steering_torque);
        metrics.insert("max_abs_f_drive_n", max_abs_drive);
        metrics.insert("max_abs_f_brake_n", max_abs_brake);
        metrics.insert("max_abs_r_omega_radps", max_abs_r_omega);
        metrics.insert("max_abs_r_phi_rad", max_abs_r_phi);
        metrics.insert("max_abs_r_delta_rad", max_abs_r_delta);
        metrics.insert(
            "rms_r_omega_radps",
            if count > 0.0 {
                (sum_sq_r_omega / count).sqrt()
            } else {
                f64::NAN
            },
        );
        metrics.insert(
            "rms_r_phi_rad",
            if count > 0.0 {
                (sum_sq_r_phi / count).sqrt()
            } else {
                f64::NAN
            },
        );
        metrics.insert(
            "rms_r_delta_rad",
            if count > 0.0 {
                (sum_sq_r_delta / count).sqrt()
            } else {
                f64::NAN
            },
        );
        metrics
    }

    fn basin_sector_aggregates_json(&self, x: &[f64], interval: usize) -> JsonValue {
        JsonValue::Object(
            self.basin_sector_scalar_metrics(x, interval)
                .into_iter()
                .map(|(key, value)| (key.to_owned(), json_number(value)))
                .collect(),
        )
    }

    fn basin_delta_by_sector_json(&self, left_x: &[f64], right_x: &[f64]) -> JsonValue {
        JsonValue::Array(
            (0..self.decision_layout.dimensions.interval_count)
                .map(|interval| {
                    let left = self.basin_sector_scalar_metrics(left_x, interval);
                    let right = self.basin_sector_scalar_metrics(right_x, interval);
                    let deltas = [
                        "min_v_mps",
                        "mean_v_mps",
                        "max_v_mps",
                        "width_span_m",
                        "max_abs_heading_relative_rad",
                        "max_abs_ay_mps2",
                        "max_abs_ax_mps2",
                        "max_kamm",
                        "max_abs_slip_rad",
                        "max_abs_steering_torque_nm",
                        "max_abs_r_omega_radps",
                        "max_abs_r_phi_rad",
                        "max_abs_r_delta_rad",
                        "rms_r_omega_radps",
                        "rms_r_phi_rad",
                        "rms_r_delta_rad",
                    ];
                    let mut entries =
                        vec![("interval".to_owned(), JsonValue::Integer(interval as i64))];
                    for key in deltas {
                        let delta = right.get(key).copied().unwrap_or(f64::NAN)
                            - left.get(key).copied().unwrap_or(f64::NAN);
                        entries.push((format!("{key}_delta"), json_number(delta)));
                    }
                    JsonValue::Object(entries)
                })
                .collect(),
        )
    }

    fn basin_residuals_by_sector_family_json(&self, x: &[f64]) -> JsonValue {
        let mut stats: BTreeMap<(usize, &'static str), BikeV1BasinResidualStats> = BTreeMap::new();
        for entry in self.residual_entries(x) {
            let Some(interval) = self.basin_row_interval(entry.row) else {
                continue;
            };
            let bucket = stats.entry((interval, entry.family)).or_default();
            bucket.count += 1;
            bucket.scaled_sum_sq += entry.scaled_violation * entry.scaled_violation;
            if entry.scaled_violation >= bucket.max_scaled_violation {
                bucket.max_scaled_violation = entry.scaled_violation;
                bucket.max_bound_violation = entry.bound_violation;
                bucket.worst_label = entry.label;
            }
        }

        JsonValue::Array(
            stats
                .into_iter()
                .map(|((interval, family), stats)| {
                    let rms = if stats.count == 0 {
                        0.0
                    } else {
                        (stats.scaled_sum_sq / stats.count as f64).sqrt()
                    };
                    JsonValue::Object(vec![
                        ("interval".to_owned(), JsonValue::Integer(interval as i64)),
                        ("family".to_owned(), family.into()),
                        ("count".to_owned(), JsonValue::Integer(stats.count as i64)),
                        ("rms_scaled_violation".to_owned(), json_number(rms)),
                        (
                            "max_scaled_violation".to_owned(),
                            json_number(stats.max_scaled_violation),
                        ),
                        (
                            "max_bound_violation".to_owned(),
                            json_number(stats.max_bound_violation),
                        ),
                        ("worst_label".to_owned(), stats.worst_label.into()),
                    ])
                })
                .collect(),
        )
    }

    fn basin_objective_by_sector_json(&self, x: &[f64]) -> JsonValue {
        let weights = self.objective_weights;
        let params = self.params;
        let closed = seed_is_closed(&self.geometry_seed);
        let interval_count = self.decision_layout.dimensions.interval_count;
        let station_count = self.decision_layout.dimensions.station_count;
        let collocation = CollocationDegree3::legendre();
        let torque_scale = params.steering_torque_max_nm.max(1.0);
        let drive_scale = params.base.drive_force_max_n.max(1.0);
        let brake_scale = params.base.brake_force_max_n.max(1.0);
        let delta_dot_scale = (params.base.steering_angle_max_rad
            / params.base.steering_response_s.max(0.02))
        .max(1.0);
        let lean_rate_scale = params.base.lean_rate_max_radps.max(1e-9);
        let ay_scale = params.base.lean_limited_lateral_accel_mps2().max(1.0);

        let mut steering_torque = Vec::with_capacity(interval_count);
        let mut force = Vec::with_capacity(interval_count);
        for interval in 0..interval_count {
            let control = self.control_from_decision(x, interval);
            steering_torque.push(control.steering_torque_nm / torque_scale);
            force.push(control.f_drive_n / drive_scale + control.f_brake_n / brake_scale);
        }
        let mut n = Vec::with_capacity(station_count);
        let mut xi = Vec::with_capacity(station_count);
        for station in 0..station_count {
            let offset = self.decision_layout.state_offset(station);
            n.push(x[offset + V1_STATE_N_M]);
            xi.push(x[offset + V1_STATE_XI_RAD]);
        }

        JsonValue::Array(
            (0..interval_count)
                .map(|interval| {
                    let next_interval = if interval + 1 == interval_count {
                        0
                    } else {
                        interval + 1
                    };
                    let prev_interval = if interval == 0 {
                        interval_count.saturating_sub(1)
                    } else {
                        interval - 1
                    };

                    let mut lap_time_s = 0.0;
                    for point in 0..self.decision_layout.collocation_degree {
                        let sigma = self
                            .sample_section_progress(
                                x,
                                BikeV1ExperimentalSample::Collocation { interval, point },
                            )
                            .sigma_dt_ds;
                        lap_time_s +=
                            self.interval_ds_m[interval] * collocation.b[point + 1] * sigma;
                    }

                    let steering_control_regularization_scale =
                        self.options.moto_v1_steering_control_regularization_scale;
                    let steering_first = weights.penalty_delta
                        * steering_control_regularization_scale
                        * (steering_torque[next_interval] - steering_torque[interval]).powi(2);
                    let steering_second = weights.penalty_delta_dd
                        * steering_control_regularization_scale
                        * (steering_torque[next_interval] - 2.0 * steering_torque[interval]
                            + steering_torque[prev_interval])
                            .powi(2);
                    let force_first =
                        weights.penalty_f * (force[next_interval] - force[interval]).powi(2);
                    let force_second = weights.penalty_f_dd
                        * (force[next_interval] - 2.0 * force[interval] + force[prev_interval])
                            .powi(2);
                    let n_second = weights.penalty_n
                        * (n[next_interval] - 2.0 * n[interval] + n[prev_interval]).powi(2);
                    let xi_second = weights.penalty_xi
                        * (xi[next_interval] - 2.0 * xi[interval] + xi[prev_interval]).powi(2);

                    let station = interval.min(station_count.saturating_sub(1));
                    let next_station = if station + 1 == station_count {
                        0
                    } else {
                        station + 1
                    };
                    let state = self.station_state_from_decision(x, station);
                    let dynamics = self.station_dynamics(x, station);
                    let next_dynamics = self.station_dynamics(x, next_station);
                    let steady_phi = (dynamics.ay_mps2 / params.base.gravity_mps2.max(1e-9)).atan();
                    let next_steady_phi =
                        (next_dynamics.ay_mps2 / params.base.gravity_mps2.max(1e-9)).atan();
                    let sigma_dt_ds = dynamics.sigma_dt_ds.max(1e-9);
                    let next_sigma_dt_ds = next_dynamics.sigma_dt_ds.max(1e-9);
                    let segment_dt = 0.5
                        * (sigma_dt_ds + next_sigma_dt_ds)
                        * self.interval_ds_m.get(interval).copied().unwrap_or(1.0);
                    let phi_eq_rate =
                        (next_steady_phi - steady_phi) / segment_dt.max(1e-9) / lean_rate_scale;
                    let ay_rate = ((next_dynamics.ay_mps2 / ay_scale)
                        - (dynamics.ay_mps2 / ay_scale))
                        / segment_dt.max(1e-9);
                    let delta_dot =
                        (state.delta_dot_radps / delta_dot_scale).powi(2) * weights.penalty_delta;
                    let roll_tau = (dynamics.steering_net_torque_nm / torque_scale).powi(2)
                        * weights.penalty_roll_tau;
                    let lean_equilibrium =
                        ((steady_phi - state.phi_rad) / BIKE_LEAN_EQUILIBRIUM_SCALE_RAD).powi(2)
                            * weights.penalty_lean_equilibrium;
                    let phi_eq_rate_term = weights.penalty_phi_eq_rate * phi_eq_rate.powi(2);
                    let ay_rate_term = weights.penalty_ay_rate * ay_rate.powi(2);
                    let basin_trust = bike_v1_basin_trust_objective_for_sector_s(self, x, interval);
                    let energy_guard =
                        bike_v1_energy_guard_objective_for_sector_s(self, x, interval);
                    let active_set_guard =
                        bike_v1_active_set_guard_objective_for_sector_s(self, x, interval);
                    let block_slack = bike_v1_block_slack_objective_for_sector_s(self, x, interval);
                    let steering_shadow_gate =
                        bike_v1_steering_shadow_gate_objective_for_sector_s(self, x, interval);
                    let kamm_margin_guard =
                        bike_v1_kamm_margin_guard_objective_for_sector_s(self, x, interval);
                    let total = lap_time_s
                        + steering_first
                        + steering_second
                        + force_first
                        + force_second
                        + n_second
                        + xi_second
                        + delta_dot
                        + roll_tau
                        + lean_equilibrium
                        + phi_eq_rate_term
                        + ay_rate_term
                        + basin_trust
                        + energy_guard
                        + active_set_guard
                        + block_slack
                        + steering_shadow_gate
                        + kamm_margin_guard;

                    JsonValue::Object(vec![
                        ("interval".to_owned(), JsonValue::Integer(interval as i64)),
                        ("lap_time_s".to_owned(), json_number(lap_time_s)),
                        (
                            "steering_regularization_s".to_owned(),
                            json_number(steering_first + steering_second),
                        ),
                        (
                            "force_regularization_s".to_owned(),
                            json_number(force_first + force_second),
                        ),
                        ("regularization_n_s".to_owned(), json_number(n_second)),
                        ("regularization_xi_s".to_owned(), json_number(xi_second)),
                        ("delta_dot_s".to_owned(), json_number(delta_dot)),
                        ("roll_tau_s".to_owned(), json_number(roll_tau)),
                        (
                            "lean_equilibrium_s".to_owned(),
                            json_number(lean_equilibrium),
                        ),
                        ("phi_eq_rate_s".to_owned(), json_number(phi_eq_rate_term)),
                        ("ay_rate_s".to_owned(), json_number(ay_rate_term)),
                        ("debug_basin_trust_s".to_owned(), json_number(basin_trust)),
                        ("debug_energy_guard_s".to_owned(), json_number(energy_guard)),
                        (
                            "debug_active_set_guard_s".to_owned(),
                            json_number(active_set_guard),
                        ),
                        ("debug_block_slack_s".to_owned(), json_number(block_slack)),
                        (
                            "debug_steering_shadow_gate_s".to_owned(),
                            json_number(steering_shadow_gate),
                        ),
                        (
                            "debug_kamm_margin_guard_s".to_owned(),
                            json_number(kamm_margin_guard),
                        ),
                        ("total_s".to_owned(), json_number(total)),
                        ("closed_loop".to_owned(), JsonValue::Bool(closed)),
                    ])
                })
                .collect(),
        )
    }

    fn basin_jacobian_by_sector_family_json(&self, x: &[f64]) -> JsonValue {
        let mut profile = BikeV1CallbackProfile::default();
        let values = match self.sparse_jacobian_numeric_profiled(x, &mut profile) {
            Ok(values) => values,
            Err(error) => {
                return JsonValue::Object(vec![
                    ("available".to_owned(), JsonValue::Bool(false)),
                    ("error".to_owned(), error.into()),
                ]);
            }
        };

        let mut stats: BTreeMap<(usize, &'static str, &'static str), BikeV1BasinJacobianStats> =
            BTreeMap::new();
        for (entry_index, ((row, variable), value)) in
            self.jacobian_pattern.iter().zip(values.iter()).enumerate()
        {
            let Ok(row_index) = usize::try_from(*row) else {
                continue;
            };
            let Ok(variable_index) = usize::try_from(*variable) else {
                continue;
            };
            let Some(row) = self.rows.get(row_index).copied() else {
                continue;
            };
            let Some(interval) = self.basin_row_interval(row) else {
                continue;
            };
            let family = bike_v1_profile_family_for_row(row);
            let variable_family = self.basin_variable_family(variable_index);
            let bucket = stats
                .entry((interval, family, variable_family))
                .or_default();
            bucket.nnz += 1;
            bucket.l2_sq += value * value;
            let abs_value = value.abs();
            bucket.linf_abs = bucket.linf_abs.max(abs_value);
            if abs_value >= bucket.max_abs_derivative {
                bucket.max_abs_derivative = abs_value;
                bucket.max_abs_row = row_index;
                bucket.max_abs_variable = variable_index;
            }
            if self
                .constraint_derivative_structured(x, row_index, variable_index)
                .is_none()
            {
                bucket.numeric_fallback_entries += 1;
            }
            let _ = entry_index;
        }

        JsonValue::Object(vec![
            ("available".to_owned(), JsonValue::Bool(true)),
            (
                "note".to_owned(),
                "Post-solve physical-units sparse Jacobian aggregation. numeric_fallback_entries counts entries that do not have a structured derivative provider and therefore use finite differences in the current V1 Jacobian path.".into(),
            ),
            (
                "callback_profile".to_owned(),
                JsonValue::Object(vec![
                    (
                        "jacobian_values".to_owned(),
                        bike_v1_profile_counter_json(profile.jacobian_values),
                    ),
                    (
                        "jacobian_numeric_fallback".to_owned(),
                        bike_v1_profile_counter_json(profile.jacobian_numeric_fallback),
                    ),
                    (
                        "jacobian_numeric_fallback_family_timing".to_owned(),
                        bike_v1_profile_map_json(&profile.jacobian_numeric_fallback_family),
                    ),
                ]),
            ),
            (
                "rows".to_owned(),
                JsonValue::Array(
                    stats
                        .into_iter()
                        .map(|((interval, family, variable_family), stats)| {
                            JsonValue::Object(vec![
                                (
                                    "interval".to_owned(),
                                    JsonValue::Integer(interval as i64),
                                ),
                                ("family".to_owned(), family.into()),
                                ("variable_family".to_owned(), variable_family.into()),
                                ("nnz".to_owned(), JsonValue::Integer(stats.nnz as i64)),
                                ("l2_norm".to_owned(), json_number(stats.l2_sq.sqrt())),
                                ("linf_norm".to_owned(), json_number(stats.linf_abs)),
                                (
                                    "max_abs_derivative".to_owned(),
                                    json_number(stats.max_abs_derivative),
                                ),
                                (
                                    "max_abs_row_index".to_owned(),
                                    JsonValue::Integer(stats.max_abs_row as i64),
                                ),
                                (
                                    "max_abs_variable_index".to_owned(),
                                    JsonValue::Integer(stats.max_abs_variable as i64),
                                ),
                                (
                                    "numeric_fallback_entries".to_owned(),
                                    JsonValue::Integer(stats.numeric_fallback_entries as i64),
                                ),
                            ])
                        })
                        .collect(),
                ),
            ),
        ])
    }

    fn basin_jacobian_transpose_lambda_by_sector_family_json(
        &self,
        x: &[f64],
        lambda: &[f64],
    ) -> JsonValue {
        if lambda.len() != self.rows.len() {
            return JsonValue::Object(vec![
                ("available".to_owned(), JsonValue::Bool(false)),
                (
                    "reason".to_owned(),
                    format!(
                        "constraint multiplier length {} does not match row count {}",
                        lambda.len(),
                        self.rows.len()
                    )
                    .into(),
                ),
            ]);
        }
        let mut profile = BikeV1CallbackProfile::default();
        let values = match self.sparse_jacobian_numeric_profiled(x, &mut profile) {
            Ok(values) => values,
            Err(error) => {
                return JsonValue::Object(vec![
                    ("available".to_owned(), JsonValue::Bool(false)),
                    ("error".to_owned(), error.into()),
                ]);
            }
        };
        let mut stats: BTreeMap<(usize, &'static str, &'static str), BikeV1BasinSignalStats> =
            BTreeMap::new();
        let mut fallback_stats: BTreeMap<(usize, &'static str, &'static str), usize> =
            BTreeMap::new();
        for ((row, variable), derivative) in self.jacobian_pattern.iter().zip(values.iter()) {
            let Ok(row_index) = usize::try_from(*row) else {
                continue;
            };
            let Ok(variable_index) = usize::try_from(*variable) else {
                continue;
            };
            let Some(row) = self.rows.get(row_index).copied() else {
                continue;
            };
            let Some(interval) = self.basin_row_interval(row) else {
                continue;
            };
            let Some((_, variable_family, variable_label)) =
                self.basin_variable_interval_family_label(variable_index)
            else {
                continue;
            };
            let row_family = bike_v1_profile_family_for_row(row);
            let contribution = derivative * lambda[row_index];
            let label = format!("{} x {}", row.label(), variable_label);
            let key = (interval, row_family, variable_family);
            let bucket = stats.entry(key).or_default();
            bike_v1_add_basin_signal(bucket, variable_index, &label, contribution);
            if self
                .constraint_derivative_structured(x, row_index, variable_index)
                .is_none()
            {
                *fallback_stats.entry(key).or_default() += 1;
            }
        }
        JsonValue::Object(vec![
            ("available".to_owned(), JsonValue::Bool(true)),
            (
                "note".to_owned(),
                "Diagnostic J^T*lambda aggregation using physical-units post-solve Jacobian entries and raw Ipopt TNLP multipliers. Use as relative KKT pressure, not physical force units.".into(),
            ),
            (
                "callback_profile".to_owned(),
                JsonValue::Object(vec![
                    (
                        "jacobian_values".to_owned(),
                        bike_v1_profile_counter_json(profile.jacobian_values),
                    ),
                    (
                        "jacobian_numeric_fallback".to_owned(),
                        bike_v1_profile_counter_json(profile.jacobian_numeric_fallback),
                    ),
                ]),
            ),
            (
                "rows".to_owned(),
                JsonValue::Array(
                    stats
                        .into_iter()
                        .map(|((interval, family, variable_family), stats)| {
                            let fallback_count = fallback_stats
                                .get(&(interval, family, variable_family))
                                .copied()
                                .unwrap_or(0);
                            let mut entry = bike_v1_basin_signal_stats_json(stats);
                            if let JsonValue::Object(fields) = &mut entry {
                                fields.insert(
                                    0,
                                    (
                                        "numeric_fallback_entries".to_owned(),
                                        JsonValue::Integer(fallback_count as i64),
                                    ),
                                );
                                fields.insert(
                                    0,
                                    ("variable_family".to_owned(), variable_family.into()),
                                );
                                fields.insert(0, ("family".to_owned(), family.into()));
                                fields.insert(
                                    0,
                                    ("interval".to_owned(), JsonValue::Integer(interval as i64)),
                                );
                            }
                            entry
                        })
                        .collect(),
                ),
            ),
        ])
    }

    fn basin_row_interval(&self, row: BikeV1ExperimentalConstraintRow) -> Option<usize> {
        let interval_count = self.decision_layout.dimensions.interval_count;
        match row {
            BikeV1ExperimentalConstraintRow::Generic(GenericMintimeConstraintRow::Continuity {
                interval,
                ..
            })
            | BikeV1ExperimentalConstraintRow::Generic(
                GenericMintimeConstraintRow::CollocationDynamics { interval, .. },
            )
            | BikeV1ExperimentalConstraintRow::Generic(
                GenericMintimeConstraintRow::ControlRate { interval, .. },
            )
            | BikeV1ExperimentalConstraintRow::Generic(GenericMintimeConstraintRow::DtDs {
                interval,
            })
            | BikeV1ExperimentalConstraintRow::DriveBrakeMutex { interval }
            | BikeV1ExperimentalConstraintRow::SteeringTorque { interval }
            | BikeV1ExperimentalConstraintRow::ControlLowFrequency { interval, .. } => {
                Some(interval)
            }
            BikeV1ExperimentalConstraintRow::Generic(
                GenericMintimeConstraintRow::TrackBounds { station },
            ) => Some(station.min(interval_count.saturating_sub(1))),
            BikeV1ExperimentalConstraintRow::Generic(
                GenericMintimeConstraintRow::ModelSpecific { .. },
            ) => None,
            BikeV1ExperimentalConstraintRow::SectionMapJacobian { sample }
            | BikeV1ExperimentalConstraintRow::SectionForwardProgress { sample }
            | BikeV1ExperimentalConstraintRow::NormalLoad { sample, .. }
            | BikeV1ExperimentalConstraintRow::Kamm { sample, .. }
            | BikeV1ExperimentalConstraintRow::PowerLimit { sample }
            | BikeV1ExperimentalConstraintRow::SlipAngle { sample, .. } => Some(sample.interval()),
        }
    }

    fn basin_variable_family(&self, variable_index: usize) -> &'static str {
        self.objective_gradient_variable_family(variable_index)
    }

    fn basin_variable_interval_family_label(
        &self,
        variable_index: usize,
    ) -> Option<(usize, &'static str, String)> {
        let interval_count = self.decision_layout.dimensions.interval_count;
        for station in 0..self.decision_layout.dimensions.station_count {
            let offset = self.decision_layout.state_offset(station);
            if (offset..offset + self.decision_layout.state_len).contains(&variable_index) {
                let state_index = variable_index - offset;
                return Some((
                    station.min(interval_count.saturating_sub(1)),
                    bike_v1_objective_station_variable_family(state_index),
                    format!(
                        "station_{station}.{}",
                        bike_v1_state_column_name(state_index)
                    ),
                ));
            }
        }
        for interval in 0..interval_count {
            let offset = self.decision_layout.control_offset(interval);
            if (offset..offset + self.decision_layout.control_len).contains(&variable_index) {
                let control_index = variable_index - offset;
                return Some((
                    interval,
                    bike_v1_objective_control_variable_family(control_index),
                    format!(
                        "control_{interval}.{}",
                        bike_v1_control_column_name(control_index)
                    ),
                ));
            }
        }
        for interval in 0..interval_count {
            for point in 0..self.decision_layout.collocation_degree {
                let offset = self
                    .decision_layout
                    .collocation_state_offset(interval, point);
                if (offset..offset + self.decision_layout.state_len).contains(&variable_index) {
                    let state_index = variable_index - offset;
                    return Some((
                        interval,
                        bike_v1_objective_collocation_variable_family(state_index),
                        format!(
                            "colloc_{interval}_{point}.{}",
                            bike_v1_state_column_name(state_index)
                        ),
                    ));
                }
            }
        }
        None
    }

    fn delta_dot_dynamics_audit_json(
        &self,
        x: &[f64],
        top_count: usize,
        focus_interval_start: usize,
        focus_interval_end: usize,
    ) -> JsonValue {
        let mut rows = self.delta_dot_dynamics_audit_rows(x);
        rows.sort_by(|left, right| {
            right
                .scaled_residual
                .abs()
                .partial_cmp(&left.scaled_residual.abs())
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        let max_abs_residual = rows
            .iter()
            .map(|row| row.residual.abs())
            .fold(0.0, f64::max);
        let max_scaled_residual = rows
            .iter()
            .map(|row| row.scaled_residual.abs())
            .fold(0.0, f64::max);
        let rms_scaled_residual = if rows.is_empty() {
            0.0
        } else {
            (rows
                .iter()
                .map(|row| row.scaled_residual * row.scaled_residual)
                .sum::<f64>()
                / rows.len() as f64)
                .sqrt()
        };

        JsonValue::Object(vec![
            (
                "schema_version".to_owned(),
                "bike_v1_delta_dot_dynamics_audit.v1".into(),
            ),
            (
                "description".to_owned(),
                "Collocation residual audit for V1 steering assembly delta_dot dynamics".into(),
            ),
            (
                "state_column".to_owned(),
                bike_v1_state_column_name(V1_STATE_DELTA_DOT_RADPS).into(),
            ),
            ("max_abs_residual".to_owned(), json_number(max_abs_residual)),
            (
                "max_scaled_residual".to_owned(),
                json_number(max_scaled_residual),
            ),
            (
                "rms_scaled_residual".to_owned(),
                json_number(rms_scaled_residual),
            ),
            (
                "top_rows".to_owned(),
                JsonValue::Array(
                    rows.iter()
                        .take(top_count)
                        .map(bike_v1_delta_dot_dynamics_audit_row_json)
                        .collect(),
                ),
            ),
            (
                "focus_interval_start".to_owned(),
                JsonValue::Integer(focus_interval_start as i64),
            ),
            (
                "focus_interval_end".to_owned(),
                JsonValue::Integer(focus_interval_end as i64),
            ),
            (
                "focus_rows".to_owned(),
                JsonValue::Array(
                    rows.iter()
                        .filter(|row| {
                            row.interval >= focus_interval_start
                                && row.interval <= focus_interval_end
                        })
                        .map(bike_v1_delta_dot_dynamics_audit_row_json)
                        .collect(),
                ),
            ),
        ])
    }

    fn delta_dot_dynamics_audit_rows(&self, x: &[f64]) -> Vec<BikeV1DeltaDotDynamicsAuditRow> {
        let collocation = CollocationDegree3::legendre();
        let mut rows = Vec::with_capacity(
            self.decision_layout.dimensions.interval_count
                * self.decision_layout.collocation_degree,
        );
        for interval in 0..self.decision_layout.dimensions.interval_count {
            let ds_m = self.interval_ds_m[interval].max(1e-9);
            for point in 0..self.decision_layout.collocation_degree {
                let sample = BikeV1ExperimentalSample::Collocation { interval, point };
                let (state, _, _) = self.sample_state_control_kappa(x, sample);
                let dynamics = self.sample_dynamics(x, sample);
                let polynomial_delta_dot_s = self.collocation_state_derivative_component_s(
                    x,
                    interval,
                    point,
                    V1_STATE_DELTA_DOT_RADPS,
                    ds_m,
                    collocation,
                );
                let dynamics_delta_dot_ds = dynamics.ddelta_dot_ds;
                let residual = polynomial_delta_dot_s - dynamics_delta_dot_ds;
                let row_index = self
                    .rows
                    .iter()
                    .position(|row| {
                        matches!(
                            row,
                            BikeV1ExperimentalConstraintRow::Generic(
                                GenericMintimeConstraintRow::CollocationDynamics {
                                    interval: row_interval,
                                    point: row_point,
                                    state_index: V1_STATE_DELTA_DOT_RADPS,
                                }
                            ) if *row_interval == interval && *row_point == point
                        )
                    })
                    .unwrap_or(usize::MAX);
                let scale = self
                    .constraint_scales
                    .get(row_index)
                    .copied()
                    .unwrap_or(1.0)
                    .max(1e-12);

                rows.push(BikeV1DeltaDotDynamicsAuditRow {
                    row_index,
                    interval,
                    point,
                    delta_rad: state.delta_rad,
                    delta_dot_radps: state.delta_dot_radps,
                    steering_torque_nm: dynamics.steering_input_torque_nm,
                    steering_net_torque_nm: dynamics.steering_net_torque_nm,
                    delta_ddot_radps2: dynamics.delta_ddot_radps2,
                    dynamics_delta_dot_ds,
                    polynomial_delta_dot_s,
                    residual,
                    scale,
                    scaled_residual: residual / scale,
                    v_mps: state.v_mps,
                    phi_rad: state.phi_rad,
                    ay_mps2: dynamics.ay_mps2,
                    front_kamm: bike_v1_kamm_for_axle(
                        self.params,
                        dynamics.tire_forces,
                        "front",
                        self.options.load_sensitive_kamm_denominator,
                    ),
                    rear_kamm: bike_v1_kamm_for_axle(
                        self.params,
                        dynamics.tire_forces,
                        "rear",
                        self.options.load_sensitive_kamm_denominator,
                    ),
                });
            }
        }
        rows
    }

    fn collocation_state_derivative_component_s(
        &self,
        x: &[f64],
        interval: usize,
        point: usize,
        state_index: usize,
        ds_m: f64,
        collocation: CollocationDegree3,
    ) -> f64 {
        let mut derivative = collocation.c[0][point + 1]
            * x[self.decision_layout.state_offset(interval) + state_index];
        for basis_point in 0..self.decision_layout.collocation_degree {
            derivative += collocation.c[basis_point + 1][point + 1]
                * x[self
                    .decision_layout
                    .collocation_state_offset(interval, basis_point)
                    + state_index];
        }
        derivative / ds_m
    }

    fn constraint_context_json(
        &self,
        x: &[f64],
        row: BikeV1ExperimentalConstraintRow,
    ) -> JsonValue {
        match row {
            BikeV1ExperimentalConstraintRow::Generic(row) => self.generic_row_context_json(x, row),
            BikeV1ExperimentalConstraintRow::SectionMapJacobian { sample }
            | BikeV1ExperimentalConstraintRow::SectionForwardProgress { sample } => {
                self.sample_context_json(x, sample, None)
            }
            BikeV1ExperimentalConstraintRow::NormalLoad { sample, axle }
            | BikeV1ExperimentalConstraintRow::Kamm { sample, axle }
            | BikeV1ExperimentalConstraintRow::SlipAngle { sample, axle } => {
                self.sample_context_json(x, sample, Some(axle))
            }
            BikeV1ExperimentalConstraintRow::PowerLimit { sample } => {
                self.sample_context_json(x, sample, None)
            }
            BikeV1ExperimentalConstraintRow::DriveBrakeMutex { interval }
            | BikeV1ExperimentalConstraintRow::SteeringTorque { interval } => {
                let control = self.control_from_decision(x, interval);
                JsonValue::Object(vec![
                    ("interval".to_owned(), JsonValue::Integer(interval as i64)),
                    (
                        "steering_torque_nm".to_owned(),
                        json_number(control.steering_torque_nm),
                    ),
                    ("f_drive_n".to_owned(), json_number(control.f_drive_n)),
                    ("f_brake_n".to_owned(), json_number(control.f_brake_n)),
                    (
                        "drive_brake_product_n2".to_owned(),
                        json_number(control.f_drive_n * control.f_brake_n),
                    ),
                ])
            }
            BikeV1ExperimentalConstraintRow::ControlLowFrequency {
                interval,
                anchor_interval,
                control_index,
            } => {
                let control = self.control_from_decision(x, interval);
                let anchor = self.control_from_decision(x, anchor_interval);
                JsonValue::Object(vec![
                    ("kind".to_owned(), "control_lowfreq".into()),
                    ("interval".to_owned(), JsonValue::Integer(interval as i64)),
                    (
                        "anchor_interval".to_owned(),
                        JsonValue::Integer(anchor_interval as i64),
                    ),
                    (
                        "control_index".to_owned(),
                        JsonValue::Integer(control_index as i64),
                    ),
                    (
                        "control_column".to_owned(),
                        bike_v1_control_column_name(control_index).into(),
                    ),
                    (
                        "current_value".to_owned(),
                        json_number(bike_v1_control_component(control, control_index)),
                    ),
                    (
                        "anchor_value".to_owned(),
                        json_number(bike_v1_control_component(anchor, control_index)),
                    ),
                ])
            }
        }
    }

    fn generic_row_context_json(&self, x: &[f64], row: GenericMintimeConstraintRow) -> JsonValue {
        match row {
            GenericMintimeConstraintRow::Continuity {
                interval,
                state_index,
            } => {
                let station =
                    next_station_index(self.decision_layout.dimensions.station_count, interval);
                let next_station =
                    next_station_index(self.decision_layout.dimensions.station_count, station);
                let left_offset = self.decision_layout.state_offset(station) + state_index;
                let right_offset = self.decision_layout.state_offset(next_station) + state_index;
                JsonValue::Object(vec![
                    ("kind".to_owned(), "continuity".into()),
                    ("interval".to_owned(), JsonValue::Integer(interval as i64)),
                    ("station".to_owned(), JsonValue::Integer(station as i64)),
                    (
                        "next_station".to_owned(),
                        JsonValue::Integer(next_station as i64),
                    ),
                    (
                        "state_index".to_owned(),
                        JsonValue::Integer(state_index as i64),
                    ),
                    (
                        "state_column".to_owned(),
                        bike_v1_state_column_name(state_index).into(),
                    ),
                    ("left_value".to_owned(), json_number(x[left_offset])),
                    ("right_value".to_owned(), json_number(x[right_offset])),
                ])
            }
            GenericMintimeConstraintRow::CollocationDynamics {
                interval,
                point,
                state_index,
            } => {
                let sample = BikeV1ExperimentalSample::Collocation { interval, point };
                let mut entries = match self.sample_context_json(x, sample, None) {
                    JsonValue::Object(entries) => entries,
                    _ => Vec::new(),
                };
                entries.push(("kind".to_owned(), "collocation_dynamics".into()));
                entries.push((
                    "state_index".to_owned(),
                    JsonValue::Integer(state_index as i64),
                ));
                entries.push((
                    "state_column".to_owned(),
                    bike_v1_state_column_name(state_index).into(),
                ));
                JsonValue::Object(entries)
            }
            GenericMintimeConstraintRow::ControlRate {
                interval,
                control_index,
            } => {
                let next_interval =
                    next_station_index(self.decision_layout.dimensions.interval_count, interval);
                let control = self.control_from_decision(x, interval);
                let next_control = self.control_from_decision(x, next_interval);
                JsonValue::Object(vec![
                    ("kind".to_owned(), "control_rate".into()),
                    ("interval".to_owned(), JsonValue::Integer(interval as i64)),
                    (
                        "next_interval".to_owned(),
                        JsonValue::Integer(next_interval as i64),
                    ),
                    (
                        "control_index".to_owned(),
                        JsonValue::Integer(control_index as i64),
                    ),
                    (
                        "control_column".to_owned(),
                        bike_v1_control_column_name(control_index).into(),
                    ),
                    (
                        "current_value".to_owned(),
                        json_number(bike_v1_control_component(control, control_index)),
                    ),
                    (
                        "next_value".to_owned(),
                        json_number(bike_v1_control_component(next_control, control_index)),
                    ),
                ])
            }
            GenericMintimeConstraintRow::TrackBounds { station } => {
                let state = self.station_state_from_decision(x, station);
                JsonValue::Object(vec![
                    ("kind".to_owned(), "track_bounds".into()),
                    ("station".to_owned(), JsonValue::Integer(station as i64)),
                    ("n_m".to_owned(), json_number(state.n_m)),
                ])
            }
            GenericMintimeConstraintRow::DtDs { interval } => {
                let state = self.station_state_from_decision(
                    x,
                    next_station_index(self.decision_layout.dimensions.station_count, interval),
                );
                let control = self.control_from_decision(x, interval);
                JsonValue::Object(vec![
                    ("kind".to_owned(), "dt_ds".into()),
                    ("interval".to_owned(), JsonValue::Integer(interval as i64)),
                    ("v_mps".to_owned(), json_number(state.v_mps)),
                    (
                        "steering_torque_nm".to_owned(),
                        json_number(control.steering_torque_nm),
                    ),
                    ("f_drive_n".to_owned(), json_number(control.f_drive_n)),
                    ("f_brake_n".to_owned(), json_number(control.f_brake_n)),
                ])
            }
            GenericMintimeConstraintRow::ModelSpecific { kind, index } => JsonValue::Object(vec![
                ("kind".to_owned(), kind.into()),
                ("index".to_owned(), JsonValue::Integer(index as i64)),
            ]),
        }
    }

