const BIKE_V1_SEED_TRANSFER_XY_RMS_LIMIT_M: f64 = 0.05;
const BIKE_V1_SEED_TRANSFER_XY_MAX_LIMIT_M: f64 = 0.25;
const BIKE_V1_SEED_TRANSFER_CLAMP_DISTANCE_TOL_M: f64 = 1.0e-6;

impl BikeV1SeedTransferMetrics {
    fn to_json(&self) -> JsonValue {
        JsonValue::Object(vec![
            (
                "station_count".to_owned(),
                JsonValue::Integer(self.station_count as i64),
            ),
            (
                "missing_station_count".to_owned(),
                JsonValue::Integer(self.missing_station_count as i64),
            ),
            (
                "source_clamp_count".to_owned(),
                JsonValue::Integer(self.source_clamp_count as i64),
            ),
            (
                "source_to_seed_xy_rms_m".to_owned(),
                json_number(self.source_to_seed_xy_rms_m),
            ),
            (
                "source_to_seed_xy_p95_m".to_owned(),
                json_number(self.source_to_seed_xy_p95_m),
            ),
            (
                "source_to_seed_xy_max_m".to_owned(),
                json_number(self.source_to_seed_xy_max_m),
            ),
            (
                "worst_station".to_owned(),
                json_option_usize(self.worst_station),
            ),
            (
                "worst_source_x_m".to_owned(),
                json_option_f64(self.worst_source_x_m),
            ),
            (
                "worst_source_y_m".to_owned(),
                json_option_f64(self.worst_source_y_m),
            ),
            (
                "worst_seed_x_m".to_owned(),
                json_option_f64(self.worst_seed_x_m),
            ),
            (
                "worst_seed_y_m".to_owned(),
                json_option_f64(self.worst_seed_y_m),
            ),
        ])
    }

    fn validate(&self) -> Result<(), SolverApiError> {
        if self.missing_station_count > 0
            || self.source_clamp_count > 0
            || self.source_to_seed_xy_rms_m > BIKE_V1_SEED_TRANSFER_XY_RMS_LIMIT_M
            || self.source_to_seed_xy_max_m > BIKE_V1_SEED_TRANSFER_XY_MAX_LIMIT_M
        {
            return Err(SolverApiError::new(
                "solve.invalidSeedTransfer",
                format!(
                    "V1 seed transfer failed: rms={:.6}m p95={:.6}m max={:.6}m clamp_count={} missing_station_count={} worst_station={:?}; station-index compatible transfer is required",
                    self.source_to_seed_xy_rms_m,
                    self.source_to_seed_xy_p95_m,
                    self.source_to_seed_xy_max_m,
                    self.source_clamp_count,
                    self.missing_station_count,
                    self.worst_station
                ),
            )
            .with_details(self.to_json()));
        }
        Ok(())
    }
}

impl BikeV1SeedReferenceSource {
    fn exact(sample_index: usize, station_index: usize, source_s_m: f64) -> Self {
        Self {
            source_index: Some(sample_index),
            source_station_index: Some(station_index),
            source_s_m: Some(source_s_m),
            source_tau: Some(0.0),
            source_was_clamped: false,
            phase_advance_distance_m: Some(0.0),
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum BikeV1SeedReferenceSpeedMode {
    ReferenceSpeed,
    GeometryOnly,
}

impl BikeV1SeedReferenceSpeedMode {
    fn as_str(self) -> &'static str {
        match self {
            Self::ReferenceSpeed => "reference_speed",
            Self::GeometryOnly => "geometry_only",
        }
    }
}

impl BikeV1SeedReference {
    fn sample_count(&self) -> usize {
        self.sample_count
    }

    fn station_indexed_sample_count(&self) -> usize {
        self.station_samples
            .iter()
            .filter(|sample| sample.is_some())
            .count()
    }

    fn sample_for_station(
        &self,
        station: usize,
    ) -> Result<BikeV1SeedReferenceSample, SolverApiError> {
        if let Some(Some(sample)) = self.station_samples.get(station) {
            return Ok(*sample);
        }
        Err(SolverApiError::new(
            "solve.invalidRequest",
            format!(
                "v1_seed_reference_path trajectory_result.station_index is missing station {station}; s_m interpolation is not allowed for V1 seed transfer"
            ),
        ))
    }

    fn speed_mode(&self) -> BikeV1SeedReferenceSpeedMode {
        self.speed_mode
    }
}

fn load_bike_v1_seed_reference(path: &PathBuf) -> Result<BikeV1SeedReference, SolverApiError> {
    let text = fs::read_to_string(path).map_err(|error| {
        SolverApiError::new(
            "solve.invalidRequest",
            format!(
                "failed to read v1_seed_reference_path {}: {error}",
                path.display()
            ),
        )
    })?;
    let root = parse_json_str(&text).map_err(|error| {
        SolverApiError::new(
            "solve.invalidRequest",
            format!(
                "failed to parse v1_seed_reference_path {}: {}",
                path.display(),
                error.message
            ),
        )
    })?;
    bike_v1_seed_reference_from_result_json(&root)
}

struct BikeV1MaterializedSeedApplyCounts {
    station_rows: usize,
    collocation_rows: usize,
    control_rows: usize,
}

fn apply_bike_v1_materialized_full_state_control_seed(
    path: &PathBuf,
    params: BikeCountersteerLeanParamsV1,
    decision_layout: DecisionLayout,
    lower_bounds: &[f64],
    upper_bounds: &[f64],
    initial_decision: &mut [f64],
) -> Result<BikeV1MaterializedSeedApplyCounts, SolverApiError> {
    let text = fs::read_to_string(path).map_err(|error| {
        SolverApiError::new(
            "solve.invalidRequest",
            format!(
                "failed to read v1_seed_reference_path {}: {error}",
                path.display()
            ),
        )
    })?;
    let root = parse_json_str(&text).map_err(|error| {
        SolverApiError::new(
            "solve.invalidRequest",
            format!(
                "failed to parse v1_seed_reference_path {}: {}",
                path.display(),
                error.message
            ),
        )
    })?;
    let seed = bike_v1_materialized_seed_json_root(&root).ok_or_else(|| {
        SolverApiError::new(
            "solve.invalidRequest",
            "materialized_full_state_control seed requires station/collocation/controls rows or diagnostics.materialized_seed",
        )
    })?;
    let steering_coordinate = seed
        .get("steering_coordinate")
        .and_then(JsonValue::as_str)
        .unwrap_or("torque_nm");

    let mut station_rows = 0usize;
    let mut collocation_rows = 0usize;
    let mut control_rows = 0usize;

    if let Some(rows) = seed.get("station").and_then(JsonValue::as_array) {
        for row in rows {
            let station = bike_v1_materialized_seed_index(row, "station_index")?;
            if station >= decision_layout.dimensions.station_count {
                return Err(SolverApiError::new(
                    "solve.invalidRequest",
                    format!(
                        "materialized_full_state_control station_index {station} is out of range"
                    ),
                ));
            }
            let offset = decision_layout.state_offset(station);
            apply_bike_v1_materialized_state_row(
                row,
                offset,
                lower_bounds,
                upper_bounds,
                initial_decision,
            );
            station_rows += 1;
        }
    }

    if let Some(rows) = seed.get("collocation").and_then(JsonValue::as_array) {
        for row in rows {
            let interval = bike_v1_materialized_seed_index(row, "interval")?;
            let point = bike_v1_materialized_seed_index(row, "point")?;
            if interval >= decision_layout.dimensions.interval_count {
                return Err(SolverApiError::new(
                    "solve.invalidRequest",
                    format!(
                        "materialized_full_state_control collocation interval {interval} is out of range"
                    ),
                ));
            }
            if point >= decision_layout.collocation_degree {
                return Err(SolverApiError::new(
                    "solve.invalidRequest",
                    format!(
                        "materialized_full_state_control collocation point {point} is out of range"
                    ),
                ));
            }
            let offset = decision_layout.collocation_state_offset(interval, point);
            apply_bike_v1_materialized_state_row(
                row,
                offset,
                lower_bounds,
                upper_bounds,
                initial_decision,
            );
            collocation_rows += 1;
        }
    }

    if let Some(rows) = seed.get("controls").and_then(JsonValue::as_array) {
        for row in rows {
            let interval = bike_v1_materialized_seed_index(row, "interval")?;
            if interval >= decision_layout.dimensions.interval_count {
                return Err(SolverApiError::new(
                    "solve.invalidRequest",
                    format!(
                        "materialized_full_state_control control interval {interval} is out of range"
                    ),
                ));
            }
            let offset = decision_layout.control_offset(interval);
            if let Some(value) =
                bike_v1_materialized_steering_input_torque_nm(row, steering_coordinate, params)
            {
                let index = offset + V1_CONTROL_STEERING_TORQUE_NM;
                initial_decision[index] = value.clamp(lower_bounds[index], upper_bounds[index]);
            }
            apply_bike_v1_materialized_control_value(
                row,
                "f_drive_n",
                offset + V1_CONTROL_F_DRIVE_N,
                lower_bounds,
                upper_bounds,
                initial_decision,
            );
            apply_bike_v1_materialized_control_value(
                row,
                "f_brake_n",
                offset + V1_CONTROL_F_BRAKE_N,
                lower_bounds,
                upper_bounds,
                initial_decision,
            );
            control_rows += 1;
        }
    }

    if station_rows == 0 && collocation_rows == 0 && control_rows == 0 {
        return Err(SolverApiError::new(
            "solve.invalidRequest",
            "materialized_full_state_control seed did not contain any applicable rows",
        ));
    }

    Ok(BikeV1MaterializedSeedApplyCounts {
        station_rows,
        collocation_rows,
        control_rows,
    })
}

fn bike_v1_materialized_steering_input_torque_nm(
    row: &JsonValue,
    steering_coordinate: &str,
    params: BikeCountersteerLeanParamsV1,
) -> Option<f64> {
    if let Some(value) = row
        .get("steering_input_torque_nm")
        .and_then(JsonValue::as_f64)
    {
        return value.is_finite().then_some(value);
    }
    if steering_coordinate == "normalized_torque" {
        return row
            .get("steering_control_normalized")
            .or_else(|| row.get("steering_control_raw"))
            .and_then(JsonValue::as_f64)
            .filter(|value| value.is_finite())
            .map(|value| value * params.steering_torque_max_nm.max(1.0));
    }
    row.get("steering_torque_nm")
        .and_then(JsonValue::as_f64)
        .filter(|value| value.is_finite())
}

fn bike_v1_materialized_seed_json_root(root: &JsonValue) -> Option<&JsonValue> {
    if root.get("station").is_some()
        || root.get("collocation").is_some()
        || root.get("controls").is_some()
    {
        return Some(root);
    }
    root.get("materialized_seed").or_else(|| {
        root.get("diagnostics")
            .and_then(|diagnostics| diagnostics.get("materialized_seed"))
    })
}

fn bike_v1_materialized_seed_index(row: &JsonValue, key: &str) -> Result<usize, SolverApiError> {
    let value = row.get(key).and_then(JsonValue::as_f64).ok_or_else(|| {
        SolverApiError::new(
            "solve.invalidRequest",
            format!("materialized_full_state_control row missing numeric {key}"),
        )
    })?;
    if value.is_finite() && value >= 0.0 && value.fract() == 0.0 {
        Ok(value as usize)
    } else {
        Err(SolverApiError::new(
            "solve.invalidRequest",
            format!("materialized_full_state_control row has invalid {key}: {value}"),
        ))
    }
}

fn apply_bike_v1_materialized_state_row(
    row: &JsonValue,
    offset: usize,
    lower_bounds: &[f64],
    upper_bounds: &[f64],
    initial_decision: &mut [f64],
) {
    apply_bike_v1_materialized_state_value(
        row,
        "v_mps",
        offset + V1_STATE_V_MPS,
        lower_bounds,
        upper_bounds,
        initial_decision,
    );
    apply_bike_v1_materialized_state_value(
        row,
        "beta_rad",
        offset + V1_STATE_BETA_RAD,
        lower_bounds,
        upper_bounds,
        initial_decision,
    );
    apply_bike_v1_materialized_state_value(
        row,
        "omega_z_radps",
        offset + V1_STATE_OMEGA_Z_RADPS,
        lower_bounds,
        upper_bounds,
        initial_decision,
    );
    apply_bike_v1_materialized_state_value(
        row,
        "n_m",
        offset + V1_STATE_N_M,
        lower_bounds,
        upper_bounds,
        initial_decision,
    );
    apply_bike_v1_materialized_state_value(
        row,
        "xi_rad",
        offset + V1_STATE_XI_RAD,
        lower_bounds,
        upper_bounds,
        initial_decision,
    );
    apply_bike_v1_materialized_state_value(
        row,
        "phi_rad",
        offset + V1_STATE_PHI_RAD,
        lower_bounds,
        upper_bounds,
        initial_decision,
    );
    apply_bike_v1_materialized_state_value(
        row,
        "phi_dot_radps",
        offset + V1_STATE_PHI_DOT_RADPS,
        lower_bounds,
        upper_bounds,
        initial_decision,
    );
    apply_bike_v1_materialized_state_value(
        row,
        "delta_rad",
        offset + V1_STATE_DELTA_RAD,
        lower_bounds,
        upper_bounds,
        initial_decision,
    );
    apply_bike_v1_materialized_state_value(
        row,
        "delta_dot_radps",
        offset + V1_STATE_DELTA_DOT_RADPS,
        lower_bounds,
        upper_bounds,
        initial_decision,
    );
}

fn apply_bike_v1_materialized_state_value(
    row: &JsonValue,
    key: &str,
    decision_index: usize,
    lower_bounds: &[f64],
    upper_bounds: &[f64],
    initial_decision: &mut [f64],
) {
    if let Some(value) = row
        .get(key)
        .and_then(JsonValue::as_f64)
        .filter(|value| value.is_finite())
    {
        initial_decision[decision_index] = clamp_to_bounds(
            value,
            lower_bounds[decision_index],
            upper_bounds[decision_index],
        );
    }
}

fn apply_bike_v1_materialized_control_value(
    row: &JsonValue,
    key: &str,
    decision_index: usize,
    lower_bounds: &[f64],
    upper_bounds: &[f64],
    initial_decision: &mut [f64],
) {
    if let Some(value) = row
        .get(key)
        .and_then(JsonValue::as_f64)
        .filter(|value| value.is_finite())
    {
        initial_decision[decision_index] = clamp_to_bounds(
            value,
            lower_bounds[decision_index],
            upper_bounds[decision_index],
        );
    }
}

fn bike_v1_seed_reference_from_result_json(
    root: &JsonValue,
) -> Result<BikeV1SeedReference, SolverApiError> {
    let trajectory = root.get("trajectory_result").ok_or_else(|| {
        SolverApiError::new(
            "solve.invalidRequest",
            "v1_seed_reference_path must contain trajectory_result",
        )
    })?;
    let s_m = required_json_f64_array(trajectory, "s_m")?;
    let x_m = required_json_f64_array(trajectory, "x_m")?;
    let y_m = required_json_f64_array(trajectory, "y_m")?;
    let speed_mode = bike_v1_seed_reference_speed_mode(root);
    let v_mps = if speed_mode == BikeV1SeedReferenceSpeedMode::ReferenceSpeed {
        Some(required_json_f64_array(trajectory, "v_mps")?)
    } else {
        None
    };
    let ax_mps2 = optional_json_f64_array(trajectory, "ax_mps2")?;
    let count = s_m.len();
    if count == 0
        || x_m.len() != count
        || y_m.len() != count
        || v_mps
            .as_ref()
            .is_some_and(|speed_values| speed_values.len() != count)
        || ax_mps2
            .as_ref()
            .is_some_and(|ax_values| ax_values.len() != count)
    {
        return Err(SolverApiError::new(
            "solve.invalidRequest",
            "v1_seed_reference_path trajectory_result arrays must be non-empty and equally sized",
        ));
    }
    let station_samples = bike_v1_seed_reference_station_samples(
        trajectory,
        &s_m,
        &x_m,
        &y_m,
        v_mps.as_deref(),
        ax_mps2.as_deref(),
    )?;
    Ok(BikeV1SeedReference {
        sample_count: count,
        station_samples,
        speed_mode,
    })
}

fn bike_v1_seed_reference_station_samples(
    trajectory: &JsonValue,
    s_m: &[f64],
    x_m: &[f64],
    y_m: &[f64],
    v_mps: Option<&[f64]>,
    ax_mps2: Option<&[f64]>,
) -> Result<Vec<Option<BikeV1SeedReferenceSample>>, SolverApiError> {
    let Some(station_index_values) = trajectory.get("station_index") else {
        return Err(SolverApiError::new(
            "solve.invalidRequest",
            "v1_seed_reference_path trajectory_result.station_index is required for V1 seed transfer; s_m interpolation is not allowed",
        ));
    };
    let station_index_values = station_index_values.as_array().ok_or_else(|| {
        SolverApiError::new(
            "solve.invalidRequest",
            "v1_seed_reference_path trajectory_result.station_index must be an array",
        )
    })?;
    if station_index_values.len() != x_m.len() {
        return Err(SolverApiError::new(
            "solve.invalidRequest",
            "v1_seed_reference_path trajectory_result.station_index length must match trajectory arrays",
        ));
    }

    let mut station_indices = Vec::with_capacity(station_index_values.len());
    let mut max_station = 0usize;
    for value in station_index_values {
        let Some(station) = value.as_f64() else {
            return Err(SolverApiError::new(
                "solve.invalidRequest",
                "v1_seed_reference_path trajectory_result.station_index contains a non-number",
            ));
        };
        if !station.is_finite() || station < 0.0 || station.fract() != 0.0 {
            return Err(SolverApiError::new(
                "solve.invalidRequest",
                "v1_seed_reference_path trajectory_result.station_index contains an invalid station id",
            ));
        }
        let station = station as usize;
        max_station = max_station.max(station);
        station_indices.push(station);
    }

    let mut station_samples = vec![None; max_station + 1];
    for (sample_index, station) in station_indices.into_iter().enumerate() {
        station_samples[station].get_or_insert(BikeV1SeedReferenceSample {
            x_m: x_m[sample_index],
            y_m: y_m[sample_index],
            v_mps: v_mps.map(|speed_values| speed_values[sample_index]),
            ax_mps2: ax_mps2.map(|ax_values| ax_values[sample_index]),
            source: BikeV1SeedReferenceSource::exact(sample_index, station, s_m[sample_index]),
        });
    }
    Ok(station_samples)
}

fn bike_v1_seed_reference_speed_mode(root: &JsonValue) -> BikeV1SeedReferenceSpeedMode {
    match root.get("schema_version").and_then(JsonValue::as_str) {
        Some("mintime_shortest_path_seed_reference.v1") => {
            BikeV1SeedReferenceSpeedMode::GeometryOnly
        }
        _ => BikeV1SeedReferenceSpeedMode::ReferenceSpeed,
    }
}

fn required_json_f64_array(value: &JsonValue, key: &str) -> Result<Vec<f64>, SolverApiError> {
    value
        .get(key)
        .and_then(JsonValue::as_array)
        .ok_or_else(|| {
            SolverApiError::new(
                "solve.invalidRequest",
                format!("v1_seed_reference_path trajectory_result.{key} must be an array"),
            )
        })?
        .iter()
        .map(|entry| {
            entry.as_f64().ok_or_else(|| {
                SolverApiError::new(
                    "solve.invalidRequest",
                    format!("v1_seed_reference_path trajectory_result.{key} contains a non-number"),
                )
            })
        })
        .collect()
}

fn optional_json_f64_array(
    value: &JsonValue,
    key: &str,
) -> Result<Option<Vec<f64>>, SolverApiError> {
    let Some(entry) = value.get(key) else {
        return Ok(None);
    };
    let array = entry.as_array().ok_or_else(|| {
        SolverApiError::new(
            "solve.invalidRequest",
            format!("v1_seed_reference_path trajectory_result.{key} must be an array"),
        )
    })?;
    array
        .iter()
        .map(|entry| {
            entry.as_f64().ok_or_else(|| {
                SolverApiError::new(
                    "solve.invalidRequest",
                    format!("v1_seed_reference_path trajectory_result.{key} contains a non-number"),
                )
            })
        })
        .collect::<Result<Vec<_>, _>>()
        .map(Some)
}

fn apply_bike_v1_reference_station_seed(
    geometry_seed: &BikeMintimeNlpSeed,
    params: BikeCountersteerLeanParamsV1,
    seed_state_source: BikeV1SeedStateSource,
    decision_layout: DecisionLayout,
    lower_bounds: &[f64],
    upper_bounds: &[f64],
    initial_decision: &mut [f64],
    reference: &BikeV1SeedReference,
) -> Result<BikeV1SeedTransferMetrics, SolverApiError> {
    let mut count = 0usize;
    let mut source_clamp_count = 0usize;
    let mut xy_distances_m = Vec::with_capacity(decision_layout.dimensions.station_count);
    let mut sum_sq = 0.0;
    let mut max_distance = 0.0;
    let mut worst_station = None;
    let mut worst_source_xy = None;
    let mut worst_seed_xy = None;
    for station in 0..decision_layout.dimensions.station_count {
        let sample = reference.sample_for_station(station)?;
        let n = project_xy_to_station_n(geometry_seed, station, [sample.x_m, sample.y_m]);
        let offset = decision_layout.state_offset(station);
        if let Some(speed_mps) = sample.v_mps {
            bike_v1_write_speed_curvature_seed_state(
                params,
                geometry_seed.kappa_1pm[station],
                speed_mps,
                &mut initial_decision[offset..],
            );
        } else {
            bike_v1_write_curvature_seed_state(
                params,
                geometry_seed.kappa_1pm[station],
                &mut initial_decision[offset..],
            );
        }
        let n_clamped = clamp_to_bounds(
            n,
            lower_bounds[offset + V1_STATE_N_M],
            upper_bounds[offset + V1_STATE_N_M],
        );
        initial_decision[offset + V1_STATE_N_M] = n_clamped;
        let seed_xy = station_xy_from_n(geometry_seed, station, n_clamped);
        let dx = seed_xy[0] - sample.x_m;
        let dy = seed_xy[1] - sample.y_m;
        let distance = (dx * dx + dy * dy).sqrt();
        if (n_clamped - n).abs() > BIKE_V1_SEED_TRANSFER_CLAMP_DISTANCE_TOL_M
            || distance > BIKE_V1_SEED_TRANSFER_CLAMP_DISTANCE_TOL_M
        {
            source_clamp_count += 1;
        }
        xy_distances_m.push(distance);
        sum_sq += distance * distance;
        if distance > max_distance {
            max_distance = distance;
            worst_station = Some(station);
            worst_source_xy = Some([sample.x_m, sample.y_m]);
            worst_seed_xy = Some(seed_xy);
        }
        count += 1;
    }
    let rms = if count > 0 {
        (sum_sq / count as f64).sqrt()
    } else {
        0.0
    };
    let p95 = percentile_nearest(&mut xy_distances_m, 0.95).unwrap_or(0.0);
    let metrics = BikeV1SeedTransferMetrics {
        station_count: count,
        missing_station_count: 0,
        source_clamp_count,
        source_to_seed_xy_rms_m: rms,
        source_to_seed_xy_p95_m: p95,
        source_to_seed_xy_max_m: max_distance,
        worst_station,
        worst_source_x_m: worst_source_xy.map(|xy| xy[0]),
        worst_source_y_m: worst_source_xy.map(|xy| xy[1]),
        worst_seed_x_m: worst_seed_xy.map(|xy| xy[0]),
        worst_seed_y_m: worst_seed_xy.map(|xy| xy[1]),
    };
    metrics.validate()?;
    if seed_state_source.uses_seed_path_geometry() {
        rewrite_bike_v1_station_seed_states_from_seed_path(
            geometry_seed,
            params,
            seed_state_source,
            decision_layout,
            initial_decision,
        );
    }
    Ok(metrics)
}

fn project_xy_to_station_n(geometry_seed: &BikeMintimeNlpSeed, station: usize, xy: Point2) -> f64 {
    let center = geometry_seed.centerline_xy_m[station];
    let section_dir = geometry_seed.section_dir_xy[station];
    (center[0] - xy[0]) * section_dir[0] + (center[1] - xy[1]) * section_dir[1]
}

fn station_xy_from_n(geometry_seed: &BikeMintimeNlpSeed, station: usize, n_m: f64) -> Point2 {
    let center = geometry_seed.centerline_xy_m[station];
    let section_dir = geometry_seed.section_dir_xy[station];
    [
        center[0] - n_m * section_dir[0],
        center[1] - n_m * section_dir[1],
    ]
}

fn percentile_nearest(values: &mut [f64], percentile: f64) -> Option<f64> {
    if values.is_empty() {
        return None;
    }
    values.sort_by(|left, right| left.total_cmp(right));
    let percentile = percentile.clamp(0.0, 1.0);
    let index = ((values.len() - 1) as f64 * percentile).round() as usize;
    values.get(index).copied()
}

fn apply_bike_v1_late_apex_seed_zone(
    geometry_seed: &BikeMintimeNlpSeed,
    decision_layout: DecisionLayout,
    lower_bounds: &[f64],
    upper_bounds: &[f64],
    initial_decision: &mut [f64],
    start_station: usize,
    end_station: usize,
    side: BikeV1ApexSide,
) -> usize {
    if start_station > end_station {
        return 0;
    }
    let station_count = decision_layout.dimensions.station_count;
    let mut count = 0usize;
    let span = (end_station - start_station).max(1) as f64;
    for station in start_station..=end_station {
        if station >= station_count {
            continue;
        }
        let tau = (station - start_station) as f64 / span;
        let boundary_fraction = if tau < 0.55 {
            0.18 + 0.12 * (tau / 0.55)
        } else {
            0.30 + 0.35 * ((tau - 0.55) / 0.45)
        };
        let target_n = match side {
            BikeV1ApexSide::Left => geometry_seed.width_left_m[station] * boundary_fraction,
            BikeV1ApexSide::Right => -geometry_seed.width_right_m[station] * boundary_fraction,
        };
        let offset = decision_layout.state_offset(station) + V1_STATE_N_M;
        initial_decision[offset] =
            clamp_to_bounds(target_n, lower_bounds[offset], upper_bounds[offset]);
        count += 1;
    }
    count
}

fn patch_bike_v1_collocation_seed_from_station_values(
    geometry_seed: &BikeMintimeNlpSeed,
    params: BikeCountersteerLeanParamsV1,
    seed_state_source: BikeV1SeedStateSource,
    decision_layout: DecisionLayout,
    collocation_kappa_1pm: &[Vec<f64>],
    lower_bounds: &[f64],
    upper_bounds: &[f64],
    initial_decision: &mut [f64],
) -> usize {
    let mut count = 0usize;
    let seed_path_geometry = seed_state_source.uses_seed_path_geometry().then(|| {
        bike_v1_seed_path_geometry_from_decision(geometry_seed, decision_layout, initial_decision)
    });
    for interval in 0..decision_layout.dimensions.interval_count {
        let next = next_station_index(decision_layout.dimensions.station_count, interval);
        let left_state_offset = decision_layout.state_offset(interval);
        let right_state_offset = decision_layout.state_offset(next);
        let n_left = initial_decision[left_state_offset + V1_STATE_N_M];
        let n_right = initial_decision[right_state_offset + V1_STATE_N_M];
        let v_left = initial_decision[left_state_offset + V1_STATE_V_MPS];
        let v_right = initial_decision[right_state_offset + V1_STATE_V_MPS];
        for point in 0..decision_layout.collocation_degree {
            let tau = bike_legendre_collocation_tau_degree3(point + 1);
            let offset = decision_layout.collocation_state_offset(interval, point);
            let speed = lerp(v_left, v_right, tau);
            let n = lerp(n_left, n_right, tau);
            initial_decision[offset + V1_STATE_N_M] = clamp_to_bounds(
                n,
                lower_bounds[offset + V1_STATE_N_M],
                upper_bounds[offset + V1_STATE_N_M],
            );
            let (yaw_kappa, lean_kappa, xi) =
                if let Some(seed_path_geometry) = seed_path_geometry.as_ref() {
                    let yaw_kappa = bike_v1_seed_state_yaw_kappa_at(
                        seed_state_source,
                        seed_path_geometry,
                        interval,
                        next,
                        tau,
                    );
                    let lean_kappa = bike_v1_seed_state_lean_kappa_at(
                        seed_state_source,
                        seed_path_geometry,
                        collocation_kappa_1pm[interval][point],
                        interval,
                        next,
                        tau,
                    );
                    let seed_heading = lerp_angle_rad(
                        seed_path_geometry
                            .heading_rad
                            .get(interval)
                            .copied()
                            .unwrap_or(0.0),
                        seed_path_geometry
                            .heading_rad
                            .get(next)
                            .copied()
                            .unwrap_or(0.0),
                        tau,
                    );
                    let ref_heading = lerp_angle_rad(
                        path_heading_rad(
                            &geometry_seed.centerline_xy_m,
                            interval,
                            seed_is_closed(geometry_seed),
                        ),
                        path_heading_rad(
                            &geometry_seed.centerline_xy_m,
                            next,
                            seed_is_closed(geometry_seed),
                        ),
                        tau,
                    );
                    (
                        yaw_kappa,
                        lean_kappa,
                        normalize_angle_rad(seed_heading - ref_heading),
                    )
                } else {
                    (
                        collocation_kappa_1pm[interval][point],
                        collocation_kappa_1pm[interval][point],
                        0.0,
                    )
                };
            let yaw_kappa = bike_v1_cap_seed_kappa_for_speed(params, yaw_kappa, speed);
            let lean_kappa = bike_v1_cap_seed_kappa_for_speed(params, lean_kappa, speed);
            bike_v1_write_split_curvature_seed_state_with_xi(
                params,
                yaw_kappa,
                lean_kappa,
                speed,
                xi,
                &mut initial_decision[offset..],
            );
            count += 1;
        }
    }
    count
}

fn bike_v1_write_curvature_seed_state(
    params: BikeCountersteerLeanParamsV1,
    kappa_1pm: f64,
    state: &mut [f64],
) {
    let base_speed = 20.0_f64.clamp(1.0, params.base.max_speed_mps);
    let ay_seed_limit = (0.45 * params.base.lean_limited_lateral_accel_mps2()).max(1.0);
    let speed = if kappa_1pm.abs() > 1.0e-6 {
        base_speed.min((ay_seed_limit / kappa_1pm.abs()).sqrt())
    } else {
        base_speed
    }
    .clamp(1.0, params.base.max_speed_mps);
    bike_v1_write_speed_curvature_seed_state(params, kappa_1pm, speed, state);
}

fn bike_v1_write_speed_curvature_seed_state(
    params: BikeCountersteerLeanParamsV1,
    kappa_1pm: f64,
    speed_mps: f64,
    state: &mut [f64],
) {
    bike_v1_write_speed_curvature_seed_state_with_xi(params, kappa_1pm, speed_mps, 0.0, state);
}

fn bike_v1_write_speed_curvature_seed_state_with_xi(
    params: BikeCountersteerLeanParamsV1,
    kappa_1pm: f64,
    speed_mps: f64,
    xi_rad: f64,
    state: &mut [f64],
) {
    bike_v1_write_split_curvature_seed_state_with_xi(
        params, kappa_1pm, kappa_1pm, speed_mps, xi_rad, state,
    );
}

fn bike_v1_write_split_curvature_seed_state_with_xi(
    params: BikeCountersteerLeanParamsV1,
    yaw_kappa_1pm: f64,
    lean_kappa_1pm: f64,
    speed_mps: f64,
    xi_rad: f64,
    state: &mut [f64],
) {
    let speed = speed_mps.clamp(1.0, params.base.max_speed_mps);
    state[V1_STATE_V_MPS] = speed;
    state[V1_STATE_BETA_RAD] = 0.0;
    state[V1_STATE_OMEGA_Z_RADPS] = speed * yaw_kappa_1pm;
    state[V1_STATE_XI_RAD] = normalize_angle_rad(xi_rad);
    state[V1_STATE_PHI_RAD] = bike_v1_seed_phi_from_kappa(params, lean_kappa_1pm, speed);
    state[V1_STATE_PHI_DOT_RADPS] = 0.0;
    state[V1_STATE_DELTA_RAD] = bike_v1_seed_delta_from_kappa(params, lean_kappa_1pm);
    state[V1_STATE_DELTA_DOT_RADPS] = 0.0;
}

fn bike_v1_cap_seed_kappa_for_speed(
    params: BikeCountersteerLeanParamsV1,
    kappa_1pm: f64,
    speed_mps: f64,
) -> f64 {
    let speed_sq = speed_mps.abs().max(1.0).powi(2);
    let lean_seed_ay_cap =
        params.base.gravity_mps2 * (0.7 * params.base.lean_angle_max_rad.max(1e-6)).tan();
    let lateral_seed_ay_cap = params.base.gravity_mps2 * params.base.lateral_grip_level.max(1e-6);
    let ay_cap = lean_seed_ay_cap.min(lateral_seed_ay_cap).max(1e-6);
    let kappa_cap = ay_cap / speed_sq;
    kappa_1pm.clamp(-kappa_cap, kappa_cap)
}

fn rewrite_bike_v1_station_seed_states_from_seed_path(
    geometry_seed: &BikeMintimeNlpSeed,
    params: BikeCountersteerLeanParamsV1,
    seed_state_source: BikeV1SeedStateSource,
    decision_layout: DecisionLayout,
    initial_decision: &mut [f64],
) {
    let seed_path_geometry =
        bike_v1_seed_path_geometry_from_decision(geometry_seed, decision_layout, initial_decision);
    let closed = seed_is_closed(geometry_seed);
    for station in 0..decision_layout.dimensions.station_count {
        let offset = decision_layout.state_offset(station);
        let speed = initial_decision[offset + V1_STATE_V_MPS];
        let reference_kappa = geometry_seed.kappa_1pm.get(station).copied().unwrap_or(0.0);
        let yaw_kappa =
            bike_v1_seed_state_yaw_kappa_station(seed_state_source, &seed_path_geometry, station);
        let lean_kappa = bike_v1_seed_state_lean_kappa_station(
            seed_state_source,
            &seed_path_geometry,
            reference_kappa,
            station,
        );
        let yaw_kappa = bike_v1_cap_seed_kappa_for_speed(params, yaw_kappa, speed);
        let lean_kappa = bike_v1_cap_seed_kappa_for_speed(params, lean_kappa, speed);
        let seed_heading = seed_path_geometry
            .heading_rad
            .get(station)
            .copied()
            .unwrap_or(0.0);
        let reference_heading = path_heading_rad(&geometry_seed.centerline_xy_m, station, closed);
        bike_v1_write_split_curvature_seed_state_with_xi(
            params,
            yaw_kappa,
            lean_kappa,
            speed,
            normalize_angle_rad(seed_heading - reference_heading),
            &mut initial_decision[offset..],
        );
    }
}

fn bike_v1_seed_state_yaw_kappa_station(
    seed_state_source: BikeV1SeedStateSource,
    seed_path_geometry: &BikeV1SeedPathGeometry,
    station: usize,
) -> f64 {
    match seed_state_source {
        BikeV1SeedStateSource::SmoothedSeedPathCurvature => {
            smoothed_seed_path_kappa_station(seed_path_geometry, station)
        }
        BikeV1SeedStateSource::PreviewCurvature => {
            preview_seed_path_kappa_station(seed_path_geometry, station)
        }
        BikeV1SeedStateSource::ReferenceCurvature
        | BikeV1SeedStateSource::SeedPathCurvature
        | BikeV1SeedStateSource::SeedPathYawReferenceLean => seed_path_geometry
            .kappa_1pm
            .get(station)
            .copied()
            .unwrap_or(0.0),
    }
}

fn bike_v1_seed_state_lean_kappa_station(
    seed_state_source: BikeV1SeedStateSource,
    seed_path_geometry: &BikeV1SeedPathGeometry,
    reference_kappa_1pm: f64,
    station: usize,
) -> f64 {
    match seed_state_source {
        BikeV1SeedStateSource::SeedPathYawReferenceLean => reference_kappa_1pm,
        BikeV1SeedStateSource::SmoothedSeedPathCurvature => {
            smoothed_seed_path_kappa_station(seed_path_geometry, station)
        }
        BikeV1SeedStateSource::PreviewCurvature => {
            preview_seed_path_kappa_station(seed_path_geometry, station)
        }
        BikeV1SeedStateSource::ReferenceCurvature | BikeV1SeedStateSource::SeedPathCurvature => {
            seed_path_geometry
                .kappa_1pm
                .get(station)
                .copied()
                .unwrap_or(0.0)
        }
    }
}

fn bike_v1_seed_state_yaw_kappa_at(
    seed_state_source: BikeV1SeedStateSource,
    seed_path_geometry: &BikeV1SeedPathGeometry,
    left: usize,
    right: usize,
    tau: f64,
) -> f64 {
    lerp(
        bike_v1_seed_state_yaw_kappa_station(seed_state_source, seed_path_geometry, left),
        bike_v1_seed_state_yaw_kappa_station(seed_state_source, seed_path_geometry, right),
        tau,
    )
}

fn bike_v1_seed_state_lean_kappa_at(
    seed_state_source: BikeV1SeedStateSource,
    seed_path_geometry: &BikeV1SeedPathGeometry,
    reference_kappa_1pm: f64,
    left: usize,
    right: usize,
    tau: f64,
) -> f64 {
    let left_kappa = bike_v1_seed_state_lean_kappa_station(
        seed_state_source,
        seed_path_geometry,
        reference_kappa_1pm,
        left,
    );
    let right_kappa = bike_v1_seed_state_lean_kappa_station(
        seed_state_source,
        seed_path_geometry,
        reference_kappa_1pm,
        right,
    );
    lerp(left_kappa, right_kappa, tau)
}

fn smoothed_seed_path_kappa_station(
    seed_path_geometry: &BikeV1SeedPathGeometry,
    station: usize,
) -> f64 {
    let values = &seed_path_geometry.kappa_1pm;
    if values.len() < 3 {
        return values.get(station).copied().unwrap_or(0.0);
    }
    let count = values.len();
    let left = values[(station + count - 1) % count];
    let center = values[station.min(count - 1)];
    let right = values[(station + 1) % count];
    0.25 * left + 0.5 * center + 0.25 * right
}

fn preview_seed_path_kappa_station(
    seed_path_geometry: &BikeV1SeedPathGeometry,
    station: usize,
) -> f64 {
    let values = &seed_path_geometry.kappa_1pm;
    if values.is_empty() {
        return 0.0;
    }
    let local = values[station.min(values.len() - 1)];
    let preview = values[(station + 1) % values.len()];
    0.5 * local + 0.5 * preview
}

fn bike_v1_seed_path_geometry_from_decision(
    geometry_seed: &BikeMintimeNlpSeed,
    decision_layout: DecisionLayout,
    x: &[f64],
) -> BikeV1SeedPathGeometry {
    let closed = seed_is_closed(geometry_seed);
    let station_points = (0..decision_layout.dimensions.station_count)
        .map(|station| bike_v1_station_xy_from(geometry_seed, decision_layout, x, station))
        .collect::<Vec<_>>();
    let kappa_1pm = python_compatible_closed_kappa_1pm(&station_points, &geometry_seed.station_s_m);
    let heading_rad = (0..decision_layout.dimensions.station_count)
        .map(|station| path_heading_rad(&station_points, station, closed))
        .collect::<Vec<_>>();
    BikeV1SeedPathGeometry {
        kappa_1pm,
        heading_rad,
    }
}

fn bike_v1_seed_phi_from_kappa(
    params: BikeCountersteerLeanParamsV1,
    kappa_1pm: f64,
    speed_mps: f64,
) -> f64 {
    let ay_seed = speed_mps * speed_mps * kappa_1pm;
    (ay_seed / params.base.gravity_mps2.max(1e-9)).atan().clamp(
        -0.7 * params.base.lean_angle_max_rad,
        0.7 * params.base.lean_angle_max_rad,
    )
}

fn bike_v1_seed_delta_from_kappa(params: BikeCountersteerLeanParamsV1, kappa_1pm: f64) -> f64 {
    (params.base.wheelbase_m * kappa_1pm).atan().clamp(
        -0.7 * params.base.steering_angle_max_rad,
        0.7 * params.base.steering_angle_max_rad,
    )
}

fn bike_v1_materialized_seed_diagnostics_json(
    geometry_seed: &BikeMintimeNlpSeed,
    params: BikeCountersteerLeanParamsV1,
    steering_actuator_mode: BikeV1SteeringActuatorMode,
    seed_state_source: BikeV1SeedStateSource,
    seed_control_source: BikeV1SeedControlSource,
    decision_layout: DecisionLayout,
    x: &[f64],
    collocation_kappa_1pm: &[Vec<f64>],
    station_reference_samples: &[Option<BikeV1SeedReferenceSample>],
) -> JsonValue {
    let closed = seed_is_closed(geometry_seed);
    let station_points = (0..decision_layout.dimensions.station_count)
        .map(|station| bike_v1_station_xy_from(geometry_seed, decision_layout, x, station))
        .collect::<Vec<_>>();
    let seed_path_kappa_1pm =
        python_compatible_closed_kappa_1pm(&station_points, &geometry_seed.station_s_m);
    let station_rows = (0..decision_layout.dimensions.station_count)
        .map(|station| {
            bike_v1_materialized_seed_station_json(
                geometry_seed,
                params,
                decision_layout,
                x,
                station,
                seed_state_source,
                station_reference_samples.get(station).copied().flatten(),
                station_points[station],
                path_heading_rad(&station_points, station, closed),
                seed_path_kappa_1pm.get(station).copied().unwrap_or(0.0),
            )
        })
        .collect::<Vec<_>>();
    let mut collocation_rows = Vec::new();
    for interval in 0..decision_layout.dimensions.interval_count {
        for point in 0..decision_layout.collocation_degree {
            collocation_rows.push(bike_v1_materialized_seed_collocation_json(
                geometry_seed,
                params,
                decision_layout,
                x,
                interval,
                point,
                seed_state_source,
                collocation_kappa_1pm,
                &seed_path_kappa_1pm,
            ));
        }
    }
    let control_rows = (0..decision_layout.dimensions.interval_count)
        .map(|interval| {
            bike_v1_materialized_seed_control_json(
                params,
                steering_actuator_mode,
                decision_layout,
                seed_control_source,
                x,
                interval,
                station_reference_samples.get(interval).copied().flatten(),
            )
        })
        .collect::<Vec<_>>();
    let source_clamp_count = station_reference_samples
        .iter()
        .filter_map(|sample| sample.as_ref())
        .filter(|sample| sample.source.source_was_clamped)
        .count();

    JsonValue::Object(vec![
        (
            "schema_version".to_owned(),
            "bike_v1_materialized_seed_diagnostics.v2".into(),
        ),
        (
            "steering_coordinate".to_owned(),
            steering_actuator_mode.steering_coordinate().into(),
        ),
        (
            "note".to_owned(),
            "Actual materialized V1 seed after reference load/projection/bounds/station write/collocation patch; this replaces invalid post-hoc phase reconstruction as evidence.".into(),
        ),
        (
            "state_source_mode".to_owned(),
            seed_state_source.as_str().into(),
        ),
        (
            "control_source_mode".to_owned(),
            seed_control_source.as_str().into(),
        ),
        (
            "collocation_source_mode".to_owned(),
            seed_state_source.collocation_source_mode().into(),
        ),
        (
            "source_clamp_count".to_owned(),
            JsonValue::Integer(source_clamp_count as i64),
        ),
        ("station".to_owned(), JsonValue::Array(station_rows)),
        ("collocation".to_owned(), JsonValue::Array(collocation_rows)),
        ("controls".to_owned(), JsonValue::Array(control_rows)),
    ])
}

fn bike_v1_materialized_seed_station_json(
    geometry_seed: &BikeMintimeNlpSeed,
    params: BikeCountersteerLeanParamsV1,
    decision_layout: DecisionLayout,
    x: &[f64],
    station: usize,
    seed_state_source: BikeV1SeedStateSource,
    source_sample: Option<BikeV1SeedReferenceSample>,
    xy_seed: Point2,
    heading_seed_path_rad: f64,
    kappa_seed_path_1pm: f64,
) -> JsonValue {
    let offset = decision_layout.state_offset(station);
    let state = bike_v1_state_from_decision(decision_layout, x, station);
    let kappa_ref_1pm = geometry_seed.kappa_1pm[station];
    let phi_ref = bike_v1_seed_phi_from_kappa(params, kappa_ref_1pm, state.v_mps);
    let phi_seed = bike_v1_seed_phi_from_kappa(params, kappa_seed_path_1pm, state.v_mps);
    let delta_ref = bike_v1_seed_delta_from_kappa(params, kappa_ref_1pm);
    let delta_seed = bike_v1_seed_delta_from_kappa(params, kappa_seed_path_1pm);
    let reference_heading = path_heading_rad(
        &geometry_seed.centerline_xy_m,
        station,
        seed_is_closed(geometry_seed),
    );
    JsonValue::Object(vec![
        (
            "station_index".to_owned(),
            JsonValue::Integer(station as i64),
        ),
        (
            "target_s_m".to_owned(),
            json_number(geometry_seed.station_s_m[station]),
        ),
        ("source".to_owned(), bike_v1_seed_source_json(source_sample)),
        ("x_seed_m".to_owned(), json_number(xy_seed[0])),
        ("y_seed_m".to_owned(), json_number(xy_seed[1])),
        ("n_m".to_owned(), json_number(state.n_m)),
        ("v_mps".to_owned(), json_number(state.v_mps)),
        ("beta_rad".to_owned(), json_number(state.beta_rad)),
        ("omega_z_radps".to_owned(), json_number(state.omega_z_radps)),
        ("xi_rad".to_owned(), json_number(state.xi_rad)),
        ("phi_rad".to_owned(), json_number(state.phi_rad)),
        ("phi_dot_radps".to_owned(), json_number(state.phi_dot_radps)),
        ("delta_rad".to_owned(), json_number(state.delta_rad)),
        (
            "delta_dot_radps".to_owned(),
            json_number(state.delta_dot_radps),
        ),
        ("kappa_ref_1pm".to_owned(), json_number(kappa_ref_1pm)),
        (
            "kappa_seed_path_1pm".to_owned(),
            json_number(kappa_seed_path_1pm),
        ),
        (
            "heading_seed_path_rad".to_owned(),
            json_number(heading_seed_path_rad),
        ),
        ("heading_ref_rad".to_owned(), json_number(reference_heading)),
        ("phi_from_ref_kappa_rad".to_owned(), json_number(phi_ref)),
        ("phi_from_seed_kappa_rad".to_owned(), json_number(phi_seed)),
        (
            "phi_seed_minus_ref_rad".to_owned(),
            json_number(phi_seed - phi_ref),
        ),
        (
            "delta_from_ref_kappa_rad".to_owned(),
            json_number(delta_ref),
        ),
        (
            "delta_from_seed_kappa_rad".to_owned(),
            json_number(delta_seed),
        ),
        (
            "delta_seed_minus_ref_rad".to_owned(),
            json_number(delta_seed - delta_ref),
        ),
        (
            "omega_from_ref_kappa_radps".to_owned(),
            json_number(state.v_mps * kappa_ref_1pm),
        ),
        (
            "omega_from_seed_kappa_radps".to_owned(),
            json_number(state.v_mps * kappa_seed_path_1pm),
        ),
        (
            "xi_from_seed_heading_rad".to_owned(),
            json_number(normalize_angle_rad(
                heading_seed_path_rad - reference_heading - state.beta_rad,
            )),
        ),
        (
            "state_vector_offset".to_owned(),
            JsonValue::Integer(offset as i64),
        ),
        (
            "state_source_mode".to_owned(),
            seed_state_source.as_str().into(),
        ),
    ])
}

fn bike_v1_materialized_seed_collocation_json(
    geometry_seed: &BikeMintimeNlpSeed,
    params: BikeCountersteerLeanParamsV1,
    decision_layout: DecisionLayout,
    x: &[f64],
    interval: usize,
    point: usize,
    seed_state_source: BikeV1SeedStateSource,
    collocation_kappa_1pm: &[Vec<f64>],
    seed_path_kappa_1pm: &[f64],
) -> JsonValue {
    let tau = bike_legendre_collocation_tau_degree3(point + 1);
    let offset = decision_layout.collocation_state_offset(interval, point);
    let state = crate::bike_mintime_v1::bike_v1_state_from_slice(
        &x[offset..offset + decision_layout.state_len],
    );
    let next = next_station_index(decision_layout.dimensions.station_count, interval);
    let center = lerp_point(
        geometry_seed.centerline_xy_m[interval],
        geometry_seed.centerline_xy_m[next],
        tau,
    );
    let section_dir = lerp_point(
        geometry_seed.section_dir_xy[interval],
        geometry_seed.section_dir_xy[next],
        tau,
    );
    let xy_seed = [
        center[0] - section_dir[0] * state.n_m,
        center[1] - section_dir[1] * state.n_m,
    ];
    let kappa_ref_1pm = collocation_kappa_1pm[interval][point];
    let kappa_seed_path = lerp(
        seed_path_kappa_1pm.get(interval).copied().unwrap_or(0.0),
        seed_path_kappa_1pm.get(next).copied().unwrap_or(0.0),
        tau,
    );
    JsonValue::Object(vec![
        ("interval".to_owned(), JsonValue::Integer(interval as i64)),
        ("point".to_owned(), JsonValue::Integer(point as i64)),
        ("tau".to_owned(), json_number(tau)),
        (
            "target_s_m".to_owned(),
            json_number(lerp(
                geometry_seed.station_s_m[interval],
                geometry_seed.station_s_m[next],
                tau,
            )),
        ),
        ("x_seed_m".to_owned(), json_number(xy_seed[0])),
        ("y_seed_m".to_owned(), json_number(xy_seed[1])),
        ("n_m".to_owned(), json_number(state.n_m)),
        ("v_mps".to_owned(), json_number(state.v_mps)),
        ("beta_rad".to_owned(), json_number(state.beta_rad)),
        ("omega_z_radps".to_owned(), json_number(state.omega_z_radps)),
        ("xi_rad".to_owned(), json_number(state.xi_rad)),
        ("phi_rad".to_owned(), json_number(state.phi_rad)),
        ("phi_dot_radps".to_owned(), json_number(state.phi_dot_radps)),
        ("delta_rad".to_owned(), json_number(state.delta_rad)),
        (
            "delta_dot_radps".to_owned(),
            json_number(state.delta_dot_radps),
        ),
        ("kappa_ref_1pm".to_owned(), json_number(kappa_ref_1pm)),
        (
            "kappa_seed_path_1pm".to_owned(),
            json_number(kappa_seed_path),
        ),
        (
            "phi_from_ref_kappa_rad".to_owned(),
            json_number(bike_v1_seed_phi_from_kappa(
                params,
                kappa_ref_1pm,
                state.v_mps,
            )),
        ),
        (
            "phi_from_seed_kappa_rad".to_owned(),
            json_number(bike_v1_seed_phi_from_kappa(
                params,
                kappa_seed_path,
                state.v_mps,
            )),
        ),
        (
            "delta_from_ref_kappa_rad".to_owned(),
            json_number(bike_v1_seed_delta_from_kappa(params, kappa_ref_1pm)),
        ),
        (
            "delta_from_seed_kappa_rad".to_owned(),
            json_number(bike_v1_seed_delta_from_kappa(params, kappa_seed_path)),
        ),
        (
            "state_vector_offset".to_owned(),
            JsonValue::Integer(offset as i64),
        ),
        (
            "collocation_source_mode".to_owned(),
            seed_state_source.collocation_source_mode().into(),
        ),
    ])
}

fn bike_v1_materialized_seed_control_json(
    params: BikeCountersteerLeanParamsV1,
    steering_actuator_mode: BikeV1SteeringActuatorMode,
    decision_layout: DecisionLayout,
    seed_control_source: BikeV1SeedControlSource,
    x: &[f64],
    interval: usize,
    source_sample: Option<BikeV1SeedReferenceSample>,
) -> JsonValue {
    let offset = decision_layout.control_offset(interval);
    let control = bike_v1_control_from_decision(decision_layout, x, interval);
    let raw_control = control.steering_torque_nm;
    let normalized_control = steering_actuator_mode.normalized_control(params, raw_control);
    let physical_input_torque =
        steering_actuator_mode.physical_input_torque_nm(params, raw_control);
    JsonValue::Object(vec![
        ("interval".to_owned(), JsonValue::Integer(interval as i64)),
        (
            "steering_torque_nm".to_owned(),
            physical_input_torque
                .map(json_number)
                .unwrap_or(JsonValue::Null),
        ),
        ("steering_control_raw".to_owned(), json_number(raw_control)),
        (
            "steering_control_normalized".to_owned(),
            json_number(normalized_control),
        ),
        (
            "steering_input_torque_nm".to_owned(),
            physical_input_torque
                .map(json_number)
                .unwrap_or(JsonValue::Null),
        ),
        ("f_drive_n".to_owned(), json_number(control.f_drive_n)),
        ("f_brake_n".to_owned(), json_number(control.f_brake_n)),
        (
            "source_ax_mps2".to_owned(),
            json_option_f64(source_sample.and_then(|sample| sample.ax_mps2)),
        ),
        (
            "control_vector_offset".to_owned(),
            JsonValue::Integer(offset as i64),
        ),
        (
            "control_source_mode".to_owned(),
            seed_control_source.as_str().into(),
        ),
    ])
}

fn bike_v1_seed_source_json(sample: Option<BikeV1SeedReferenceSample>) -> JsonValue {
    let Some(sample) = sample else {
        return JsonValue::Object(vec![
            ("available".to_owned(), JsonValue::Bool(false)),
            ("source_was_clamped".to_owned(), JsonValue::Bool(false)),
        ]);
    };
    JsonValue::Object(vec![
        ("available".to_owned(), JsonValue::Bool(true)),
        ("source_x_m".to_owned(), json_number(sample.x_m)),
        ("source_y_m".to_owned(), json_number(sample.y_m)),
        ("source_v_mps".to_owned(), json_option_f64(sample.v_mps)),
        ("source_ax_mps2".to_owned(), json_option_f64(sample.ax_mps2)),
        (
            "source_index".to_owned(),
            json_option_usize(sample.source.source_index),
        ),
        (
            "source_station_index".to_owned(),
            json_option_usize(sample.source.source_station_index),
        ),
        (
            "source_s_m".to_owned(),
            json_option_f64(sample.source.source_s_m),
        ),
        (
            "source_tau".to_owned(),
            json_option_f64(sample.source.source_tau),
        ),
        (
            "source_was_clamped".to_owned(),
            JsonValue::Bool(sample.source.source_was_clamped),
        ),
        (
            "phase_advance_distance_m".to_owned(),
            json_option_f64(sample.source.phase_advance_distance_m),
        ),
    ])
}

fn clamp_to_bounds(value: f64, lower: f64, upper: f64) -> f64 {
    value.clamp(lower, upper)
}

fn bike_v1_collocation_kappa_samples(
    geometry_seed: &BikeMintimeNlpSeed,
    decision_layout: DecisionLayout,
) -> Vec<Vec<f64>> {
    (0..decision_layout.dimensions.interval_count)
        .map(|interval| {
            (0..decision_layout.collocation_degree)
                .map(|point| {
                    let tau = bike_legendre_collocation_tau_degree3(point + 1);
                    interpolated_sections_geometry(geometry_seed, interval, tau).kappa_1pm
                })
                .collect()
        })
        .collect()
}

fn bike_v1_experimental_constraint_rows(
    decision_layout: DecisionLayout,
    options: &BikeMintimeSolveOptions,
) -> Vec<BikeV1ExperimentalConstraintRow> {
    let mut rows = generic_mintime_constraint_rows(
        decision_layout,
        GenericConstraintRowOptions::with_control_rate(),
    )
    .into_iter()
    .map(BikeV1ExperimentalConstraintRow::Generic)
    .collect::<Vec<_>>();

    for interval in 0..decision_layout.dimensions.interval_count {
        let interval_start_sample = BikeV1ExperimentalSample::IntervalStart { interval };
        bike_v1_push_physical_sample_rows(&mut rows, interval_start_sample);
        let station_sample = BikeV1ExperimentalSample::Station { interval };
        bike_v1_push_physical_sample_rows(&mut rows, station_sample);
        for point in 0..decision_layout.collocation_degree {
            let collocation_sample = BikeV1ExperimentalSample::Collocation { interval, point };
            bike_v1_push_physical_sample_rows(&mut rows, collocation_sample);
        }
        for guard_index in 0..BIKE_V1_TAU_GUARD_VALUES.len() {
            let guard_sample = BikeV1ExperimentalSample::TauGuard {
                interval,
                guard_index,
            };
            bike_v1_push_physical_sample_rows(&mut rows, guard_sample);
        }
        rows.push(BikeV1ExperimentalConstraintRow::DriveBrakeMutex { interval });
        rows.push(BikeV1ExperimentalConstraintRow::SteeringTorque { interval });
        if options.debug_v1_control_lowfreq_mode.is_enabled()
            && options.debug_v1_control_lowfreq_block_size > 1
        {
            let anchor_interval = bike_v1_lowfreq_anchor_interval(
                interval,
                options.debug_v1_control_lowfreq_block_size,
            );
            if anchor_interval != interval {
                for control_index in 0..decision_layout.control_len {
                    if options
                        .debug_v1_control_lowfreq_mode
                        .includes_control(control_index)
                    {
                        rows.push(BikeV1ExperimentalConstraintRow::ControlLowFrequency {
                            interval,
                            anchor_interval,
                            control_index,
                        });
                    }
                }
            }
        }
    }

    rows
}

fn bike_v1_lowfreq_anchor_interval(interval: usize, block_size: usize) -> usize {
    if block_size <= 1 {
        interval
    } else {
        interval - interval % block_size
    }
}

fn bike_v1_push_physical_sample_rows(
    rows: &mut Vec<BikeV1ExperimentalConstraintRow>,
    sample: BikeV1ExperimentalSample,
) {
    rows.push(BikeV1ExperimentalConstraintRow::SectionMapJacobian { sample });
    rows.push(BikeV1ExperimentalConstraintRow::SectionForwardProgress { sample });
    for axle in ["front", "rear"] {
        rows.push(BikeV1ExperimentalConstraintRow::NormalLoad { sample, axle });
        rows.push(BikeV1ExperimentalConstraintRow::Kamm { sample, axle });
        rows.push(BikeV1ExperimentalConstraintRow::SlipAngle { sample, axle });
    }
    rows.push(BikeV1ExperimentalConstraintRow::PowerLimit { sample });
}

fn bike_v1_experimental_sparse_pattern(
    decision_layout: DecisionLayout,
    rows: &[BikeV1ExperimentalConstraintRow],
    steering_basis_mode: BikeV1SteeringBasisMode,
    steering_basis_stride: usize,
    steering_actuator_mode: BikeV1SteeringActuatorMode,
    omit_tau_guard_next_station_columns: bool,
) -> Vec<(usize, usize)> {
    let generic_rows = rows
        .iter()
        .filter_map(|row| match row {
            BikeV1ExperimentalConstraintRow::Generic(row) => Some(*row),
            _ => None,
        })
        .collect::<Vec<_>>();
    let mut pattern = generic_mintime_sparse_pattern(decision_layout, &generic_rows);

    for (row_index, row) in rows.iter().enumerate().skip(generic_rows.len()) {
        let mut variables = BTreeSet::new();
        match *row {
            BikeV1ExperimentalConstraintRow::Generic(_) => {}
            BikeV1ExperimentalConstraintRow::SectionMapJacobian { sample }
            | BikeV1ExperimentalConstraintRow::SectionForwardProgress { sample }
            | BikeV1ExperimentalConstraintRow::NormalLoad { sample, .. }
            | BikeV1ExperimentalConstraintRow::Kamm { sample, .. }
            | BikeV1ExperimentalConstraintRow::PowerLimit { sample }
            | BikeV1ExperimentalConstraintRow::SlipAngle { sample, .. } => {
                bike_v1_insert_sample_columns_with_tau_guard_next_station(
                    decision_layout,
                    &mut variables,
                    sample,
                    !omit_tau_guard_next_station_columns,
                );
            }
            BikeV1ExperimentalConstraintRow::DriveBrakeMutex { interval } => {
                bike_v1_insert_control_columns(decision_layout, &mut variables, interval);
            }
            BikeV1ExperimentalConstraintRow::SteeringTorque { interval } => {
                if steering_actuator_mode.uses_sr3_actual_steering_authority() {
                    bike_v1_insert_sample_columns(
                        decision_layout,
                        &mut variables,
                        BikeV1ExperimentalSample::IntervalStart { interval },
                    );
                } else {
                    bike_v1_insert_control_columns(decision_layout, &mut variables, interval);
                }
            }
            BikeV1ExperimentalConstraintRow::ControlLowFrequency {
                interval,
                anchor_interval,
                control_index,
            } => {
                variables.insert(decision_layout.control_offset(interval) + control_index);
                variables.insert(decision_layout.control_offset(anchor_interval) + control_index);
            }
        }
        pattern.extend(variables.into_iter().map(|variable| (row_index, variable)));
    }

    if steering_basis_mode.is_reduced() {
        bike_v1_augment_reduced_steering_sparse_pattern(
            decision_layout,
            rows,
            steering_basis_stride,
            &mut pattern,
        );
    }
    if steering_actuator_mode.uses_sr3_actual_steering_authority() {
        for (row_index, row) in rows.iter().enumerate() {
            if let BikeV1ExperimentalConstraintRow::Generic(
                GenericMintimeConstraintRow::ControlRate {
                    interval,
                    control_index: V1_CONTROL_STEERING_TORQUE_NM,
                },
            ) = *row
            {
                let next_interval =
                    next_station_index(decision_layout.dimensions.interval_count, interval);
                let mut variables = BTreeSet::new();
                bike_v1_insert_sample_columns(
                    decision_layout,
                    &mut variables,
                    BikeV1ExperimentalSample::IntervalStart { interval },
                );
                bike_v1_insert_sample_columns(
                    decision_layout,
                    &mut variables,
                    BikeV1ExperimentalSample::IntervalStart {
                        interval: next_interval,
                    },
                );
                pattern.extend(variables.into_iter().map(|variable| (row_index, variable)));
            }
        }
    }
    let mut unique = BTreeSet::new();
    pattern.retain(|entry| unique.insert(*entry));
    pattern
}

fn bike_v1_augment_reduced_steering_sparse_pattern(
    decision_layout: DecisionLayout,
    rows: &[BikeV1ExperimentalConstraintRow],
    steering_basis_stride: usize,
    pattern: &mut Vec<(usize, usize)>,
) {
    for (row_index, row) in rows.iter().enumerate() {
        match *row {
            BikeV1ExperimentalConstraintRow::Generic(
                GenericMintimeConstraintRow::CollocationDynamics { interval, .. },
            )
            | BikeV1ExperimentalConstraintRow::SectionMapJacobian {
                sample:
                    BikeV1ExperimentalSample::IntervalStart { interval }
                    | BikeV1ExperimentalSample::Station { interval }
                    | BikeV1ExperimentalSample::Collocation { interval, .. }
                    | BikeV1ExperimentalSample::TauGuard { interval, .. },
            }
            | BikeV1ExperimentalConstraintRow::SectionForwardProgress {
                sample:
                    BikeV1ExperimentalSample::IntervalStart { interval }
                    | BikeV1ExperimentalSample::Station { interval }
                    | BikeV1ExperimentalSample::Collocation { interval, .. }
                    | BikeV1ExperimentalSample::TauGuard { interval, .. },
            }
            | BikeV1ExperimentalConstraintRow::NormalLoad {
                sample:
                    BikeV1ExperimentalSample::IntervalStart { interval }
                    | BikeV1ExperimentalSample::Station { interval }
                    | BikeV1ExperimentalSample::Collocation { interval, .. }
                    | BikeV1ExperimentalSample::TauGuard { interval, .. },
                ..
            }
            | BikeV1ExperimentalConstraintRow::Kamm {
                sample:
                    BikeV1ExperimentalSample::IntervalStart { interval }
                    | BikeV1ExperimentalSample::Station { interval }
                    | BikeV1ExperimentalSample::Collocation { interval, .. }
                    | BikeV1ExperimentalSample::TauGuard { interval, .. },
                ..
            }
            | BikeV1ExperimentalConstraintRow::PowerLimit {
                sample:
                    BikeV1ExperimentalSample::IntervalStart { interval }
                    | BikeV1ExperimentalSample::Station { interval }
                    | BikeV1ExperimentalSample::Collocation { interval, .. }
                    | BikeV1ExperimentalSample::TauGuard { interval, .. },
            }
            | BikeV1ExperimentalConstraintRow::SlipAngle {
                sample:
                    BikeV1ExperimentalSample::IntervalStart { interval }
                    | BikeV1ExperimentalSample::Station { interval }
                    | BikeV1ExperimentalSample::Collocation { interval, .. }
                    | BikeV1ExperimentalSample::TauGuard { interval, .. },
                ..
            }
            | BikeV1ExperimentalConstraintRow::SteeringTorque { interval } => {
                bike_v1_push_reduced_steering_anchor_column(
                    decision_layout,
                    steering_basis_stride,
                    pattern,
                    row_index,
                    interval,
                );
            }
            BikeV1ExperimentalConstraintRow::Generic(
                GenericMintimeConstraintRow::ControlRate {
                    interval,
                    control_index: V1_CONTROL_STEERING_TORQUE_NM,
                },
            ) => {
                bike_v1_push_reduced_steering_anchor_column(
                    decision_layout,
                    steering_basis_stride,
                    pattern,
                    row_index,
                    interval,
                );
                bike_v1_push_reduced_steering_anchor_column(
                    decision_layout,
                    steering_basis_stride,
                    pattern,
                    row_index,
                    next_station_index(decision_layout.dimensions.interval_count, interval),
                );
            }
            BikeV1ExperimentalConstraintRow::ControlLowFrequency {
                interval,
                anchor_interval,
                control_index: V1_CONTROL_STEERING_TORQUE_NM,
            } => {
                bike_v1_push_reduced_steering_anchor_column(
                    decision_layout,
                    steering_basis_stride,
                    pattern,
                    row_index,
                    interval,
                );
                bike_v1_push_reduced_steering_anchor_column(
                    decision_layout,
                    steering_basis_stride,
                    pattern,
                    row_index,
                    anchor_interval,
                );
            }
            _ => {}
        }
    }
}

fn bike_v1_push_reduced_steering_anchor_column(
    decision_layout: DecisionLayout,
    steering_basis_stride: usize,
    pattern: &mut Vec<(usize, usize)>,
    row_index: usize,
    interval: usize,
) {
    let anchor = bike_v1_reduced_steering_anchor_interval(
        interval,
        decision_layout.dimensions.interval_count,
        steering_basis_stride,
    );
    pattern.push((
        row_index,
        decision_layout.control_offset(anchor) + V1_CONTROL_STEERING_TORQUE_NM,
    ));
}

fn bike_v1_insert_sample_columns(
    decision_layout: DecisionLayout,
    columns: &mut BTreeSet<usize>,
    sample: BikeV1ExperimentalSample,
) {
    bike_v1_insert_sample_columns_with_tau_guard_next_station(
        decision_layout,
        columns,
        sample,
        true,
    );
}

fn bike_v1_insert_sample_columns_with_tau_guard_next_station(
    decision_layout: DecisionLayout,
    columns: &mut BTreeSet<usize>,
    sample: BikeV1ExperimentalSample,
    include_tau_guard_next_station: bool,
) {
    match sample {
        BikeV1ExperimentalSample::IntervalStart { interval } => {
            let state_offset = decision_layout.state_offset(interval);
            for state_index in 0..decision_layout.state_len {
                columns.insert(state_offset + state_index);
            }
            bike_v1_insert_control_columns(decision_layout, columns, interval);
        }
        BikeV1ExperimentalSample::Station { interval } => {
            let station = next_station_index(decision_layout.dimensions.station_count, interval);
            let state_offset = decision_layout.state_offset(station);
            for state_index in 0..decision_layout.state_len {
                columns.insert(state_offset + state_index);
            }
            bike_v1_insert_control_columns(decision_layout, columns, interval);
        }
        BikeV1ExperimentalSample::Collocation { interval, point } => {
            let state_offset = decision_layout.collocation_state_offset(interval, point);
            for state_index in 0..decision_layout.state_len {
                columns.insert(state_offset + state_index);
            }
            bike_v1_insert_control_columns(decision_layout, columns, interval);
        }
        BikeV1ExperimentalSample::TauGuard { interval, .. } => {
            let station_count = decision_layout.dimensions.station_count;
            let next_station = next_station_index(station_count, interval);
            let station_indices = if include_tau_guard_next_station {
                vec![interval, next_station]
            } else {
                vec![interval]
            };
            for station in station_indices {
                let state_offset = decision_layout.state_offset(station);
                for state_index in 0..decision_layout.state_len {
                    columns.insert(state_offset + state_index);
                }
            }
            for point in 0..decision_layout.collocation_degree {
                let state_offset = decision_layout.collocation_state_offset(interval, point);
                for state_index in 0..decision_layout.state_len {
                    columns.insert(state_offset + state_index);
                }
            }
            bike_v1_insert_control_columns(decision_layout, columns, interval);
        }
    }
}

fn bike_v1_insert_control_columns(
    decision_layout: DecisionLayout,
    columns: &mut BTreeSet<usize>,
    interval: usize,
) {
    let control_offset = decision_layout.control_offset(interval);
    for control_index in 0..decision_layout.control_len {
        columns.insert(control_offset + control_index);
    }
}

fn bike_v1_experimental_constraint_bounds(
    rows: &[BikeV1ExperimentalConstraintRow],
    params: BikeCountersteerLeanParamsV1,
    options: &BikeMintimeSolveOptions,
) -> (Vec<f64>, Vec<f64>) {
    let mut lower = Vec::with_capacity(rows.len());
    let mut upper = Vec::with_capacity(rows.len());
    for row in rows {
        match *row {
            BikeV1ExperimentalConstraintRow::Generic(
                GenericMintimeConstraintRow::Continuity { .. }
                | GenericMintimeConstraintRow::CollocationDynamics { .. },
            ) => {
                lower.push(0.0);
                upper.push(0.0);
            }
            BikeV1ExperimentalConstraintRow::Generic(
                GenericMintimeConstraintRow::ControlRate { control_index, .. },
            ) => {
                let limit = match control_index {
                    V1_CONTROL_STEERING_TORQUE_NM
                        if options.debug_v1_steering_actuator_mode.uses_delta_cmd() =>
                    {
                        params.base.steering_angle_max_rad.max(1e-6)
                    }
                    V1_CONTROL_STEERING_TORQUE_NM => params.steering_torque_max_nm.max(1.0),
                    V1_CONTROL_F_DRIVE_N => params.base.drive_force_max_n.max(1.0),
                    V1_CONTROL_F_BRAKE_N => params.base.brake_force_max_n.max(1.0),
                    _ => 1.0,
                };
                lower.push(-limit);
                upper.push(limit);
            }
            BikeV1ExperimentalConstraintRow::SectionMapJacobian { .. } => {
                lower.push(BIKE_V1_SECTION_MAP_DET_MIN);
                upper.push(f64::INFINITY);
            }
            BikeV1ExperimentalConstraintRow::SectionForwardProgress { .. } => {
                lower.push(BIKE_V1_SECTION_FORWARD_PROGRESS_MIN);
                upper.push(f64::INFINITY);
            }
            BikeV1ExperimentalConstraintRow::NormalLoad { axle, .. } => {
                lower.push(min_normal_force_for_axle(params.base, axle));
                upper.push(f64::INFINITY);
            }
            BikeV1ExperimentalConstraintRow::Kamm { .. } => {
                lower.push(0.0);
                upper.push(1.0);
            }
            BikeV1ExperimentalConstraintRow::PowerLimit { .. } => {
                lower.push(f64::NEG_INFINITY);
                upper.push(params.base.power_max_w);
            }
            BikeV1ExperimentalConstraintRow::SlipAngle { axle, .. } => {
                let physical_limit = match axle {
                    "front" => params.base.alpha_front_max_rad,
                    "rear" => params.base.alpha_rear_max_rad,
                    _ => 0.0,
                };
                let peak_limit = match axle {
                    "front" => bike_v1_pacejka_peak_slip_rad(
                        params.base.tire_b_front,
                        params.base.tire_c_front,
                        params.base.tire_e_front,
                    ),
                    "rear" => bike_v1_pacejka_peak_slip_rad(
                        params.base.tire_b_rear,
                        params.base.tire_c_rear,
                        params.base.tire_e_rear,
                    ),
                    _ => 0.0,
                };
                let limit = if options.moto_v1_tire_force_mode.uses_prepeak_slip_limit() {
                    physical_limit.min(options.moto_v1_prepeak_grip_margin * peak_limit)
                } else {
                    physical_limit
                };
                lower.push(-limit);
                upper.push(limit);
            }
            BikeV1ExperimentalConstraintRow::DriveBrakeMutex { .. } => {
                lower.push(BIKE_DRIVE_BRAKE_MUTEX_LOWER_N2);
                upper.push(0.0);
            }
            BikeV1ExperimentalConstraintRow::SteeringTorque { .. } => {
                if options.debug_v1_steering_actuator_mode.uses_delta_cmd() {
                    let limit = params.base.steering_angle_max_rad.max(1e-6);
                    lower.push(-limit);
                    upper.push(limit);
                } else {
                    lower.push(-params.steering_torque_max_nm);
                    upper.push(params.steering_torque_max_nm);
                }
            }
            BikeV1ExperimentalConstraintRow::ControlLowFrequency { .. } => {
                lower.push(0.0);
                upper.push(0.0);
            }
            BikeV1ExperimentalConstraintRow::Generic(
                GenericMintimeConstraintRow::TrackBounds { .. }
                | GenericMintimeConstraintRow::DtDs { .. }
                | GenericMintimeConstraintRow::ModelSpecific { .. },
            ) => {
                lower.push(f64::NEG_INFINITY);
                upper.push(f64::INFINITY);
            }
        }
    }
    (lower, upper)
}

fn bike_v1_relaxed_block_slack_constraint_bounds(
    rows: &[BikeV1ExperimentalConstraintRow],
    hard_lower: &[f64],
    hard_upper: &[f64],
    mode: BikeV1BlockSlackMode,
) -> (Vec<f64>, Vec<f64>) {
    if !mode.is_enabled() {
        return (hard_lower.to_vec(), hard_upper.to_vec());
    }
    let mut lower = hard_lower.to_vec();
    let mut upper = hard_upper.to_vec();
    for (index, row) in rows.iter().enumerate() {
        if bike_v1_block_slack_row_matches(mode, *row) {
            lower[index] = f64::NEG_INFINITY;
            upper[index] = f64::INFINITY;
        }
    }
    (lower, upper)
}

fn bike_v1_block_slack_row_matches(
    mode: BikeV1BlockSlackMode,
    row: BikeV1ExperimentalConstraintRow,
) -> bool {
    match mode {
        BikeV1BlockSlackMode::Off => false,
        BikeV1BlockSlackMode::Power => {
            matches!(row, BikeV1ExperimentalConstraintRow::PowerLimit { .. })
        }
        BikeV1BlockSlackMode::CollocationVContinuityV => matches!(
            row,
            BikeV1ExperimentalConstraintRow::Generic(
                GenericMintimeConstraintRow::Continuity {
                    state_index: V1_STATE_V_MPS,
                    ..
                } | GenericMintimeConstraintRow::CollocationDynamics {
                    state_index: V1_STATE_V_MPS,
                    ..
                }
            )
        ),
        BikeV1BlockSlackMode::LoadTire => matches!(
            row,
            BikeV1ExperimentalConstraintRow::NormalLoad { .. }
                | BikeV1ExperimentalConstraintRow::Kamm { .. }
                | BikeV1ExperimentalConstraintRow::SlipAngle { .. }
        ),
        BikeV1BlockSlackMode::SteerActuator => matches!(
            row,
            BikeV1ExperimentalConstraintRow::SteeringTorque { .. }
                | BikeV1ExperimentalConstraintRow::Generic(
                    GenericMintimeConstraintRow::ControlRate {
                        control_index: V1_CONTROL_STEERING_TORQUE_NM,
                        ..
                    } | GenericMintimeConstraintRow::CollocationDynamics {
                        state_index: V1_STATE_DELTA_RAD | V1_STATE_DELTA_DOT_RADPS,
                        ..
                    } | GenericMintimeConstraintRow::Continuity {
                        state_index: V1_STATE_DELTA_RAD | V1_STATE_DELTA_DOT_RADPS,
                        ..
                    }
                )
        ),
        BikeV1BlockSlackMode::LeanRoll => matches!(
            row,
            BikeV1ExperimentalConstraintRow::Generic(
                GenericMintimeConstraintRow::CollocationDynamics {
                    state_index: V1_STATE_PHI_RAD | V1_STATE_PHI_DOT_RADPS,
                    ..
                } | GenericMintimeConstraintRow::Continuity {
                    state_index: V1_STATE_PHI_RAD | V1_STATE_PHI_DOT_RADPS,
                    ..
                }
            )
        ),
    }
}

fn bike_v1_block_slack_row_subfamily(row: BikeV1ExperimentalConstraintRow) -> &'static str {
    match row {
        BikeV1ExperimentalConstraintRow::PowerLimit { .. } => "power",
        BikeV1ExperimentalConstraintRow::NormalLoad { .. } => "normal_load",
        BikeV1ExperimentalConstraintRow::Kamm { .. } => "kamm",
        BikeV1ExperimentalConstraintRow::SlipAngle { .. } => "slip_angle",
        BikeV1ExperimentalConstraintRow::SteeringTorque { .. } => "steering_torque_bound",
        BikeV1ExperimentalConstraintRow::Generic(GenericMintimeConstraintRow::ControlRate {
            control_index: V1_CONTROL_STEERING_TORQUE_NM,
            ..
        }) => "steering_torque_rate",
        BikeV1ExperimentalConstraintRow::Generic(GenericMintimeConstraintRow::Continuity {
            state_index,
            ..
        }) => match state_index {
            V1_STATE_V_MPS => "continuity_v",
            V1_STATE_PHI_RAD => "continuity_phi",
            V1_STATE_PHI_DOT_RADPS => "continuity_phi_dot",
            V1_STATE_DELTA_RAD => "continuity_delta",
            V1_STATE_DELTA_DOT_RADPS => "continuity_delta_dot",
            _ => "continuity_other",
        },
        BikeV1ExperimentalConstraintRow::Generic(
            GenericMintimeConstraintRow::CollocationDynamics { state_index, .. },
        ) => match state_index {
            V1_STATE_V_MPS => "collocation_v",
            V1_STATE_PHI_RAD => "collocation_phi",
            V1_STATE_PHI_DOT_RADPS => "collocation_phi_dot",
            V1_STATE_DELTA_RAD => "collocation_delta",
            V1_STATE_DELTA_DOT_RADPS => "collocation_delta_dot",
            _ => "collocation_other",
        },
        _ => "other",
    }
}

fn bike_v1_variable_scales(
    decision_layout: DecisionLayout,
    params: BikeCountersteerLeanParamsV1,
    scaling_mode: BikeV1ScalingMode,
    state_representation: BikeV1StateRepresentationMode,
    steering_actuator_mode: BikeV1SteeringActuatorMode,
) -> Vec<f64> {
    if matches!(scaling_mode, BikeV1ScalingMode::None) {
        return vec![1.0; decision_layout.dimensions.decision_variable_count()];
    }
    let state_scale = bike_v1_state_scale(params, state_representation);
    let mut control_scale = bike_v1_control_scale(params);
    if steering_actuator_mode.uses_sr3_actual_steering_authority() {
        control_scale[V1_CONTROL_STEERING_TORQUE_NM] = 1.0;
    }
    let mut scales = Vec::with_capacity(decision_layout.dimensions.decision_variable_count());
    for _ in 0..decision_layout.dimensions.station_count {
        scales.extend_from_slice(&state_scale);
    }
    for _ in 0..decision_layout.dimensions.interval_count {
        scales.extend_from_slice(&control_scale);
    }
    for _ in 0..decision_layout.dimensions.interval_count * decision_layout.collocation_degree {
        scales.extend_from_slice(&state_scale);
    }
    scales
}

const BIKE_V1_KAPPA_YAW_SPEED_FLOOR_MPS: f64 = 1.0;
const BIKE_V1_KAPPA_YAW_SCALE_1PM: f64 = 0.1;

fn bike_v1_state_scale(
    params: BikeCountersteerLeanParamsV1,
    state_representation: BikeV1StateRepresentationMode,
) -> [f64; 9] {
    let mut scale = [
        50.0,
        0.5,
        1.0,
        5.0,
        1.0,
        1.0,
        params.base.lean_rate_max_radps.max(1e-9),
        params.base.steering_angle_max_rad.max(0.1),
        (params.base.steering_angle_max_rad / params.base.steering_response_s.max(0.02)).max(1.0),
    ];
    if state_representation.uses_kappa_yaw() {
        scale[V1_STATE_OMEGA_Z_RADPS] = BIKE_V1_KAPPA_YAW_SCALE_1PM;
    }
    scale
}

fn apply_bike_v1_state_representation_to_initial_guess(
    state_representation: BikeV1StateRepresentationMode,
    decision_layout: DecisionLayout,
    x: &mut [f64],
) {
    if !state_representation.uses_kappa_yaw() {
        return;
    }
    for station in 0..decision_layout.dimensions.station_count {
        let offset = decision_layout.state_offset(station);
        convert_bike_v1_raw_omega_slot_to_kappa_yaw(
            &mut x[offset..offset + decision_layout.state_len],
        );
    }
    for interval in 0..decision_layout.dimensions.interval_count {
        for point in 0..decision_layout.collocation_degree {
            let offset = decision_layout.collocation_state_offset(interval, point);
            convert_bike_v1_raw_omega_slot_to_kappa_yaw(
                &mut x[offset..offset + decision_layout.state_len],
            );
        }
    }
}

fn convert_bike_v1_raw_omega_slot_to_kappa_yaw(state_values: &mut [f64]) {
    let v_safe = state_values[V1_STATE_V_MPS].max(BIKE_V1_KAPPA_YAW_SPEED_FLOOR_MPS);
    state_values[V1_STATE_OMEGA_Z_RADPS] /= v_safe;
}

fn apply_bike_v1_steering_basis_to_initial_guess_and_bounds(
    steering_basis_mode: BikeV1SteeringBasisMode,
    steering_basis_stride: usize,
    decision_layout: DecisionLayout,
    x: &mut [f64],
    lower_bounds: &mut [f64],
    upper_bounds: &mut [f64],
) {
    if !steering_basis_mode.is_reduced() {
        return;
    }
    let stride = steering_basis_stride.max(1);
    let interval_count = decision_layout.dimensions.interval_count;
    let mut anchor_values = Vec::new();
    let mut block_start = 0usize;
    while block_start < interval_count {
        let block_end = (block_start + stride).min(interval_count);
        let mut sum = 0.0;
        let mut count = 0.0;
        for interval in block_start..block_end {
            let index = decision_layout.control_offset(interval) + V1_CONTROL_STEERING_TORQUE_NM;
            sum += x[index];
            count += 1.0;
        }
        anchor_values.push((block_start, if count > 0.0 { sum / count } else { 0.0 }));
        block_start += stride;
    }

    for (anchor, value) in anchor_values {
        let anchor_index = decision_layout.control_offset(anchor) + V1_CONTROL_STEERING_TORQUE_NM;
        x[anchor_index] = value.clamp(lower_bounds[anchor_index], upper_bounds[anchor_index]);
    }

    for interval in 0..interval_count {
        if bike_v1_reduced_steering_anchor_interval(interval, interval_count, stride) == interval {
            continue;
        }
        let index = decision_layout.control_offset(interval) + V1_CONTROL_STEERING_TORQUE_NM;
        x[index] = 0.0;
        lower_bounds[index] = 0.0;
        upper_bounds[index] = 0.0;
    }
}

fn apply_bike_v1_debug_steering_to_initial_guess_and_bounds(
    steering_actuator_mode: BikeV1SteeringActuatorMode,
    params: BikeCountersteerLeanParamsV1,
    decision_layout: DecisionLayout,
    x: &mut [f64],
    lower_bounds: &mut [f64],
    upper_bounds: &mut [f64],
) {
    if !steering_actuator_mode.uses_debug_steering_dynamics() {
        return;
    }
    let delta_limit = params.base.steering_angle_max_rad.max(1e-6);
    let torque_limit = params.steering_torque_max_nm.max(1.0);
    let delta_accel_scale = bike_v1_sr3_delta_accel_scale(params);
    for interval in 0..decision_layout.dimensions.interval_count {
        let state_offset = decision_layout.state_offset(interval);
        let control_index =
            decision_layout.control_offset(interval) + V1_CONTROL_STEERING_TORQUE_NM;
        match steering_actuator_mode {
            BikeV1SteeringActuatorMode::DeltaCmdFirstOrder => {
                let delta_cmd =
                    x[state_offset + V1_STATE_DELTA_RAD].clamp(-delta_limit, delta_limit);
                x[control_index] = delta_cmd;
                lower_bounds[control_index] = -delta_limit;
                upper_bounds[control_index] = delta_limit;
            }
            BikeV1SteeringActuatorMode::Sr3NormalizedTorque => {
                x[control_index] = (x[control_index] / torque_limit).clamp(-1.0, 1.0);
                lower_bounds[control_index] = -1.0;
                upper_bounds[control_index] = 1.0;
            }
            BikeV1SteeringActuatorMode::Sr3DeltaAccel => {
                let state = bike_v1_state_from_decision(decision_layout, x, interval);
                let control = bike_v1_control_from_decision(decision_layout, x, interval);
                let dynamics = bike_countersteer_lean_time_dynamics_v1(params, state, control);
                x[control_index] =
                    (dynamics.delta_ddot_radps2 / delta_accel_scale).clamp(-1.0, 1.0);
                lower_bounds[control_index] = -1.0;
                upper_bounds[control_index] = 1.0;
            }
            BikeV1SteeringActuatorMode::Torque => {}
        }
    }
}

fn apply_bike_v1_longitudinal_control_to_initial_guess_and_bounds(
    longitudinal_control_mode: BikeV1LongitudinalControlMode,
    params: BikeCountersteerLeanParamsV1,
    decision_layout: DecisionLayout,
    x: &mut [f64],
    lower_bounds: &mut [f64],
    upper_bounds: &mut [f64],
) {
    if !matches!(
        longitudinal_control_mode,
        BikeV1LongitudinalControlMode::SignedForceSlotSmooth
    ) {
        return;
    }
    let drive_upper = params.base.drive_force_max_n.max(1.0);
    let brake_lower = -params.base.brake_force_max_n.max(1.0);
    for interval in 0..decision_layout.dimensions.interval_count {
        let offset = decision_layout.control_offset(interval);
        let drive_index = offset + V1_CONTROL_F_DRIVE_N;
        let brake_index = offset + V1_CONTROL_F_BRAKE_N;
        let signed_force = x[drive_index] + x[brake_index];
        x[drive_index] = signed_force.clamp(brake_lower, drive_upper);
        lower_bounds[drive_index] = brake_lower;
        upper_bounds[drive_index] = drive_upper;
        x[brake_index] = 0.0;
        lower_bounds[brake_index] = 0.0;
        upper_bounds[brake_index] = 0.0;
    }
}

fn bike_v1_sr3_delta_accel_scale(params: BikeCountersteerLeanParamsV1) -> f64 {
    (params.steering_torque_max_nm.max(1.0) / params.steering_inertia_kgm2.max(1e-9)).max(1.0)
}

#[derive(Clone, Copy, Debug)]
struct BikeV1LongitudinalControlDerivatives {
    drive_by_raw_drive: f64,
    drive_by_raw_brake: f64,
    brake_by_raw_drive: f64,
    brake_by_raw_brake: f64,
}

fn bike_v1_apply_longitudinal_control_mode(
    mode: BikeV1LongitudinalControlMode,
    eps_n: f64,
    mut control: crate::bike_dynamics_v1::BikeCountersteerLeanControlV1,
) -> crate::bike_dynamics_v1::BikeCountersteerLeanControlV1 {
    if !mode.uses_signed_split() {
        return control;
    }
    let signed_force_n = control.f_drive_n + control.f_brake_n;
    match mode {
        BikeV1LongitudinalControlMode::Native => {}
        BikeV1LongitudinalControlMode::SignedSplitHard => {
            control.f_drive_n = signed_force_n.max(0.0);
            control.f_brake_n = signed_force_n.min(0.0);
        }
        BikeV1LongitudinalControlMode::SignedSplitSmooth
        | BikeV1LongitudinalControlMode::SignedForceSlotSmooth => {
            let signed_force_n =
                if matches!(mode, BikeV1LongitudinalControlMode::SignedForceSlotSmooth) {
                    control.f_drive_n
                } else {
                    signed_force_n
                };
            let smooth_abs = (signed_force_n * signed_force_n + eps_n.max(1.0e-9).powi(2)).sqrt();
            control.f_drive_n = 0.5 * (signed_force_n + smooth_abs);
            control.f_brake_n = 0.5 * (signed_force_n - smooth_abs);
        }
    }
    control
}

fn bike_v1_longitudinal_control_derivatives(
    mode: BikeV1LongitudinalControlMode,
    eps_n: f64,
    raw: crate::bike_dynamics_v1::BikeCountersteerLeanControlV1,
) -> BikeV1LongitudinalControlDerivatives {
    match mode {
        BikeV1LongitudinalControlMode::Native => BikeV1LongitudinalControlDerivatives {
            drive_by_raw_drive: 1.0,
            drive_by_raw_brake: 0.0,
            brake_by_raw_drive: 0.0,
            brake_by_raw_brake: 1.0,
        },
        BikeV1LongitudinalControlMode::SignedSplitHard => {
            let signed_force_n = raw.f_drive_n + raw.f_brake_n;
            let (drive_by_force, brake_by_force) = if signed_force_n >= 0.0 {
                (1.0, 0.0)
            } else {
                (0.0, 1.0)
            };
            BikeV1LongitudinalControlDerivatives {
                drive_by_raw_drive: drive_by_force,
                drive_by_raw_brake: drive_by_force,
                brake_by_raw_drive: brake_by_force,
                brake_by_raw_brake: brake_by_force,
            }
        }
        BikeV1LongitudinalControlMode::SignedSplitSmooth => {
            let signed_force_n = raw.f_drive_n + raw.f_brake_n;
            let smooth_abs = (signed_force_n * signed_force_n + eps_n.max(1.0e-9).powi(2)).sqrt();
            let ratio = signed_force_n / smooth_abs.max(1.0e-12);
            let drive_by_force = 0.5 * (1.0 + ratio);
            let brake_by_force = 0.5 * (1.0 - ratio);
            BikeV1LongitudinalControlDerivatives {
                drive_by_raw_drive: drive_by_force,
                drive_by_raw_brake: drive_by_force,
                brake_by_raw_drive: brake_by_force,
                brake_by_raw_brake: brake_by_force,
            }
        }
        BikeV1LongitudinalControlMode::SignedForceSlotSmooth => {
            let signed_force_n = raw.f_drive_n;
            let smooth_abs = (signed_force_n * signed_force_n + eps_n.max(1.0e-9).powi(2)).sqrt();
            let ratio = signed_force_n / smooth_abs.max(1.0e-12);
            let drive_by_force = 0.5 * (1.0 + ratio);
            let brake_by_force = 0.5 * (1.0 - ratio);
            BikeV1LongitudinalControlDerivatives {
                drive_by_raw_drive: drive_by_force,
                drive_by_raw_brake: 0.0,
                brake_by_raw_drive: brake_by_force,
                brake_by_raw_brake: 0.0,
            }
        }
    }
}

fn bike_v1_reduced_steering_anchor_interval(
    interval: usize,
    interval_count: usize,
    stride: usize,
) -> usize {
    if interval_count == 0 {
        return 0;
    }
    (interval / stride.max(1) * stride.max(1)).min(interval_count - 1)
}

fn bike_v1_control_scale(params: BikeCountersteerLeanParamsV1) -> [f64; 3] {
    [
        params.steering_torque_max_nm.max(1.0),
        params.base.drive_force_max_n.max(1.0),
        params.base.brake_force_max_n.max(1.0),
    ]
}

fn bike_v1_is_steer_roll_state_index(state_index: usize) -> bool {
    matches!(
        state_index,
        V1_STATE_BETA_RAD
            | V1_STATE_OMEGA_Z_RADPS
            | V1_STATE_XI_RAD
            | V1_STATE_PHI_RAD
            | V1_STATE_PHI_DOT_RADPS
            | V1_STATE_DELTA_RAD
            | V1_STATE_DELTA_DOT_RADPS
    )
}

fn bike_v1_is_hot_defect_state_index(state_index: usize) -> bool {
    matches!(
        state_index,
        V1_STATE_V_MPS
            | V1_STATE_BETA_RAD
            | V1_STATE_OMEGA_Z_RADPS
            | V1_STATE_XI_RAD
            | V1_STATE_PHI_RAD
            | V1_STATE_PHI_DOT_RADPS
            | V1_STATE_DELTA_RAD
            | V1_STATE_DELTA_DOT_RADPS
    )
}

fn bike_v1_is_progress_state_index(state_index: usize) -> bool {
    matches!(state_index, V1_STATE_N_M | V1_STATE_XI_RAD | V1_STATE_V_MPS)
}

fn bike_v1_constraint_scales(
    rows: &[BikeV1ExperimentalConstraintRow],
    interval_ds_m: &[f64],
    params: BikeCountersteerLeanParamsV1,
    scaling_mode: BikeV1ScalingMode,
    state_representation: BikeV1StateRepresentationMode,
    grip_constraint_scaling_mode: BikeV1GripConstraintScalingMode,
) -> Vec<f64> {
    if matches!(scaling_mode, BikeV1ScalingMode::None) {
        return vec![1.0; rows.len()];
    }
    let state_scale = bike_v1_state_scale(params, state_representation);
    let control_scale = bike_v1_control_scale(params);
    rows.iter()
        .map(|row| match *row {
            BikeV1ExperimentalConstraintRow::Generic(GenericMintimeConstraintRow::Continuity {
                state_index,
                ..
            }) => state_scale[state_index],
            BikeV1ExperimentalConstraintRow::Generic(
                GenericMintimeConstraintRow::CollocationDynamics {
                    interval,
                    state_index,
                    ..
                },
            ) => {
                let use_physical_row_scale = match scaling_mode {
                    BikeV1ScalingMode::PhysicalRows => true,
                    BikeV1ScalingMode::TargetedYawSteerRows
                    | BikeV1ScalingMode::Rs1SteerRollRowsLow => {
                        bike_v1_is_steer_roll_state_index(state_index)
                    }
                    BikeV1ScalingMode::TargetedHotDefectRows => {
                        bike_v1_is_hot_defect_state_index(state_index)
                    }
                    BikeV1ScalingMode::Rs3ProgressSectionRowsLow => {
                        bike_v1_is_progress_state_index(state_index)
                    }
                    BikeV1ScalingMode::Rs4CoupledLow => {
                        bike_v1_is_steer_roll_state_index(state_index)
                            || bike_v1_is_progress_state_index(state_index)
                    }
                    _ => false,
                };
                if use_physical_row_scale {
                    state_scale[state_index].max(1e-6)
                } else {
                    (state_scale[state_index] / interval_ds_m[interval].max(1e-6)).max(1e-6)
                }
            }
            BikeV1ExperimentalConstraintRow::Generic(
                GenericMintimeConstraintRow::ControlRate { control_index, .. },
            ) => {
                if matches!(
                    scaling_mode,
                    BikeV1ScalingMode::PhysicalRows
                        | BikeV1ScalingMode::Rs1SteerRollRowsLow
                        | BikeV1ScalingMode::Rs4CoupledLow
                ) && control_index == V1_CONTROL_STEERING_TORQUE_NM
                {
                    (control_scale[control_index]
                        / interval_ds_m.first().copied().unwrap_or(1.0).max(1e-6))
                    .max(1e-6)
                } else {
                    control_scale[control_index]
                }
            }
            BikeV1ExperimentalConstraintRow::Generic(GenericMintimeConstraintRow::DtDs {
                ..
            }) => {
                if matches!(
                    scaling_mode,
                    BikeV1ScalingMode::Rs3ProgressSectionRowsLow | BikeV1ScalingMode::Rs4CoupledLow
                ) {
                    1.0 / 30.0
                } else {
                    1.0
                }
            }
            BikeV1ExperimentalConstraintRow::SectionMapJacobian { .. }
            | BikeV1ExperimentalConstraintRow::SectionForwardProgress { .. } => {
                if matches!(
                    scaling_mode,
                    BikeV1ScalingMode::Rs3ProgressSectionRowsLow | BikeV1ScalingMode::Rs4CoupledLow
                ) {
                    0.5
                } else {
                    1.0
                }
            }
            BikeV1ExperimentalConstraintRow::NormalLoad { .. } => {
                let scale = (params.base.rider_bike_mass_kg * params.base.gravity_mps2).max(1.0);
                if matches!(
                    scaling_mode,
                    BikeV1ScalingMode::Rs2TireLoadRowsLow | BikeV1ScalingMode::Rs4CoupledLow
                ) {
                    0.5 * scale
                } else {
                    scale
                }
            }
            BikeV1ExperimentalConstraintRow::Kamm { .. } => 1.0,
            BikeV1ExperimentalConstraintRow::PowerLimit { .. } => {
                let base = params.base.power_max_w.max(1.0);
                if matches!(scaling_mode, BikeV1ScalingMode::TargetedHotDefectRows) {
                    2.0 * base
                } else {
                    base
                }
            }
            BikeV1ExperimentalConstraintRow::SlipAngle { axle, .. } => {
                if matches!(
                    grip_constraint_scaling_mode,
                    BikeV1GripConstraintScalingMode::PeakNormalized
                ) {
                    return match axle {
                        "front" => bike_v1_pacejka_peak_slip_rad(
                            params.base.tire_b_front,
                            params.base.tire_c_front,
                            params.base.tire_e_front,
                        ),
                        "rear" => bike_v1_pacejka_peak_slip_rad(
                            params.base.tire_b_rear,
                            params.base.tire_c_rear,
                            params.base.tire_e_rear,
                        ),
                        _ => 0.5,
                    }
                    .max(1e-6);
                }
                if matches!(
                    scaling_mode,
                    BikeV1ScalingMode::Rs2TireLoadRowsLow | BikeV1ScalingMode::Rs4CoupledLow
                ) {
                    0.25
                } else {
                    0.5
                }
            }
            BikeV1ExperimentalConstraintRow::DriveBrakeMutex { .. } => 20_000.0,
            BikeV1ExperimentalConstraintRow::SteeringTorque { .. } => {
                params.steering_torque_max_nm.max(1.0)
            }
            BikeV1ExperimentalConstraintRow::ControlLowFrequency { control_index, .. } => {
                control_scale[control_index]
            }
            _ => 1.0,
        })
        .collect()
}

fn bike_v1_regularization_objective_s(problem: &BikeV1ExperimentalProblem, x: &[f64]) -> f64 {
    bike_v1_regularization_objective_profiled_s(problem, x, None)
}

fn bike_v1_steering_control_unit_value(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    interval: usize,
) -> f64 {
    let control = problem.control_from_decision(x, interval);
    match problem.options.debug_v1_steering_actuator_mode {
        BikeV1SteeringActuatorMode::DeltaCmdFirstOrder => {
            control.steering_torque_nm / problem.params.base.steering_angle_max_rad.max(1e-9)
        }
        BikeV1SteeringActuatorMode::Sr3NormalizedTorque
        | BikeV1SteeringActuatorMode::Sr3DeltaAccel => control.steering_torque_nm,
        BikeV1SteeringActuatorMode::Torque => {
            control.steering_torque_nm / problem.params.steering_torque_max_nm.max(1.0)
        }
    }
}

fn bike_v1_segment_time_s(problem: &BikeV1ExperimentalProblem, x: &[f64], segment: usize) -> f64 {
    let station_count = problem.decision_layout.dimensions.station_count;
    let interval_count = problem.decision_layout.dimensions.interval_count;
    if station_count == 0 || interval_count == 0 {
        return 1.0;
    }
    let segment = segment.min(interval_count.saturating_sub(1));
    let left_station = segment.min(station_count.saturating_sub(1));
    let right_station = if left_station + 1 == station_count {
        0
    } else {
        left_station + 1
    };
    let left = problem.station_dynamics(x, left_station);
    let right = problem.station_dynamics(x, right_station);
    0.5 * (left.sigma_dt_ds + right.sigma_dt_ds).max(1e-9)
        * problem.interval_ds_m.get(segment).copied().unwrap_or(1.0)
}

fn bike_v1_time_normalized_steering_rate_at_segment(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    segment: usize,
) -> f64 {
    let interval_count = problem.decision_layout.dimensions.interval_count;
    if interval_count < 2 {
        return 0.0;
    }
    let segment = segment.min(interval_count.saturating_sub(1));
    let next = if segment + 1 == interval_count {
        0
    } else {
        segment + 1
    };
    let current_value = bike_v1_steering_control_unit_value(problem, x, segment);
    let next_value = bike_v1_steering_control_unit_value(problem, x, next);
    let dt = bike_v1_segment_time_s(problem, x, segment).max(1e-9);
    (next_value - current_value) * problem.params.base.steering_response_s.max(0.02) / dt
}

fn bike_v1_time_normalized_steering_accel_at_segment(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    segment: usize,
) -> f64 {
    let interval_count = problem.decision_layout.dimensions.interval_count;
    if interval_count < 3 {
        return 0.0;
    }
    let segment = segment.min(interval_count.saturating_sub(1));
    let previous = if segment == 0 {
        interval_count - 1
    } else {
        segment - 1
    };
    let previous_rate = bike_v1_time_normalized_steering_rate_at_segment(problem, x, previous);
    let current_rate = bike_v1_time_normalized_steering_rate_at_segment(problem, x, segment);
    let dt = 0.5
        * (bike_v1_segment_time_s(problem, x, previous)
            + bike_v1_segment_time_s(problem, x, segment))
        .max(1e-9);
    (current_rate - previous_rate) * problem.params.base.steering_response_s.max(0.02) / dt
}

fn bike_v1_time_normalized_steering_regularization_enabled(
    problem: &BikeV1ExperimentalProblem,
) -> bool {
    problem
        .options
        .moto_v1_steering_control_regularization_mode
        .is_vehicle_time_normalized()
        && problem
            .options
            .moto_v1_steering_control_regularization_scale
            > 0.0
}

fn bike_v1_time_normalized_steering_regularization_objective_s(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
) -> f64 {
    if !bike_v1_time_normalized_steering_regularization_enabled(problem) {
        return 0.0;
    }
    let weights = problem.objective_weights;
    let scale = problem
        .options
        .moto_v1_steering_control_regularization_scale;
    let interval_count = problem.decision_layout.dimensions.interval_count;
    let closed = seed_is_closed(&problem.geometry_seed);
    let segment_count = if closed {
        interval_count
    } else {
        interval_count.saturating_sub(1)
    };
    let mut total = 0.0;
    for segment in 0..segment_count {
        let rate = bike_v1_time_normalized_steering_rate_at_segment(problem, x, segment);
        total += weights.penalty_delta * scale * rate * rate;
        let accel = bike_v1_time_normalized_steering_accel_at_segment(problem, x, segment);
        total += weights.penalty_delta_dd * scale * accel * accel;
    }
    total
}

fn bike_v1_time_normalized_steering_regularization_objective_for_indices_s(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    affected: &BikeV1ComplexRegularizationAffected,
) -> f64 {
    if !bike_v1_time_normalized_steering_regularization_enabled(problem) {
        return 0.0;
    }
    let weights = problem.objective_weights;
    let scale = problem
        .options
        .moto_v1_steering_control_regularization_scale;
    let mut total = 0.0;
    for &segment in &affected.segments {
        let rate = bike_v1_time_normalized_steering_rate_at_segment(problem, x, segment);
        total += weights.penalty_delta * scale * rate * rate;
        let accel = bike_v1_time_normalized_steering_accel_at_segment(problem, x, segment);
        total += weights.penalty_delta_dd * scale * accel * accel;
    }
    total
}

fn bike_v1_positive_hinge_squared(value: f64, limit: f64) -> f64 {
    let excess = value.abs() / limit.max(1e-9) - 1.0;
    if excess > 0.0 {
        excess * excess
    } else {
        0.0
    }
}

fn bike_v1_steering_authority_envelope_component_count(
    problem: &BikeV1ExperimentalProblem,
) -> usize {
    if problem.options.moto_v1_steering_authority_envelope_weight <= 0.0 {
        return 0;
    }
    let interval_count = problem.decision_layout.dimensions.interval_count;
    let station_count = problem.decision_layout.dimensions.station_count;
    interval_count.saturating_mul(2) + station_count.saturating_mul(3)
}

fn bike_v1_steering_authority_envelope_station_sum(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    station: usize,
) -> f64 {
    let state = problem.station_state_from_decision(x, station);
    let dynamics = problem.station_dynamics(x, station);
    let params = problem.params;
    let steering_tau = params.base.steering_response_s.max(0.02);
    let delta_rate_limit = (params.base.steering_angle_max_rad / steering_tau)
        .abs()
        .max(1.0);
    let delta_accel_limit = (delta_rate_limit / steering_tau).abs().max(1.0);
    let torque_limit = params.steering_torque_max_nm.max(1.0);
    let steering_power_limit = (torque_limit * delta_rate_limit).max(1.0);
    let delta_dot_term = bike_v1_positive_hinge_squared(state.delta_dot_radps, delta_rate_limit);
    let delta_accel_term =
        bike_v1_positive_hinge_squared(dynamics.delta_ddot_radps2, delta_accel_limit);
    let steering_power = dynamics.steering_input_torque_nm * state.delta_dot_radps;
    let power_term = bike_v1_positive_hinge_squared(steering_power, steering_power_limit);
    delta_dot_term + delta_accel_term + power_term
}

fn bike_v1_steering_authority_envelope_segment_sum(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    segment: usize,
) -> f64 {
    let rate = bike_v1_time_normalized_steering_rate_at_segment(problem, x, segment);
    let accel = bike_v1_time_normalized_steering_accel_at_segment(problem, x, segment);
    let rate_term = bike_v1_positive_hinge_squared(rate, 1.0);
    let accel_term = bike_v1_positive_hinge_squared(accel, 1.0);
    rate_term + accel_term
}

fn bike_v1_steering_authority_envelope_objective_s(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
) -> f64 {
    let component_count = bike_v1_steering_authority_envelope_component_count(problem);
    if component_count == 0 {
        return 0.0;
    }
    let mut total = 0.0;
    for station in 0..problem.decision_layout.dimensions.station_count {
        total += bike_v1_steering_authority_envelope_station_sum(problem, x, station);
    }
    for segment in 0..problem.decision_layout.dimensions.interval_count {
        total += bike_v1_steering_authority_envelope_segment_sum(problem, x, segment);
    }
    problem.options.moto_v1_steering_authority_envelope_weight * total / component_count as f64
}

fn bike_v1_steering_authority_envelope_objective_for_indices_s(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    affected: &BikeV1ComplexRegularizationAffected,
) -> f64 {
    let component_count = bike_v1_steering_authority_envelope_component_count(problem);
    if component_count == 0 {
        return 0.0;
    }
    let mut total = 0.0;
    for &station in &affected.stations {
        if station < problem.decision_layout.dimensions.station_count {
            total += bike_v1_steering_authority_envelope_station_sum(problem, x, station);
        }
    }
    for &segment in &affected.segments {
        if segment < problem.decision_layout.dimensions.interval_count {
            total += bike_v1_steering_authority_envelope_segment_sum(problem, x, segment);
        }
    }
    problem.options.moto_v1_steering_authority_envelope_weight * total / component_count as f64
}

fn bike_v1_regularization_objective_profiled_s(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    mut profile: Option<&mut BikeV1CallbackProfile>,
) -> f64 {
    let weights = problem.objective_weights;
    let params = problem.params;
    let closed = seed_is_closed(&problem.geometry_seed);
    let interval_count = problem.decision_layout.dimensions.interval_count;
    let station_count = problem.decision_layout.dimensions.station_count;

    let torque_scale = params.steering_torque_max_nm.max(1.0);
    let drive_scale = params.base.drive_force_max_n.max(1.0);
    let brake_scale = params.base.brake_force_max_n.max(1.0);
    let delta_dot_scale =
        (params.base.steering_angle_max_rad / params.base.steering_response_s.max(0.02)).max(1.0);
    let lean_rate_scale = params.base.lean_rate_max_radps.max(1e-9);
    let ay_scale = params.base.lean_limited_lateral_accel_mps2().max(1.0);
    let steering_control_regularization_scale = problem
        .options
        .moto_v1_steering_control_regularization_scale;

    let steering_mode = problem.options.debug_v1_steering_actuator_mode;
    let mut steering_torque = Vec::with_capacity(interval_count);
    let mut force = Vec::with_capacity(interval_count);
    let control_series_start = Instant::now();
    for interval in 0..interval_count {
        let control = problem.control_from_decision(x, interval);
        let steering_value = match steering_mode {
            BikeV1SteeringActuatorMode::DeltaCmdFirstOrder => {
                control.steering_torque_nm / params.base.steering_angle_max_rad.max(1e-9)
            }
            BikeV1SteeringActuatorMode::Sr3NormalizedTorque
            | BikeV1SteeringActuatorMode::Sr3DeltaAccel => control.steering_torque_nm,
            BikeV1SteeringActuatorMode::Torque => control.steering_torque_nm / torque_scale,
        };
        steering_torque.push(steering_value);
        force.push(control.f_drive_n / drive_scale + control.f_brake_n / brake_scale);
    }
    if let Some(profile) = profile.as_deref_mut() {
        profile.add_objective_term(
            "regularization.control_series",
            control_series_start.elapsed(),
        );
    }

    let mut delta_dot = Vec::with_capacity(station_count);
    let mut delta_accel = Vec::with_capacity(station_count);
    let mut steering_input_torque = Vec::with_capacity(station_count);
    let mut steering_net_torque = Vec::with_capacity(station_count);
    let mut phi_eq_error = Vec::with_capacity(station_count);
    let mut phi_eq = Vec::with_capacity(station_count);
    let mut ay = Vec::with_capacity(station_count);
    let mut dt = Vec::with_capacity(station_count);
    let station_series_start = Instant::now();
    for station in 0..station_count {
        let state = bike_v1_state_from_decision(problem.decision_layout, x, station);
        let dynamics = problem.station_dynamics(x, station);
        delta_dot.push(state.delta_dot_radps / delta_dot_scale);
        let delta_accel_scale = (torque_scale / params.steering_inertia_kgm2.max(1e-9)).max(1.0);
        delta_accel.push(dynamics.delta_ddot_radps2 / delta_accel_scale);
        steering_input_torque.push(dynamics.steering_input_torque_nm / torque_scale);
        steering_net_torque.push(dynamics.steering_net_torque_nm / torque_scale);
        let steady_phi = (dynamics.ay_mps2 / params.base.gravity_mps2.max(1e-9)).atan();
        phi_eq_error.push((steady_phi - state.phi_rad) / BIKE_LEAN_EQUILIBRIUM_SCALE_RAD);
        phi_eq.push(steady_phi);
        ay.push(dynamics.ay_mps2 / ay_scale);

        let previous = if station == 0 {
            station_count.saturating_sub(1)
        } else {
            station - 1
        };
        let interval = if station == 0 {
            interval_count.saturating_sub(1)
        } else {
            station - 1
        };
        let previous_dynamics = problem.station_dynamics(x, previous);
        dt.push(
            0.5 * (dynamics.sigma_dt_ds + previous_dynamics.sigma_dt_ds).max(1e-9)
                * problem.interval_ds_m.get(interval).copied().unwrap_or(1.0),
        );
    }
    if let Some(profile) = profile.as_deref_mut() {
        profile.add_objective_term(
            "regularization.station_dynamics_series",
            station_series_start.elapsed(),
        );
    }

    let mut n = Vec::with_capacity(station_count);
    let mut xi = Vec::with_capacity(station_count);
    let mut phi_eq_rate = Vec::with_capacity(station_count);
    let mut ay_rate = Vec::with_capacity(station_count);
    let segment_count = if closed {
        station_count
    } else {
        station_count.saturating_sub(1)
    };
    for station in 0..station_count {
        let offset = problem.decision_layout.state_offset(station);
        n.push(x[offset + V1_STATE_N_M]);
        xi.push(x[offset + V1_STATE_XI_RAD]);
    }
    for index in 0..segment_count {
        let next = if index + 1 == station_count {
            0
        } else {
            index + 1
        };
        let segment_dt = dt[next].max(1e-9);
        phi_eq_rate.push((phi_eq[next] - phi_eq[index]) / segment_dt / lean_rate_scale);
        ay_rate.push((ay[next] - ay[index]) / segment_dt);
    }
    let mut term = |name: &'static str, value_fn: &dyn Fn() -> f64| -> f64 {
        let start = Instant::now();
        let value = value_fn();
        if let Some(profile) = profile.as_deref_mut() {
            profile.add_objective_term(name, start.elapsed());
        }
        value
    };

    let use_time_normalized_steering = problem
        .options
        .moto_v1_steering_control_regularization_mode
        .is_vehicle_time_normalized();
    let regularization = term("regularization.steering_torque_first_difference", &|| {
        if use_time_normalized_steering {
            0.0
        } else {
            weights.penalty_delta
                * steering_control_regularization_scale
                * first_difference_squared(&steering_torque, closed)
        }
    }) + term("regularization.steering_torque_second_difference", &|| {
        if use_time_normalized_steering {
            0.0
        } else {
            weights.penalty_delta_dd
                * steering_control_regularization_scale
                * second_difference_squared(&steering_torque, closed)
        }
    }) + term("regularization.v1_steering_time_normalized", &|| {
        bike_v1_time_normalized_steering_regularization_objective_s(problem, x)
    }) + term("regularization.force_first_difference", &|| {
        weights.penalty_f * first_difference_squared(&force, closed)
    }) + term("regularization.force_second_difference", &|| {
        weights.penalty_f_dd * second_difference_squared(&force, closed)
    }) + term("regularization.delta_dot", &|| {
        weights.penalty_delta * sum_squared(&delta_dot)
    }) + term("regularization.v1_delta_accel", &|| {
        weights.penalty_v1_delta_accel * sum_squared(&delta_accel)
    }) + term("regularization.v1_delta_jerk", &|| {
        weights.penalty_v1_delta_jerk * first_difference_squared(&delta_accel, closed)
    }) + term("regularization.v1_steering_input_torque_rate", &|| {
        weights.penalty_v1_steering_torque_rate
            * first_difference_squared(&steering_input_torque, closed)
    }) + term("regularization.n_second_difference", &|| {
        weights.penalty_n * second_difference_squared(&n, closed)
    }) + term("regularization.xi_second_difference", &|| {
        weights.penalty_xi * second_difference_squared(&xi, closed)
    }) + term("regularization.steering_net_torque", &|| {
        weights.penalty_roll_tau * sum_squared(&steering_net_torque)
    }) + term("regularization.phi_eq_error", &|| {
        weights.penalty_lean_equilibrium * sum_squared(&phi_eq_error)
    }) + term("regularization.phi_eq_rate", &|| {
        weights.penalty_phi_eq_rate * sum_squared(&phi_eq_rate)
    }) + term("regularization.ay_rate", &|| {
        weights.penalty_ay_rate * sum_squared(&ay_rate)
    });

    regularization
        + term("regularization.debug_basin_trust", &|| {
            bike_v1_basin_trust_objective_s(problem, x)
        })
        + term("regularization.debug_energy_guard", &|| {
            bike_v1_energy_guard_objective_s(problem, x)
        })
        + term("regularization.debug_active_set_guard", &|| {
            bike_v1_active_set_guard_objective_s(problem, x)
        })
        + term("regularization.debug_block_slack", &|| {
            bike_v1_block_slack_objective_s(problem, x)
        })
        + term("regularization.debug_steering_shadow_gate", &|| {
            bike_v1_steering_shadow_gate_objective_s(problem, x)
        })
        + term("regularization.v1_steering_authority_envelope", &|| {
            bike_v1_steering_authority_envelope_objective_s(problem, x)
        })
        + term("regularization.debug_kamm_margin_guard", &|| {
            bike_v1_kamm_margin_guard_objective_s(problem, x)
        })
        + term("regularization.debug_dense_shape_guard", &|| {
            bike_v1_dense_shape_guard_objective_s(problem, x)
        })
        + term("regularization.debug_yaw_path_guard", &|| {
            bike_v1_yaw_path_guard_objective_s(problem, x)
        })
        + term("regularization.debug_force_loop_smooth", &|| {
            bike_v1_force_loop_smooth_objective_s(problem, x)
        })
        + term("regularization.debug_progress_guard", &|| {
            bike_v1_progress_guard_objective_s(problem, x)
        })
}

const BIKE_V1_BASIN_TRUST_SPEED_SCALE_MPS: f64 = 10.0;
const BIKE_V1_BASIN_TRUST_HEADING_SCALE_RAD: f64 = 0.25;
const BIKE_V1_BASIN_TRUST_N_SCALE_M: f64 = 2.0;
const BIKE_V1_BASIN_TRUST_OMEGA_Z_SCALE_RADPS: f64 = 1.0;

fn bike_v1_basin_trust_component_count(problem: &BikeV1ExperimentalProblem) -> usize {
    let mode = problem.options.debug_v1_basin_trust_mode;
    if !mode.is_enabled() || problem.options.debug_v1_basin_trust_weight <= 0.0 {
        return 0;
    }
    let station_count = problem.decision_layout.dimensions.station_count;
    let collocation_count = problem.decision_layout.dimensions.interval_count
        * problem.decision_layout.collocation_degree;
    (station_count + collocation_count) * mode.component_count()
}

fn bike_v1_basin_trust_objective_s(problem: &BikeV1ExperimentalProblem, x: &[f64]) -> f64 {
    let component_count = bike_v1_basin_trust_component_count(problem);
    if component_count == 0 {
        return 0.0;
    }
    let mode = problem.options.debug_v1_basin_trust_mode;
    let mut sum = 0.0;
    for station in 0..problem.decision_layout.dimensions.station_count {
        let offset = problem.decision_layout.state_offset(station);
        sum += bike_v1_basin_trust_state_sum(problem, x, offset, mode);
    }
    for interval in 0..problem.decision_layout.dimensions.interval_count {
        for point in 0..problem.decision_layout.collocation_degree {
            let offset = problem
                .decision_layout
                .collocation_state_offset(interval, point);
            sum += bike_v1_basin_trust_state_sum(problem, x, offset, mode);
        }
    }
    problem.options.debug_v1_basin_trust_weight * sum / component_count as f64
}

fn bike_v1_basin_trust_state_sum(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    offset: usize,
    mode: BikeV1BasinTrustMode,
) -> f64 {
    let reference = &problem.initial_guess;
    let speed_delta = (x[offset + V1_STATE_V_MPS] - reference[offset + V1_STATE_V_MPS])
        / BIKE_V1_BASIN_TRUST_SPEED_SCALE_MPS;
    let heading_delta = normalize_angle_rad(
        (x[offset + V1_STATE_XI_RAD] + x[offset + V1_STATE_BETA_RAD])
            - (reference[offset + V1_STATE_XI_RAD] + reference[offset + V1_STATE_BETA_RAD]),
    ) / BIKE_V1_BASIN_TRUST_HEADING_SCALE_RAD;
    let mut sum = speed_delta * speed_delta + heading_delta * heading_delta;
    if mode.includes_n() {
        let n_delta = (x[offset + V1_STATE_N_M] - reference[offset + V1_STATE_N_M])
            / BIKE_V1_BASIN_TRUST_N_SCALE_M;
        sum += n_delta * n_delta;
    }
    if mode.includes_omega_z() {
        let omega_delta = (x[offset + V1_STATE_OMEGA_Z_RADPS]
            - reference[offset + V1_STATE_OMEGA_Z_RADPS])
            / BIKE_V1_BASIN_TRUST_OMEGA_Z_SCALE_RADPS;
        sum += omega_delta * omega_delta;
    }
    sum
}

fn bike_v1_basin_trust_objective_for_sector_s(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    interval: usize,
) -> f64 {
    let component_count = bike_v1_basin_trust_component_count(problem);
    if component_count == 0 {
        return 0.0;
    }
    let mode = problem.options.debug_v1_basin_trust_mode;
    let mut sum = 0.0;
    let station_count = problem.decision_layout.dimensions.station_count;
    if station_count > 0 {
        let station = interval.min(station_count - 1);
        let offset = problem.decision_layout.state_offset(station);
        sum += bike_v1_basin_trust_state_sum(problem, x, offset, mode);
    }
    if interval < problem.decision_layout.dimensions.interval_count {
        for point in 0..problem.decision_layout.collocation_degree {
            let offset = problem
                .decision_layout
                .collocation_state_offset(interval, point);
            sum += bike_v1_basin_trust_state_sum(problem, x, offset, mode);
        }
    }
    problem.options.debug_v1_basin_trust_weight * sum / component_count as f64
}

fn add_bike_v1_basin_trust_gradient_structured(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    gradient: &mut [f64],
) {
    let component_count = bike_v1_basin_trust_component_count(problem);
    if component_count == 0 {
        return;
    }
    let mode = problem.options.debug_v1_basin_trust_mode;
    let factor = 2.0 * problem.options.debug_v1_basin_trust_weight / component_count as f64;
    for station in 0..problem.decision_layout.dimensions.station_count {
        let offset = problem.decision_layout.state_offset(station);
        add_bike_v1_basin_trust_state_gradient(problem, x, gradient, offset, mode, factor);
    }
    for interval in 0..problem.decision_layout.dimensions.interval_count {
        for point in 0..problem.decision_layout.collocation_degree {
            let offset = problem
                .decision_layout
                .collocation_state_offset(interval, point);
            add_bike_v1_basin_trust_state_gradient(problem, x, gradient, offset, mode, factor);
        }
    }
}

fn add_bike_v1_basin_trust_state_gradient(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    gradient: &mut [f64],
    offset: usize,
    mode: BikeV1BasinTrustMode,
    factor: f64,
) {
    let reference = &problem.initial_guess;
    let speed_delta = (x[offset + V1_STATE_V_MPS] - reference[offset + V1_STATE_V_MPS])
        / BIKE_V1_BASIN_TRUST_SPEED_SCALE_MPS;
    gradient[offset + V1_STATE_V_MPS] += factor * speed_delta / BIKE_V1_BASIN_TRUST_SPEED_SCALE_MPS;

    let heading_delta = normalize_angle_rad(
        (x[offset + V1_STATE_XI_RAD] + x[offset + V1_STATE_BETA_RAD])
            - (reference[offset + V1_STATE_XI_RAD] + reference[offset + V1_STATE_BETA_RAD]),
    ) / BIKE_V1_BASIN_TRUST_HEADING_SCALE_RAD;
    let heading_gradient = factor * heading_delta / BIKE_V1_BASIN_TRUST_HEADING_SCALE_RAD;
    gradient[offset + V1_STATE_XI_RAD] += heading_gradient;
    gradient[offset + V1_STATE_BETA_RAD] += heading_gradient;

    if mode.includes_n() {
        let n_delta = (x[offset + V1_STATE_N_M] - reference[offset + V1_STATE_N_M])
            / BIKE_V1_BASIN_TRUST_N_SCALE_M;
        gradient[offset + V1_STATE_N_M] += factor * n_delta / BIKE_V1_BASIN_TRUST_N_SCALE_M;
    }
    if mode.includes_omega_z() {
        let omega_delta = (x[offset + V1_STATE_OMEGA_Z_RADPS]
            - reference[offset + V1_STATE_OMEGA_Z_RADPS])
            / BIKE_V1_BASIN_TRUST_OMEGA_Z_SCALE_RADPS;
        gradient[offset + V1_STATE_OMEGA_Z_RADPS] +=
            factor * omega_delta / BIKE_V1_BASIN_TRUST_OMEGA_Z_SCALE_RADPS;
    }
}

const BIKE_V1_ENERGY_GUARD_SPEED_SCALE_MPS: f64 = 5.0;

fn bike_v1_energy_guard_component_count(problem: &BikeV1ExperimentalProblem) -> usize {
    if problem.options.debug_v1_energy_guard_weight <= 0.0 {
        return 0;
    }
    problem.decision_layout.dimensions.station_count
        + problem.decision_layout.dimensions.interval_count
            * problem.decision_layout.collocation_degree
}

fn bike_v1_energy_guard_objective_s(problem: &BikeV1ExperimentalProblem, x: &[f64]) -> f64 {
    let component_count = bike_v1_energy_guard_component_count(problem);
    if component_count == 0 {
        return 0.0;
    }
    let mut sum = 0.0;
    for station in 0..problem.decision_layout.dimensions.station_count {
        let offset = problem.decision_layout.state_offset(station);
        sum += bike_v1_energy_guard_state_sum(problem, x, offset);
    }
    for interval in 0..problem.decision_layout.dimensions.interval_count {
        for point in 0..problem.decision_layout.collocation_degree {
            let offset = problem
                .decision_layout
                .collocation_state_offset(interval, point);
            sum += bike_v1_energy_guard_state_sum(problem, x, offset);
        }
    }
    problem.options.debug_v1_energy_guard_weight * sum / component_count as f64
}

fn bike_v1_energy_guard_objective_for_sector_s(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    interval: usize,
) -> f64 {
    let component_count = bike_v1_energy_guard_component_count(problem);
    if component_count == 0 {
        return 0.0;
    }
    let mut sum = 0.0;
    let station_count = problem.decision_layout.dimensions.station_count;
    if station_count > 0 {
        let station = interval.min(station_count - 1);
        let offset = problem.decision_layout.state_offset(station);
        sum += bike_v1_energy_guard_state_sum(problem, x, offset);
    }
    if interval < problem.decision_layout.dimensions.interval_count {
        for point in 0..problem.decision_layout.collocation_degree {
            let offset = problem
                .decision_layout
                .collocation_state_offset(interval, point);
            sum += bike_v1_energy_guard_state_sum(problem, x, offset);
        }
    }
    problem.options.debug_v1_energy_guard_weight * sum / component_count as f64
}

fn bike_v1_energy_guard_state_sum(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    offset: usize,
) -> f64 {
    let reference_speed = problem.initial_guess[offset + V1_STATE_V_MPS];
    let floor_speed = (reference_speed - problem.options.debug_v1_energy_guard_margin_mps).max(0.0);
    let deficit = ((floor_speed - x[offset + V1_STATE_V_MPS])
        / BIKE_V1_ENERGY_GUARD_SPEED_SCALE_MPS)
        .max(0.0);
    deficit * deficit
}

fn add_bike_v1_energy_guard_gradient_structured(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    gradient: &mut [f64],
) {
    let component_count = bike_v1_energy_guard_component_count(problem);
    if component_count == 0 {
        return;
    }
    let factor = problem.options.debug_v1_energy_guard_weight / component_count as f64;
    for station in 0..problem.decision_layout.dimensions.station_count {
        let offset = problem.decision_layout.state_offset(station);
        add_bike_v1_energy_guard_state_gradient(problem, x, gradient, offset, factor);
    }
    for interval in 0..problem.decision_layout.dimensions.interval_count {
        for point in 0..problem.decision_layout.collocation_degree {
            let offset = problem
                .decision_layout
                .collocation_state_offset(interval, point);
            add_bike_v1_energy_guard_state_gradient(problem, x, gradient, offset, factor);
        }
    }
}

fn add_bike_v1_energy_guard_state_gradient(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    gradient: &mut [f64],
    offset: usize,
    factor: f64,
) {
    let index = offset + V1_STATE_V_MPS;
    let reference_speed = problem.initial_guess[index];
    let floor_speed = (reference_speed - problem.options.debug_v1_energy_guard_margin_mps).max(0.0);
    let deficit = (floor_speed - x[index]) / BIKE_V1_ENERGY_GUARD_SPEED_SCALE_MPS;
    if deficit > 0.0 {
        gradient[index] += -2.0 * factor * deficit / BIKE_V1_ENERGY_GUARD_SPEED_SCALE_MPS;
    }
}

fn bike_v1_active_set_guard_component_count(problem: &BikeV1ExperimentalProblem) -> usize {
    if problem.options.debug_v1_active_set_guard_weight <= 0.0
        || problem.options.debug_v1_active_set_guard_margin <= 0.0
    {
        return 0;
    }
    let station_components = problem.decision_layout.dimensions.station_count * 4;
    let collocation_components = problem.decision_layout.dimensions.interval_count
        * problem.decision_layout.collocation_degree
        * 4;
    let control_components = problem.decision_layout.dimensions.interval_count;
    station_components + collocation_components + control_components
}

fn bike_v1_active_set_guard_objective_s(problem: &BikeV1ExperimentalProblem, x: &[f64]) -> f64 {
    let component_count = bike_v1_active_set_guard_component_count(problem);
    if component_count == 0 {
        return 0.0;
    }
    let mut sum = 0.0;
    for station in 0..problem.decision_layout.dimensions.station_count {
        let offset = problem.decision_layout.state_offset(station);
        sum += bike_v1_active_set_guard_state_sum(problem, x, offset);
    }
    for interval in 0..problem.decision_layout.dimensions.interval_count {
        for point in 0..problem.decision_layout.collocation_degree {
            let offset = problem
                .decision_layout
                .collocation_state_offset(interval, point);
            sum += bike_v1_active_set_guard_state_sum(problem, x, offset);
        }
        let offset = problem.decision_layout.control_offset(interval);
        sum += bike_v1_active_set_guard_variable_sum(
            problem,
            x,
            offset + V1_CONTROL_STEERING_TORQUE_NM,
            false,
        );
    }
    problem.options.debug_v1_active_set_guard_weight * sum / component_count as f64
}

fn bike_v1_active_set_guard_objective_for_sector_s(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    interval: usize,
) -> f64 {
    let component_count = bike_v1_active_set_guard_component_count(problem);
    if component_count == 0 {
        return 0.0;
    }
    let mut sum = 0.0;
    let station_count = problem.decision_layout.dimensions.station_count;
    if station_count > 0 {
        let station = interval.min(station_count - 1);
        let offset = problem.decision_layout.state_offset(station);
        sum += bike_v1_active_set_guard_state_sum(problem, x, offset);
    }
    if interval < problem.decision_layout.dimensions.interval_count {
        for point in 0..problem.decision_layout.collocation_degree {
            let offset = problem
                .decision_layout
                .collocation_state_offset(interval, point);
            sum += bike_v1_active_set_guard_state_sum(problem, x, offset);
        }
        let offset = problem.decision_layout.control_offset(interval);
        sum += bike_v1_active_set_guard_variable_sum(
            problem,
            x,
            offset + V1_CONTROL_STEERING_TORQUE_NM,
            false,
        );
    }
    problem.options.debug_v1_active_set_guard_weight * sum / component_count as f64
}

fn bike_v1_active_set_guard_state_sum(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    offset: usize,
) -> f64 {
    bike_v1_active_set_guard_variable_sum(problem, x, offset + V1_STATE_V_MPS, true)
        + bike_v1_active_set_guard_variable_sum(problem, x, offset + V1_STATE_OMEGA_Z_RADPS, false)
        + bike_v1_active_set_guard_variable_sum(problem, x, offset + V1_STATE_PHI_RAD, false)
        + bike_v1_active_set_guard_variable_sum(problem, x, offset + V1_STATE_DELTA_RAD, false)
}

fn bike_v1_active_set_guard_variable_sum(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    index: usize,
    lower_only: bool,
) -> f64 {
    let Some((deficit, _gradient_sign)) =
        bike_v1_active_set_guard_variable_deficit(problem, x, index, lower_only)
    else {
        return 0.0;
    };
    deficit * deficit
}

fn bike_v1_active_set_guard_variable_deficit(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    index: usize,
    lower_only: bool,
) -> Option<(f64, f64)> {
    let lower = *problem.lower_bounds.get(index)?;
    let upper = *problem.upper_bounds.get(index)?;
    if !(lower.is_finite() && upper.is_finite() && upper > lower) {
        return None;
    }
    let range = upper - lower;
    if range <= 1.0e-9 {
        return None;
    }
    let value = *x.get(index)?;
    let lower_dist = ((value - lower) / range).clamp(0.0, f64::INFINITY);
    let (distance, gradient_sign) = if lower_only {
        (lower_dist, -1.0 / range)
    } else {
        let upper_dist = ((upper - value) / range).clamp(0.0, f64::INFINITY);
        if lower_dist <= upper_dist {
            (lower_dist, -1.0 / range)
        } else {
            (upper_dist, 1.0 / range)
        }
    };
    let deficit = problem.options.debug_v1_active_set_guard_margin - distance;
    (deficit > 0.0).then_some((deficit, gradient_sign))
}

fn add_bike_v1_active_set_guard_gradient_structured(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    gradient: &mut [f64],
) {
    let component_count = bike_v1_active_set_guard_component_count(problem);
    if component_count == 0 {
        return;
    }
    let factor = problem.options.debug_v1_active_set_guard_weight / component_count as f64;
    for station in 0..problem.decision_layout.dimensions.station_count {
        let offset = problem.decision_layout.state_offset(station);
        add_bike_v1_active_set_guard_state_gradient(problem, x, gradient, offset, factor);
    }
    for interval in 0..problem.decision_layout.dimensions.interval_count {
        for point in 0..problem.decision_layout.collocation_degree {
            let offset = problem
                .decision_layout
                .collocation_state_offset(interval, point);
            add_bike_v1_active_set_guard_state_gradient(problem, x, gradient, offset, factor);
        }
        let offset = problem.decision_layout.control_offset(interval);
        add_bike_v1_active_set_guard_variable_gradient(
            problem,
            x,
            gradient,
            offset + V1_CONTROL_STEERING_TORQUE_NM,
            false,
            factor,
        );
    }
}

fn add_bike_v1_active_set_guard_state_gradient(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    gradient: &mut [f64],
    offset: usize,
    factor: f64,
) {
    add_bike_v1_active_set_guard_variable_gradient(
        problem,
        x,
        gradient,
        offset + V1_STATE_V_MPS,
        true,
        factor,
    );
    add_bike_v1_active_set_guard_variable_gradient(
        problem,
        x,
        gradient,
        offset + V1_STATE_OMEGA_Z_RADPS,
        false,
        factor,
    );
    add_bike_v1_active_set_guard_variable_gradient(
        problem,
        x,
        gradient,
        offset + V1_STATE_PHI_RAD,
        false,
        factor,
    );
    add_bike_v1_active_set_guard_variable_gradient(
        problem,
        x,
        gradient,
        offset + V1_STATE_DELTA_RAD,
        false,
        factor,
    );
}

fn add_bike_v1_active_set_guard_variable_gradient(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    gradient: &mut [f64],
    index: usize,
    lower_only: bool,
    factor: f64,
) {
    let Some((deficit, gradient_sign)) =
        bike_v1_active_set_guard_variable_deficit(problem, x, index, lower_only)
    else {
        return;
    };
    gradient[index] += 2.0 * factor * deficit * gradient_sign;
}

const BIKE_V1_KAMM_MARGIN_GUARD_SCALE: f64 = 0.02;

fn bike_v1_dense_shape_guard_component_count(problem: &BikeV1ExperimentalProblem) -> usize {
    if problem.options.debug_v1_dense_shape_guard_weight <= 0.0
        || problem.options.debug_v1_dense_shape_guard_samples == 0
    {
        return 0;
    }
    problem.decision_layout.dimensions.interval_count
        * problem.options.debug_v1_dense_shape_guard_samples
}

fn bike_v1_dense_shape_guard_objective_s(problem: &BikeV1ExperimentalProblem, x: &[f64]) -> f64 {
    let component_count = bike_v1_dense_shape_guard_component_count(problem);
    if component_count == 0 {
        return 0.0;
    }
    let mut sum = 0.0;
    for interval in 0..problem.decision_layout.dimensions.interval_count {
        for dense_sample in 0..problem.options.debug_v1_dense_shape_guard_samples {
            sum += bike_v1_dense_shape_guard_sample_sum(problem, x, interval, dense_sample);
        }
    }
    problem.options.debug_v1_dense_shape_guard_weight * sum / component_count as f64
}

fn bike_v1_dense_shape_guard_objective_for_indices_s(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    affected: &BikeV1ComplexRegularizationAffected,
) -> f64 {
    let component_count = bike_v1_dense_shape_guard_component_count(problem);
    if component_count == 0 {
        return 0.0;
    }
    let mut sum = 0.0;
    for &segment in &affected.segments {
        if segment >= problem.decision_layout.dimensions.interval_count {
            continue;
        }
        for dense_sample in 0..problem.options.debug_v1_dense_shape_guard_samples {
            sum += bike_v1_dense_shape_guard_sample_sum(problem, x, segment, dense_sample);
        }
    }
    problem.options.debug_v1_dense_shape_guard_weight * sum / component_count as f64
}

fn bike_v1_dense_shape_guard_sample_sum(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    interval: usize,
    dense_sample: usize,
) -> f64 {
    let dense_sample_count = problem.options.debug_v1_dense_shape_guard_samples;
    let station_count = problem.decision_layout.dimensions.station_count;
    if dense_sample_count == 0
        || station_count == 0
        || interval >= problem.decision_layout.dimensions.interval_count
    {
        return 0.0;
    }
    let tau = bike_v1_kamm_margin_guard_dense_tau(dense_sample, dense_sample_count);
    let state_values =
        bike_v1_collocation_state_values_at_tau(problem.decision_layout, x, interval, tau);
    let left_station = interval.min(station_count - 1);
    let right_station = next_station_index(station_count, left_station);
    let left_n = x[problem.decision_layout.state_offset(left_station) + V1_STATE_N_M];
    let right_n = x[problem.decision_layout.state_offset(right_station) + V1_STATE_N_M];
    let linear_n = left_n + tau * (right_n - left_n);
    let normalized = (state_values[V1_STATE_N_M] - linear_n)
        / problem.options.debug_v1_dense_shape_guard_scale_m;
    normalized * normalized
}

