fn bike_v1_yaw_path_guard_sample_sum(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    interval: usize,
    dense_sample: usize,
) -> f64 {
    let dense_sample_count = problem.options.debug_v1_yaw_path_guard_samples;
    if dense_sample_count == 0 || interval >= problem.decision_layout.dimensions.interval_count {
        return 0.0;
    }
    let tau = bike_v1_kamm_margin_guard_dense_tau(dense_sample, dense_sample_count);
    let frame_sampler = DenseSectionFrameHermiteSampler {
        station_s_m: &problem.geometry_seed.station_s_m,
        centerline_xy_m: &problem.geometry_seed.centerline_xy_m,
        tangent_xy: &problem.geometry_seed.ref_tangent_xy,
        section_dir_xy: &problem.geometry_seed.section_dir_xy,
        section_dir_derivative_xy: &problem.geometry_seed.section_dir_derivative_xy,
        closed: seed_is_closed(&problem.geometry_seed),
    };
    let geometry = frame_sampler
        .sample_at_interval_tau(interval, tau)
        .expect("valid coherent section-frame bike v1 yaw-path guard sample");
    let state_values =
        bike_v1_collocation_state_values_at_tau(problem.decision_layout, x, interval, tau);
    let state_ds_values = bike_v1_collocation_state_derivatives_at_tau(
        problem.decision_layout,
        x,
        interval,
        tau,
        problem.interval_ds_m[interval],
    );
    let state_d2s_values = bike_v1_collocation_state_second_derivatives_at_tau(
        problem.decision_layout,
        x,
        interval,
        tau,
        problem.interval_ds_m[interval],
    );
    let dense = build_dense_section_frame_sample_from_geometry(
        geometry,
        DenseSectionFrameInput {
            n_m: state_values[V1_STATE_N_M],
            dn_ds: state_ds_values[V1_STATE_N_M],
            d2n_ds2: state_d2s_values[V1_STATE_N_M],
            v_mps: state_values[V1_STATE_V_MPS],
        },
    );
    let yaw_kappa =
        state_values[V1_STATE_OMEGA_Z_RADPS] / state_values[V1_STATE_V_MPS].abs().max(1.0);
    let normalized =
        (yaw_kappa - dense.kappa_geo_1pm) / problem.options.debug_v1_yaw_path_guard_scale_1pm;
    normalized * normalized
}

