fn bike_v1_progress_guard_sample_sum(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    interval: usize,
    dense_sample: usize,
) -> f64 {
    let dense_sample_count = problem.options.debug_v1_progress_guard_samples;
    if dense_sample_count == 0 || interval >= problem.decision_layout.dimensions.interval_count {
        return 0.0;
    }
    let tau = bike_v1_kamm_margin_guard_dense_tau(dense_sample, dense_sample_count);
    let frame_sampler = DenseSectionFrameHermiteSampler {
        station_s_m: &problem.geometry_seed.station_s_m,
        centerline_xy_m: &problem.geometry_seed.centerline_xy_m,
        tangent_xy: &problem.geometry_seed.ref_tangent_xy,
        section_dir_xy: &problem.geometry_seed.section_dir_xy,
        section_dir_derivative_xy: &problem.geometry_seed.section_dir_derivative_xy,
        closed: seed_is_closed(&problem.geometry_seed),
    };
    let geometry = frame_sampler
        .sample_at_interval_tau(interval, tau)
        .expect("valid coherent section-frame bike v1 progress guard sample");
    let state_values =
        bike_v1_collocation_state_values_at_tau(problem.decision_layout, x, interval, tau);
    let state = problem.state_from_values(&state_values);
    let control = problem.control_from_decision(x, interval);
    let coherent_geometry = SectionFrameGeometry::from_dense(geometry)
        .expect("non-degenerate coherent section-frame bike v1 progress guard sample");
    let progress = section_frame_progress_from_derivatives(
        state.n_m,
        state.v_mps,
        state.beta_rad,
        state.xi_rad,
        coherent_geometry.ref_tangent_xy,
        coherent_geometry.ref_left_normal_xy,
        coherent_geometry.centerline_derivative_xy,
        coherent_geometry.section_dir_xy,
        coherent_geometry.section_dir_derivative_xy,
    );
    let centerline_kappa =
        curvature_from_derivatives(geometry.centerline_ds, geometry.centerline_d2s);
    let pure_frenet = pure_frenet_path_factor(state.n_m, centerline_kappa);
    let heading_projection = heading_forward_projection(state.beta_rad, state.xi_rad);
    let forward_deficit = (problem.options.debug_v1_progress_guard_min_forward
        - progress.forward_progress_per_speed)
        .max(0.0);
    let pure_frenet_deficit =
        (problem.options.debug_v1_progress_guard_min_pure_frenet - pure_frenet).max(0.0);
    let heading_deficit = (problem
        .options
        .debug_v1_progress_guard_min_heading_projection
        - heading_projection)
        .max(0.0);
    if forward_deficit <= 0.0 && pure_frenet_deficit <= 0.0 && heading_deficit <= 0.0 {
        return 0.0;
    }
    let power_w = (state.v_mps * control.f_drive_n).max(0.0);
    let power_util = power_w / problem.params.base.power_max_w.max(1.0);
    let power_factor = if problem.options.debug_v1_progress_guard_power_coupled {
        ((power_util - 0.80) / 0.20).clamp(0.0, 1.0)
    } else {
        1.0
    };
    let scale = problem.options.debug_v1_progress_guard_scale;
    let forward_normalized = forward_deficit / scale;
    let pure_frenet_normalized = pure_frenet_deficit / scale;
    let heading_normalized = heading_deficit / scale;
    power_factor
        * power_factor
        * (forward_normalized * forward_normalized
            + pure_frenet_normalized * pure_frenet_normalized
            + heading_normalized * heading_normalized)
}

fn bike_v1_kamm_margin_guard_component_count(problem: &BikeV1ExperimentalProblem) -> usize {
    if problem.options.debug_v1_kamm_margin_guard_weight <= 0.0 {
        return 0;
    }
    let station_components = problem.decision_layout.dimensions.station_count * 2;
    let collocation_components = problem.decision_layout.dimensions.interval_count
        * problem.decision_layout.collocation_degree
        * 2;
    let dense_components = problem.decision_layout.dimensions.interval_count
        * problem.options.debug_v1_kamm_margin_guard_dense_samples
        * 2;
    station_components + collocation_components + dense_components
}

fn bike_v1_kamm_margin_guard_objective_s(problem: &BikeV1ExperimentalProblem, x: &[f64]) -> f64 {
    let component_count = bike_v1_kamm_margin_guard_component_count(problem);
    if component_count == 0 {
        return 0.0;
    }
    let mut sum = 0.0;
    for station in 0..problem.decision_layout.dimensions.station_count {
        sum += bike_v1_kamm_margin_guard_sample_sum(
            problem,
            x,
            BikeV1ExperimentalSample::Station { interval: station },
        );
    }
    for interval in 0..problem.decision_layout.dimensions.interval_count {
        for point in 0..problem.decision_layout.collocation_degree {
            sum += bike_v1_kamm_margin_guard_sample_sum(
                problem,
                x,
                BikeV1ExperimentalSample::Collocation { interval, point },
            );
        }
        for dense_sample in 0..problem.options.debug_v1_kamm_margin_guard_dense_samples {
            sum += bike_v1_kamm_margin_guard_dense_sample_sum(problem, x, interval, dense_sample);
        }
    }
    problem.options.debug_v1_kamm_margin_guard_weight * sum / component_count as f64
}

fn bike_v1_kamm_margin_guard_objective_for_sector_s(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    interval: usize,
) -> f64 {
    let component_count = bike_v1_kamm_margin_guard_component_count(problem);
    if component_count == 0 {
        return 0.0;
    }
    let mut sum = 0.0;
    let station_count = problem.decision_layout.dimensions.station_count;
    if station_count > 0 {
        sum += bike_v1_kamm_margin_guard_sample_sum(
            problem,
            x,
            BikeV1ExperimentalSample::Station {
                interval: interval.min(station_count - 1),
            },
        );
    }
    if interval < problem.decision_layout.dimensions.interval_count {
        for point in 0..problem.decision_layout.collocation_degree {
            sum += bike_v1_kamm_margin_guard_sample_sum(
                problem,
                x,
                BikeV1ExperimentalSample::Collocation { interval, point },
            );
        }
        for dense_sample in 0..problem.options.debug_v1_kamm_margin_guard_dense_samples {
            sum += bike_v1_kamm_margin_guard_dense_sample_sum(problem, x, interval, dense_sample);
        }
    }
    problem.options.debug_v1_kamm_margin_guard_weight * sum / component_count as f64
}

fn bike_v1_kamm_margin_guard_objective_for_indices_s(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    affected: &BikeV1ComplexRegularizationAffected,
) -> f64 {
    let component_count = bike_v1_kamm_margin_guard_component_count(problem);
    if component_count == 0 {
        return 0.0;
    }
    let mut sum = 0.0;
    let station_count = problem.decision_layout.dimensions.station_count;
    for &station in &affected.stations {
        if station < station_count {
            sum += bike_v1_kamm_margin_guard_sample_sum(
                problem,
                x,
                BikeV1ExperimentalSample::Station { interval: station },
            );
        }
    }
    for &segment in &affected.segments {
        if segment < problem.decision_layout.dimensions.interval_count {
            for point in 0..problem.decision_layout.collocation_degree {
                sum += bike_v1_kamm_margin_guard_sample_sum(
                    problem,
                    x,
                    BikeV1ExperimentalSample::Collocation {
                        interval: segment,
                        point,
                    },
                );
            }
            for dense_sample in 0..problem.options.debug_v1_kamm_margin_guard_dense_samples {
                sum +=
                    bike_v1_kamm_margin_guard_dense_sample_sum(problem, x, segment, dense_sample);
            }
        }
    }
    problem.options.debug_v1_kamm_margin_guard_weight * sum / component_count as f64
}

fn bike_v1_kamm_margin_guard_dense_tau(dense_sample: usize, dense_sample_count: usize) -> f64 {
    if dense_sample_count == 0 {
        return 0.0;
    }
    (dense_sample + 1) as f64 / (dense_sample_count + 1) as f64
}

fn bike_v1_kamm_margin_guard_dense_sample_sum(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    interval: usize,
    dense_sample: usize,
) -> f64 {
    let dense_sample_count = problem.options.debug_v1_kamm_margin_guard_dense_samples;
    if dense_sample_count == 0 || interval >= problem.decision_layout.dimensions.interval_count {
        return 0.0;
    }
    let tau = bike_v1_kamm_margin_guard_dense_tau(dense_sample, dense_sample_count);
    let geometry = interpolated_sections_geometry(&problem.geometry_seed, interval, tau);
    let state_values =
        bike_v1_collocation_state_values_at_tau(problem.decision_layout, x, interval, tau);
    let state = problem.state_from_values(&state_values);
    let control = problem.control_from_decision(x, interval);
    let mut tire = bike_v1_dynamics_with_sections_geometry(
        problem.feedback_params(),
        state,
        control,
        geometry.kappa_1pm,
        geometry,
        problem.options.debug_v1_smooth_tire_load_clamp,
        problem.options.debug_v1_smooth_tire_load_eps_n,
        problem.options.debug_v1_load_transfer_gain,
        problem.options.debug_v1_lean_residual_quasi_steady,
        problem.options.debug_v1_direct_delta_rate_steering,
        problem.options.debug_v1_steering_actuator_mode,
        problem.options.debug_v1_delta_cmd_tau_s,
        problem.options.debug_v1_steering_torque_residual_scale,
        problem.options.moto_v1_tire_force_mode,
        problem.options.moto_v1_progress_mode,
    )
    .tire_forces;

    let high_frequency_gain = problem.options.debug_v1_load_feedback_filter_gain;
    if high_frequency_gain < 1.0 - 1e-12 {
        let station_count = problem.decision_layout.dimensions.station_count;
        if station_count >= 3 {
            let clamped_interval = interval.min(station_count.saturating_sub(1));
            let previous = if clamped_interval == 0 {
                station_count - 1
            } else {
                clamped_interval - 1
            };
            let next = next_station_index(station_count, clamped_interval);
            let mut front_sum = 0.0;
            let mut rear_sum = 0.0;
            let mut count = 0.0;
            for station in [previous, clamped_interval, next] {
                let station_tire = problem.station_dynamics(x, station).tire_forces;
                front_sum += station_tire.fz_front_n;
                rear_sum += station_tire.fz_rear_n;
                count += 1.0;
            }
            if count > 0.0 {
                let front_low = front_sum / count;
                let rear_low = rear_sum / count;
                tire.fz_front_n = front_low + high_frequency_gain * (tire.fz_front_n - front_low);
                tire.fz_rear_n = rear_low + high_frequency_gain * (tire.fz_rear_n - rear_low);
            }
        }
    }

    bike_v1_kamm_margin_guard_tire_sum(problem, tire)
}

fn bike_v1_kamm_margin_guard_sample_sum(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    sample: BikeV1ExperimentalSample,
) -> f64 {
    let tire = problem.sample_capacity_constraint_tire_forces(x, sample);
    bike_v1_kamm_margin_guard_tire_sum(problem, tire)
}

fn bike_v1_kamm_margin_guard_tire_sum(
    problem: &BikeV1ExperimentalProblem,
    tire: crate::bike_dynamics_v1::BikeCountersteerLeanTireForcesV1,
) -> f64 {
    ["front", "rear"]
        .into_iter()
        .map(|axle| {
            let kamm = bike_v1_kamm_for_axle(
                problem.params,
                tire,
                axle,
                problem.options.load_sensitive_kamm_denominator,
            );
            let excess = ((kamm - problem.options.debug_v1_kamm_margin_guard_limit)
                / BIKE_V1_KAMM_MARGIN_GUARD_SCALE)
                .max(0.0);
            excess * excess
        })
        .sum()
}

fn bike_v1_block_slack_component_count(problem: &BikeV1ExperimentalProblem) -> usize {
    if !problem.options.debug_v1_block_slack_mode.is_enabled()
        || problem.options.debug_v1_block_slack_weight <= 0.0
    {
        return 0;
    }
    problem
        .rows
        .iter()
        .filter(|row| {
            bike_v1_block_slack_row_matches(problem.options.debug_v1_block_slack_mode, **row)
        })
        .count()
}

fn bike_v1_block_slack_objective_s(problem: &BikeV1ExperimentalProblem, x: &[f64]) -> f64 {
    let component_count = bike_v1_block_slack_component_count(problem);
    if component_count == 0 {
        return 0.0;
    }
    let mut sum = 0.0;
    for (row_index, row) in problem.rows.iter().enumerate() {
        if !bike_v1_block_slack_row_matches(problem.options.debug_v1_block_slack_mode, *row) {
            continue;
        }
        let Some(normalized_slack) =
            bike_v1_block_slack_normalized_violation(problem, x, row_index)
        else {
            continue;
        };
        sum += normalized_slack * normalized_slack;
    }
    problem.options.debug_v1_block_slack_weight * sum / component_count as f64
}

fn bike_v1_block_slack_objective_for_sector_s(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    interval: usize,
) -> f64 {
    let component_count = bike_v1_block_slack_component_count(problem);
    if component_count == 0 {
        return 0.0;
    }
    let mut sum = 0.0;
    for (row_index, row) in problem.rows.iter().enumerate() {
        if !bike_v1_block_slack_row_matches(problem.options.debug_v1_block_slack_mode, *row) {
            continue;
        }
        if problem.basin_row_interval(*row) != Some(interval) {
            continue;
        }
        let Some(normalized_slack) =
            bike_v1_block_slack_normalized_violation(problem, x, row_index)
        else {
            continue;
        };
        sum += normalized_slack * normalized_slack;
    }
    problem.options.debug_v1_block_slack_weight * sum / component_count as f64
}

fn bike_v1_block_slack_normalized_violation(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    row_index: usize,
) -> Option<f64> {
    let row = *problem.rows.get(row_index)?;
    let value = problem.constraint_value(x, row).ok()?;
    let lower = *problem.hard_constraint_lower_bounds.get(row_index)?;
    let upper = *problem.hard_constraint_upper_bounds.get(row_index)?;
    let signed = signed_constraint_bound_violation(value, lower, upper)?;
    let scale = problem
        .constraint_scales
        .get(row_index)
        .copied()
        .unwrap_or(1.0)
        .max(1.0e-12);
    Some(signed / scale)
}

fn signed_constraint_bound_violation(value: f64, lower: f64, upper: f64) -> Option<f64> {
    if lower.is_finite() && upper.is_finite() && (upper - lower).abs() <= 1.0e-12 {
        return Some(value - lower);
    }
    if lower.is_finite() && value < lower {
        return Some(value - lower);
    }
    if upper.is_finite() && value > upper {
        return Some(value - upper);
    }
    if lower.is_finite() || upper.is_finite() {
        return Some(0.0);
    }
    None
}

fn add_bike_v1_block_slack_gradient_structured(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    gradient: &mut [f64],
) -> Result<(), String> {
    let component_count = bike_v1_block_slack_component_count(problem);
    if component_count == 0 {
        return Ok(());
    }
    let factor = 2.0 * problem.options.debug_v1_block_slack_weight / component_count as f64;
    let mut plus = x.to_vec();
    let mut minus = x.to_vec();
    for (row_i32, variable_i32) in &problem.jacobian_pattern {
        let row_index =
            usize::try_from(*row_i32).map_err(|_| "negative V1 block-slack row".to_owned())?;
        let variable_index = usize::try_from(*variable_i32)
            .map_err(|_| "negative V1 block-slack variable".to_owned())?;
        let Some(row) = problem.rows.get(row_index).copied() else {
            continue;
        };
        if !bike_v1_block_slack_row_matches(problem.options.debug_v1_block_slack_mode, row) {
            continue;
        }
        let Some(normalized_slack) =
            bike_v1_block_slack_normalized_violation(problem, x, row_index)
        else {
            continue;
        };
        if normalized_slack == 0.0 {
            continue;
        }
        let scale = problem
            .constraint_scales
            .get(row_index)
            .copied()
            .unwrap_or(1.0)
            .max(1.0e-12);
        let derivative = if let Some(value) =
            problem.constraint_derivative_structured(x, row_index, variable_index)
        {
            value
        } else {
            problem.constraint_derivative_finite_difference(
                &mut plus,
                &mut minus,
                x,
                row_index,
                variable_index,
                1.0e-6,
            )?
        };
        gradient[variable_index] += factor * normalized_slack * derivative / scale;
    }
    Ok(())
}

fn bike_v1_block_slack_diagnostics_json(
    problem: &BikeV1ExperimentalProblem,
    initial_x: &[f64],
    final_x: &[f64],
    final_lap_time_s: f64,
) -> JsonValue {
    let component_count = bike_v1_block_slack_component_count(problem);
    let final_objective_s = bike_v1_block_slack_objective_s(problem, final_x);
    JsonValue::Object(vec![
        (
            "schema_version".to_owned(),
            "bike_v1_debug_block_slack.v1".into(),
        ),
        (
            "mode".to_owned(),
            problem.options.debug_v1_block_slack_mode.as_str().into(),
        ),
        (
            "weight".to_owned(),
            json_number(problem.options.debug_v1_block_slack_weight),
        ),
        (
            "report_enabled".to_owned(),
            JsonValue::Bool(problem.options.debug_v1_block_slack_report),
        ),
        (
            "selected_row_count".to_owned(),
            JsonValue::Integer(component_count as i64),
        ),
        (
            "objective_s_final".to_owned(),
            json_number(final_objective_s),
        ),
        (
            "objective_over_lap_time_final".to_owned(),
            json_number(final_objective_s / final_lap_time_s.max(1.0e-9)),
        ),
        (
            "note".to_owned(),
            "Diagnostic-only eliminated-slack mode: selected hard constraint bounds are relaxed in Ipopt, while the original hard-bound violation is penalized and reported. Do not use as product feasibility.".into(),
        ),
        (
            "initial".to_owned(),
            bike_v1_block_slack_state_summary_json(problem, initial_x, component_count),
        ),
        (
            "final".to_owned(),
            bike_v1_block_slack_state_summary_json(problem, final_x, component_count),
        ),
    ])
}

fn bike_v1_block_slack_state_summary_json(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    component_count: usize,
) -> JsonValue {
    let mut all = BikeV1BlockSlackStats::default();
    let mut by_subfamily: BTreeMap<&'static str, BikeV1BlockSlackStats> = BTreeMap::new();
    let mut by_sector: BTreeMap<usize, BikeV1BlockSlackStats> = BTreeMap::new();
    let mut rows = Vec::new();
    for (row_index, row) in problem.rows.iter().enumerate() {
        if !bike_v1_block_slack_row_matches(problem.options.debug_v1_block_slack_mode, *row) {
            continue;
        }
        let Some(normalized_slack) =
            bike_v1_block_slack_normalized_violation(problem, x, row_index)
        else {
            continue;
        };
        let scale = problem
            .constraint_scales
            .get(row_index)
            .copied()
            .unwrap_or(1.0)
            .max(1.0e-12);
        let abs_slack = normalized_slack.abs();
        let label = row.label();
        bike_v1_add_block_slack_stats(&mut all, row_index, &label, normalized_slack);
        let subfamily = bike_v1_block_slack_row_subfamily(*row);
        bike_v1_add_block_slack_stats(
            by_subfamily.entry(subfamily).or_default(),
            row_index,
            &label,
            normalized_slack,
        );
        let interval = problem.basin_row_interval(*row);
        if let Some(interval) = interval {
            bike_v1_add_block_slack_stats(
                by_sector.entry(interval).or_default(),
                row_index,
                &label,
                normalized_slack,
            );
        }
        rows.push((
            abs_slack,
            JsonValue::Object(vec![
                ("row_index".to_owned(), JsonValue::Integer(row_index as i64)),
                ("label".to_owned(), label.into()),
                ("subfamily".to_owned(), subfamily.into()),
                (
                    "interval".to_owned(),
                    interval
                        .map(|value| JsonValue::Integer(value as i64))
                        .unwrap_or(JsonValue::Null),
                ),
                (
                    "signed_normalized_slack".to_owned(),
                    json_number(normalized_slack),
                ),
                ("abs_normalized_slack".to_owned(), json_number(abs_slack)),
                (
                    "signed_physical_slack".to_owned(),
                    json_number(normalized_slack * scale),
                ),
                ("scale".to_owned(), json_number(scale)),
            ]),
        ));
    }
    rows.sort_by(|left, right| {
        right
            .0
            .partial_cmp(&left.0)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    let max_sector_sum_sq = by_sector
        .values()
        .map(|stats| stats.sum_sq)
        .fold(0.0, f64::max);
    let sector_localized_fraction = if all.sum_sq > 0.0 {
        max_sector_sum_sq / all.sum_sq
    } else {
        0.0
    };
    let objective_s = if component_count == 0 {
        0.0
    } else {
        problem.options.debug_v1_block_slack_weight * all.sum_sq / component_count as f64
    };
    JsonValue::Object(vec![
        ("all".to_owned(), bike_v1_block_slack_stats_json(&all)),
        ("objective_s".to_owned(), json_number(objective_s)),
        (
            "sector_localized_fraction".to_owned(),
            json_number(sector_localized_fraction),
        ),
        (
            "by_subfamily".to_owned(),
            JsonValue::Array(
                by_subfamily
                    .into_iter()
                    .map(|(subfamily, stats)| {
                        let mut value = bike_v1_block_slack_stats_json(&stats);
                        if let JsonValue::Object(fields) = &mut value {
                            fields.insert(0, ("subfamily".to_owned(), subfamily.into()));
                        }
                        value
                    })
                    .collect(),
            ),
        ),
        (
            "by_sector".to_owned(),
            JsonValue::Array(
                by_sector
                    .into_iter()
                    .map(|(interval, stats)| {
                        let mut value = bike_v1_block_slack_stats_json(&stats);
                        if let JsonValue::Object(fields) = &mut value {
                            fields.insert(
                                0,
                                ("interval".to_owned(), JsonValue::Integer(interval as i64)),
                            );
                        }
                        value
                    })
                    .collect(),
            ),
        ),
        (
            "top_rows".to_owned(),
            JsonValue::Array(rows.into_iter().take(16).map(|(_, row)| row).collect()),
        ),
    ])
}

fn bike_v1_add_block_slack_stats(
    stats: &mut BikeV1BlockSlackStats,
    row_index: usize,
    label: &str,
    normalized_slack: f64,
) {
    stats.count += 1;
    stats.sum_sq += normalized_slack * normalized_slack;
    let abs_slack = normalized_slack.abs();
    if abs_slack >= stats.max_abs {
        stats.max_abs = abs_slack;
        stats.max_abs_row = row_index;
        stats.max_abs_label = label.to_owned();
    }
}

fn bike_v1_block_slack_stats_json(stats: &BikeV1BlockSlackStats) -> JsonValue {
    let rms = if stats.count == 0 {
        0.0
    } else {
        (stats.sum_sq / stats.count as f64).sqrt()
    };
    JsonValue::Object(vec![
        ("count".to_owned(), JsonValue::Integer(stats.count as i64)),
        ("rms_normalized_slack".to_owned(), json_number(rms)),
        (
            "max_abs_normalized_slack".to_owned(),
            json_number(stats.max_abs),
        ),
        (
            "max_abs_row_index".to_owned(),
            JsonValue::Integer(stats.max_abs_row as i64),
        ),
        (
            "max_abs_label".to_owned(),
            stats.max_abs_label.clone().into(),
        ),
    ])
}

fn bike_v1_steering_shadow_gate_component_count(problem: &BikeV1ExperimentalProblem) -> usize {
    if problem.options.debug_v1_steering_shadow_gate_weight <= 0.0 {
        return 0;
    }
    if !problem.options.debug_v1_direct_delta_rate_steering
        && !problem
            .options
            .debug_v1_steering_actuator_mode
            .uses_delta_cmd()
    {
        return 0;
    }
    problem.decision_layout.dimensions.station_count
}

fn bike_v1_steering_shadow_gate_objective_s(problem: &BikeV1ExperimentalProblem, x: &[f64]) -> f64 {
    let component_count = bike_v1_steering_shadow_gate_component_count(problem);
    if component_count == 0 {
        return 0.0;
    }
    let sum = (0..problem.decision_layout.dimensions.station_count)
        .map(|station| bike_v1_steering_shadow_gate_station_sum(problem, x, station))
        .sum::<f64>();
    problem.options.debug_v1_steering_shadow_gate_weight * sum / component_count as f64
}

fn bike_v1_steering_shadow_gate_objective_for_sector_s(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    interval: usize,
) -> f64 {
    let component_count = bike_v1_steering_shadow_gate_component_count(problem);
    if component_count == 0 || problem.decision_layout.dimensions.station_count == 0 {
        return 0.0;
    }
    let station = interval.min(problem.decision_layout.dimensions.station_count - 1);
    problem.options.debug_v1_steering_shadow_gate_weight
        * bike_v1_steering_shadow_gate_station_sum(problem, x, station)
        / component_count as f64
}

fn bike_v1_steering_shadow_gate_station_sum(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    station: usize,
) -> f64 {
    if station >= problem.decision_layout.dimensions.station_count {
        return 0.0;
    }
    let state = problem.station_state_from_decision(x, station);
    let control_interval = bike_v1_station_publication_interval(problem.decision_layout, station);
    let control = problem.control_from_decision(x, control_interval);
    let dynamics = problem.station_dynamics(x, station);
    let params = problem.params;
    let torque_scale = params.steering_torque_max_nm.max(1.0);
    let delta_rate_limit =
        (params.base.steering_angle_max_rad / params.base.steering_response_s.max(0.02)).max(1.0);
    let commanded_delta_rate = if problem
        .options
        .debug_v1_steering_actuator_mode
        .uses_delta_cmd()
    {
        let delta_cmd = control.steering_torque_nm.clamp(
            -params.base.steering_angle_max_rad,
            params.base.steering_angle_max_rad,
        );
        ((delta_cmd - state.delta_rad) / problem.options.debug_v1_delta_cmd_tau_s.max(0.02))
            .clamp(-delta_rate_limit, delta_rate_limit)
    } else if problem.options.debug_v1_direct_delta_rate_steering {
        (control.steering_torque_nm / torque_scale).clamp(-1.0, 1.0) * delta_rate_limit
    } else {
        state.delta_dot_radps
    };
    let steering_tau = params.base.steering_response_s.max(0.02);
    let debug_delta_accel = if problem.options.debug_v1_direct_delta_rate_steering
        || problem
            .options
            .debug_v1_steering_actuator_mode
            .uses_delta_cmd()
    {
        (commanded_delta_rate - state.delta_dot_radps) / steering_tau
    } else {
        dynamics.steering_net_torque_nm / params.steering_inertia_kgm2.max(1e-9)
    };
    let physical_delta_accel =
        dynamics.steering_net_torque_nm / params.steering_inertia_kgm2.max(1e-9);
    let command_gap = (commanded_delta_rate - state.delta_dot_radps) / delta_rate_limit;
    let hidden_control_gap =
        (params.steering_inertia_kgm2 * (debug_delta_accel - physical_delta_accel)) / torque_scale;
    command_gap * command_gap + hidden_control_gap * hidden_control_gap
}

fn bike_v1_force_loop_smooth_force_scale(problem: &BikeV1ExperimentalProblem) -> f64 {
    (problem.params.base.rider_bike_mass_kg * problem.params.base.gravity_mps2).max(1.0)
}

fn bike_v1_force_loop_smooth_component_count(problem: &BikeV1ExperimentalProblem) -> usize {
    if problem.options.debug_v1_force_loop_smooth_weight <= 0.0 {
        return 0;
    }
    let station_count = problem.decision_layout.dimensions.station_count;
    if station_count < 3 {
        return 0;
    }
    station_count * 4
}

fn bike_v1_force_loop_smooth_station_terms(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    station: usize,
) -> [f64; 4] {
    let dynamics = problem.station_dynamics(x, station);
    let scale = bike_v1_force_loop_smooth_force_scale(problem);
    [
        dynamics.tire_forces.fy_front_n / scale,
        dynamics.tire_forces.fy_rear_n / scale,
        dynamics.tire_forces.fz_front_n / scale,
        dynamics.tire_forces.fz_rear_n / scale,
    ]
}

fn bike_v1_force_loop_smooth_center_sum(left: [f64; 4], center: [f64; 4], right: [f64; 4]) -> f64 {
    let mut sum = 0.0;
    for index in 0..4 {
        let diff = left[index] - 2.0 * center[index] + right[index];
        sum += diff * diff;
    }
    sum
}

fn bike_v1_force_loop_smooth_objective_s(problem: &BikeV1ExperimentalProblem, x: &[f64]) -> f64 {
    let component_count = bike_v1_force_loop_smooth_component_count(problem);
    if component_count == 0 {
        return 0.0;
    }
    let station_count = problem.decision_layout.dimensions.station_count;
    let closed = seed_is_closed(&problem.geometry_seed);
    let mut total = 0.0;
    if closed {
        for station in 0..station_count {
            let left = (station + station_count - 1) % station_count;
            let right = (station + 1) % station_count;
            total += bike_v1_force_loop_smooth_center_sum(
                bike_v1_force_loop_smooth_station_terms(problem, x, left),
                bike_v1_force_loop_smooth_station_terms(problem, x, station),
                bike_v1_force_loop_smooth_station_terms(problem, x, right),
            );
        }
    } else {
        for station in 1..station_count - 1 {
            total += bike_v1_force_loop_smooth_center_sum(
                bike_v1_force_loop_smooth_station_terms(problem, x, station - 1),
                bike_v1_force_loop_smooth_station_terms(problem, x, station),
                bike_v1_force_loop_smooth_station_terms(problem, x, station + 1),
            );
        }
    }
    problem.options.debug_v1_force_loop_smooth_weight * total / component_count as f64
}

fn bike_v1_force_loop_smooth_terms_from_complex_station(
    terms: BikeV1ComplexStationTerms,
) -> [f64; 4] {
    [
        terms.front_fy_norm,
        terms.rear_fy_norm,
        terms.front_fz_norm,
        terms.rear_fz_norm,
    ]
}

fn bike_v1_force_loop_smooth_objective_for_indices_s(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    affected: &BikeV1ComplexRegularizationAffected,
) -> f64 {
    let component_count = bike_v1_force_loop_smooth_component_count(problem);
    if component_count == 0 || affected.stations.is_empty() {
        return 0.0;
    }
    let station_count = problem.decision_layout.dimensions.station_count;
    let closed = seed_is_closed(&problem.geometry_seed);
    let mut centers = BTreeSet::new();
    for &station in &affected.stations {
        bike_v1_insert_station_index(&mut centers, station_count, closed, station as isize - 1);
        bike_v1_insert_station_index(&mut centers, station_count, closed, station as isize);
        bike_v1_insert_station_index(&mut centers, station_count, closed, station as isize + 1);
    }

    let mut cache: BTreeMap<usize, BikeV1ComplexStationTerms> = BTreeMap::new();
    let mut terms_for = |station: usize| -> BikeV1ComplexStationTerms {
        if let Some(terms) = cache.get(&station) {
            return *terms;
        }
        let state = bike_v1_state_from_decision(problem.decision_layout, x, station);
        let dynamics = problem.station_dynamics(x, station);
        let params = problem.params;
        let force_scale = bike_v1_force_loop_smooth_force_scale(problem);
        let steady_phi = (dynamics.ay_mps2 / params.base.gravity_mps2.max(1e-9)).atan();
        let terms = BikeV1ComplexStationTerms {
            steering_net_torque: dynamics.steering_net_torque_nm
                / params.steering_torque_max_nm.max(1.0),
            phi_eq_error: (steady_phi - state.phi_rad) / BIKE_LEAN_EQUILIBRIUM_SCALE_RAD,
            phi_eq: steady_phi,
            ay: dynamics.ay_mps2 / params.base.lean_limited_lateral_accel_mps2().max(1.0),
            sigma_dt_ds: dynamics.sigma_dt_ds,
            front_fy_norm: dynamics.tire_forces.fy_front_n / force_scale,
            rear_fy_norm: dynamics.tire_forces.fy_rear_n / force_scale,
            front_fz_norm: dynamics.tire_forces.fz_front_n / force_scale,
            rear_fz_norm: dynamics.tire_forces.fz_rear_n / force_scale,
        };
        cache.insert(station, terms);
        terms
    };

    let mut total = 0.0;
    for center in centers {
        if !closed && (center == 0 || center + 1 >= station_count) {
            continue;
        }
        let left = if center == 0 {
            station_count - 1
        } else {
            center - 1
        };
        let right = if center + 1 == station_count {
            0
        } else {
            center + 1
        };
        total += bike_v1_force_loop_smooth_center_sum(
            bike_v1_force_loop_smooth_terms_from_complex_station(terms_for(left)),
            bike_v1_force_loop_smooth_terms_from_complex_station(terms_for(center)),
            bike_v1_force_loop_smooth_terms_from_complex_station(terms_for(right)),
        );
    }
    problem.options.debug_v1_force_loop_smooth_weight * total / component_count as f64
}

#[cfg(test)]
fn bike_v1_complex_regularization_objective_profiled_s(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    mut profile: Option<&mut BikeV1CallbackProfile>,
) -> f64 {
    let weights = problem.objective_weights;
    let params = problem.params;
    let closed = seed_is_closed(&problem.geometry_seed);
    let interval_count = problem.decision_layout.dimensions.interval_count;
    let station_count = problem.decision_layout.dimensions.station_count;

    let torque_scale = params.steering_torque_max_nm.max(1.0);
    let lean_rate_scale = params.base.lean_rate_max_radps.max(1e-9);
    let ay_scale = params.base.lean_limited_lateral_accel_mps2().max(1.0);

    let mut steering_net_torque = Vec::with_capacity(station_count);
    let mut phi_eq_error = Vec::with_capacity(station_count);
    let mut phi_eq = Vec::with_capacity(station_count);
    let mut ay = Vec::with_capacity(station_count);
    let mut dt = Vec::with_capacity(station_count);
    let station_series_start = Instant::now();
    for station in 0..station_count {
        let state = bike_v1_state_from_decision(problem.decision_layout, x, station);
        let dynamics = problem.station_dynamics(x, station);
        steering_net_torque.push(dynamics.steering_net_torque_nm / torque_scale);
        let steady_phi = (dynamics.ay_mps2 / params.base.gravity_mps2.max(1e-9)).atan();
        phi_eq_error.push((steady_phi - state.phi_rad) / BIKE_LEAN_EQUILIBRIUM_SCALE_RAD);
        phi_eq.push(steady_phi);
        ay.push(dynamics.ay_mps2 / ay_scale);

        let previous = if station == 0 {
            station_count.saturating_sub(1)
        } else {
            station - 1
        };
        let interval = if station == 0 {
            interval_count.saturating_sub(1)
        } else {
            station - 1
        };
        let previous_dynamics = problem.station_dynamics(x, previous);
        dt.push(
            0.5 * (dynamics.sigma_dt_ds + previous_dynamics.sigma_dt_ds).max(1e-9)
                * problem.interval_ds_m.get(interval).copied().unwrap_or(1.0),
        );
    }
    if let Some(profile) = profile.as_deref_mut() {
        profile.add_objective_term(
            "fallback.regularization.station_dynamics_series",
            station_series_start.elapsed(),
        );
    }

    let mut phi_eq_rate = Vec::with_capacity(station_count);
    let mut ay_rate = Vec::with_capacity(station_count);
    let segment_count = if closed {
        station_count
    } else {
        station_count.saturating_sub(1)
    };
    for index in 0..segment_count {
        let next = if index + 1 == station_count {
            0
        } else {
            index + 1
        };
        let segment_dt = dt[next].max(1e-9);
        phi_eq_rate.push((phi_eq[next] - phi_eq[index]) / segment_dt / lean_rate_scale);
        ay_rate.push((ay[next] - ay[index]) / segment_dt);
    }

    let mut term = |name: &'static str, value_fn: &dyn Fn() -> f64| -> f64 {
        let start = Instant::now();
        let value = value_fn();
        if let Some(profile) = profile.as_deref_mut() {
            profile.add_objective_term(name, start.elapsed());
        }
        value
    };

    term("fallback.regularization.steering_net_torque", &|| {
        weights.penalty_roll_tau * sum_squared(&steering_net_torque)
    }) + term("fallback.regularization.phi_eq_error", &|| {
        weights.penalty_lean_equilibrium * sum_squared(&phi_eq_error)
    }) + term("fallback.regularization.phi_eq_rate", &|| {
        weights.penalty_phi_eq_rate * sum_squared(&phi_eq_rate)
    }) + term("fallback.regularization.ay_rate", &|| {
        weights.penalty_ay_rate * sum_squared(&ay_rate)
    }) + term(
        "fallback.regularization.debug_steering_shadow_gate",
        &|| bike_v1_steering_shadow_gate_objective_s(problem, x),
    ) + term(
        "fallback.regularization.v1_steering_time_normalized",
        &|| bike_v1_time_normalized_steering_regularization_objective_s(problem, x),
    ) + term(
        "fallback.regularization.v1_steering_authority_envelope",
        &|| bike_v1_steering_authority_envelope_objective_s(problem, x),
    ) + term("fallback.regularization.debug_kamm_margin_guard", &|| {
        bike_v1_kamm_margin_guard_objective_s(problem, x)
    }) + term("fallback.regularization.debug_dense_shape_guard", &|| {
        bike_v1_dense_shape_guard_objective_s(problem, x)
    }) + term("fallback.regularization.debug_yaw_path_guard", &|| {
        bike_v1_yaw_path_guard_objective_s(problem, x)
    }) + term("fallback.regularization.debug_force_loop_smooth", &|| {
        bike_v1_force_loop_smooth_objective_s(problem, x)
    }) + term("fallback.regularization.debug_progress_guard", &|| {
        bike_v1_progress_guard_objective_s(problem, x)
    })
}

#[derive(Clone, Debug, Default)]
struct BikeV1ComplexRegularizationAffected {
    stations: Vec<usize>,
    segments: Vec<usize>,
}

impl BikeV1ComplexRegularizationAffected {
    fn from_sets(stations: BTreeSet<usize>, segments: BTreeSet<usize>) -> Self {
        Self {
            stations: stations.into_iter().collect(),
            segments: segments.into_iter().collect(),
        }
    }
}

#[derive(Clone, Copy, Debug)]
struct BikeV1ComplexStationTerms {
    steering_net_torque: f64,
    phi_eq_error: f64,
    phi_eq: f64,
    ay: f64,
    sigma_dt_ds: f64,
    front_fy_norm: f64,
    rear_fy_norm: f64,
    front_fz_norm: f64,
    rear_fz_norm: f64,
}

fn bike_v1_complex_regularization_terms_for_indices(
    problem: &BikeV1ExperimentalProblem,
    x: &[f64],
    affected: &BikeV1ComplexRegularizationAffected,
    profile: Option<&mut BikeV1CallbackProfile>,
) -> f64 {
    let weights = problem.objective_weights;
    let params = problem.params;
    let station_count = problem.decision_layout.dimensions.station_count;
    let torque_scale = params.steering_torque_max_nm.max(1.0);
    let lean_rate_scale = params.base.lean_rate_max_radps.max(1e-9);
    let ay_scale = params.base.lean_limited_lateral_accel_mps2().max(1.0);
    let mut station_cache: BTreeMap<usize, BikeV1ComplexStationTerms> = BTreeMap::new();
    let station_terms_start = Instant::now();

    let mut station_terms_for = |station: usize| -> BikeV1ComplexStationTerms {
        if let Some(terms) = station_cache.get(&station) {
            return *terms;
        }
        let state = bike_v1_state_from_decision(problem.decision_layout, x, station);
        let dynamics = problem.station_dynamics(x, station);
        let steady_phi = (dynamics.ay_mps2 / params.base.gravity_mps2.max(1e-9)).atan();
        let force_scale = bike_v1_force_loop_smooth_force_scale(problem);
        let terms = BikeV1ComplexStationTerms {
            steering_net_torque: dynamics.steering_net_torque_nm / torque_scale,
            phi_eq_error: (steady_phi - state.phi_rad) / BIKE_LEAN_EQUILIBRIUM_SCALE_RAD,
            phi_eq: steady_phi,
            ay: dynamics.ay_mps2 / ay_scale,
            sigma_dt_ds: dynamics.sigma_dt_ds,
            front_fy_norm: dynamics.tire_forces.fy_front_n / force_scale,
            rear_fy_norm: dynamics.tire_forces.fy_rear_n / force_scale,
            front_fz_norm: dynamics.tire_forces.fz_front_n / force_scale,
            rear_fz_norm: dynamics.tire_forces.fz_rear_n / force_scale,
        };
        station_cache.insert(station, terms);
        terms
    };

    let mut total = 0.0;
    for &station in &affected.stations {
        if station >= station_count {
            continue;
        }
        let terms = station_terms_for(station);
        total += weights.penalty_roll_tau * terms.steering_net_torque * terms.steering_net_torque;
        total += weights.penalty_lean_equilibrium * terms.phi_eq_error * terms.phi_eq_error;
        if problem.options.debug_v1_steering_shadow_gate_weight > 0.0 {
            total += problem.options.debug_v1_steering_shadow_gate_weight
                * bike_v1_steering_shadow_gate_station_sum(problem, x, station)
                / bike_v1_steering_shadow_gate_component_count(problem).max(1) as f64;
        }
    }

    let segment_count = if seed_is_closed(&problem.geometry_seed) {
        station_count
    } else {
        station_count.saturating_sub(1)
    };
    for &segment in &affected.segments {
        if segment >= segment_count || station_count == 0 {
            continue;
        }
        let next = if segment + 1 == station_count {
            0
        } else {
            segment + 1
        };
        let left = station_terms_for(segment);
        let right = station_terms_for(next);
        let interval = if next == 0 {
            problem
                .decision_layout
                .dimensions
                .interval_count
                .saturating_sub(1)
        } else {
            next - 1
        };
        let segment_dt = 0.5
            * (right.sigma_dt_ds + left.sigma_dt_ds).max(1e-9)
            * problem.interval_ds_m.get(interval).copied().unwrap_or(1.0);
        let phi_eq_rate = (right.phi_eq - left.phi_eq) / segment_dt.max(1e-9) / lean_rate_scale;
        let ay_rate = (right.ay - left.ay) / segment_dt.max(1e-9);
        total += weights.penalty_phi_eq_rate * phi_eq_rate * phi_eq_rate;
        total += weights.penalty_ay_rate * ay_rate * ay_rate;
    }

    if let Some(profile) = profile {
        profile.add_objective_term(
            "fallback.localized.station_dynamics_terms",
            station_terms_start.elapsed(),
        );
    }

    total += bike_v1_kamm_margin_guard_objective_for_indices_s(problem, x, affected);
    total += bike_v1_dense_shape_guard_objective_for_indices_s(problem, x, affected);
    total += bike_v1_yaw_path_guard_objective_for_indices_s(problem, x, affected);
    total += bike_v1_force_loop_smooth_objective_for_indices_s(problem, x, affected);
    total += bike_v1_progress_guard_objective_for_indices_s(problem, x, affected);
    total += bike_v1_time_normalized_steering_regularization_objective_for_indices_s(
        problem, x, affected,
    );
    total += bike_v1_steering_authority_envelope_objective_for_indices_s(problem, x, affected);

    total
}

fn bike_v1_insert_station_index(
    stations: &mut BTreeSet<usize>,
    station_count: usize,
    closed: bool,
    station: isize,
) {
    if station_count == 0 {
        return;
    }
    if closed {
        let count = station_count as isize;
        stations.insert(station.rem_euclid(count) as usize);
    } else if (0..station_count as isize).contains(&station) {
        stations.insert(station as usize);
    }
}

fn bike_v1_insert_segment_index(
    segments: &mut BTreeSet<usize>,
    station_count: usize,
    closed: bool,
    segment: isize,
) {
    let segment_count = if closed {
        station_count
    } else {
        station_count.saturating_sub(1)
    };
    if segment_count == 0 {
        return;
    }
    if closed {
        let count = segment_count as isize;
        segments.insert(segment.rem_euclid(count) as usize);
    } else if (0..segment_count as isize).contains(&segment) {
        segments.insert(segment as usize);
    }
}

fn bike_v1_insert_adjacent_segments(
    segments: &mut BTreeSet<usize>,
    station_count: usize,
    closed: bool,
    station: usize,
) {
    let station = station as isize;
    for offset in -1..=1 {
        bike_v1_insert_segment_index(segments, station_count, closed, station + offset);
    }
}

fn bike_v1_state_from_decision(
    decision_layout: DecisionLayout,
    x: &[f64],
    station: usize,
) -> crate::bike_dynamics_v1::BikeCountersteerLeanStateV1 {
    let offset = decision_layout.state_offset(station);
    crate::bike_mintime_v1::bike_v1_state_from_slice(&x[offset..offset + decision_layout.state_len])
}

fn bike_v1_control_from_decision(
    decision_layout: DecisionLayout,
    x: &[f64],
    interval: usize,
) -> crate::bike_dynamics_v1::BikeCountersteerLeanControlV1 {
    let offset = decision_layout.control_offset(interval);
    crate::bike_mintime_v1::bike_v1_control_from_slice(
        &x[offset..offset + decision_layout.control_len],
    )
}

