fn bike_v1_station_xy_from(
    geometry_seed: &BikeMintimeNlpSeed,
    decision_layout: DecisionLayout,
    x: &[f64],
    station: usize,
) -> Point2 {
    let n = x[decision_layout.state_offset(station) + V1_STATE_N_M];
    [
        geometry_seed.centerline_xy_m[station][0] - geometry_seed.section_dir_xy[station][0] * n,
        geometry_seed.centerline_xy_m[station][1] - geometry_seed.section_dir_xy[station][1] * n,
    ]
}

fn bike_v1_station_publication_interval(decision_layout: DecisionLayout, station: usize) -> usize {
    let interval_count = decision_layout.dimensions.interval_count;
    if interval_count <= 1
        || station == 0 && interval_count < decision_layout.dimensions.station_count
    {
        return 0;
    }
    if station == 0 {
        interval_count - 1
    } else {
        (station - 1).min(interval_count - 1)
    }
}

fn bike_v1_collocation_state_values_at_tau(
    decision_layout: DecisionLayout,
    x: &[f64],
    interval: usize,
    tau: f64,
) -> Vec<f64> {
    let basis = bike_collocation_lagrange_basis_at_tau(tau);
    let mut values = vec![0.0; decision_layout.state_len];
    for state_index in 0..decision_layout.state_len {
        values[state_index] += basis[0] * x[decision_layout.state_offset(interval) + state_index];
        for point in 0..decision_layout.collocation_degree {
            values[state_index] += basis[point + 1]
                * x[decision_layout.collocation_state_offset(interval, point) + state_index];
        }
    }
    values
}

fn bike_v1_collocation_state_derivatives_at_tau(
    decision_layout: DecisionLayout,
    x: &[f64],
    interval: usize,
    tau: f64,
    ds_m: f64,
) -> Vec<f64> {
    let basis = bike_collocation_lagrange_basis_derivative_at_tau(tau);
    let mut values = vec![0.0; decision_layout.state_len];
    for state_index in 0..decision_layout.state_len {
        values[state_index] += basis[0] * x[decision_layout.state_offset(interval) + state_index];
        for point in 0..decision_layout.collocation_degree {
            values[state_index] += basis[point + 1]
                * x[decision_layout.collocation_state_offset(interval, point) + state_index];
        }
        values[state_index] /= ds_m.max(1e-9);
    }
    values
}

fn bike_v1_collocation_state_second_derivatives_at_tau(
    decision_layout: DecisionLayout,
    x: &[f64],
    interval: usize,
    tau: f64,
    ds_m: f64,
) -> Vec<f64> {
    let basis = bike_collocation_lagrange_basis_second_derivative_at_tau(tau);
    let mut values = vec![0.0; decision_layout.state_len];
    for state_index in 0..decision_layout.state_len {
        values[state_index] += basis[0] * x[decision_layout.state_offset(interval) + state_index];
        for point in 0..decision_layout.collocation_degree {
            values[state_index] += basis[point + 1]
                * x[decision_layout.collocation_state_offset(interval, point) + state_index];
        }
        values[state_index] /= ds_m.max(1e-9).powi(2);
    }
    values
}

