const STRICT_DENSE_KAMM_CLEAN_MAX: f64 = 1.002;
const PRODUCT_DENSE_KAMM_CLEAN_MAX: f64 = 1.02;
const PRODUCT_DENSE_KAMM_WARNING_MAX: f64 = 1.05;
const PRODUCT_DENSE_KAMM_SEVERE_MIN: f64 = 1.10;

fn bike_product_dense_max_kamm(trajectory_dense: &JsonValue) -> Option<f64> {
    let front_kamm = json_f64_array_field(trajectory_dense, "front_kamm");
    let rear_kamm = json_f64_array_field(trajectory_dense, "rear_kamm");
    front_kamm
        .into_iter()
        .chain(rear_kamm)
        .filter(|value| value.is_finite())
        .max_by(f64::total_cmp)
}

fn bike_v1_product_dense_feasibility_json(trajectory_dense: &JsonValue) -> JsonValue {
    let front_kamm = json_f64_array_field(trajectory_dense, "front_kamm");
    let rear_kamm = json_f64_array_field(trajectory_dense, "rear_kamm");
    let interval_index = json_f64_array_field(trajectory_dense, "interval_index");
    let tau = json_f64_array_field(trajectory_dense, "tau");
    let mut values = Vec::with_capacity(front_kamm.len() + rear_kamm.len());
    values.extend(front_kamm.iter().copied());
    values.extend(rear_kamm.iter().copied());
    if values.is_empty() {
        return JsonValue::Object(vec![
            (
                "schema_version".to_owned(),
                "v1_product_dense_feasibility.v1".into(),
            ),
            ("dense_kamm_status".to_owned(), "missing".into()),
            ("strict_dense_status".to_owned(), "missing".into()),
            ("product_dense_status".to_owned(), "missing".into()),
            ("max_kamm_dense".to_owned(), JsonValue::Null),
            ("dense_kamm_gt_1p02_count".to_owned(), JsonValue::Null),
            ("dense_kamm_gt_1p05_count".to_owned(), JsonValue::Null),
            ("dense_kamm_gt_1p10_count".to_owned(), JsonValue::Null),
            ("worst_dense_kamm_interval".to_owned(), JsonValue::Null),
            ("worst_dense_kamm_tau".to_owned(), JsonValue::Null),
            ("worst_dense_kamm_axle".to_owned(), JsonValue::Null),
            (
                "meaning".to_owned(),
                "Product dense feasibility is missing because trajectory_dense front_kamm/rear_kamm arrays are unavailable".into(),
            ),
        ]);
    }

    let max_kamm_dense = values.iter().copied().fold(f64::NEG_INFINITY, f64::max);
    let (worst_axle, worst_index, _) = worst_dense_kamm_axis_sample(&front_kamm, &rear_kamm);
    let product_dense_status = product_dense_kamm_status(max_kamm_dense);
    JsonValue::Object(vec![
        (
            "schema_version".to_owned(),
            "v1_product_dense_feasibility.v1".into(),
        ),
        (
            "dense_kamm_status".to_owned(),
            product_dense_status.into(),
        ),
        (
            "strict_dense_status".to_owned(),
            strict_dense_kamm_status(max_kamm_dense).into(),
        ),
        (
            "product_dense_status".to_owned(),
            product_dense_status.into(),
        ),
        ("max_kamm_dense".to_owned(), json_number(max_kamm_dense)),
        (
            "dense_kamm_gt_1p02_count".to_owned(),
            JsonValue::Integer(count_values_gt(&values, PRODUCT_DENSE_KAMM_CLEAN_MAX) as i64),
        ),
        (
            "dense_kamm_gt_1p05_count".to_owned(),
            JsonValue::Integer(count_values_gt(&values, PRODUCT_DENSE_KAMM_WARNING_MAX) as i64),
        ),
        (
            "dense_kamm_gt_1p10_count".to_owned(),
            JsonValue::Integer(count_values_gt(&values, PRODUCT_DENSE_KAMM_SEVERE_MIN) as i64),
        ),
        (
            "worst_dense_kamm_interval".to_owned(),
            dense_numeric_at(&interval_index, worst_index),
        ),
        (
            "worst_dense_kamm_tau".to_owned(),
            dense_numeric_at(&tau, worst_index),
        ),
        ("worst_dense_kamm_axle".to_owned(), worst_axle.into()),
        (
            "thresholds".to_owned(),
            JsonValue::Object(vec![
                (
                    "strict_dense_clean_max_kamm".to_owned(),
                    json_number(STRICT_DENSE_KAMM_CLEAN_MAX),
                ),
                (
                    "product_dense_clean_max_kamm".to_owned(),
                    json_number(PRODUCT_DENSE_KAMM_CLEAN_MAX),
                ),
                (
                    "product_dense_warning_max_kamm".to_owned(),
                    json_number(PRODUCT_DENSE_KAMM_WARNING_MAX),
                ),
                (
                    "product_dense_severe_min_kamm".to_owned(),
                    json_number(PRODUCT_DENSE_KAMM_SEVERE_MIN),
                ),
            ]),
        ),
        (
            "meaning".to_owned(),
            "strict_dense_clean means max dense Kamm <= 1.002; product_dense_clean means <= 1.02; product_dense_warning means <= 1.05; product_dense_fail means > 1.05; product_dense_severe means > 1.10".into(),
        ),
    ])
}

fn json_f64_array_field(root: &JsonValue, key: &str) -> Vec<f64> {
    root.get(key)
        .and_then(JsonValue::as_array)
        .map(|values| values.iter().filter_map(JsonValue::as_f64).collect())
        .unwrap_or_default()
}

fn worst_dense_kamm_axis_sample(front: &[f64], rear: &[f64]) -> (&'static str, usize, f64) {
    let mut worst_axle = "";
    let mut worst_index = 0_usize;
    let mut worst_value = f64::NEG_INFINITY;
    for (axle, values) in [("front", front), ("rear", rear)] {
        for (index, value) in values.iter().copied().enumerate() {
            if value > worst_value {
                worst_axle = axle;
                worst_index = index;
                worst_value = value;
            }
        }
    }
    (worst_axle, worst_index, worst_value)
}

fn dense_numeric_at(values: &[f64], index: usize) -> JsonValue {
    values
        .get(index)
        .copied()
        .map(json_number)
        .unwrap_or(JsonValue::Null)
}

fn count_values_gt(values: &[f64], threshold: f64) -> usize {
    values.iter().filter(|value| **value > threshold).count()
}

fn strict_dense_kamm_status(max_kamm_dense: f64) -> &'static str {
    if !max_kamm_dense.is_finite() {
        "missing"
    } else if max_kamm_dense <= STRICT_DENSE_KAMM_CLEAN_MAX {
        "strict_dense_clean"
    } else {
        "strict_dense_not_clean"
    }
}

fn product_dense_kamm_status(max_kamm_dense: f64) -> &'static str {
    if !max_kamm_dense.is_finite() {
        "missing"
    } else if max_kamm_dense > PRODUCT_DENSE_KAMM_SEVERE_MIN {
        "product_dense_severe"
    } else if max_kamm_dense > PRODUCT_DENSE_KAMM_WARNING_MAX {
        "product_dense_fail"
    } else if max_kamm_dense > PRODUCT_DENSE_KAMM_CLEAN_MAX {
        "product_dense_warning"
    } else {
        "product_dense_clean"
    }
}

