fn bike_linear_state_at_tau(
    seed: &BikeMintimeNlpSeed,
    x: &[f64],
    interval: usize,
    tau: f64,
) -> BikeSingleTrackLeanState {
    let current = bike_state_from(seed, x, interval);
    let next = bike_state_from(
        seed,
        x,
        next_station_index(seed.dimensions.station_count, interval),
    );
    BikeSingleTrackLeanState {
        v_mps: lerp(current.v_mps, next.v_mps, tau),
        beta_rad: lerp(current.beta_rad, next.beta_rad, tau),
        omega_z_radps: lerp(current.omega_z_radps, next.omega_z_radps, tau),
        n_m: lerp(current.n_m, next.n_m, tau),
        xi_rad: lerp(current.xi_rad, next.xi_rad, tau),
        phi_rad: lerp(current.phi_rad, next.phi_rad, tau),
        phi_dot_radps: lerp(current.phi_dot_radps, next.phi_dot_radps, tau),
    }
}

fn bike_collocation_polynomial_state_at_tau(
    seed: &BikeMintimeNlpSeed,
    x: &[f64],
    interval: usize,
    tau: f64,
) -> BikeSingleTrackLeanState {
    let basis = bike_collocation_lagrange_basis_at_tau(tau);
    let states = [
        bike_state_from(seed, x, interval),
        collocation_state_from(seed, x, interval, 0),
        collocation_state_from(seed, x, interval, 1),
        collocation_state_from(seed, x, interval, 2),
    ];
    BikeSingleTrackLeanState {
        v_mps: collocation_lerp_state_component(&states, &basis, |state| state.v_mps),
        beta_rad: collocation_lerp_state_component(&states, &basis, |state| state.beta_rad),
        omega_z_radps: collocation_lerp_state_component(&states, &basis, |state| {
            state.omega_z_radps
        }),
        n_m: collocation_lerp_state_component(&states, &basis, |state| state.n_m),
        xi_rad: collocation_lerp_state_component(&states, &basis, |state| state.xi_rad),
        phi_rad: collocation_lerp_state_component(&states, &basis, |state| state.phi_rad),
        phi_dot_radps: collocation_lerp_state_component(&states, &basis, |state| {
            state.phi_dot_radps
        }),
    }
}

fn bike_collocation_state_derivatives_at_tau(
    seed: &BikeMintimeNlpSeed,
    x: &[f64],
    interval: usize,
    tau: f64,
) -> BikeSingleTrackLeanState {
    let basis = bike_collocation_lagrange_basis_derivative_at_tau(tau);
    let states = bike_collocation_interval_states(seed, x, interval);
    bike_collocation_state_from_basis(&states, &basis, 1.0 / interval_ds_m(seed, interval))
}

fn bike_collocation_state_second_derivatives_at_tau(
    seed: &BikeMintimeNlpSeed,
    x: &[f64],
    interval: usize,
    tau: f64,
) -> BikeSingleTrackLeanState {
    let ds_m = interval_ds_m(seed, interval);
    let basis = bike_collocation_lagrange_basis_second_derivative_at_tau(tau);
    let states = bike_collocation_interval_states(seed, x, interval);
    bike_collocation_state_from_basis(&states, &basis, 1.0 / (ds_m * ds_m))
}

fn bike_collocation_interval_states(
    seed: &BikeMintimeNlpSeed,
    x: &[f64],
    interval: usize,
) -> [BikeSingleTrackLeanState; BIKE_COLLOCATION_DEGREE + 1] {
    [
        bike_state_from(seed, x, interval),
        collocation_state_from(seed, x, interval, 0),
        collocation_state_from(seed, x, interval, 1),
        collocation_state_from(seed, x, interval, 2),
    ]
}

fn bike_collocation_lagrange_basis_at_tau(tau: f64) -> [f64; BIKE_COLLOCATION_DEGREE + 1] {
    let nodes = bike_legendre_collocation_coefficients_degree3().tau;
    let mut basis = [0.0; BIKE_COLLOCATION_DEGREE + 1];
    for node_index in 0..=BIKE_COLLOCATION_DEGREE {
        let mut value = 1.0;
        for other_index in 0..=BIKE_COLLOCATION_DEGREE {
            if node_index == other_index {
                continue;
            }
            value *= (tau - nodes[other_index]) / (nodes[node_index] - nodes[other_index]);
        }
        basis[node_index] = value;
    }
    basis
}

fn bike_collocation_lagrange_basis_derivative_at_tau(
    tau: f64,
) -> [f64; BIKE_COLLOCATION_DEGREE + 1] {
    let nodes = bike_legendre_collocation_coefficients_degree3().tau;
    let mut basis = [0.0; BIKE_COLLOCATION_DEGREE + 1];
    for node_index in 0..=BIKE_COLLOCATION_DEGREE {
        let mut value = 0.0;
        for derivative_index in 0..=BIKE_COLLOCATION_DEGREE {
            if derivative_index == node_index {
                continue;
            }
            let mut term = 1.0 / (nodes[node_index] - nodes[derivative_index]);
            for product_index in 0..=BIKE_COLLOCATION_DEGREE {
                if product_index == node_index || product_index == derivative_index {
                    continue;
                }
                term *= (tau - nodes[product_index]) / (nodes[node_index] - nodes[product_index]);
            }
            value += term;
        }
        basis[node_index] = value;
    }
    basis
}

fn bike_collocation_lagrange_basis_second_derivative_at_tau(
    tau: f64,
) -> [f64; BIKE_COLLOCATION_DEGREE + 1] {
    let nodes = bike_legendre_collocation_coefficients_degree3().tau;
    let mut basis = [0.0; BIKE_COLLOCATION_DEGREE + 1];
    for node_index in 0..=BIKE_COLLOCATION_DEGREE {
        let mut value = 0.0;
        for first_derivative_index in 0..=BIKE_COLLOCATION_DEGREE {
            if first_derivative_index == node_index {
                continue;
            }
            for second_derivative_index in 0..=BIKE_COLLOCATION_DEGREE {
                if second_derivative_index == node_index
                    || second_derivative_index == first_derivative_index
                {
                    continue;
                }
                let mut term = 1.0
                    / ((nodes[node_index] - nodes[first_derivative_index])
                        * (nodes[node_index] - nodes[second_derivative_index]));
                for product_index in 0..=BIKE_COLLOCATION_DEGREE {
                    if product_index == node_index
                        || product_index == first_derivative_index
                        || product_index == second_derivative_index
                    {
                        continue;
                    }
                    term *=
                        (tau - nodes[product_index]) / (nodes[node_index] - nodes[product_index]);
                }
                value += term;
            }
        }
        basis[node_index] = value;
    }
    basis
}

fn bike_collocation_state_from_basis(
    states: &[BikeSingleTrackLeanState; BIKE_COLLOCATION_DEGREE + 1],
    basis: &[f64; BIKE_COLLOCATION_DEGREE + 1],
    scale: f64,
) -> BikeSingleTrackLeanState {
    BikeSingleTrackLeanState {
        v_mps: scale * collocation_lerp_state_component(states, basis, |state| state.v_mps),
        beta_rad: scale * collocation_lerp_state_component(states, basis, |state| state.beta_rad),
        omega_z_radps: scale
            * collocation_lerp_state_component(states, basis, |state| state.omega_z_radps),
        n_m: scale * collocation_lerp_state_component(states, basis, |state| state.n_m),
        xi_rad: scale * collocation_lerp_state_component(states, basis, |state| state.xi_rad),
        phi_rad: scale * collocation_lerp_state_component(states, basis, |state| state.phi_rad),
        phi_dot_radps: scale
            * collocation_lerp_state_component(states, basis, |state| state.phi_dot_radps),
    }
}

fn collocation_lerp_state_component(
    states: &[BikeSingleTrackLeanState; BIKE_COLLOCATION_DEGREE + 1],
    basis: &[f64; BIKE_COLLOCATION_DEGREE + 1],
    component: impl Fn(BikeSingleTrackLeanState) -> f64,
) -> f64 {
    states
        .iter()
        .zip(basis.iter())
        .map(|(state, weight)| weight * component(*state))
        .sum()
}

#[derive(Clone, Debug)]
struct AyConsistencySample {
    frame: &'static str,
    sample_index: f64,
    station: Option<usize>,
    interval: Option<usize>,
    tau: Option<f64>,
    ay_model_mps2: f64,
    ay_xy_mps2: f64,
    diff_mps2: f64,
    kappa_xy_1pm: f64,
    kappa_ref_1pm: f64,
    speed_mps: f64,
}

#[derive(Clone, Debug)]
struct AyConsistencyPoint {
    frame: &'static str,
    sample_index: f64,
    station: Option<usize>,
    interval: Option<usize>,
    tau: Option<f64>,
    xy_m: Point2,
    speed_mps: f64,
    ay_model_mps2: f64,
    kappa_ref_1pm: f64,
}

fn ay_xy_consistency_json(
    problem: &BikeMintimeNlpProblem,
    x: &[f64],
    trajectory: &TrajectoryResultSeriesV1,
    closed: bool,
) -> JsonValue {
    let published = published_final_xy_consistency_points(trajectory);
    let station_path = station_path_consistency_points(problem, x);
    let collocation_polynomial = collocation_polynomial_consistency_points(problem, x);
    let published_json = ay_xy_consistency_frame_json("published_final_xy", &published, closed);
    let station_json = ay_xy_consistency_frame_json("station_path", &station_path, closed);
    let collocation_json =
        ay_xy_consistency_frame_json("collocation_polynomial", &collocation_polynomial, closed);

    JsonValue::Object(vec![
        ("schema_version".to_owned(), "ay_xy_consistency.v2".into()),
        (
            "interpretation".to_owned(),
            "Each frame computes ay_xy from the same XY samples used by that frame. published_final_xy is the overlay/result trajectory; station_path is the solver station state frame; collocation_polynomial is a transcription diagnostic frame.".into(),
        ),
        (
            "primary_frame".to_owned(),
            "published_final_xy".into(),
        ),
        (
            "overlay_conclusions_reliable".to_owned(),
            frame_reliable(&published_json),
        ),
        (
            "frames".to_owned(),
            JsonValue::Object(vec![
                ("published_final_xy".to_owned(), published_json),
                ("station_path".to_owned(), station_json),
                ("collocation_polynomial".to_owned(), collocation_json),
            ]),
        ),
    ])
}

fn frame_reliable(frame_json: &JsonValue) -> JsonValue {
    if let JsonValue::Object(entries) = frame_json {
        entries
            .iter()
            .find_map(|(key, value)| (key == "frame_reliable").then_some(value.clone()))
            .unwrap_or(JsonValue::Bool(false))
    } else {
        JsonValue::Bool(false)
    }
}

fn published_final_xy_consistency_points(
    trajectory: &TrajectoryResultSeriesV1,
) -> Vec<AyConsistencyPoint> {
    let count = trajectory
        .x_m
        .len()
        .min(trajectory.y_m.len())
        .min(trajectory.v_mps.len())
        .min(trajectory.ay_mps2.len())
        .min(trajectory.kappa_1pm.len());
    (0..count)
        .map(|station| AyConsistencyPoint {
            frame: "published_final_xy",
            sample_index: station as f64,
            station: Some(station),
            interval: None,
            tau: None,
            xy_m: [trajectory.x_m[station], trajectory.y_m[station]],
            speed_mps: trajectory.v_mps[station],
            ay_model_mps2: trajectory.ay_mps2[station],
            kappa_ref_1pm: trajectory.kappa_1pm[station],
        })
        .collect()
}

fn station_path_consistency_points(
    problem: &BikeMintimeNlpProblem,
    x: &[f64],
) -> Vec<AyConsistencyPoint> {
    (0..problem.seed.dimensions.station_count)
        .map(|station| {
            let state = bike_state_from(&problem.seed, x, station);
            let dynamics =
                bike_mintime_station_dynamics_from(&problem.seed, problem.params, x, station);
            AyConsistencyPoint {
                frame: "station_path",
                sample_index: station as f64,
                station: Some(station),
                interval: Some(station_publication_interval(&problem.seed, station)),
                tau: None,
                xy_m: station_xy_from(&problem.seed, x, station),
                speed_mps: state.v_mps,
                ay_model_mps2: dynamics.ay_mps2,
                kappa_ref_1pm: problem.seed.kappa_1pm[station],
            }
        })
        .collect()
}

fn collocation_polynomial_consistency_points(
    problem: &BikeMintimeNlpProblem,
    x: &[f64],
) -> Vec<AyConsistencyPoint> {
    let tau_values = [0.0, 0.112_701_665_379_258_3, 0.5, 0.887_298_334_620_741_7];
    let mut points = Vec::with_capacity(problem.seed.dimensions.interval_count * tau_values.len());
    for interval in 0..problem.seed.dimensions.interval_count {
        for tau in tau_values {
            let state = bike_collocation_polynomial_state_at_tau(&problem.seed, x, interval, tau);
            let geometry = interpolated_sections_geometry(&problem.seed, interval, tau);
            let dynamics = bike_mintime_dynamics_with_sections_geometry(
                problem.params,
                state,
                bike_control_from(&problem.seed, x, interval),
                geometry,
            );
            points.push(AyConsistencyPoint {
                frame: "collocation_polynomial",
                sample_index: interval as f64 + tau,
                station: None,
                interval: Some(interval),
                tau: Some(tau),
                xy_m: collocation_polynomial_xy_at_tau(&problem.seed, x, interval, tau),
                speed_mps: state.v_mps,
                ay_model_mps2: dynamics.ay_mps2,
                kappa_ref_1pm: geometry.kappa_1pm,
            });
        }
    }
    points
}

fn collocation_polynomial_xy_at_tau(
    seed: &BikeMintimeNlpSeed,
    x: &[f64],
    interval: usize,
    tau: f64,
) -> Point2 {
    let state = bike_collocation_polynomial_state_at_tau(seed, x, interval, tau);
    let next = next_station_index(seed.dimensions.station_count, interval);
    let geometry = interpolated_sections_geometry(seed, interval, tau);
    let center = lerp_point(
        seed.centerline_xy_m[interval],
        seed.centerline_xy_m[next],
        tau,
    );
    let normal = normalize_point([-geometry.section_dir_xy[0], -geometry.section_dir_xy[1]]);
    [
        center[0] + normal[0] * state.n_m,
        center[1] + normal[1] * state.n_m,
    ]
}

fn ay_xy_consistency_frame_json(
    frame_name: &'static str,
    points: &[AyConsistencyPoint],
    closed: bool,
) -> JsonValue {
    let count = points.len();
    let mut samples = Vec::<AyConsistencySample>::new();
    let mut abs_diffs = Vec::<f64>::new();
    let mut sum_sq = 0.0;
    let mut max_model_ay = 0.0_f64;

    for station in 0..count {
        if !closed && (station == 0 || station + 1 == count) {
            continue;
        }
        let previous = if station == 0 {
            count.saturating_sub(1)
        } else {
            station - 1
        };
        let next = if station + 1 == count { 0 } else { station + 1 };
        let prev = points[previous].xy_m;
        let current = points[station].xy_m;
        let following = points[next].xy_m;
        let kappa_xy = signed_three_point_curvature_1pm(prev, current, following);
        if !kappa_xy.is_finite() {
            continue;
        }
        let ay_xy = points[station].speed_mps * points[station].speed_mps * kappa_xy;
        let ay_model = points[station].ay_model_mps2;
        let diff = ay_model - ay_xy;
        max_model_ay = max_model_ay.max(ay_model.abs());
        sum_sq += diff * diff;
        abs_diffs.push(diff.abs());
        samples.push(AyConsistencySample {
            frame: points[station].frame,
            sample_index: points[station].sample_index,
            station: points[station].station,
            interval: points[station].interval,
            tau: points[station].tau,
            ay_model_mps2: ay_model,
            ay_xy_mps2: ay_xy,
            diff_mps2: diff,
            kappa_xy_1pm: kappa_xy,
            kappa_ref_1pm: points[station].kappa_ref_1pm,
            speed_mps: points[station].speed_mps,
        });
    }

    samples.sort_by(|left, right| {
        right
            .diff_mps2
            .abs()
            .partial_cmp(&left.diff_mps2.abs())
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    abs_diffs.sort_by(|left, right| left.partial_cmp(right).unwrap_or(std::cmp::Ordering::Equal));
    let sample_count = abs_diffs.len();
    let rms = if sample_count > 0 {
        (sum_sq / sample_count as f64).sqrt()
    } else {
        f64::NAN
    };
    let p95 = percentile_sorted(&abs_diffs, 0.95);
    let max_abs = abs_diffs.last().copied().unwrap_or(f64::NAN);
    let threshold = 0.5_f64.max(0.10 * max_model_ay);
    let reliable = rms.is_finite() && rms <= threshold;

    JsonValue::Object(vec![
        ("frame".to_owned(), frame_name.into()),
        (
            "sample_count".to_owned(),
            JsonValue::Integer(sample_count as i64),
        ),
        (
            "ay_model_source".to_owned(),
            match frame_name {
                "published_final_xy" => "trajectory_result.ay_mps2",
                "station_path" => "bike_mintime_station_dynamics_from",
                "collocation_polynomial" => {
                    "bike_mintime_dynamics_with_sections_geometry(collocation polynomial state)"
                }
                _ => "unknown",
            }
            .into(),
        ),
        (
            "ay_xy_formula".to_owned(),
            "v_mps^2 * signed_three_point_curvature(frame_xy)".into(),
        ),
        ("rms_diff_mps2".to_owned(), json_number(rms)),
        ("p95_abs_diff_mps2".to_owned(), json_number(p95)),
        ("max_abs_diff_mps2".to_owned(), json_number(max_abs)),
        (
            "reliability_threshold_mps2".to_owned(),
            json_number(threshold),
        ),
        ("frame_reliable".to_owned(), JsonValue::Bool(reliable)),
        (
            "warning".to_owned(),
            if reliable {
                JsonValue::Null
            } else {
                "large ay_model vs v^2*kappa_xy mismatch; geometry-only overlay conclusions need caution".into()
            },
        ),
        (
            "worst_samples".to_owned(),
            JsonValue::Array(
                samples
                    .iter()
                    .take(8)
                    .map(ay_consistency_sample_json)
                    .collect(),
            ),
        ),
    ])
}

fn ay_consistency_sample_json(sample: &AyConsistencySample) -> JsonValue {
    JsonValue::Object(vec![
        ("frame".to_owned(), sample.frame.into()),
        ("sample_index".to_owned(), json_number(sample.sample_index)),
        (
            "station_index".to_owned(),
            sample
                .station
                .map(|station| JsonValue::Integer(station as i64))
                .unwrap_or(JsonValue::Null),
        ),
        (
            "interval_index".to_owned(),
            sample
                .interval
                .map(|interval| JsonValue::Integer(interval as i64))
                .unwrap_or(JsonValue::Null),
        ),
        (
            "tau".to_owned(),
            sample.tau.map(json_number).unwrap_or(JsonValue::Null),
        ),
        (
            "ay_model_mps2".to_owned(),
            json_number(sample.ay_model_mps2),
        ),
        ("ay_xy_mps2".to_owned(), json_number(sample.ay_xy_mps2)),
        (
            "ay_model_minus_xy_mps2".to_owned(),
            json_number(sample.diff_mps2),
        ),
        ("kappa_xy_1pm".to_owned(), json_number(sample.kappa_xy_1pm)),
        (
            "kappa_ref_1pm".to_owned(),
            json_number(sample.kappa_ref_1pm),
        ),
        ("speed_mps".to_owned(), json_number(sample.speed_mps)),
    ])
}

#[derive(Clone, Debug)]
struct AyCurvatureMismatchStation {
    station: usize,
    ay_model_mps2: f64,
    ay_xy_mps2: f64,
    ay_model_minus_xy_mps2: f64,
    kappa_dyn_1pm: f64,
    kappa_yaw_1pm: f64,
    kappa_xy_1pm: f64,
    kappa_ref_1pm: f64,
    kappa_dyn_minus_xy_1pm: f64,
    kappa_yaw_minus_xy_1pm: f64,
    v_mps: f64,
    n_m: f64,
    dn_ds_model: f64,
    dn_ds_fd: f64,
    dn_ds_model_minus_fd: f64,
    ddn_ds2_fd: f64,
    xi_rad: f64,
    beta_rad: f64,
    omega_z_radps: f64,
    ds_prev_m: f64,
    ds_next_m: f64,
    section_dir_rotation_prev_rad: f64,
    section_dir_rotation_next_rad: f64,
    section_dir_derivative_norm: f64,
    heading_path_rad: f64,
    heading_model_rad: f64,
    heading_vehicle_rad: f64,
    heading_path_minus_model_rad: f64,
    heading_path_minus_vehicle_rad: f64,
    kappa_from_heading_path_1pm: f64,
    kappa_from_heading_state_1pm: f64,
    kappa_from_heading_vehicle_1pm: f64,
    kappa_heading_path_minus_xy_1pm: f64,
    kappa_heading_state_minus_dyn_1pm: f64,
    kappa_heading_vehicle_minus_dyn_1pm: f64,
}

fn bike_ay_curvature_mismatch_audit_json(
    problem: &BikeMintimeNlpProblem,
    x: &[f64],
    closed: bool,
) -> JsonValue {
    let count = problem.seed.dimensions.station_count;
    let final_points = (0..count)
        .map(|station| station_xy_from(&problem.seed, x, station))
        .collect::<Vec<_>>();
    let n_values = (0..count)
        .map(|station| bike_state_from(&problem.seed, x, station).n_m)
        .collect::<Vec<_>>();
    let dn_values = (0..count)
        .map(|station| finite_station_derivative(&problem.seed, &n_values, station, closed))
        .collect::<Vec<_>>();
    let heading_path_values = (0..count)
        .map(|station| path_heading_rad(&final_points, station, closed))
        .collect::<Vec<_>>();
    let heading_state_values = (0..count)
        .map(|station| {
            let state = bike_state_from(&problem.seed, x, station);
            let ref_heading = problem.seed.ref_tangent_xy[station][1]
                .atan2(problem.seed.ref_tangent_xy[station][0]);
            normalize_angle_rad(ref_heading + state.xi_rad)
        })
        .collect::<Vec<_>>();
    let heading_vehicle_values = (0..count)
        .map(|station| {
            let state = bike_state_from(&problem.seed, x, station);
            let ref_heading = problem.seed.ref_tangent_xy[station][1]
                .atan2(problem.seed.ref_tangent_xy[station][0]);
            normalize_angle_rad(ref_heading + state.xi_rad + state.beta_rad)
        })
        .collect::<Vec<_>>();

    let mut rows = (0..count)
        .filter(|station| closed || (*station > 0 && *station + 1 < count))
        .map(|station| {
            bike_ay_curvature_mismatch_station(
                problem,
                x,
                &final_points,
                &dn_values,
                &heading_path_values,
                &heading_state_values,
                &heading_vehicle_values,
                station,
                closed,
            )
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        right
            .ay_model_minus_xy_mps2
            .abs()
            .partial_cmp(&left.ay_model_minus_xy_mps2.abs())
            .unwrap_or(std::cmp::Ordering::Equal)
    });

    let focus_indices = [12_usize, 16, 22, 0, count / 4, count / 2, (3 * count) / 4];
    let focus_rows = focus_indices
        .into_iter()
        .filter(|station| *station < count)
        .map(|station| {
            bike_ay_curvature_mismatch_station(
                problem,
                x,
                &final_points,
                &dn_values,
                &heading_path_values,
                &heading_state_values,
                &heading_vehicle_values,
                station,
                closed,
            )
        })
        .collect::<Vec<_>>();

    JsonValue::Object(vec![
        ("schema_version".to_owned(), "bike_ay_curvature_mismatch_audit.v1".into()),
        (
            "interpretation".to_owned(),
            "Compares model ay against curvature implied by published station XY. kappa_dyn=ay_model/v^2, kappa_yaw=omega_z/v, kappa_xy=signed three-point curvature of station XY.".into(),
        ),
        (
            "top_mismatch_stations".to_owned(),
            JsonValue::Array(
                rows.iter()
                    .take(12)
                    .map(ay_curvature_mismatch_station_json)
                    .collect(),
            ),
        ),
        (
            "focus_stations".to_owned(),
            JsonValue::Array(
                focus_rows
                    .iter()
                    .map(ay_curvature_mismatch_station_json)
                    .collect(),
            ),
        ),
    ])
}

fn bike_station_trajectory_consistency_audit_json(
    problem: &BikeMintimeNlpProblem,
    x: &[f64],
    closed: bool,
) -> JsonValue {
    let count = problem.seed.dimensions.station_count;
    let final_points = (0..count)
        .map(|station| station_xy_from(&problem.seed, x, station))
        .collect::<Vec<_>>();
    let n_values = (0..count)
        .map(|station| bike_state_from(&problem.seed, x, station).n_m)
        .collect::<Vec<_>>();
    let dn_values = (0..count)
        .map(|station| finite_station_derivative(&problem.seed, &n_values, station, closed))
        .collect::<Vec<_>>();
    let heading_path_values = (0..count)
        .map(|station| path_heading_rad(&final_points, station, closed))
        .collect::<Vec<_>>();
    let heading_state_values = (0..count)
        .map(|station| {
            let state = bike_state_from(&problem.seed, x, station);
            let ref_heading = problem.seed.ref_tangent_xy[station][1]
                .atan2(problem.seed.ref_tangent_xy[station][0]);
            normalize_angle_rad(ref_heading + state.xi_rad)
        })
        .collect::<Vec<_>>();
    let heading_vehicle_values = (0..count)
        .map(|station| {
            let state = bike_state_from(&problem.seed, x, station);
            let ref_heading = problem.seed.ref_tangent_xy[station][1]
                .atan2(problem.seed.ref_tangent_xy[station][0]);
            normalize_angle_rad(ref_heading + state.xi_rad + state.beta_rad)
        })
        .collect::<Vec<_>>();
    let rows = (0..count)
        .filter(|station| closed || (*station > 0 && *station + 1 < count))
        .map(|station| {
            bike_ay_curvature_mismatch_station(
                problem,
                x,
                &final_points,
                &dn_values,
                &heading_path_values,
                &heading_state_values,
                &heading_vehicle_values,
                station,
                closed,
            )
        })
        .collect::<Vec<_>>();

    bike_station_trajectory_consistency_audit_rows_json(rows, count)
}

fn bike_station_trajectory_consistency_audit_rows_json(
    rows: Vec<AyCurvatureMismatchStation>,
    count: usize,
) -> JsonValue {
    let ay_diffs = rows
        .iter()
        .map(|sample| sample.ay_model_minus_xy_mps2)
        .collect::<Vec<_>>();
    let heading_state_diffs = rows
        .iter()
        .map(|sample| sample.heading_path_minus_model_rad)
        .collect::<Vec<_>>();
    let heading_vehicle_diffs = rows
        .iter()
        .map(|sample| sample.heading_path_minus_vehicle_rad)
        .collect::<Vec<_>>();
    let dn_diffs = rows
        .iter()
        .map(|sample| sample.dn_ds_model_minus_fd)
        .collect::<Vec<_>>();
    let kappa_dyn_diffs = rows
        .iter()
        .map(|sample| sample.kappa_dyn_minus_xy_1pm)
        .collect::<Vec<_>>();
    let kappa_yaw_diffs = rows
        .iter()
        .map(|sample| sample.kappa_yaw_minus_xy_1pm)
        .collect::<Vec<_>>();
    let kappa_heading_path_diffs = rows
        .iter()
        .map(|sample| sample.kappa_heading_path_minus_xy_1pm)
        .collect::<Vec<_>>();
    let kappa_heading_state_diffs = rows
        .iter()
        .map(|sample| sample.kappa_heading_state_minus_dyn_1pm)
        .collect::<Vec<_>>();
    let kappa_heading_vehicle_diffs = rows
        .iter()
        .map(|sample| sample.kappa_heading_vehicle_minus_dyn_1pm)
        .collect::<Vec<_>>();

    JsonValue::Object(vec![
        (
            "schema_version".to_owned(),
            "station_trajectory_consistency_audit.v2".into(),
        ),
        ("model_family".to_owned(), "bike".into()),
        (
            "interpretation".to_owned(),
            "Compares station-offset published XY with the station dynamics frame. heading_state=ref_heading+xi; heading_vehicle=ref_heading+xi+beta; kappa_dyn=ay_model/v^2; kappa_yaw=omega_z/v; dn/ds_model is the NLP path derivative.".into(),
        ),
        ("station_count".to_owned(), JsonValue::Integer(count as i64)),
        (
            "sample_count".to_owned(),
            JsonValue::Integer(rows.len() as i64),
        ),
        (
            "summary".to_owned(),
            JsonValue::Object(vec![
                (
                    "ay_model_minus_xy_mps2".to_owned(),
                    bike_signed_delta_stats_json(&ay_diffs),
                ),
                (
                    "heading_path_minus_state_rad".to_owned(),
                    bike_signed_delta_stats_json(&heading_state_diffs),
                ),
                (
                    "heading_path_minus_vehicle_rad".to_owned(),
                    bike_signed_delta_stats_json(&heading_vehicle_diffs),
                ),
                (
                    "dn_ds_model_minus_fd".to_owned(),
                    bike_signed_delta_stats_json(&dn_diffs),
                ),
                (
                    "kappa_dyn_minus_xy_1pm".to_owned(),
                    bike_signed_delta_stats_json(&kappa_dyn_diffs),
                ),
                (
                    "kappa_yaw_minus_xy_1pm".to_owned(),
                    bike_signed_delta_stats_json(&kappa_yaw_diffs),
                ),
                (
                    "kappa_heading_path_minus_xy_1pm".to_owned(),
                    bike_signed_delta_stats_json(&kappa_heading_path_diffs),
                ),
                (
                    "kappa_heading_state_minus_dyn_1pm".to_owned(),
                    bike_signed_delta_stats_json(&kappa_heading_state_diffs),
                ),
                (
                    "kappa_heading_vehicle_minus_dyn_1pm".to_owned(),
                    bike_signed_delta_stats_json(&kappa_heading_vehicle_diffs),
                ),
            ]),
        ),
        (
            "top_ay_mismatch_stations".to_owned(),
            JsonValue::Array(bike_top_station_consistency_rows(&rows, |sample| {
                sample.ay_model_minus_xy_mps2.abs()
            })),
        ),
        (
            "top_heading_state_mismatch_stations".to_owned(),
            JsonValue::Array(bike_top_station_consistency_rows(&rows, |sample| {
                sample.heading_path_minus_model_rad.abs()
            })),
        ),
        (
            "top_heading_vehicle_mismatch_stations".to_owned(),
            JsonValue::Array(bike_top_station_consistency_rows(&rows, |sample| {
                sample.heading_path_minus_vehicle_rad.abs()
            })),
        ),
        (
            "top_dn_ds_mismatch_stations".to_owned(),
            JsonValue::Array(bike_top_station_consistency_rows(&rows, |sample| {
                sample.dn_ds_model_minus_fd.abs()
            })),
        ),
        (
            "top_kappa_dyn_mismatch_stations".to_owned(),
            JsonValue::Array(bike_top_station_consistency_rows(&rows, |sample| {
                sample.kappa_dyn_minus_xy_1pm.abs()
            })),
        ),
        (
            "top_heading_curvature_state_mismatch_stations".to_owned(),
            JsonValue::Array(bike_top_station_consistency_rows(&rows, |sample| {
                sample.kappa_heading_state_minus_dyn_1pm.abs()
            })),
        ),
        (
            "top_heading_curvature_vehicle_mismatch_stations".to_owned(),
            JsonValue::Array(bike_top_station_consistency_rows(&rows, |sample| {
                sample.kappa_heading_vehicle_minus_dyn_1pm.abs()
            })),
        ),
        (
            "focus_stations".to_owned(),
            JsonValue::Array(
                [12_usize, 16, 22, 0, count / 4, count / 2, (3 * count) / 4]
                    .into_iter()
                    .filter_map(|station| rows.iter().find(|row| row.station == station))
                    .map(ay_curvature_mismatch_station_json)
                    .collect(),
            ),
        ),
    ])
}

fn bike_top_station_consistency_rows(
    rows: &[AyCurvatureMismatchStation],
    score: impl Fn(&AyCurvatureMismatchStation) -> f64,
) -> Vec<JsonValue> {
    let mut sorted = rows.iter().collect::<Vec<_>>();
    sorted.sort_by(|left, right| {
        score(right)
            .partial_cmp(&score(left))
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    sorted
        .into_iter()
        .take(12)
        .map(ay_curvature_mismatch_station_json)
        .collect()
}

fn bike_signed_delta_stats_json(values: &[f64]) -> JsonValue {
    let finite = values
        .iter()
        .copied()
        .filter(|value| value.is_finite())
        .collect::<Vec<_>>();
    if finite.is_empty() {
        return JsonValue::Object(vec![("count".to_owned(), JsonValue::Integer(0))]);
    }

    let count = finite.len();
    let mean = finite.iter().sum::<f64>() / count as f64;
    let rms = (finite.iter().map(|value| value * value).sum::<f64>() / count as f64).sqrt();
    let mut abs_values = finite.iter().map(|value| value.abs()).collect::<Vec<_>>();
    abs_values.sort_by(|left, right| left.partial_cmp(right).unwrap_or(std::cmp::Ordering::Equal));
    JsonValue::Object(vec![
        ("count".to_owned(), JsonValue::Integer(count as i64)),
        ("mean".to_owned(), json_number(mean)),
        ("rms".to_owned(), json_number(rms)),
        (
            "p95_abs".to_owned(),
            json_number(percentile_sorted(&abs_values, 0.95)),
        ),
        (
            "max_abs".to_owned(),
            json_number(abs_values.last().copied().unwrap_or(f64::NAN)),
        ),
    ])
}

fn bike_ay_curvature_mismatch_station(
    problem: &BikeMintimeNlpProblem,
    x: &[f64],
    final_points: &[Point2],
    dn_values: &[f64],
    heading_path_values: &[f64],
    heading_state_values: &[f64],
    heading_vehicle_values: &[f64],
    station: usize,
    closed: bool,
) -> AyCurvatureMismatchStation {
    let seed = &problem.seed;
    let state = bike_state_from(seed, x, station);
    let dynamics = bike_mintime_station_dynamics_from(seed, problem.params, x, station);
    let kappa_xy_1pm = final_xy_curvature_1pm(seed, x, station);
    let ay_xy_mps2 = state.v_mps * state.v_mps * kappa_xy_1pm;
    let v_safe = state.v_mps.abs().max(1e-6);
    let prev_interval = previous_interval_index(seed, station);
    let next_interval = station.min(seed.dimensions.interval_count.saturating_sub(1));
    let section_dir_heading = |index: usize| {
        let direction = seed.section_dir_xy[index];
        direction[1].atan2(direction[0])
    };
    let previous_station = previous_station_index(seed, station, closed);
    let next_station = next_station_index(seed.dimensions.station_count, station);
    let section_dir_rotation_prev_rad =
        normalize_angle_rad(section_dir_heading(station) - section_dir_heading(previous_station));
    let section_dir_rotation_next_rad =
        normalize_angle_rad(section_dir_heading(next_station) - section_dir_heading(station));
    let ref_heading_rad = seed.ref_tangent_xy[station][1].atan2(seed.ref_tangent_xy[station][0]);
    let heading_model_rad = normalize_angle_rad(ref_heading_rad + state.xi_rad);
    let heading_vehicle_rad = normalize_angle_rad(ref_heading_rad + state.xi_rad + state.beta_rad);
    let heading_path_rad = path_heading_rad(final_points, station, closed);
    let kappa_dyn_1pm = velocity_heading_curvature_1pm(
        state.v_mps,
        state.omega_z_radps,
        dynamics.dbeta_ds,
        dynamics.sigma_dt_ds,
    );
    let kappa_yaw_1pm = state.omega_z_radps / v_safe;
    let kappa_from_heading_path_1pm =
        finite_angle_station_derivative(seed, heading_path_values, station, closed);
    let kappa_from_heading_state_1pm =
        finite_angle_station_derivative(seed, heading_state_values, station, closed);
    let kappa_from_heading_vehicle_1pm =
        finite_angle_station_derivative(seed, heading_vehicle_values, station, closed);

    AyCurvatureMismatchStation {
        station,
        ay_model_mps2: dynamics.ay_mps2,
        ay_xy_mps2,
        ay_model_minus_xy_mps2: dynamics.ay_mps2 - ay_xy_mps2,
        kappa_dyn_1pm,
        kappa_yaw_1pm,
        kappa_xy_1pm,
        kappa_ref_1pm: seed.kappa_1pm[station],
        kappa_dyn_minus_xy_1pm: kappa_dyn_1pm - kappa_xy_1pm,
        kappa_yaw_minus_xy_1pm: kappa_yaw_1pm - kappa_xy_1pm,
        v_mps: state.v_mps,
        n_m: state.n_m,
        dn_ds_model: dynamics.dn_ds,
        dn_ds_fd: dn_values[station],
        dn_ds_model_minus_fd: dynamics.dn_ds - dn_values[station],
        ddn_ds2_fd: finite_station_derivative(seed, dn_values, station, closed),
        xi_rad: state.xi_rad,
        beta_rad: state.beta_rad,
        omega_z_radps: state.omega_z_radps,
        ds_prev_m: interval_ds_m(seed, prev_interval),
        ds_next_m: interval_ds_m(seed, next_interval),
        section_dir_rotation_prev_rad,
        section_dir_rotation_next_rad,
        section_dir_derivative_norm: seed.section_dir_derivative_xy[station][0]
            .hypot(seed.section_dir_derivative_xy[station][1]),
        heading_path_rad,
        heading_model_rad,
        heading_vehicle_rad,
        heading_path_minus_model_rad: normalize_angle_rad(heading_path_rad - heading_model_rad),
        heading_path_minus_vehicle_rad: normalize_angle_rad(heading_path_rad - heading_vehicle_rad),
        kappa_from_heading_path_1pm,
        kappa_from_heading_state_1pm,
        kappa_from_heading_vehicle_1pm,
        kappa_heading_path_minus_xy_1pm: kappa_from_heading_path_1pm - kappa_xy_1pm,
        kappa_heading_state_minus_dyn_1pm: kappa_from_heading_state_1pm - kappa_dyn_1pm,
        kappa_heading_vehicle_minus_dyn_1pm: kappa_from_heading_vehicle_1pm - kappa_dyn_1pm,
    }
}

fn previous_station_index(seed: &BikeMintimeNlpSeed, station: usize, closed: bool) -> usize {
    if station == 0 && closed {
        seed.dimensions.station_count.saturating_sub(1)
    } else {
        station.saturating_sub(1)
    }
}

fn previous_interval_index(seed: &BikeMintimeNlpSeed, station: usize) -> usize {
    if station == 0 && seed_is_closed(seed) {
        seed.dimensions.interval_count.saturating_sub(1)
    } else {
        station
            .saturating_sub(1)
            .min(seed.dimensions.interval_count.saturating_sub(1))
    }
}

fn finite_station_derivative(
    seed: &BikeMintimeNlpSeed,
    values: &[f64],
    station: usize,
    closed: bool,
) -> f64 {
    if values.is_empty() || station >= values.len() {
        return f64::NAN;
    }
    let previous = previous_station_index(seed, station, closed);
    let next = if closed {
        (station + 1) % values.len()
    } else {
        (station + 1).min(values.len().saturating_sub(1))
    };
    let prev_interval = previous_interval_index(seed, station);
    let next_interval = station.min(seed.dimensions.interval_count.saturating_sub(1));
    let ds = (interval_ds_m(seed, prev_interval) + interval_ds_m(seed, next_interval)).max(1e-9);
    (values[next] - values[previous]) / ds
}

fn finite_angle_station_derivative(
    seed: &BikeMintimeNlpSeed,
    values: &[f64],
    station: usize,
    closed: bool,
) -> f64 {
    if values.is_empty() || station >= values.len() {
        return f64::NAN;
    }
    let previous = previous_station_index(seed, station, closed);
    let next = if closed {
        (station + 1) % values.len()
    } else {
        (station + 1).min(values.len().saturating_sub(1))
    };
    let prev_interval = previous_interval_index(seed, station);
    let next_interval = station.min(seed.dimensions.interval_count.saturating_sub(1));
    let ds = (interval_ds_m(seed, prev_interval) + interval_ds_m(seed, next_interval)).max(1e-9);
    normalize_angle_rad(values[next] - values[previous]) / ds
}

