fn bike_v1_profile_map_json(map: &BTreeMap<&'static str, BikeV1ProfileCounter>) -> JsonValue {
    JsonValue::Array(
        map.iter()
            .map(|(family, counter)| {
                let total_s = counter.total.as_secs_f64();
                JsonValue::Object(vec![
                    ("family".to_owned(), (*family).into()),
                    ("calls".to_owned(), JsonValue::Integer(counter.calls as i64)),
                    ("total_s".to_owned(), json_number(total_s)),
                    (
                        "avg_s".to_owned(),
                        if counter.calls == 0 {
                            JsonValue::Null
                        } else {
                            json_number(total_s / counter.calls as f64)
                        },
                    ),
                ])
            })
            .collect(),
    )
}

fn bike_v1_profile_counter_json(counter: BikeV1ProfileCounter) -> JsonValue {
    let total_s = counter.total.as_secs_f64();
    JsonValue::Object(vec![
        ("calls".to_owned(), JsonValue::Integer(counter.calls as i64)),
        ("total_s".to_owned(), json_number(total_s)),
        (
            "avg_s".to_owned(),
            if counter.calls == 0 {
                JsonValue::Null
            } else {
                json_number(total_s / counter.calls as f64)
            },
        ),
    ])
}

fn bike_callback_timing_json(count: u32, total: Duration) -> JsonValue {
    let total_s = total.as_secs_f64();
    let avg_s = if count == 0 {
        JsonValue::Null
    } else {
        json_number(total_s / f64::from(count))
    };
    JsonValue::Object(vec![
        ("count".to_owned(), JsonValue::Integer(i64::from(count))),
        ("total_s".to_owned(), json_number(total_s)),
        ("avg_s".to_owned(), avg_s),
    ])
}

#[derive(Clone, Copy, Debug)]
struct BikeStageTimings {
    ipopt_solve: Duration,
    post_ipopt_result_assembly: Duration,
    diagnostics: Duration,
    dense_trajectory: Option<Duration>,
    failure_artifact: Option<Duration>,
    internal_total: Duration,
}

fn append_bike_stage_timings(diagnostics: &mut JsonValue, timings: JsonValue) {
    if let JsonValue::Object(entries) = diagnostics {
        entries.push(("stage_timings".to_owned(), timings));
    }
}

fn bike_stage_timings_json(timings: BikeStageTimings) -> JsonValue {
    let dense_trajectory = timings
        .dense_trajectory
        .map(duration_json_seconds)
        .unwrap_or(JsonValue::Null);
    let failure_artifact = timings
        .failure_artifact
        .map(duration_json_seconds)
        .unwrap_or(JsonValue::Null);

    JsonValue::Object(vec![
        ("schema_version".to_owned(), "bike_stage_timings.v1".into()),
        (
            "note".to_owned(),
            "Internal Rust timing around Ipopt solve and post-solve artifact generation; CLI/file write time is reported by rlc-model-contracts stdout.".into(),
        ),
        (
            "ipopt_solve_s".to_owned(),
            duration_json_seconds(timings.ipopt_solve),
        ),
        (
            "post_ipopt_result_assembly_s".to_owned(),
            duration_json_seconds(timings.post_ipopt_result_assembly),
        ),
        (
            "diagnostics_s".to_owned(),
            duration_json_seconds(timings.diagnostics),
        ),
        ("dense_trajectory_s".to_owned(), dense_trajectory),
        ("failure_artifact_s".to_owned(), failure_artifact),
        (
            "internal_total_s".to_owned(),
            duration_json_seconds(timings.internal_total),
        ),
    ])
}

fn duration_json_seconds(duration: Duration) -> JsonValue {
    json_number(duration.as_secs_f64())
}

fn bike_mintime_physics_bundle_json(problem: &BikeMintimeNlpProblem, x: &[f64]) -> JsonValue {
    let station_columns = bike_mintime_physics_bundle_columns();
    let collocation_columns = station_columns.clone();
    let station_rows = (0..problem.seed.dimensions.station_count)
        .map(|station| bike_mintime_station_physics_row(problem, x, station))
        .collect::<Vec<_>>();
    let collocation_rows = (0..problem.seed.dimensions.interval_count)
        .flat_map(|interval| {
            (1..=BIKE_COLLOCATION_DEGREE)
                .map(move |point| bike_mintime_collocation_physics_row(problem, x, interval, point))
        })
        .collect::<Vec<_>>();

    JsonValue::Object(vec![
        ("schema_version".to_owned(), "bike_physics_bundle_v1".into()),
        (
            "tire_envelope_contract".to_owned(),
            tire_envelope_contract_json(problem.params.tire_load_sensitivity_mode),
        ),
        (
            "sample_frame".to_owned(),
            "stations and degree-3 collocation points in final physical solution".into(),
        ),
        (
            "objective_split".to_owned(),
            bike_mintime_objective_split_json(problem, x),
        ),
        (
            "station_columns".to_owned(),
            json_string_array(&station_columns),
        ),
        ("station_rows".to_owned(), JsonValue::Array(station_rows)),
        (
            "collocation_columns".to_owned(),
            json_string_array(&collocation_columns),
        ),
        (
            "collocation_rows".to_owned(),
            JsonValue::Array(collocation_rows),
        ),
    ])
}

