#[derive(Clone, Copy, Debug, Default, PartialEq)]
struct BikeRegularizationComponents {
    delta_s: f64,
    force_s: f64,
    delta_dd_s: f64,
    force_dd_s: f64,
    phi_cmd_dd_s: f64,
    n_s: f64,
    xi_s: f64,
    lean_equilibrium_s: f64,
    roll_tau_s: f64,
    roll_tau_rate_s: f64,
    ay_rate_s: f64,
    phi_eq_rate_s: f64,
}

fn bike_mintime_regularization_components_s(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    weights: BikeMintimeObjectiveWeights,
    x: &[f64],
) -> BikeRegularizationComponents {
    let count = seed.dimensions.interval_count;
    if count == 0 {
        return BikeRegularizationComponents::default();
    }

    let delta = control_series(seed, x, CONTROL_DELTA_RAD, 1.0);
    let steering_regularization =
        bike_steering_regularization_series(params, weights.steering_regularization, &delta);
    let force = drive_brake_regularization_series(seed, x);
    let phi_cmd = control_series(
        seed,
        x,
        CONTROL_PHI_DOT_RADPS,
        1.0 / params.lean_rate_max_radps.max(1e-9),
    );
    let n = state_series(x, count, STATE_N_M, 1.0);
    let xi = state_series(x, count, STATE_XI_RAD, 1.0);
    let closed = seed_is_closed(seed);
    let lean_equilibrium = lean_equilibrium_regularization_series(seed, params, x);
    let roll_tau = roll_tau_regularization_series(seed, params, x);
    let ay_rate = ay_rate_regularization_series(seed, params, x);
    let phi_eq_rate = phi_eq_rate_regularization_series(seed, params, x);

    BikeRegularizationComponents {
        delta_s: weights.penalty_delta * first_difference_squared(&steering_regularization, closed),
        force_s: weights.penalty_f * first_difference_squared(&force, closed),
        delta_dd_s: weights.penalty_delta_dd
            * second_difference_squared(&steering_regularization, closed),
        force_dd_s: weights.penalty_f_dd * second_difference_squared(&force, closed),
        phi_cmd_dd_s: weights.penalty_phi_cmd_dd * second_difference_squared(&phi_cmd, closed),
        n_s: weights.penalty_n * second_difference_squared(&n, closed),
        xi_s: weights.penalty_xi * second_difference_squared(&xi, closed),
        lean_equilibrium_s: weights.penalty_lean_equilibrium * sum_squared(&lean_equilibrium),
        roll_tau_s: weights.penalty_roll_tau * sum_squared(&roll_tau),
        roll_tau_rate_s: weights.penalty_roll_tau_rate
            * first_difference_squared(&roll_tau, closed),
        ay_rate_s: weights.penalty_ay_rate * sum_squared(&ay_rate),
        phi_eq_rate_s: weights.penalty_phi_eq_rate * sum_squared(&phi_eq_rate),
    }
}

fn bike_mintime_residual_report_json(
    problem: &BikeMintimeNlpProblem,
    constraint_scales: &[f64],
    x: &[f64],
    top_count: usize,
) -> JsonValue {
    let mut entries = bike_mintime_residual_entries(problem, constraint_scales, x);
    let max_scaled_violation = entries
        .iter()
        .map(|entry| entry.scaled_violation)
        .fold(0.0, f64::max);
    let max_physical_violation = entries
        .iter()
        .map(|entry| entry.bound_violation)
        .fold(0.0, f64::max);
    let rms_scaled_violation = if entries.is_empty() {
        0.0
    } else {
        (entries
            .iter()
            .map(|entry| entry.scaled_violation * entry.scaled_violation)
            .sum::<f64>()
            / entries.len() as f64)
            .sqrt()
    };

    let mut family_stats: BTreeMap<&'static str, BikeResidualFamilyStats> = BTreeMap::new();
    for entry in &entries {
        let stats = family_stats.entry(entry.family).or_default();
        stats.count += 1;
        stats.scaled_sum_sq += entry.scaled_violation * entry.scaled_violation;
        if entry.scaled_violation >= stats.max_scaled_violation {
            stats.max_scaled_violation = entry.scaled_violation;
            stats.worst_label = entry.label.clone();
        }
    }

    entries.sort_by(|left, right| {
        right
            .scaled_violation
            .partial_cmp(&left.scaled_violation)
            .unwrap_or(std::cmp::Ordering::Equal)
    });

    JsonValue::Object(vec![
        (
            "max_scaled_violation".to_owned(),
            max_scaled_violation.into(),
        ),
        (
            "max_physical_violation".to_owned(),
            max_physical_violation.into(),
        ),
        (
            "rms_scaled_violation".to_owned(),
            rms_scaled_violation.into(),
        ),
        (
            "by_family".to_owned(),
            JsonValue::Array(
                family_stats
                    .into_iter()
                    .map(|(family, stats)| {
                        let rms = if stats.count == 0 {
                            0.0
                        } else {
                            (stats.scaled_sum_sq / stats.count as f64).sqrt()
                        };
                        JsonValue::Object(vec![
                            ("family".to_owned(), family.into()),
                            ("count".to_owned(), JsonValue::Integer(stats.count as i64)),
                            ("rms_scaled_violation".to_owned(), rms.into()),
                            (
                                "max_scaled_violation".to_owned(),
                                stats.max_scaled_violation.into(),
                            ),
                            ("worst_label".to_owned(), stats.worst_label.into()),
                        ])
                    })
                    .collect(),
            ),
        ),
        (
            "top_constraints".to_owned(),
            JsonValue::Array(
                entries
                    .iter()
                    .take(top_count)
                    .map(bike_constraint_residual_entry_json)
                    .collect(),
            ),
        ),
    ])
}

fn bike_mintime_residual_entries(
    problem: &BikeMintimeNlpProblem,
    constraint_scales: &[f64],
    x: &[f64],
) -> Vec<BikeConstraintResidualEntry> {
    problem
        .constraints
        .iter()
        .enumerate()
        .map(|(row_index, row)| {
            let value = problem.constraint_value(row, x);
            let lower = problem.constraint_lower_bounds[row_index];
            let upper = problem.constraint_upper_bounds[row_index];
            let scale = constraint_scales
                .get(row_index)
                .copied()
                .unwrap_or(1.0)
                .max(1e-12);
            let bound_violation = constraint_bound_violation(value, lower, upper);

            BikeConstraintResidualEntry {
                row_index,
                family: row.family(),
                label: row.label(),
                value,
                lower,
                upper,
                scale,
                bound_violation,
                scaled_violation: bound_violation / scale,
            }
        })
        .collect()
}

fn bike_constraint_residual_entry_json(entry: &BikeConstraintResidualEntry) -> JsonValue {
    JsonValue::Object(vec![
        (
            "row_index".to_owned(),
            JsonValue::Integer(entry.row_index as i64),
        ),
        ("family".to_owned(), entry.family.into()),
        ("label".to_owned(), entry.label.clone().into()),
        ("value".to_owned(), json_f64_or_string(entry.value)),
        ("lower".to_owned(), json_f64_or_string(entry.lower)),
        ("upper".to_owned(), json_f64_or_string(entry.upper)),
        ("scale".to_owned(), entry.scale.into()),
        ("bound_violation".to_owned(), entry.bound_violation.into()),
        ("scaled_violation".to_owned(), entry.scaled_violation.into()),
    ])
}

fn constraint_bound_violation(value: f64, lower: f64, upper: f64) -> f64 {
    let lower_violation = if lower.is_finite() && value < lower {
        lower - value
    } else {
        0.0
    };
    let upper_violation = if upper.is_finite() && value > upper {
        value - upper
    } else {
        0.0
    };
    lower_violation.max(upper_violation)
}

fn json_f64_or_string(value: f64) -> JsonValue {
    if value.is_finite() {
        value.into()
    } else if value.is_sign_negative() {
        "-inf".into()
    } else {
        "inf".into()
    }
}

