fn bike_mintime_station_physics_row(
    problem: &BikeMintimeNlpProblem,
    x: &[f64],
    station: usize,
) -> JsonValue {
    let interval = station_publication_interval(&problem.seed, station);
    let state = bike_state_from(&problem.seed, x, station);
    let control = bike_control_from(&problem.seed, x, interval);
    let dynamics = bike_mintime_station_dynamics_from(&problem.seed, problem.params, x, station);
    let point = station_xy_from(&problem.seed, x, station);
    let (n_lower, n_upper) = bike_n_bounds_at_station(&problem.seed, station);
    let kappa_ref_1pm = problem.seed.kappa_1pm[station];
    let kappa_xy_final_1pm = final_xy_curvature_1pm(&problem.seed, x, station);
    let ay_xy_mps2 = state.v_mps * state.v_mps * kappa_xy_final_1pm;
    let ay_model_minus_xy_mps2 = dynamics.ay_mps2 - ay_xy_mps2;
    bike_mintime_physics_row_json(
        0.0,
        station as f64,
        interval as f64,
        0.0,
        0.0,
        problem.seed.station_s_m[station],
        point,
        state,
        control,
        dynamics,
        problem,
        x,
        interval,
        n_lower,
        n_upper,
        kappa_ref_1pm,
        kappa_xy_final_1pm,
        ay_xy_mps2,
        ay_model_minus_xy_mps2,
    )
}

fn bike_mintime_collocation_physics_row(
    problem: &BikeMintimeNlpProblem,
    x: &[f64],
    interval: usize,
    point: usize,
) -> JsonValue {
    let coeffs = bike_legendre_collocation_coefficients_degree3();
    let tau = coeffs.tau[point];
    let state = collocation_state_from(&problem.seed, x, interval, point - 1);
    let control = bike_control_from(&problem.seed, x, interval);
    let dynamics =
        bike_mintime_collocation_dynamics_from(&problem.seed, problem.params, x, interval, point);
    let geometry = interpolated_sections_geometry(&problem.seed, interval, tau);
    let next = next_station_index(problem.seed.dimensions.station_count, interval);
    let center = lerp_point(
        problem.seed.centerline_xy_m[interval],
        problem.seed.centerline_xy_m[next],
        tau,
    );
    let normal = normalize_point([-geometry.section_dir_xy[0], -geometry.section_dir_xy[1]]);
    let position = [
        center[0] + normal[0] * state.n_m,
        center[1] + normal[1] * state.n_m,
    ];
    let (n_lower, n_upper) = bike_n_bounds_at_interval_tau(&problem.seed, interval, tau);
    let kappa_ref_1pm = lerp(
        problem.seed.kappa_1pm[interval],
        problem.seed.kappa_1pm[next],
        tau,
    );
    bike_mintime_physics_row_json(
        1.0,
        interval as f64 + tau,
        interval as f64,
        point as f64,
        tau,
        lerp(
            problem.seed.station_s_m[interval],
            problem.seed.station_s_m[next],
            tau,
        ),
        position,
        state,
        control,
        dynamics,
        problem,
        x,
        interval,
        n_lower,
        n_upper,
        kappa_ref_1pm,
        f64::NAN,
        f64::NAN,
        f64::NAN,
    )
}

#[allow(clippy::too_many_arguments)]
fn bike_mintime_physics_row_json(
    sample_kind: f64,
    station_index: f64,
    interval_index: f64,
    collocation_point: f64,
    tau: f64,
    s_m: f64,
    point: Point2,
    state: BikeSingleTrackLeanState,
    control: BikeSingleTrackLeanControl,
    dynamics: BikeSingleTrackLeanDynamics,
    problem: &BikeMintimeNlpProblem,
    x: &[f64],
    interval: usize,
    n_lower: f64,
    n_upper: f64,
    kappa_ref_1pm: f64,
    kappa_xy_final_1pm: f64,
    ay_xy_mps2: f64,
    ay_model_minus_xy_mps2: f64,
) -> JsonValue {
    let params = problem.params;
    let tire = dynamics.tire_forces;
    let front_load_factor = tire_capacity_factor(params, tire.fz_front_n, "front");
    let rear_load_factor = tire_capacity_factor(params, tire.fz_rear_n, "rear");
    let front_pacejka_capacity = tire_pacejka_capacity_n(params, tire.fz_front_n, "front");
    let rear_pacejka_capacity = tire_pacejka_capacity_n(params, tire.fz_rear_n, "rear");
    let front_kamm_capacity = tire_kamm_capacity_n(
        params,
        tire.fz_front_n,
        "front",
        problem.options.load_sensitive_kamm_denominator,
    );
    let rear_kamm_capacity = tire_kamm_capacity_n(
        params,
        tire.fz_rear_n,
        "rear",
        problem.options.load_sensitive_kamm_denominator,
    );
    let front_kamm = kamm_for_axle(
        params,
        tire,
        "front",
        problem.options.load_sensitive_kamm_denominator,
    );
    let rear_kamm = kamm_for_axle(
        params,
        tire,
        "rear",
        problem.options.load_sensitive_kamm_denominator,
    );
    let front_kamm_load_sensitive = kamm_for_axle(params, tire, "front", true);
    let rear_kamm_load_sensitive = kamm_for_axle(params, tire, "rear", true);
    let n_span = n_upper - n_lower;
    let n_normalized = if n_span.abs() > 1e-9 {
        (state.n_m - n_lower) / n_span
    } else {
        0.5
    };
    let power_w = state.v_mps * control.f_drive_n;
    let drive_brake_product = control.f_drive_n * control.f_brake_n;
    let delta_rate = bike_control_rate_value(problem, x, interval, CONTROL_DELTA_RAD);
    let drive_rate = bike_control_rate_value(problem, x, interval, CONTROL_F_DRIVE_N);
    let brake_rate = bike_control_rate_value(problem, x, interval, CONTROL_F_BRAKE_N);
    let lean_cmd_rate = bike_control_rate_value(problem, x, interval, CONTROL_PHI_DOT_RADPS);
    let (delta_rate_lower, delta_rate_upper) = control_rate_bounds(params, "delta_rad");
    let (drive_rate_lower, drive_rate_upper) = control_rate_bounds(params, "f_drive_N");
    let (brake_rate_lower, brake_rate_upper) = control_rate_bounds(params, "f_brake_N");
    let (lean_rate_lower, lean_rate_upper) = control_rate_bounds(params, "phi_dot_radps");
    let front_tire_ay = lateral_accel_remaining_mps2(
        params,
        tire.fx_front_n,
        tire_nominal_capacity_n(params, tire.fx_front_n, tire.fz_front_n),
        front_kamm_capacity,
    );
    let rear_tire_ay = lateral_accel_remaining_mps2(
        params,
        tire.fx_rear_n,
        tire_nominal_capacity_n(params, tire.fx_rear_n, tire.fz_rear_n),
        rear_kamm_capacity,
    );
    let combined_tire_ay = front_tire_ay + rear_tire_ay;
    let lean_ay = params.lean_limited_lateral_accel_mps2();
    let ay_abs = dynamics.ay_mps2.abs();

    json_number_array(&[
        sample_kind,
        station_index,
        interval_index,
        collocation_point,
        tau,
        s_m,
        point[0],
        point[1],
        n_lower,
        n_upper,
        n_normalized,
        n_upper - state.n_m,
        state.n_m - n_lower,
        state.v_mps,
        state.beta_rad,
        state.omega_z_radps,
        state.n_m,
        state.xi_rad,
        state.phi_rad,
        state.phi_dot_radps,
        control.delta_rad,
        control.f_drive_n,
        control.f_brake_n,
        control.phi_dot_cmd_radps,
        dynamics.sigma_dt_ds,
        dynamics.ax_mps2,
        dynamics.ay_mps2,
        dynamics.ax_body_mps2,
        dynamics.ay_body_mps2,
        dynamics.dv_ds,
        dynamics.dbeta_ds,
        dynamics.domega_z_ds,
        dynamics.dn_ds,
        dynamics.dxi_ds,
        dynamics.dphi_ds,
        dynamics.dphi_dot_ds,
        tire.fx_front_n,
        tire.fx_rear_n,
        tire.fy_front_n,
        tire.fy_rear_n,
        tire.fz_front_n,
        tire.fz_rear_n,
        tire.alpha_front_rad,
        tire.alpha_rear_rad,
        front_load_factor,
        rear_load_factor,
        params.lateral_grip_level * front_load_factor,
        params.lateral_grip_level * rear_load_factor,
        front_load_factor - params.tire_min_capacity_factor,
        rear_load_factor - params.tire_min_capacity_factor,
        front_pacejka_capacity,
        rear_pacejka_capacity,
        front_kamm_capacity,
        rear_kamm_capacity,
        front_kamm,
        rear_kamm,
        front_kamm_load_sensitive,
        rear_kamm_load_sensitive,
        1.0 - front_kamm,
        1.0 - rear_kamm,
        1.0 - front_kamm_load_sensitive,
        1.0 - rear_kamm_load_sensitive,
        tire.fz_front_n - min_normal_force_for_axle(params, "front"),
        tire.fz_rear_n - min_normal_force_for_axle(params, "rear"),
        params.alpha_front_max_rad - tire.alpha_front_rad.abs(),
        params.alpha_rear_max_rad - tire.alpha_rear_rad.abs(),
        params.lean_angle_max_rad - state.phi_rad.abs(),
        params.lean_rate_max_radps - state.phi_dot_radps.abs(),
        params.lean_rate_max_radps - control.phi_dot_cmd_radps.abs(),
        dynamics.roll_tau_cmd_nm,
        params.roll_tau_max_nm - dynamics.roll_tau_cmd_nm.abs(),
        dynamics.roll_moment_nm,
        dynamics.phi_ddot_radps2,
        dynamics.ay_mps2 - params.gravity_mps2 * state.phi_rad.tan(),
        power_w,
        params.power_max_w - power_w,
        drive_brake_product,
        drive_brake_product - BIKE_DRIVE_BRAKE_MUTEX_LOWER_N2,
        delta_rate,
        interval_bound_margin(delta_rate, delta_rate_lower, delta_rate_upper),
        drive_rate,
        interval_bound_margin(drive_rate, drive_rate_lower, drive_rate_upper),
        brake_rate,
        interval_bound_margin(brake_rate, brake_rate_lower, brake_rate_upper),
        lean_cmd_rate,
        interval_bound_margin(lean_cmd_rate, lean_rate_lower, lean_rate_upper),
        lean_ay,
        front_tire_ay,
        rear_tire_ay,
        combined_tire_ay,
        lean_ay - ay_abs,
        combined_tire_ay - ay_abs,
        kappa_ref_1pm,
        kappa_xy_final_1pm,
        ay_xy_mps2,
        ay_model_minus_xy_mps2,
    ])
}

fn bike_n_bounds_at_station(seed: &BikeMintimeNlpSeed, station: usize) -> (f64, f64) {
    let offset = state_offset(station) + STATE_N_M;
    (seed.lower_bounds[offset], seed.upper_bounds[offset])
}

fn bike_n_bounds_at_interval_tau(
    seed: &BikeMintimeNlpSeed,
    interval: usize,
    tau: f64,
) -> (f64, f64) {
    let next = next_station_index(seed.dimensions.station_count, interval);
    let (lower_current, upper_current) = bike_n_bounds_at_station(seed, interval);
    let (lower_next, upper_next) = bike_n_bounds_at_station(seed, next);
    (
        lerp(lower_current, lower_next, tau),
        lerp(upper_current, upper_next, tau),
    )
}

fn tire_capacity_factor(params: BikeSingleTrackLeanParams, normal_load_n: f64, axle: &str) -> f64 {
    let eps = match axle {
        "front" => params.tire_eps_front,
        "rear" => params.tire_eps_rear,
        _ => unreachable!("unknown bike axle {axle}"),
    };
    let normal_load_n = normal_load_n.max(1e-6);
    let fz0_n = params.tire_reference_load_n(axle).max(1e-6);
    match params.tire_load_sensitivity_mode {
        TireLoadSensitivityMode::UpstreamRaw => 1.0 + eps * normal_load_n / fz0_n,
        TireLoadSensitivityMode::ReferenceNormalizedDfz => {
            1.0 + eps * ((normal_load_n - fz0_n) / fz0_n)
        }
    }
}

fn signed_max_abs_hard(value: f64, min_abs: f64) -> f64 {
    if value.abs() >= min_abs {
        value
    } else if value < 0.0 {
        -min_abs
    } else {
        min_abs
    }
}

fn bike_v1_hard_pacejka_lateral_force_n(
    grip: f64,
    normal_load_n: f64,
    b: f64,
    c: f64,
    e: f64,
    alpha_rad: f64,
    capacity_factor: f64,
) -> f64 {
    let shape = c * (b * alpha_rad - e * (b * alpha_rad - (b * alpha_rad).atan())).atan();
    grip * normal_load_n.max(1e-6) * capacity_factor * shape.sin()
}

fn bike_v1_pacejka_shape_derivative_per_rad(b: f64, c: f64, e: f64, alpha_rad: f64) -> f64 {
    let b_alpha = b * alpha_rad;
    let z = b_alpha - e * (b_alpha - b_alpha.atan());
    let dz_dalpha = b - e * (b - b / (1.0 + b_alpha * b_alpha));
    (c * z.atan()).cos() * c * dz_dalpha / (1.0 + z * z)
}

fn bike_v1_pacejka_peak_slip_rad(b: f64, c: f64, e: f64) -> f64 {
    let b = b.max(1.0e-9);
    let c = c.max(1.0e-9);
    let target = (std::f64::consts::FRAC_PI_2 / c).tan();
    let z = |alpha: f64| {
        let b_alpha = b * alpha;
        b_alpha - e * (b_alpha - b_alpha.atan())
    };
    let mut lower = 0.0;
    let mut upper = 0.25;
    while z(upper) < target && upper < 4.0 {
        upper *= 2.0;
    }
    for _ in 0..80 {
        let middle = 0.5 * (lower + upper);
        if z(middle) < target {
            lower = middle;
        } else {
            upper = middle;
        }
    }
    0.5 * (lower + upper)
}

fn bike_v1_effective_pacejka_slip_rad(
    tire_force_mode: BikeV1TireForceMode,
    b: f64,
    c: f64,
    e: f64,
    alpha_raw_rad: f64,
) -> f64 {
    match tire_force_mode {
        BikeV1TireForceMode::LegacyPacejka | BikeV1TireForceMode::PrepeakGripDomain => {
            alpha_raw_rad
        }
        BikeV1TireForceMode::MonotonicTanh => {
            let peak = bike_v1_pacejka_peak_slip_rad(b, c, e).max(1.0e-9);
            peak * (alpha_raw_rad / peak).tanh()
        }
    }
}

fn bike_v1_effective_pacejka_slip_derivative(
    tire_force_mode: BikeV1TireForceMode,
    b: f64,
    c: f64,
    e: f64,
    alpha_raw_rad: f64,
) -> f64 {
    match tire_force_mode {
        BikeV1TireForceMode::LegacyPacejka | BikeV1TireForceMode::PrepeakGripDomain => 1.0,
        BikeV1TireForceMode::MonotonicTanh => {
            let peak = bike_v1_pacejka_peak_slip_rad(b, c, e).max(1.0e-9);
            let cosh = (alpha_raw_rad / peak).cosh();
            1.0 / (cosh * cosh)
        }
    }
}

fn bike_v1_tire_branch(alpha_rad: f64, peak_slip_rad: f64) -> &'static str {
    let ratio = alpha_rad.abs() / peak_slip_rad.max(1.0e-9);
    if ratio < 0.98 {
        "pre_peak"
    } else if ratio <= 1.02 {
        "near_peak"
    } else {
        "post_peak"
    }
}

fn tire_pacejka_capacity_n(
    params: BikeSingleTrackLeanParams,
    normal_load_n: f64,
    axle: &str,
) -> f64 {
    params.lateral_grip_level
        * normal_load_n.max(1e-6)
        * tire_capacity_factor(params, normal_load_n, axle)
}

fn tire_nominal_capacity_n(
    params: BikeSingleTrackLeanParams,
    longitudinal_force_n: f64,
    normal_load_n: f64,
) -> f64 {
    directional_longitudinal_tire_capacity_n(
        params.drive_grip_level,
        params.brake_grip_level,
        longitudinal_force_n,
        normal_load_n,
    )
}

fn tire_kamm_capacity_n(
    params: BikeSingleTrackLeanParams,
    normal_load_n: f64,
    axle: &str,
    load_sensitive_denominator: bool,
) -> f64 {
    let factor = if load_sensitive_denominator {
        tire_capacity_factor(params, normal_load_n, axle)
    } else {
        1.0
    };
    (params.lateral_grip_level * normal_load_n.max(1e-6) * factor).max(1e-6)
}

fn lateral_accel_remaining_mps2(
    params: BikeSingleTrackLeanParams,
    longitudinal_force_n: f64,
    longitudinal_capacity_n: f64,
    lateral_capacity_n: f64,
) -> f64 {
    lateral_capacity_n
        * (1.0 - (longitudinal_force_n / longitudinal_capacity_n).powi(2))
            .max(0.0)
            .sqrt()
        / params.rider_bike_mass_kg.max(1e-6)
}

fn bike_control_rate_value(
    problem: &BikeMintimeNlpProblem,
    x: &[f64],
    interval: usize,
    control_index: usize,
) -> f64 {
    let current = control_value_from(&problem.seed, x, interval, control_index);
    let previous = control_value_from(&problem.seed, x, interval.saturating_sub(1), control_index);
    let ds = interval_ds_m(&problem.seed, interval.saturating_sub(1)).max(1e-6);
    let sigma = bike_mintime_path_dynamics_from(
        &problem.seed,
        problem.params,
        x,
        interval.saturating_sub(1),
    )
    .sigma_dt_ds;
    (current - previous) / (ds * sigma).max(1e-6)
}

fn interval_bound_margin(value: f64, lower: f64, upper: f64) -> f64 {
    let lower_margin = if lower.is_finite() {
        value - lower
    } else {
        f64::INFINITY
    };
    let upper_margin = if upper.is_finite() {
        upper - value
    } else {
        f64::INFINITY
    };
    lower_margin.min(upper_margin)
}

fn json_string_array(values: &[&str]) -> JsonValue {
    JsonValue::Array(
        values
            .iter()
            .copied()
            .map(JsonValue::from)
            .collect::<Vec<_>>(),
    )
}

fn json_number_array(values: &[f64]) -> JsonValue {
    JsonValue::Array(values.iter().copied().map(json_number).collect())
}

fn json_number(value: f64) -> JsonValue {
    if value.is_finite() {
        JsonValue::from(value)
    } else {
        JsonValue::Null
    }
}

fn json_option_f64(value: Option<f64>) -> JsonValue {
    value.map_or(JsonValue::Null, json_number)
}

fn json_option_usize(value: Option<usize>) -> JsonValue {
    value.map_or(JsonValue::Null, |number| JsonValue::Integer(number as i64))
}

fn bike_mintime_failure_artifact_json(
    status: &str,
    lap_time_estimate_s: Option<f64>,
    trajectory_result: &TrajectoryResultSeriesV1,
    model_track_area: &TrackAreaContractV1,
    visualization: &JsonValue,
) -> JsonValue {
    JsonValue::Object(vec![
        (
            "schema_version".to_owned(),
            "rust_solver_response.v1".into(),
        ),
        ("runtime".to_owned(), "rust_bike_mintime_ipopt".into()),
        ("status".to_owned(), format!("failed:{status}").into()),
        (
            "lap_time_estimate_s".to_owned(),
            lap_time_estimate_s
                .map(JsonValue::from)
                .unwrap_or(JsonValue::Null),
        ),
        (
            "trajectory_result".to_owned(),
            trajectory_result.to_json_value(),
        ),
        (
            "model_track_area".to_owned(),
            model_track_area.to_json_value(),
        ),
        ("visualization".to_owned(), visualization.clone()),
        (
            "warnings".to_owned(),
            JsonValue::Array(vec![
                "diagnostic failure artifact; Ipopt did not report success".into(),
            ]),
        ),
    ])
}

fn native_backend_error(message: String) -> SolverApiError {
    SolverApiError::new("solve.nativeBackendUnavailable", message)
}

fn state_index(state_name: &str) -> usize {
    match state_name {
        "v_mps" => STATE_V_MPS,
        "beta_rad" => STATE_BETA_RAD,
        "omega_z_radps" => STATE_OMEGA_Z_RADPS,
        "n_m" => STATE_N_M,
        "xi_rad" => STATE_XI_RAD,
        "phi_rad" => STATE_PHI_RAD,
        "phi_dot_radps" => STATE_PHI_DOT_RADPS,
        _ => unreachable!("unknown bike state {state_name}"),
    }
}

fn control_index(control_name: &str) -> usize {
    match control_name {
        "delta_rad" => CONTROL_DELTA_RAD,
        "f_drive_N" => CONTROL_F_DRIVE_N,
        "f_brake_N" => CONTROL_F_BRAKE_N,
        "phi_dot_radps" => CONTROL_PHI_DOT_RADPS,
        _ => unreachable!("unknown bike control {control_name}"),
    }
}

fn state_offset(station: usize) -> usize {
    station * BIKE_STATE_LEN
}

fn control_offset(seed: &BikeMintimeNlpSeed, interval: usize) -> usize {
    seed.dimensions.state_variable_count + interval * BIKE_CONTROL_LEN
}

fn collocation_state_offset(seed: &BikeMintimeNlpSeed, interval: usize, point: usize) -> usize {
    seed.dimensions.state_variable_count
        + seed.dimensions.control_variable_count
        + (interval * BIKE_COLLOCATION_DEGREE + point) * BIKE_STATE_LEN
}

fn state_value_from(x: &[f64], station: usize, state_index: usize) -> f64 {
    x[state_offset(station) + state_index]
}

fn state_series(x: &[f64], count: usize, state_index: usize, scale: f64) -> Vec<f64> {
    (0..count)
        .map(|index| x[state_offset(index) + state_index] * scale)
        .collect()
}

fn control_series(
    seed: &BikeMintimeNlpSeed,
    x: &[f64],
    control_index: usize,
    scale: f64,
) -> Vec<f64> {
    (0..seed.dimensions.interval_count)
        .map(|index| x[control_offset(seed, index) + control_index] * scale)
        .collect()
}

fn drive_brake_regularization_series(seed: &BikeMintimeNlpSeed, x: &[f64]) -> Vec<f64> {
    (0..seed.dimensions.interval_count)
        .map(|index| {
            let offset = control_offset(seed, index);
            (x[offset + CONTROL_F_DRIVE_N] + x[offset + CONTROL_F_BRAKE_N]) / 10_000.0
        })
        .collect()
}

fn state_norm_value_from(
    params: BikeSingleTrackLeanParams,
    x: &[f64],
    station: usize,
    state_index: usize,
) -> f64 {
    state_value_from(x, station, state_index) / bike_state_scale(params)[state_index]
}

fn collocation_state_norm_value_from(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    x: &[f64],
    interval: usize,
    point: usize,
    state_index: usize,
) -> f64 {
    x[collocation_state_offset(seed, interval, point) + state_index]
        / bike_state_scale(params)[state_index]
}

fn control_value_from(
    seed: &BikeMintimeNlpSeed,
    x: &[f64],
    interval: usize,
    control_index: usize,
) -> f64 {
    x[control_offset(seed, interval) + control_index]
}

fn bike_state_from(
    _seed: &BikeMintimeNlpSeed,
    x: &[f64],
    station: usize,
) -> BikeSingleTrackLeanState {
    BikeSingleTrackLeanState {
        v_mps: state_value_from(x, station, STATE_V_MPS),
        beta_rad: state_value_from(x, station, STATE_BETA_RAD),
        omega_z_radps: state_value_from(x, station, STATE_OMEGA_Z_RADPS),
        n_m: state_value_from(x, station, STATE_N_M),
        xi_rad: state_value_from(x, station, STATE_XI_RAD),
        phi_rad: state_value_from(x, station, STATE_PHI_RAD),
        phi_dot_radps: state_value_from(x, station, STATE_PHI_DOT_RADPS),
    }
}

fn collocation_state_from(
    seed: &BikeMintimeNlpSeed,
    x: &[f64],
    interval: usize,
    point: usize,
) -> BikeSingleTrackLeanState {
    let offset = collocation_state_offset(seed, interval, point);
    BikeSingleTrackLeanState {
        v_mps: x[offset + STATE_V_MPS],
        beta_rad: x[offset + STATE_BETA_RAD],
        omega_z_radps: x[offset + STATE_OMEGA_Z_RADPS],
        n_m: x[offset + STATE_N_M],
        xi_rad: x[offset + STATE_XI_RAD],
        phi_rad: x[offset + STATE_PHI_RAD],
        phi_dot_radps: x[offset + STATE_PHI_DOT_RADPS],
    }
}

fn bike_control_from(
    seed: &BikeMintimeNlpSeed,
    x: &[f64],
    interval: usize,
) -> BikeSingleTrackLeanControl {
    let offset = control_offset(seed, interval);
    BikeSingleTrackLeanControl {
        delta_rad: x[offset + CONTROL_DELTA_RAD],
        f_drive_n: x[offset + CONTROL_F_DRIVE_N],
        f_brake_n: x[offset + CONTROL_F_BRAKE_N],
        phi_dot_cmd_radps: x[offset + CONTROL_PHI_DOT_RADPS],
    }
}

fn bike_state_scale(params: BikeSingleTrackLeanParams) -> [f64; BIKE_STATE_LEN] {
    [
        50.0,
        0.5,
        1.0,
        5.0,
        1.0,
        1.0,
        params.lean_rate_max_radps.max(1e-9),
    ]
}

fn bike_control_scale(params: BikeSingleTrackLeanParams) -> [f64; BIKE_CONTROL_LEN] {
    [0.5, 7_500.0, 20_000.0, params.lean_rate_max_radps.max(1e-9)]
}

fn bike_mintime_decision_variable_scales(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
) -> Vec<f64> {
    let state_scale = bike_state_scale(params);
    let control_scale = bike_control_scale(params);
    let mut scales = Vec::with_capacity(seed.dimensions.decision_variable_count());

    for _ in 0..seed.dimensions.station_count {
        scales.extend_from_slice(&state_scale);
    }
    for _ in 0..seed.dimensions.interval_count {
        scales.extend_from_slice(&control_scale);
    }
    for _ in 0..seed.dimensions.interval_count * BIKE_COLLOCATION_DEGREE {
        scales.extend_from_slice(&state_scale);
    }

    scales
}

fn bike_normalized_derivative(
    params: BikeSingleTrackLeanParams,
    dynamics: BikeSingleTrackLeanDynamics,
) -> [f64; BIKE_STATE_LEN] {
    let scale = bike_state_scale(params);
    [
        dynamics.dv_ds / scale[STATE_V_MPS],
        dynamics.dbeta_ds / scale[STATE_BETA_RAD],
        dynamics.domega_z_ds / scale[STATE_OMEGA_Z_RADPS],
        dynamics.dn_ds / scale[STATE_N_M],
        dynamics.dxi_ds / scale[STATE_XI_RAD],
        dynamics.dphi_ds / scale[STATE_PHI_RAD],
        dynamics.dphi_dot_ds / scale[STATE_PHI_DOT_RADPS],
    ]
}

fn bike_mintime_collocation_dynamics_residual(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    x: &[f64],
    interval: usize,
    point: usize,
    state_index: usize,
) -> f64 {
    let coefficients = bike_legendre_collocation_coefficients_degree3();
    let ds = interval_ds_m(seed, interval);
    let dynamics = bike_mintime_collocation_dynamics_from(seed, params, x, interval, point);
    let derivative_norm = bike_normalized_derivative(params, dynamics);
    let mut xp_norm =
        coefficients.c[0][point] * state_norm_value_from(params, x, interval, state_index);
    for collocation_point in 0..BIKE_COLLOCATION_DEGREE {
        xp_norm += coefficients.c[collocation_point + 1][point]
            * collocation_state_norm_value_from(
                seed,
                params,
                x,
                interval,
                collocation_point,
                state_index,
            );
    }

    ds * derivative_norm[state_index] - xp_norm
}

fn bike_mintime_collocation_dynamics_rhs_norm(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    x: &[f64],
    interval: usize,
    point: usize,
    state_index: usize,
) -> f64 {
    let ds = interval_ds_m(seed, interval);
    let dynamics = bike_mintime_collocation_dynamics_from(seed, params, x, interval, point);
    let derivative_norm = bike_normalized_derivative(params, dynamics);
    ds * derivative_norm[state_index]
}

fn bike_mintime_collocation_dynamics_rhs_norm_vector(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    x: &[f64],
    interval: usize,
    point: usize,
) -> [f64; BIKE_STATE_LEN] {
    let ds = interval_ds_m(seed, interval);
    let dynamics = bike_mintime_collocation_dynamics_from(seed, params, x, interval, point);
    let derivative_norm = bike_normalized_derivative(params, dynamics);
    let mut output = [0.0; BIKE_STATE_LEN];
    for index in 0..BIKE_STATE_LEN {
        output[index] = ds * derivative_norm[index];
    }
    output
}

fn bike_mintime_collocation_continuity_residual(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    x: &[f64],
    interval: usize,
    state_index: usize,
) -> f64 {
    let coefficients = bike_legendre_collocation_coefficients_degree3();
    let mut end_state_norm =
        coefficients.d[0] * state_norm_value_from(params, x, interval, state_index);
    for collocation_point in 0..BIKE_COLLOCATION_DEGREE {
        end_state_norm += coefficients.d[collocation_point + 1]
            * collocation_state_norm_value_from(
                seed,
                params,
                x,
                interval,
                collocation_point,
                state_index,
            );
    }

    end_state_norm
        - state_norm_value_from(
            params,
            x,
            next_station_index(seed.dimensions.station_count, interval),
            state_index,
        )
}

fn bike_mintime_path_dynamics_from(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    x: &[f64],
    interval: usize,
) -> BikeSingleTrackLeanDynamics {
    let state_interval = next_station_index(seed.dimensions.station_count, interval);
    bike_mintime_dynamics_for_state_control(
        seed,
        params,
        x,
        state_interval,
        interval,
        state_interval,
    )
}

fn bike_mintime_station_dynamics_from(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    x: &[f64],
    station: usize,
) -> BikeSingleTrackLeanDynamics {
    let control_interval = station_publication_interval(seed, station);
    bike_mintime_dynamics_for_state_control(seed, params, x, station, control_interval, station)
}

fn station_publication_interval(seed: &BikeMintimeNlpSeed, station: usize) -> usize {
    let interval_count = seed.dimensions.interval_count;
    if interval_count <= 1 || station == 0 && !seed_is_closed(seed) {
        return 0;
    }
    if station == 0 {
        interval_count - 1
    } else {
        (station - 1).min(interval_count - 1)
    }
}

fn bike_mintime_collocation_dynamics_from(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    x: &[f64],
    interval: usize,
    point: usize,
) -> BikeSingleTrackLeanDynamics {
    let coefficients = bike_legendre_collocation_coefficients_degree3();
    let geometry = interpolated_sections_geometry(seed, interval, coefficients.tau[point]);
    bike_mintime_dynamics_with_sections_geometry(
        params,
        collocation_state_from(seed, x, interval, point - 1),
        bike_control_from(seed, x, interval),
        geometry,
    )
}

fn bike_mintime_dynamics_for_state_control(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    x: &[f64],
    state_interval: usize,
    control_interval: usize,
    geometry_interval: usize,
) -> BikeSingleTrackLeanDynamics {
    let geometry = station_sections_geometry(seed, geometry_interval);
    bike_mintime_dynamics_with_sections_geometry(
        params,
        bike_state_from(seed, x, state_interval),
        bike_control_from(seed, x, control_interval),
        geometry,
    )
}

fn station_sections_geometry(
    seed: &BikeMintimeNlpSeed,
    station: usize,
) -> InterpolatedSectionsGeometry {
    let interval_count = seed.dimensions.interval_count;
    debug_assert!(interval_count > 0);
    if station < interval_count {
        interpolated_sections_geometry(seed, station, 0.0)
    } else {
        interpolated_sections_geometry(seed, interval_count - 1, 1.0)
    }
}

fn bike_mintime_dynamics_with_sections_geometry(
    params: BikeSingleTrackLeanParams,
    state: BikeSingleTrackLeanState,
    control: BikeSingleTrackLeanControl,
    geometry: InterpolatedSectionsGeometry,
) -> BikeSingleTrackLeanDynamics {
    let mut dynamics = bike_single_track_lean_dynamics(params, state, control, geometry.kappa_1pm);
    let base_sigma = dynamics.sigma_dt_ds.max(1e-9);
    let section_progress = section_frame_progress_from_derivatives(
        state.n_m,
        state.v_mps,
        state.beta_rad,
        state.xi_rad,
        geometry.ref_tangent_xy,
        geometry.ref_left_normal_xy,
        geometry.centerline_derivative_xy,
        geometry.section_dir_xy,
        geometry.section_dir_derivative_xy,
    );
    let sections_sigma = section_progress.sigma_dt_ds;
    let scale = sections_sigma / base_sigma;

    dynamics.dv_ds *= scale;
    dynamics.dbeta_ds *= scale;
    dynamics.domega_z_ds *= scale;
    dynamics.dn_ds = section_progress.dn_ds;
    dynamics.dxi_ds = sections_sigma * state.omega_z_radps - geometry.heading_rate_per_s;
    dynamics.dphi_ds *= scale;
    dynamics.dphi_dot_ds *= scale;
    dynamics.sigma_dt_ds = sections_sigma;
    dynamics
}

fn bike_v1_pure_frenet_progress(
    state: BikeCountersteerLeanStateV1,
    kappa_1pm: f64,
) -> SectionFrameProgress {
    let theta = state.xi_rad + state.beta_rad;
    let pure = pure_frenet_path_factor(state.n_m, kappa_1pm);
    let det_for_division = signed_max_abs(pure, 1.0e-9);
    let forward_progress_per_speed = theta.cos() / det_for_division;
    let speed = state.v_mps.max(1.0e-6);
    let s_dot = speed * forward_progress_per_speed;
    let n_dot = speed * theta.sin();
    let sigma_dt_ds = (1.0 / signed_max_abs(s_dot, 1.0e-9)).max(1.0e-9);
    SectionFrameProgress {
        det_geom: pure,
        forward_progress_per_speed,
        s_dot,
        n_dot,
        sigma_dt_ds,
        dn_ds: sigma_dt_ds * n_dot,
    }
}

fn bike_v1_progress_for_mode(
    progress_mode: BikeV1ProgressMode,
    state: BikeCountersteerLeanStateV1,
    kappa_1pm: f64,
    geometry: InterpolatedSectionsGeometry,
) -> SectionFrameProgress {
    match progress_mode {
        BikeV1ProgressMode::SectionFrame => section_frame_progress_from_derivatives(
            state.n_m,
            state.v_mps,
            state.beta_rad,
            state.xi_rad,
            geometry.ref_tangent_xy,
            geometry.ref_left_normal_xy,
            geometry.centerline_derivative_xy,
            geometry.section_dir_xy,
            geometry.section_dir_derivative_xy,
        ),
        BikeV1ProgressMode::PureFrenet => bike_v1_pure_frenet_progress(state, kappa_1pm),
    }
}

fn bike_v1_dynamics_with_sections_geometry(
    params: BikeCountersteerLeanParamsV1,
    state: BikeCountersteerLeanStateV1,
    control: BikeCountersteerLeanControlV1,
    kappa_1pm: f64,
    geometry: InterpolatedSectionsGeometry,
    smooth_tire_load_clamp: bool,
    smooth_tire_load_eps_n: f64,
    load_transfer_gain: f64,
    lean_residual_quasi_steady: bool,
    direct_delta_rate_steering: bool,
    steering_actuator_mode: BikeV1SteeringActuatorMode,
    delta_cmd_tau_s: f64,
    steering_torque_residual_scale: f64,
    tire_force_mode: BikeV1TireForceMode,
    progress_mode: BikeV1ProgressMode,
) -> BikeCountersteerLeanDynamicsV1 {
    let uses_debug_dynamics = smooth_tire_load_clamp
        || (load_transfer_gain - 1.0).abs() > 1e-12
        || lean_residual_quasi_steady
        || direct_delta_rate_steering
        || steering_actuator_mode.uses_debug_steering_dynamics()
        || steering_torque_residual_scale > 0.0
        || !matches!(tire_force_mode, BikeV1TireForceMode::LegacyPacejka);
    let time_dynamics = if uses_debug_dynamics {
        bike_v1_debug_time_dynamics(
            params,
            state,
            control,
            smooth_tire_load_clamp,
            smooth_tire_load_eps_n,
            load_transfer_gain,
            lean_residual_quasi_steady,
            direct_delta_rate_steering,
            steering_actuator_mode,
            delta_cmd_tau_s,
            steering_torque_residual_scale,
            tire_force_mode,
        )
    } else {
        bike_countersteer_lean_time_dynamics_v1(params, state, control)
    };
    let progress = bike_v1_progress_for_mode(progress_mode, state, kappa_1pm, geometry);
    let heading_rate_per_s = match progress_mode {
        BikeV1ProgressMode::SectionFrame => geometry.heading_rate_per_s,
        BikeV1ProgressMode::PureFrenet => kappa_1pm,
    };
    bike_countersteer_lean_spatial_dynamics_v1(
        time_dynamics,
        state,
        heading_rate_per_s,
        progress.sigma_dt_ds,
        progress.dn_ds,
    )
}

fn bike_v1_debug_time_dynamics(
    params: BikeCountersteerLeanParamsV1,
    state: BikeCountersteerLeanStateV1,
    control: BikeCountersteerLeanControlV1,
    smooth_tire_load_clamp: bool,
    smooth_tire_load_eps_n: f64,
    load_transfer_gain: f64,
    lean_residual_quasi_steady: bool,
    direct_delta_rate_steering: bool,
    steering_actuator_mode: BikeV1SteeringActuatorMode,
    delta_cmd_tau_s: f64,
    steering_torque_residual_scale: f64,
    tire_force_mode: BikeV1TireForceMode,
) -> BikeCountersteerLeanTimeDynamicsV1 {
    let base = params.base;
    let v = if smooth_tire_load_clamp {
        smooth_floor(state.v_mps, 1e-6, 1e-6)
    } else {
        state.v_mps.max(1e-6)
    };
    let beta = state.beta_rad;
    let omega_z = state.omega_z_radps;
    let delta = state.delta_rad;
    let mass = base.rider_bike_mass_kg;
    let gravity = base.gravity_mps2;

    let drag = base.drag_coeff_n_per_mps2 * v.powi(2);
    let rolling_total = base.rolling_resistance_coeff * mass * gravity;
    let rolling_front = rolling_total * base.wheelbase_rear_m / base.wheelbase_m;
    let rolling_rear = rolling_total * base.wheelbase_front_m / base.wheelbase_m;

    let fz_static_front = mass * gravity * base.wheelbase_rear_m / base.wheelbase_m;
    let fz_static_rear = mass * gravity * base.wheelbase_front_m / base.wheelbase_m;
    let longitudinal_force_for_transfer =
        control.f_drive_n + control.f_brake_n - drag - rolling_total;
    let fz_dyn_front =
        -base.cg_height_m / base.wheelbase_m * longitudinal_force_for_transfer * load_transfer_gain;
    let fz_dyn_rear = -fz_dyn_front;
    let fz_front_raw = fz_static_front + base.liftcoeff_front * v.powi(2) + fz_dyn_front;
    let fz_rear_raw = fz_static_rear + base.liftcoeff_rear * v.powi(2) + fz_dyn_rear;
    let fz_front = if smooth_tire_load_clamp {
        smooth_floor(fz_front_raw, 1e-6, smooth_tire_load_eps_n)
    } else {
        fz_front_raw
    };
    let fz_rear = if smooth_tire_load_clamp {
        smooth_floor(fz_rear_raw, 1e-6, smooth_tire_load_eps_n)
    } else {
        fz_rear_raw
    };

    let vx = if smooth_tire_load_clamp {
        smooth_signed_abs_floor(v * beta.cos(), 1e-6, 1e-6)
    } else {
        signed_max_abs_hard(v * beta.cos(), 1e-6)
    };
    let alpha_front = delta - ((v * beta.sin() + base.wheelbase_front_m * omega_z) / vx).atan();
    let alpha_rear = ((-v * beta.sin() + base.wheelbase_rear_m * omega_z) / vx).atan();
    let alpha_front_effective = bike_v1_effective_pacejka_slip_rad(
        tire_force_mode,
        base.tire_b_front,
        base.tire_c_front,
        base.tire_e_front,
        alpha_front,
    );
    let alpha_rear_effective = bike_v1_effective_pacejka_slip_rad(
        tire_force_mode,
        base.tire_b_rear,
        base.tire_c_rear,
        base.tire_e_rear,
        alpha_rear,
    );

    let fy_front = if smooth_tire_load_clamp {
        bike_v1_smooth_pacejka_lateral_force_n(
            base.lateral_grip_level,
            fz_front,
            base.tire_eps_front,
            base.tire_fz0_front_n,
            base.tire_load_sensitivity_mode,
            base.tire_b_front,
            base.tire_c_front,
            base.tire_e_front,
            alpha_front_effective,
            smooth_tire_load_eps_n,
        )
    } else {
        bike_v1_hard_pacejka_lateral_force_n(
            base.lateral_grip_level,
            fz_front,
            base.tire_b_front,
            base.tire_c_front,
            base.tire_e_front,
            alpha_front_effective,
            tire_capacity_factor(base, fz_front, "front"),
        )
    };
    let fy_rear = if smooth_tire_load_clamp {
        bike_v1_smooth_pacejka_lateral_force_n(
            base.lateral_grip_level,
            fz_rear,
            base.tire_eps_rear,
            base.tire_fz0_rear_n,
            base.tire_load_sensitivity_mode,
            base.tire_b_rear,
            base.tire_c_rear,
            base.tire_e_rear,
            alpha_rear_effective,
            smooth_tire_load_eps_n,
        )
    } else {
        bike_v1_hard_pacejka_lateral_force_n(
            base.lateral_grip_level,
            fz_rear,
            base.tire_b_rear,
            base.tire_c_rear,
            base.tire_e_rear,
            alpha_rear_effective,
            tire_capacity_factor(base, fz_rear, "rear"),
        )
    };

    let fx_front = base.front_brake_bias * control.f_brake_n - rolling_front;
    let fx_rear =
        control.f_drive_n + (1.0 - base.front_brake_bias) * control.f_brake_n - rolling_rear;

    let ax_body = (fx_rear + fx_front * delta.cos() - fy_front * delta.sin() - drag) / mass;
    let ay_body = (fx_front * delta.sin() + fy_rear + fy_front * delta.cos()) / mass;
    let ax = ax_body * beta.cos() + ay_body * beta.sin();
    let ay = -ax_body * beta.sin() + ay_body * beta.cos();

    let dv_dt = (fx_rear * beta.cos() + fx_front * (delta - beta).cos() + fy_rear * beta.sin()
        - fy_front * (delta - beta).sin()
        - drag * beta.cos())
        / mass;
    let dbeta_dt = -omega_z
        + (-fx_rear * beta.sin()
            + fx_front * (delta - beta).sin()
            + fy_rear * beta.cos()
            + fy_front * (delta - beta).cos()
            + drag * beta.sin())
            / (mass * v);
    let domega_z_dt = (-fy_rear * base.wheelbase_rear_m
        + (fy_front * delta.cos() + fx_front * delta.sin()) * base.wheelbase_front_m)
        / base.yaw_inertia_kgm2;

    let roll_moment =
        mass * base.cg_height_m * (ay * state.phi_rad.cos() - gravity * state.phi_rad.sin());
    let physical_phi_ddot =
        (roll_moment - base.roll_damping * state.phi_dot_radps) / base.roll_inertia_kgm2;
    let phi_eq = (ay / gravity.max(1e-9)).atan();
    let lean_tau = base.lean_response_s.max(0.02);
    let phi_residual_rate = (phi_eq - state.phi_rad) / lean_tau;
    let phi_ddot = if lean_residual_quasi_steady {
        (phi_residual_rate - state.phi_dot_radps) / lean_tau
    } else {
        physical_phi_ddot
    };

    let uses_delta_cmd = steering_actuator_mode.uses_delta_cmd();
    let uses_sr3_delta_accel = matches!(
        steering_actuator_mode,
        BikeV1SteeringActuatorMode::Sr3DeltaAccel
    );
    let steering_aligning_torque = -params.pneumatic_trail_m * fy_front;
    let steering_roll_torque = params.roll_steer_gain_nm_per_rad * state.phi_rad;
    let steering_centering_torque = -params.steering_stiffness_nm_per_rad * delta;
    let steering_damping_torque = -params.steering_damping_nm_per_radps * state.delta_dot_radps;
    let steering_torque_limit = params.steering_torque_max_nm.max(1.0);
    let delta_accel_scale = bike_v1_sr3_delta_accel_scale(params);
    let residual_scale = steering_torque_residual_scale.clamp(0.0, 1.0);
    let steering_balance_torque = -(steering_aligning_torque
        + steering_roll_torque
        + steering_centering_torque
        + steering_damping_torque);
    let steering_self_torque = steering_aligning_torque
        + steering_roll_torque
        + steering_centering_torque
        + steering_damping_torque;
    let sr3_delta_accel = control.steering_torque_nm * delta_accel_scale;
    let steering_input_torque = match steering_actuator_mode {
        BikeV1SteeringActuatorMode::DeltaCmdFirstOrder => 0.0,
        BikeV1SteeringActuatorMode::Sr3NormalizedTorque => {
            control.steering_torque_nm * steering_torque_limit
        }
        BikeV1SteeringActuatorMode::Sr3DeltaAccel => {
            params.steering_inertia_kgm2 * sr3_delta_accel - steering_self_torque
        }
        BikeV1SteeringActuatorMode::Torque => {
            if residual_scale > 0.0 {
                (steering_balance_torque + residual_scale * control.steering_torque_nm)
                    .clamp(-steering_torque_limit, steering_torque_limit)
            } else {
                control.steering_torque_nm
            }
        }
    };
    let steering_net_torque = if uses_sr3_delta_accel {
        params.steering_inertia_kgm2 * sr3_delta_accel
    } else {
        steering_input_torque + steering_self_torque
    };
    let physical_delta_ddot = steering_net_torque / params.steering_inertia_kgm2;
    let delta_rate_limit =
        (base.steering_angle_max_rad / base.steering_response_s.max(0.02)).max(1.0);
    let commanded_delta_rate = if uses_delta_cmd {
        let delta_cmd = control
            .steering_torque_nm
            .clamp(-base.steering_angle_max_rad, base.steering_angle_max_rad);
        ((delta_cmd - delta) / delta_cmd_tau_s.max(0.02)).clamp(-delta_rate_limit, delta_rate_limit)
    } else {
        (control.steering_torque_nm / steering_torque_limit).clamp(-1.0, 1.0) * delta_rate_limit
    };
    let steering_tau = base.steering_response_s.max(0.02);
    let delta_ddot = if uses_delta_cmd || direct_delta_rate_steering {
        (commanded_delta_rate - state.delta_dot_radps) / steering_tau
    } else if uses_sr3_delta_accel {
        sr3_delta_accel
    } else {
        physical_delta_ddot
    };
    let delta_dot = if uses_delta_cmd || direct_delta_rate_steering {
        commanded_delta_rate
    } else {
        state.delta_dot_radps
    };

    BikeCountersteerLeanTimeDynamicsV1 {
        dv_dt,
        dbeta_dt,
        domega_z_dt,
        dphi_dt: state.phi_dot_radps,
        dphi_dot_dt: phi_ddot,
        ddelta_dt: delta_dot,
        ddelta_dot_dt: delta_ddot,
        ax_body_mps2: ax_body,
        ay_body_mps2: ay_body,
        ax_mps2: ax,
        ay_mps2: ay,
        roll_moment_nm: roll_moment,
        phi_ddot_radps2: phi_ddot,
        steering_input_torque_nm: steering_input_torque,
        steering_aligning_torque_nm: steering_aligning_torque,
        steering_roll_torque_nm: steering_roll_torque,
        steering_centering_torque_nm: steering_centering_torque,
        steering_damping_torque_nm: steering_damping_torque,
        steering_net_torque_nm: steering_net_torque,
        delta_ddot_radps2: delta_ddot,
        tire_forces: BikeCountersteerLeanTireForcesV1 {
            fx_front_n: fx_front,
            fx_rear_n: fx_rear,
            fy_front_n: fy_front,
            fy_rear_n: fy_rear,
            fz_front_n: fz_front,
            fz_rear_n: fz_rear,
            alpha_front_rad: alpha_front,
            alpha_rear_rad: alpha_rear,
            alpha_front_effective_rad: alpha_front_effective,
            alpha_rear_effective_rad: alpha_rear_effective,
        },
    }
}

#[allow(clippy::too_many_arguments)]
fn bike_v1_smooth_pacejka_lateral_force_n(
    grip: f64,
    normal_load_n: f64,
    eps: f64,
    fz0_n: f64,
    mode: TireLoadSensitivityMode,
    b: f64,
    c: f64,
    e: f64,
    alpha_rad: f64,
    smooth_tire_load_eps_n: f64,
) -> f64 {
    let normal_load_n = smooth_floor(normal_load_n, 1e-6, smooth_tire_load_eps_n);
    grip * normal_load_n
        * bike_v1_smooth_tire_capacity_factor(normal_load_n, eps, fz0_n, mode)
        * (c * (b * alpha_rad - e * (b * alpha_rad - (b * alpha_rad).atan())).atan()).sin()
}

fn bike_v1_smooth_tire_capacity_factor(
    normal_load_n: f64,
    eps: f64,
    fz0_n: f64,
    mode: TireLoadSensitivityMode,
) -> f64 {
    let fz0_n = smooth_floor(fz0_n, 1e-6, 1e-6);
    let raw = match mode {
        TireLoadSensitivityMode::UpstreamRaw => 1.0 + eps * normal_load_n / fz0_n,
        TireLoadSensitivityMode::ReferenceNormalizedDfz => {
            1.0 + eps * ((normal_load_n - fz0_n) / fz0_n)
        }
    };
    smooth_floor(raw, 0.05, 0.01)
}

fn smooth_floor(value: f64, floor: f64, eps: f64) -> f64 {
    if eps <= 0.0 {
        return value.max(floor);
    }
    let z = (value - floor) / eps;
    if z > 40.0 {
        value
    } else if z < -40.0 {
        floor
    } else {
        floor + eps * z.exp().ln_1p()
    }
}

fn smooth_positive(value: f64, eps: f64) -> f64 {
    if eps <= 0.0 {
        return value.max(0.0);
    }
    let z = value / eps;
    if z > 40.0 {
        value
    } else if z < -40.0 {
        0.0
    } else {
        eps * z.exp().ln_1p()
    }
}

fn smooth_abs(value: f64, eps: f64) -> f64 {
    smooth_positive(value, eps) + smooth_positive(-value, eps)
}

fn smooth_signed_abs_floor(value: f64, min_abs: f64, eps: f64) -> f64 {
    if value.is_sign_negative() {
        -smooth_floor(-value, min_abs, eps)
    } else {
        smooth_floor(value, min_abs, eps)
    }
}

fn station_xy_from(seed: &BikeMintimeNlpSeed, x: &[f64], station: usize) -> Point2 {
    let center = seed.centerline_xy_m[station];
    let normal = station_path_normal(seed, station);
    let n_m = state_value_from(x, station, STATE_N_M);

    [center[0] + normal[0] * n_m, center[1] + normal[1] * n_m]
}

fn station_path_normal(seed: &BikeMintimeNlpSeed, station: usize) -> Point2 {
    seed.section_dir_xy
        .get(station)
        .copied()
        .filter(|direction| direction[0].hypot(direction[1]) > 1e-9)
        .map(|direction| {
            let normalized = normalize_point(direction);
            [-normalized[0], -normalized[1]]
        })
        .unwrap_or_else(|| station_normal(seed, station, seed_is_closed(seed)))
}

fn station_normal(seed: &BikeMintimeNlpSeed, station: usize, closed: bool) -> Point2 {
    let previous = if station == 0 && closed {
        seed.centerline_xy_m.len().saturating_sub(1)
    } else if station == 0 {
        0
    } else {
        station - 1
    };
    let next = if closed {
        (station + 1) % seed.centerline_xy_m.len().max(1)
    } else {
        (station + 1).min(seed.centerline_xy_m.len().saturating_sub(1))
    };
    let tangent = [
        seed.centerline_xy_m[next][0] - seed.centerline_xy_m[previous][0],
        seed.centerline_xy_m[next][1] - seed.centerline_xy_m[previous][1],
    ];
    let length = tangent[0].hypot(tangent[1]).max(1e-9);

    [-tangent[1] / length, tangent[0] / length]
}

fn path_heading_rad(points: &[Point2], station: usize, closed: bool) -> f64 {
    if points.len() < 2 {
        return 0.0;
    }

    let previous = if station == 0 && closed {
        points.len() - 1
    } else if station == 0 {
        0
    } else {
        station - 1
    };
    let next = if closed {
        (station + 1) % points.len().max(1)
    } else {
        (station + 1).min(points.len() - 1)
    };

    (points[next][1] - points[previous][1]).atan2(points[next][0] - points[previous][0])
}

fn kappa_1pm(seed: &BikeMintimeNlpSeed, station: usize) -> f64 {
    seed.kappa_1pm.get(station).copied().unwrap_or(0.0)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum TireValue {
    NormalLoad,
    SlipAngle,
}

fn tire_value_for_axle(tire: BikeSingleTrackLeanTireForces, axle: &str, value: TireValue) -> f64 {
    match (axle, value) {
        ("front", TireValue::NormalLoad) => tire.fz_front_n,
        ("rear", TireValue::NormalLoad) => tire.fz_rear_n,
        ("front", TireValue::SlipAngle) => tire.alpha_front_rad,
        ("rear", TireValue::SlipAngle) => tire.alpha_rear_rad,
        _ => unreachable!("unknown bike axle {axle}"),
    }
}

fn min_normal_force_for_axle(params: BikeSingleTrackLeanParams, axle: &str) -> f64 {
    let static_load = match axle {
        "front" => params.static_axle_loads_n().front_n,
        "rear" => params.static_axle_loads_n().rear_n,
        _ => unreachable!("unknown bike axle {axle}"),
    };

    params
        .min_normal_force_n
        .max(params.min_normal_force_static_fraction * static_load)
}

fn capacity_factor_for_axle(
    params: BikeSingleTrackLeanParams,
    tire: BikeSingleTrackLeanTireForces,
    axle: &str,
) -> f64 {
    let normal_load_n = match axle {
        "front" => tire.fz_front_n,
        "rear" => tire.fz_rear_n,
        _ => unreachable!("unknown bike axle {axle}"),
    };
    tire_capacity_factor(params, normal_load_n, axle)
}

fn kamm_for_axle(
    params: BikeSingleTrackLeanParams,
    tire: BikeSingleTrackLeanTireForces,
    axle: &str,
    load_sensitive_denominator: bool,
) -> f64 {
    let lateral_factor = if load_sensitive_denominator {
        capacity_factor_for_axle(params, tire, axle)
    } else {
        1.0
    };
    let (fx, fy, fz) = match axle {
        "front" => (tire.fx_front_n, tire.fy_front_n, tire.fz_front_n),
        "rear" => (tire.fx_rear_n, tire.fy_rear_n, tire.fz_rear_n),
        _ => unreachable!("unknown bike axle {axle}"),
    };
    let longitudinal_capacity = directional_longitudinal_tire_capacity_n(
        params.drive_grip_level,
        params.brake_grip_level,
        fx,
        fz,
    );
    let lateral_capacity = (params.lateral_grip_level * fz.max(1e-6) * lateral_factor).max(1e-6);

    (fx / longitudinal_capacity).powi(2) + (fy / lateral_capacity).powi(2)
}

fn control_rate_bounds(params: BikeSingleTrackLeanParams, control_name: &str) -> (f64, f64) {
    match control_name {
        "delta_rad" => (
            -params.steering_angle_max_rad / params.steering_response_s,
            params.steering_angle_max_rad / params.steering_response_s,
        ),
        "f_drive_N" => (
            f64::NEG_INFINITY,
            params.drive_force_max_n / params.throttle_response_s,
        ),
        "f_brake_N" => (
            -params.brake_force_max_n / params.brake_response_s,
            f64::INFINITY,
        ),
        "phi_dot_radps" => (
            -params.lean_rate_max_radps / params.lean_response_s,
            params.lean_rate_max_radps / params.lean_response_s,
        ),
        _ => unreachable!("unknown bike control {control_name}"),
    }
}

fn bike_mintime_energy_kwh(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    x: &[f64],
) -> f64 {
    (0..seed.dimensions.interval_count)
        .map(|interval| {
            let dt_s = bike_mintime_interval_dt_s(seed, params, x, interval);
            let state = bike_state_from(
                seed,
                x,
                next_station_index(seed.dimensions.station_count, interval),
            );
            let control = bike_control_from(seed, x, interval);
            state.v_mps * control.f_drive_n * dt_s
        })
        .sum::<f64>()
        / 3_600_000.0
}

fn bike_mintime_interval_dt_s(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    x: &[f64],
    interval: usize,
) -> f64 {
    let coefficients = bike_legendre_collocation_coefficients_degree3();
    let ds = interval_ds_m(seed, interval);
    (1..=BIKE_COLLOCATION_DEGREE)
        .map(|point| {
            ds * coefficients.b[point]
                * bike_mintime_collocation_sigma_dt_ds(seed, params, x, interval, point)
        })
        .sum()
}

fn bike_mintime_collocation_sigma_dt_ds(
    seed: &BikeMintimeNlpSeed,
    _params: BikeSingleTrackLeanParams,
    x: &[f64],
    interval: usize,
    point: usize,
) -> f64 {
    let coefficients = bike_legendre_collocation_coefficients_degree3();
    let geometry = interpolated_sections_geometry(seed, interval, coefficients.tau[point]);
    let state = collocation_state_from(seed, x, interval, point - 1);
    section_frame_progress_from_derivatives(
        state.n_m,
        state.v_mps,
        state.beta_rad,
        state.xi_rad,
        geometry.ref_tangent_xy,
        geometry.ref_left_normal_xy,
        geometry.centerline_derivative_xy,
        geometry.section_dir_xy,
        geometry.section_dir_derivative_xy,
    )
    .sigma_dt_ds
}

fn bike_mintime_collocation_objective_s(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    x: &[f64],
) -> f64 {
    (0..seed.dimensions.interval_count)
        .map(|interval| bike_mintime_interval_dt_s(seed, params, x, interval))
        .sum()
}

fn bike_mintime_lap_time_terms_for_variable_s(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    x: &[f64],
    variable_index: usize,
) -> f64 {
    let control_start = seed.dimensions.state_variable_count;
    let collocation_start = control_start + seed.dimensions.control_variable_count;

    if (control_start..collocation_start).contains(&variable_index) {
        let interval = (variable_index - control_start) / BIKE_CONTROL_LEN;
        return bike_mintime_interval_dt_s(seed, params, x, interval);
    }
    if variable_index >= collocation_start {
        let collocation_state = (variable_index - collocation_start) / BIKE_STATE_LEN;
        let interval = collocation_state / BIKE_COLLOCATION_DEGREE;
        if interval < seed.dimensions.interval_count {
            return bike_mintime_interval_dt_s(seed, params, x, interval);
        }
    }

    0.0
}

fn bike_mintime_objective_gradient_columns(
    seed: &BikeMintimeNlpSeed,
    weights: BikeMintimeObjectiveWeights,
) -> Vec<usize> {
    let mut columns = BTreeSet::new();
    for interval in 0..seed.dimensions.interval_count {
        insert_bike_collocation_state_component_columns(seed, &mut columns, interval, STATE_V_MPS);
        insert_bike_collocation_state_component_columns(
            seed,
            &mut columns,
            interval,
            STATE_BETA_RAD,
        );
        insert_bike_collocation_state_component_columns(seed, &mut columns, interval, STATE_N_M);
        insert_bike_collocation_state_component_columns(seed, &mut columns, interval, STATE_XI_RAD);
    }
    if weights.penalty_n != 0.0 {
        for station in 0..seed.dimensions.station_count {
            columns.insert(state_offset(station) + STATE_N_M);
        }
    }
    if weights.penalty_xi != 0.0 {
        for station in 0..seed.dimensions.station_count {
            columns.insert(state_offset(station) + STATE_XI_RAD);
        }
    }
    if bike_objective_weights_need_station_dynamics_regularization(weights) {
        for station in 0..seed.dimensions.station_count {
            insert_bike_state_columns(&mut columns, station);
        }
        for interval in 0..seed.dimensions.interval_count {
            insert_bike_control_columns(seed, &mut columns, interval);
        }
    } else if weights.penalty_delta != 0.0
        || weights.penalty_delta_dd != 0.0
        || weights.penalty_f != 0.0
        || weights.penalty_f_dd != 0.0
        || weights.penalty_phi_cmd_dd != 0.0
    {
        for interval in 0..seed.dimensions.interval_count {
            insert_bike_control_columns(seed, &mut columns, interval);
        }
    }

    columns.into_iter().collect()
}

fn bike_objective_weights_need_station_dynamics_regularization(
    weights: BikeMintimeObjectiveWeights,
) -> bool {
    weights.penalty_lean_equilibrium != 0.0
        || weights.penalty_roll_tau != 0.0
        || bike_objective_weights_need_station_rate_regularization(weights)
}

fn bike_objective_weights_need_station_rate_regularization(
    weights: BikeMintimeObjectiveWeights,
) -> bool {
    weights.penalty_roll_tau_rate != 0.0
        || weights.penalty_ay_rate != 0.0
        || weights.penalty_phi_eq_rate != 0.0
}

fn bike_mintime_regularization_depends_on_variable(
    seed: &BikeMintimeNlpSeed,
    weights: BikeMintimeObjectiveWeights,
    variable_index: usize,
) -> bool {
    if variable_index < seed.dimensions.state_variable_count {
        let state_index = variable_index % BIKE_STATE_LEN;
        return (state_index == STATE_N_M && weights.penalty_n != 0.0)
            || (state_index == STATE_XI_RAD && weights.penalty_xi != 0.0)
            || bike_objective_weights_need_station_dynamics_regularization(weights);
    }

    let control_start = seed.dimensions.state_variable_count;
    let control_end = control_start + seed.dimensions.control_variable_count;
    if (control_start..control_end).contains(&variable_index) {
        let control_index = (variable_index - control_start) % BIKE_CONTROL_LEN;
        if bike_objective_weights_need_station_dynamics_regularization(weights) {
            return true;
        }
        return match control_index {
            CONTROL_DELTA_RAD => weights.penalty_delta != 0.0 || weights.penalty_delta_dd != 0.0,
            CONTROL_F_DRIVE_N | CONTROL_F_BRAKE_N => {
                weights.penalty_f != 0.0 || weights.penalty_f_dd != 0.0
            }
            CONTROL_PHI_DOT_RADPS => weights.penalty_phi_cmd_dd != 0.0,
            _ => false,
        };
    }

    false
}

fn bike_mintime_regularization_terms_for_variable_s(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    weights: BikeMintimeObjectiveWeights,
    x: &[f64],
    variable_index: usize,
) -> f64 {
    let mut total = 0.0;
    let closed = seed_is_closed(seed);

    if variable_index < seed.dimensions.state_variable_count {
        let station = variable_index / BIKE_STATE_LEN;
        let state_index = variable_index % BIKE_STATE_LEN;

        if state_index == STATE_N_M && weights.penalty_n != 0.0 {
            let n = state_series(x, seed.dimensions.interval_count, STATE_N_M, 1.0);
            total += weights.penalty_n * second_difference_squared(&n, closed);
        }
        if state_index == STATE_XI_RAD && weights.penalty_xi != 0.0 {
            let xi = state_series(x, seed.dimensions.interval_count, STATE_XI_RAD, 1.0);
            total += weights.penalty_xi * second_difference_squared(&xi, closed);
        }
        if weights.penalty_lean_equilibrium != 0.0 || weights.penalty_roll_tau != 0.0 {
            total +=
                bike_mintime_station_lean_roll_regularization_s(seed, params, weights, x, station);
        }
        if bike_objective_weights_need_station_rate_regularization(weights) {
            total += bike_mintime_station_rate_regularization_s_for_station(
                seed, params, weights, x, station,
            );
        }

        return total;
    }

    let control_start = seed.dimensions.state_variable_count;
    let control_end = control_start + seed.dimensions.control_variable_count;
    if (control_start..control_end).contains(&variable_index) {
        let control_index = (variable_index - control_start) % BIKE_CONTROL_LEN;

        if matches!(control_index, CONTROL_DELTA_RAD)
            && (weights.penalty_delta != 0.0 || weights.penalty_delta_dd != 0.0)
        {
            let delta = control_series(seed, x, CONTROL_DELTA_RAD, 1.0);
            let steering = bike_steering_regularization_series(
                params,
                weights.steering_regularization,
                &delta,
            );
            total += weights.penalty_delta * first_difference_squared(&steering, closed);
            total += weights.penalty_delta_dd * second_difference_squared(&steering, closed);
        }
        if matches!(control_index, CONTROL_F_DRIVE_N | CONTROL_F_BRAKE_N)
            && (weights.penalty_f != 0.0 || weights.penalty_f_dd != 0.0)
        {
            let force = drive_brake_regularization_series(seed, x);
            total += weights.penalty_f * first_difference_squared(&force, closed);
            total += weights.penalty_f_dd * second_difference_squared(&force, closed);
        }
        if matches!(control_index, CONTROL_PHI_DOT_RADPS) && weights.penalty_phi_cmd_dd != 0.0 {
            let phi_cmd = control_series(
                seed,
                x,
                CONTROL_PHI_DOT_RADPS,
                1.0 / params.lean_rate_max_radps.max(1e-9),
            );
            total += weights.penalty_phi_cmd_dd * second_difference_squared(&phi_cmd, closed);
        }
        if weights.penalty_lean_equilibrium != 0.0 || weights.penalty_roll_tau != 0.0 {
            let interval = (variable_index - control_start) / BIKE_CONTROL_LEN;
            for station in bike_control_regularization_affected_stations(seed, interval) {
                total += bike_mintime_station_lean_roll_regularization_s(
                    seed, params, weights, x, station,
                );
            }
        }
        if bike_objective_weights_need_station_rate_regularization(weights) {
            let interval = (variable_index - control_start) / BIKE_CONTROL_LEN;
            for station in bike_control_regularization_affected_stations(seed, interval) {
                total += bike_mintime_station_rate_regularization_s_for_station(
                    seed, params, weights, x, station,
                );
            }
        }
    }

    total
}

fn bike_control_regularization_affected_stations(
    seed: &BikeMintimeNlpSeed,
    interval: usize,
) -> Vec<usize> {
    let station_count = seed.dimensions.station_count;
    if station_count == 0 {
        return Vec::new();
    }
    if seed_is_closed(seed) {
        return vec![(interval + 1) % station_count];
    }
    if interval == 0 {
        return (0..=1.min(station_count - 1)).collect();
    }
    let station = interval + 1;
    if station < station_count {
        vec![station]
    } else {
        Vec::new()
    }
}

fn bike_mintime_station_lean_roll_regularization_s(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    weights: BikeMintimeObjectiveWeights,
    x: &[f64],
    station: usize,
) -> f64 {
    let mut total = 0.0;
    if station >= seed.dimensions.station_count {
        return total;
    }
    let state = bike_state_from(seed, x, station);
    let dynamics = bike_mintime_station_dynamics_from(seed, params, x, station);
    if weights.penalty_lean_equilibrium != 0.0 {
        let residual = lean_equilibrium_regularization_value(params, state, dynamics);
        total += weights.penalty_lean_equilibrium * residual * residual;
    }
    if weights.penalty_roll_tau != 0.0 {
        let scale = params.roll_tau_max_nm.max(1e-9);
        let residual = dynamics.roll_tau_cmd_nm / scale;
        total += weights.penalty_roll_tau * residual * residual;
    }
    total
}

fn bike_mintime_station_rate_regularization_s_for_station(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    weights: BikeMintimeObjectiveWeights,
    x: &[f64],
    station: usize,
) -> f64 {
    let mut total = 0.0;
    if station >= seed.dimensions.station_count {
        return total;
    }

    let closed = seed_is_closed(seed);
    if station > 0 {
        total += bike_mintime_station_rate_regularization_s_for_segment(
            seed,
            params,
            weights,
            x,
            station - 1,
        );
    } else if closed {
        total += bike_mintime_station_rate_regularization_s_for_segment(
            seed,
            params,
            weights,
            x,
            seed.dimensions.station_count.saturating_sub(1),
        );
    }
    total +=
        bike_mintime_station_rate_regularization_s_for_segment(seed, params, weights, x, station);
    total
}

fn bike_mintime_station_rate_regularization_s_for_segment(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    weights: BikeMintimeObjectiveWeights,
    x: &[f64],
    station: usize,
) -> f64 {
    let count = seed.dimensions.station_count;
    if count < 2 || station >= count || (!seed_is_closed(seed) && station + 1 >= count) {
        return 0.0;
    }

    let next = next_station_index(count, station);
    let current = bike_mintime_station_dynamics_from(seed, params, x, station);
    let next_dynamics = bike_mintime_station_dynamics_from(seed, params, x, next);
    let dt_s = station_transition_dt_s(seed, station, current, next_dynamics);
    let gravity = params.gravity_mps2.max(1e-9);

    let roll_tau_delta = (next_dynamics.roll_tau_cmd_nm - current.roll_tau_cmd_nm)
        / params.roll_tau_max_nm.max(1e-9);
    let ay_rate = ((next_dynamics.ay_mps2 - current.ay_mps2) / dt_s) / gravity;
    let current_phi_eq = (current.ay_mps2 / gravity).atan();
    let next_phi_eq = (next_dynamics.ay_mps2 / gravity).atan();
    let phi_eq_rate = (next_phi_eq - current_phi_eq) / dt_s / params.lean_rate_max_radps.max(1e-9);

    weights.penalty_roll_tau_rate * roll_tau_delta * roll_tau_delta
        + weights.penalty_ay_rate * ay_rate * ay_rate
        + weights.penalty_phi_eq_rate * phi_eq_rate * phi_eq_rate
}

fn bike_mintime_regularization_objective_s(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    weights: BikeMintimeObjectiveWeights,
    x: &[f64],
) -> f64 {
    let count = seed.dimensions.interval_count;
    if count == 0 {
        return 0.0;
    }

    let delta = control_series(seed, x, CONTROL_DELTA_RAD, 1.0);
    let steering_regularization =
        bike_steering_regularization_series(params, weights.steering_regularization, &delta);
    let force = drive_brake_regularization_series(seed, x);
    let phi_cmd = control_series(
        seed,
        x,
        CONTROL_PHI_DOT_RADPS,
        1.0 / params.lean_rate_max_radps.max(1e-9),
    );
    let n = state_series(x, count, STATE_N_M, 1.0);
    let xi = state_series(x, count, STATE_XI_RAD, 1.0);
    let closed = seed_is_closed(seed);
    let lean_equilibrium = lean_equilibrium_regularization_series(seed, params, x);
    let roll_tau = roll_tau_regularization_series(seed, params, x);
    let ay_rate = ay_rate_regularization_series(seed, params, x);
    let phi_eq_rate = phi_eq_rate_regularization_series(seed, params, x);

    weights.penalty_delta * first_difference_squared(&steering_regularization, closed)
        + weights.penalty_f * first_difference_squared(&force, closed)
        + weights.penalty_delta_dd * second_difference_squared(&steering_regularization, closed)
        + weights.penalty_f_dd * second_difference_squared(&force, closed)
        + weights.penalty_phi_cmd_dd * second_difference_squared(&phi_cmd, closed)
        + weights.penalty_n * second_difference_squared(&n, closed)
        + weights.penalty_xi * second_difference_squared(&xi, closed)
        + weights.penalty_lean_equilibrium * sum_squared(&lean_equilibrium)
        + weights.penalty_roll_tau * sum_squared(&roll_tau)
        + weights.penalty_roll_tau_rate * first_difference_squared(&roll_tau, closed)
        + weights.penalty_ay_rate * sum_squared(&ay_rate)
        + weights.penalty_phi_eq_rate * sum_squared(&phi_eq_rate)
}

fn bike_steering_regularization_series(
    params: BikeSingleTrackLeanParams,
    mode: BikeSteeringRegularizationMode,
    delta_rad: &[f64],
) -> Vec<f64> {
    match mode {
        BikeSteeringRegularizationMode::Curvature => {
            let wheelbase = params.wheelbase_m.max(1e-9);
            delta_rad
                .iter()
                .map(|delta| delta.tan() / wheelbase)
                .collect()
        }
        BikeSteeringRegularizationMode::RawDelta => delta_rad.to_vec(),
    }
}

fn lean_equilibrium_regularization_series(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    x: &[f64],
) -> Vec<f64> {
    (0..seed.dimensions.station_count)
        .map(|station| {
            let state = bike_state_from(seed, x, station);
            let dynamics = bike_mintime_station_dynamics_from(seed, params, x, station);
            lean_equilibrium_regularization_value(params, state, dynamics)
        })
        .collect()
}

fn lean_equilibrium_regularization_value(
    params: BikeSingleTrackLeanParams,
    state: BikeSingleTrackLeanState,
    dynamics: BikeSingleTrackLeanDynamics,
) -> f64 {
    let phi_equilibrium = (dynamics.ay_mps2 / params.gravity_mps2.max(1e-9)).atan();
    (state.phi_rad - phi_equilibrium) / BIKE_LEAN_EQUILIBRIUM_SCALE_RAD
}

fn roll_tau_regularization_series(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    x: &[f64],
) -> Vec<f64> {
    let scale = params.roll_tau_max_nm.max(1e-9);
    (0..seed.dimensions.station_count)
        .map(|station| {
            bike_mintime_station_dynamics_from(seed, params, x, station).roll_tau_cmd_nm / scale
        })
        .collect()
}

fn ay_rate_regularization_series(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    x: &[f64],
) -> Vec<f64> {
    let count = seed.dimensions.station_count;
    if count < 2 {
        return Vec::new();
    }
    let closed = seed_is_closed(seed);
    let segment_count = if closed { count } else { count - 1 };
    let gravity = params.gravity_mps2.max(1e-9);
    (0..segment_count)
        .map(|station| {
            let next = next_station_index(count, station);
            let current = bike_mintime_station_dynamics_from(seed, params, x, station);
            let next_dynamics = bike_mintime_station_dynamics_from(seed, params, x, next);
            let dt_s = station_transition_dt_s(seed, station, current, next_dynamics);
            ((next_dynamics.ay_mps2 - current.ay_mps2) / dt_s) / gravity
        })
        .collect()
}

fn phi_eq_rate_regularization_series(
    seed: &BikeMintimeNlpSeed,
    params: BikeSingleTrackLeanParams,
    x: &[f64],
) -> Vec<f64> {
    let count = seed.dimensions.station_count;
    if count < 2 {
        return Vec::new();
    }
    let closed = seed_is_closed(seed);
    let segment_count = if closed { count } else { count - 1 };
    let gravity = params.gravity_mps2.max(1e-9);
    let lean_rate = params.lean_rate_max_radps.max(1e-9);
    (0..segment_count)
        .map(|station| {
            let next = next_station_index(count, station);
            let current = bike_mintime_station_dynamics_from(seed, params, x, station);
            let next_dynamics = bike_mintime_station_dynamics_from(seed, params, x, next);
            let current_phi_eq = (current.ay_mps2 / gravity).atan();
            let next_phi_eq = (next_dynamics.ay_mps2 / gravity).atan();
            let dt_s = station_transition_dt_s(seed, station, current, next_dynamics);
            (next_phi_eq - current_phi_eq) / dt_s / lean_rate
        })
        .collect()
}

fn station_transition_dt_s(
    seed: &BikeMintimeNlpSeed,
    station: usize,
    current: BikeSingleTrackLeanDynamics,
    next: BikeSingleTrackLeanDynamics,
) -> f64 {
    let interval = station.min(seed.dimensions.interval_count.saturating_sub(1));
    let mean_sigma = 0.5 * (current.sigma_dt_ds + next.sigma_dt_ds).max(1e-9);
    interval_ds_m(seed, interval) * mean_sigma
}

fn sum_squared(values: &[f64]) -> f64 {
    values.iter().map(|value| value * value).sum()
}

fn first_difference_squared(values: &[f64], closed: bool) -> f64 {
    let count = values.len();
    if count < 2 {
        return 0.0;
    }

    let segment_count = if closed { count } else { count - 1 };
    (0..segment_count)
        .map(|index| {
            let next = if index + 1 == count { 0 } else { index + 1 };
            let diff = values[index] - values[next];
            diff * diff
        })
        .sum()
}

fn second_difference_squared(values: &[f64], closed: bool) -> f64 {
    let count = values.len();
    if count < 3 {
        return 0.0;
    }

    if closed {
        (0..count)
            .map(|index| {
                let diff = values[(index + count - 1) % count] - 2.0 * values[index]
                    + values[(index + 1) % count];
                diff * diff
            })
            .sum()
    } else {
        (1..count - 1)
            .map(|index| {
                let diff = values[index - 1] - 2.0 * values[index] + values[index + 1];
                diff * diff
            })
            .sum()
    }
}

fn add_first_difference_squared_gradient(
    values: &[f64],
    closed: bool,
    weight: f64,
    gradient: &mut [f64],
) {
    if weight == 0.0 || values.len() < 2 {
        return;
    }
    let count = values.len();
    let segment_count = if closed { count } else { count - 1 };
    for index in 0..segment_count {
        let next = if index + 1 == count { 0 } else { index + 1 };
        let diff = values[index] - values[next];
        gradient[index] += 2.0 * weight * diff;
        gradient[next] -= 2.0 * weight * diff;
    }
}

fn add_second_difference_squared_gradient(
    values: &[f64],
    closed: bool,
    weight: f64,
    gradient: &mut [f64],
) {
    if weight == 0.0 || values.len() < 3 {
        return;
    }
    let count = values.len();
    if closed {
        for index in 0..count {
            let previous = (index + count - 1) % count;
            let next = (index + 1) % count;
            let diff = values[previous] - 2.0 * values[index] + values[next];
            gradient[previous] += 2.0 * weight * diff;
            gradient[index] -= 4.0 * weight * diff;
            gradient[next] += 2.0 * weight * diff;
        }
    } else {
        for index in 1..count - 1 {
            let diff = values[index - 1] - 2.0 * values[index] + values[index + 1];
            gradient[index - 1] += 2.0 * weight * diff;
            gradient[index] -= 4.0 * weight * diff;
            gradient[index + 1] += 2.0 * weight * diff;
        }
    }
}

