    #[test]
    fn bike_v1_experimental_builds_physically_constrained_ipopt_problem() {
        let request = MintimeSolveRequestV1::parse(
            &bike_mintime_test_request_json(
                r#""solve_options": {
                    "width_opt": 0.86,
                    "bike_model_version": "v1_experimental",
                    "max_iter": 2,
                    "ipopt_print_level": 0
                }"#,
            ),
            VehicleDynamicsModelFamily::BikeDynamics,
        )
        .unwrap();
        let base_params =
            BikeSingleTrackLeanParams::from_profile(&request.vehicle_dynamics_profile).unwrap();
        let options = BikeMintimeSolveOptions::from_request(&request).unwrap();
        let geometry_seed = build_bike_mintime_nlp_seed(&request, base_params).unwrap();
        let problem = build_bike_v1_experimental_problem(
            geometry_seed,
            BikeCountersteerLeanParamsV1::from_v05(base_params),
            options,
            BikeMintimeObjectiveWeights::from_request(&request),
            MintimeStageProgressMapping::single_stage(),
        )
        .unwrap();
        assert_eq!(
            problem
                .seed_override_summary
                .get("source")
                .and_then(JsonValue::as_str),
            Some("current")
        );
        assert_eq!(
            problem
                .seed_override_summary
                .get("applied")
                .map(|value| matches!(value, JsonValue::Bool(true))),
            Some(false)
        );

        assert_eq!(
            problem.decision_layout.state_len,
            crate::bike_mintime_v1::BIKE_V1_STATE_LEN
        );
        assert_eq!(
            problem.decision_layout.control_len,
            crate::bike_mintime_v1::BIKE_V1_CONTROL_LEN
        );
        assert_eq!(
            problem.initial_guess.len(),
            problem.decision_layout.dimensions.decision_variable_count()
        );
        assert_eq!(
            problem
                .materialized_seed_diagnostics
                .get("schema_version")
                .and_then(JsonValue::as_str),
            Some("bike_v1_materialized_seed_diagnostics.v2")
        );
        assert_eq!(
            problem
                .materialized_seed_diagnostics
                .get("state_source_mode")
                .and_then(JsonValue::as_str),
            Some("reference_curvature")
        );
        assert_eq!(
            problem
                .materialized_seed_diagnostics
                .get("station")
                .and_then(JsonValue::as_array)
                .map(|rows| rows.len()),
            Some(problem.decision_layout.dimensions.station_count)
        );
        assert_eq!(
            problem
                .materialized_seed_diagnostics
                .get("collocation")
                .and_then(JsonValue::as_array)
                .map(|rows| rows.len()),
            Some(
                problem.decision_layout.dimensions.interval_count
                    * problem.decision_layout.collocation_degree
            )
        );
        if problem
            .geometry_seed
            .kappa_1pm
            .iter()
            .any(|kappa| kappa.abs() > 1.0e-6)
        {
            assert!(
                (0..problem.decision_layout.dimensions.station_count).any(|station| {
                    let offset = problem.decision_layout.state_offset(station);
                    problem.initial_guess[offset + crate::bike_mintime_v1::V1_STATE_OMEGA_Z_RADPS]
                        .abs()
                        > 1.0e-6
                        || problem.initial_guess[offset + crate::bike_mintime_v1::V1_STATE_PHI_RAD]
                            .abs()
                            > 1.0e-6
                        || problem.initial_guess
                            [offset + crate::bike_mintime_v1::V1_STATE_DELTA_RAD]
                            .abs()
                            > 1.0e-6
                })
            );
        }
        assert_eq!(problem.rows.len(), problem.constraint_lower_bounds.len());
        assert_eq!(problem.rows.len(), problem.constraint_upper_bounds.len());
        assert!(!problem.jacobian_pattern.is_empty());
        assert_eq!(problem.constraint_scales.len(), problem.rows.len());
        assert!(problem.rows.iter().any(|row| matches!(
            row,
            BikeV1ExperimentalConstraintRow::Kamm {
                sample: BikeV1ExperimentalSample::Station { .. },
                axle: "front"
            }
        )));
        assert_eq!(
            problem
                .rows
                .iter()
                .filter(|row| matches!(
                    row,
                    BikeV1ExperimentalConstraintRow::SectionMapJacobian {
                        sample: BikeV1ExperimentalSample::IntervalStart { .. }
                    } | BikeV1ExperimentalConstraintRow::SectionForwardProgress {
                        sample: BikeV1ExperimentalSample::IntervalStart { .. }
                    } | BikeV1ExperimentalConstraintRow::NormalLoad {
                        sample: BikeV1ExperimentalSample::IntervalStart { .. },
                        ..
                    } | BikeV1ExperimentalConstraintRow::Kamm {
                        sample: BikeV1ExperimentalSample::IntervalStart { .. },
                        ..
                    } | BikeV1ExperimentalConstraintRow::PowerLimit {
                        sample: BikeV1ExperimentalSample::IntervalStart { .. }
                    } | BikeV1ExperimentalConstraintRow::SlipAngle {
                        sample: BikeV1ExperimentalSample::IntervalStart { .. },
                        ..
                    }
                ))
                .count(),
            problem.decision_layout.dimensions.interval_count * 9
        );
        let interval_start_rows = problem
            .rows
            .iter()
            .copied()
            .filter(|row| {
                matches!(
                    row,
                    BikeV1ExperimentalConstraintRow::SectionMapJacobian {
                        sample: BikeV1ExperimentalSample::IntervalStart { .. },
                    } | BikeV1ExperimentalConstraintRow::SectionForwardProgress {
                        sample: BikeV1ExperimentalSample::IntervalStart { .. },
                    } | BikeV1ExperimentalConstraintRow::NormalLoad {
                        sample: BikeV1ExperimentalSample::IntervalStart { .. },
                        ..
                    } | BikeV1ExperimentalConstraintRow::Kamm {
                        sample: BikeV1ExperimentalSample::IntervalStart { .. },
                        ..
                    } | BikeV1ExperimentalConstraintRow::PowerLimit {
                        sample: BikeV1ExperimentalSample::IntervalStart { .. },
                    } | BikeV1ExperimentalConstraintRow::SlipAngle {
                        sample: BikeV1ExperimentalSample::IntervalStart { .. },
                        ..
                    }
                )
            })
            .collect::<Vec<_>>();
        assert!(!interval_start_rows.is_empty());
        for row in interval_start_rows.iter().take(16) {
            assert!(problem
                .constraint_value(&problem.initial_guess, *row)
                .unwrap()
                .is_finite());
        }
        let tau_guard_rows = problem
            .rows
            .iter()
            .copied()
            .filter(|row| {
                matches!(
                    row,
                    BikeV1ExperimentalConstraintRow::SectionMapJacobian {
                        sample: BikeV1ExperimentalSample::TauGuard { .. },
                    } | BikeV1ExperimentalConstraintRow::SectionForwardProgress {
                        sample: BikeV1ExperimentalSample::TauGuard { .. },
                    } | BikeV1ExperimentalConstraintRow::NormalLoad {
                        sample: BikeV1ExperimentalSample::TauGuard { .. },
                        ..
                    } | BikeV1ExperimentalConstraintRow::Kamm {
                        sample: BikeV1ExperimentalSample::TauGuard { .. },
                        ..
                    } | BikeV1ExperimentalConstraintRow::PowerLimit {
                        sample: BikeV1ExperimentalSample::TauGuard { .. },
                    } | BikeV1ExperimentalConstraintRow::SlipAngle {
                        sample: BikeV1ExperimentalSample::TauGuard { .. },
                        ..
                    }
                )
            })
            .collect::<Vec<_>>();
        assert_eq!(
            tau_guard_rows.len(),
            problem.decision_layout.dimensions.interval_count
                * super::BIKE_V1_TAU_GUARD_VALUES.len()
                * 9
        );
        // With unfiltered load feedback, a TauGuard sample is evaluated from its
        // own interval state.  Its next-station state basis is therefore exactly
        // zero and must not inflate the sparse Jacobian pattern.
        for (row_index, row) in problem.rows.iter().copied().enumerate() {
            let (BikeV1ExperimentalConstraintRow::SectionMapJacobian {
                sample: BikeV1ExperimentalSample::TauGuard { interval, .. },
            }
            | BikeV1ExperimentalConstraintRow::SectionForwardProgress {
                sample: BikeV1ExperimentalSample::TauGuard { interval, .. },
            }
            | BikeV1ExperimentalConstraintRow::NormalLoad {
                sample: BikeV1ExperimentalSample::TauGuard { interval, .. },
                ..
            }
            | BikeV1ExperimentalConstraintRow::Kamm {
                sample: BikeV1ExperimentalSample::TauGuard { interval, .. },
                ..
            }
            | BikeV1ExperimentalConstraintRow::PowerLimit {
                sample: BikeV1ExperimentalSample::TauGuard { interval, .. },
            }
            | BikeV1ExperimentalConstraintRow::SlipAngle {
                sample: BikeV1ExperimentalSample::TauGuard { interval, .. },
                ..
            }) = row
            else {
                continue;
            };
            let next_state_offset = problem.decision_layout.state_offset(interval + 1);
            for state_index in 0..crate::bike_mintime_v1::BIKE_V1_STATE_LEN {
                assert!(
                    !problem
                        .jacobian_pattern
                        .contains(&(
                            i32::try_from(row_index).unwrap(),
                            i32::try_from(next_state_offset + state_index).unwrap(),
                        )),
                    "TauGuard row {row_index} unexpectedly depends on next-station state {state_index}"
                );
            }
        }
        for row in tau_guard_rows.iter().take(16) {
            assert!(problem
                .constraint_value(&problem.initial_guess, *row)
                .unwrap()
                .is_finite());
        }
        assert!(problem.rows.iter().any(|row| matches!(
            row,
            BikeV1ExperimentalConstraintRow::Kamm {
                sample: BikeV1ExperimentalSample::Collocation { .. },
                axle: "rear"
            }
        )));
        assert!(problem
            .rows
            .iter()
            .any(|row| matches!(row, BikeV1ExperimentalConstraintRow::NormalLoad { .. })));
        assert!(problem
            .rows
            .iter()
            .any(|row| matches!(row, BikeV1ExperimentalConstraintRow::PowerLimit { .. })));
        assert!(problem
            .rows
            .iter()
            .any(|row| matches!(row, BikeV1ExperimentalConstraintRow::SlipAngle { .. })));
        assert!(problem
            .rows
            .iter()
            .any(|row| matches!(row, BikeV1ExperimentalConstraintRow::DriveBrakeMutex { .. })));
        assert!(problem
            .rows
            .iter()
            .any(|row| matches!(row, BikeV1ExperimentalConstraintRow::SteeringTorque { .. })));
        assert!(problem.rows.iter().any(|row| matches!(
            row,
            BikeV1ExperimentalConstraintRow::SectionMapJacobian {
                sample: BikeV1ExperimentalSample::Station { .. }
            }
        )));
        assert!(problem.rows.iter().any(|row| matches!(
            row,
            BikeV1ExperimentalConstraintRow::SectionMapJacobian {
                sample: BikeV1ExperimentalSample::Collocation { .. }
            }
        )));
        assert!(problem.rows.iter().any(|row| matches!(
            row,
            BikeV1ExperimentalConstraintRow::SectionForwardProgress { .. }
        )));
        assert!(problem
            .lap_time_objective_s(&problem.initial_guess)
            .unwrap()
            .is_finite());
        let lap_time_s = problem
            .lap_time_objective_s(&problem.initial_guess)
            .unwrap();
        let regularization_s = problem.regularization_objective_s(&problem.initial_guess);
        let objective_s = problem.objective_s(&problem.initial_guess).unwrap();
        assert!(regularization_s.is_finite());
        assert!(objective_s >= lap_time_s);
        let dense_objective_gradient = problem
            .objective_gradient_numeric(&problem.initial_guess)
            .unwrap();
        let objective_gradient = problem
            .objective_gradient_structured_numeric(&problem.initial_guess)
            .unwrap();
        assert_eq!(objective_gradient.len(), problem.initial_guess.len());
        assert!(objective_gradient.iter().all(|value| value.is_finite()));
        let max_gradient_delta = dense_objective_gradient
            .iter()
            .zip(objective_gradient.iter())
            .map(|(dense, structured)| (dense - structured).abs())
            .fold(0.0, f64::max);
        assert!(
            max_gradient_delta < 1.0e-5,
            "V1 structured objective gradient mismatch: max delta {max_gradient_delta}"
        );
        let mut perturbed = problem.initial_guess.clone();
        let station_count = problem.decision_layout.dimensions.station_count;
        perturbed[problem.decision_layout.state_offset(0) + V1_STATE_V_MPS] += 0.5;
        perturbed[problem.decision_layout.state_offset(1) + V1_STATE_BETA_RAD] += 0.01;
        perturbed
            [problem.decision_layout.state_offset(station_count - 1) + V1_STATE_DELTA_DOT_RADPS] +=
            0.03;
        perturbed[problem.decision_layout.control_offset(0) + V1_CONTROL_STEERING_TORQUE_NM] += 2.0;
        perturbed[problem
            .decision_layout
            .control_offset(problem.decision_layout.dimensions.interval_count - 1)
            + V1_CONTROL_F_DRIVE_N] += 50.0;
        let dense_perturbed_gradient = problem.objective_gradient_numeric(&perturbed).unwrap();
        let structured_perturbed_gradient = problem
            .objective_gradient_structured_numeric(&perturbed)
            .unwrap();
        let max_perturbed_gradient_delta = dense_perturbed_gradient
            .iter()
            .zip(structured_perturbed_gradient.iter())
            .map(|(dense, structured)| (dense - structured).abs())
            .fold(0.0, f64::max);
        assert!(
            max_perturbed_gradient_delta < 1.0e-5,
            "V1 localized structured objective gradient mismatch on perturbed seed: max delta {max_perturbed_gradient_delta}"
        );
        let full_complex_gradient =
            problem.complex_regularization_gradient_numeric_full(&perturbed);
        let localized_complex_gradient =
            problem.complex_regularization_gradient_numeric_localized(&perturbed);
        let max_complex_gradient_delta = full_complex_gradient
            .iter()
            .zip(localized_complex_gradient.iter())
            .map(|(full, localized)| (full - localized).abs())
            .fold(0.0, f64::max);
        assert!(
            max_complex_gradient_delta < 1.0e-5,
            "V1 localized complex regularization gradient mismatch: max delta {max_complex_gradient_delta}"
        );
        assert!(
            problem.objective_gradient_variable_indices().len() == problem.initial_guess.len(),
            "V1 objective should include collocation states because lap time uses collocation quadrature"
        );
        let first_collocation_offset = problem.decision_layout.collocation_state_offset(0, 0);
        assert!(
            objective_gradient[first_collocation_offset + V1_STATE_V_MPS] < 0.0,
            "collocation quadrature lap objective should depend on collocation speed"
        );
        let values = problem.constraint_values(&problem.initial_guess).unwrap();
        assert_eq!(values.len(), problem.rows.len());
        assert!(values.iter().all(|value| value.is_finite()));
        let mut constraint_profile = BikeV1CallbackProfile::default();
        let blocked_values = problem
            .constraint_values_profiled(&problem.initial_guess, &mut constraint_profile)
            .unwrap();
        let max_blocked_constraint_delta = values
            .iter()
            .zip(blocked_values.iter())
            .map(|(reference, blocked)| (reference - blocked).abs())
            .fold(0.0, f64::max);
        assert!(
            max_blocked_constraint_delta <= 1.0e-10,
            "V1 block constraint evaluation changed a row: max delta {max_blocked_constraint_delta}"
        );
        let mut callback_profile = BikeV1CallbackProfile::default();
        let jacobian = problem
            .sparse_jacobian_numeric_profiled(&problem.initial_guess, &mut callback_profile)
            .unwrap();
        assert_eq!(jacobian.len(), problem.jacobian_pattern.len());
        assert!(jacobian.iter().all(|value| value.is_finite()));
        let mut plus = problem.initial_guess.clone();
        let mut minus = problem.initial_guess.clone();
        let mut checked_structured_derivatives = 0;
        for (entry_index, row_index, variable_index, structured) in
            problem.jacobian_pattern.iter().enumerate().filter_map(
                |(entry_index, (row, variable))| {
                    let row = usize::try_from(*row).ok()?;
                    let variable = usize::try_from(*variable).ok()?;
                    problem
                        .constraint_derivative_structured(&problem.initial_guess, row, variable)
                        .map(|structured| (entry_index, row, variable, structured))
                },
            )
        {
            let numeric = problem
                .constraint_derivative_finite_difference(
                    &mut plus,
                    &mut minus,
                    &problem.initial_guess,
                    row_index,
                    variable_index,
                    1.0e-6,
                )
                .unwrap();
            assert!(numeric.is_finite());
            assert!(structured.is_finite());
            assert!(
                (jacobian[entry_index] - structured).abs() < 1.0e-10,
                "V1 block Jacobian mismatch at row {row_index}, variable {variable_index}: block={} structured={structured}",
                jacobian[entry_index]
            );
            assert!(
                (numeric - structured).abs() < 1.0e-5,
                "V1 structured derivative mismatch at row {row_index}, variable {variable_index}: numeric={numeric}"
            );
            checked_structured_derivatives += 1;
        }
        assert!(checked_structured_derivatives > 0);
        let JsonValue::Object(model_specific) =
            problem.model_specific_diagnostics_json(&problem.initial_guess)
        else {
            panic!("V1 model-specific diagnostics must be a JSON object");
        };
        assert!(model_specific.iter().any(
            |(key, value)| key == "mode" && value.as_str() == Some("hard_constraints_enabled")
        ));
        assert!(model_specific
            .iter()
            .any(|(key, value)| key == "debug_basin_trust_mode" && value.as_str() == Some("off")));
        assert!(model_specific
            .iter()
            .any(|(key, _)| key == "debug_basin_trust_weight"));
        assert!(model_specific
            .iter()
            .any(|(key, _)| key == "max_front_kamm"));
        assert!(model_specific
            .iter()
            .any(|(key, _)| key == "max_steering_torque_util"));
        assert!(model_specific
            .iter()
            .any(|(key, _)| key == "max_phi_eq_dot_util"));
        assert!(model_specific
            .iter()
            .any(|(key, _)| key == "min_section_det_station"));
        assert!(model_specific
            .iter()
            .any(|(key, _)| key == "min_section_det_collocation"));
        assert!(model_specific
            .iter()
            .any(|(key, _)| key == "sigma_clamp_risk_count_station"));
        let JsonValue::Object(geometry_diagnostics) =
            problem.geometry_diagnostics_json(&problem.initial_guess)
        else {
            panic!("V1 geometry diagnostics must be a JSON object");
        };
        assert!(geometry_diagnostics.iter().any(
            |(key, value)| key == "geometry_source" && value.as_str() == Some("section_frame")
        ));
        assert!(geometry_diagnostics
            .iter()
            .any(|(key, _)| key == "min_section_det_dense"));
        assert!(geometry_diagnostics
            .iter()
            .any(|(key, _)| key == "min_abs_section_det_dense"));
        assert!(geometry_diagnostics
            .iter()
            .any(|(key, _)| key == "section_det_reference_sign"));
        assert!(geometry_diagnostics
            .iter()
            .any(|(key, _)| key == "section_det_sign_flip_count"));
        assert!(geometry_diagnostics
            .iter()
            .any(|(key, _)| key == "sigma_clamp_count"));
        let JsonValue::Object(dense) = problem.dense_trajectory_json(&problem.initial_guess, 2)
        else {
            panic!("V1 dense trajectory must be a JSON object");
        };
        assert!(dense
            .iter()
            .any(|(key, value)| key == "bike_model_version"
                && value.as_str() == Some("v1_experimental")));
        assert!(dense.iter().any(|(key, _)| key == "steering_torque_nm"));
        assert!(dense
            .iter()
            .any(|(key, _)| key == "steering_control_normalized"));
        assert!(dense
            .iter()
            .any(|(key, _)| key == "steering_input_torque_nm"));
        assert!(dense.iter().any(|(key, _)| key == "front_kamm"));
        assert!(dense.iter().any(|(key, _)| key == "alpha_front_rad"));
        assert!(dense
            .iter()
            .any(|(key, _)| key == "d_fy_front_d_alpha_n_per_rad"));
        assert!(dense.iter().any(|(key, _)| key == "tire_branch_front"));
        assert!(dense
            .iter()
            .any(|(key, _)| key == "front_drive_utilization"));
        assert!(dense
            .iter()
            .any(|(key, _)| key == "rear_lateral_capacity_n"));
        assert!(dense.iter().any(|(key, _)| key == "phi_rad"));
        let residual_report = problem.residual_report_json(&problem.initial_guess, 8);
        assert_eq!(
            residual_report
                .get("schema_version")
                .and_then(JsonValue::as_str),
            Some("bike_v1_residual_report.v1")
        );
        assert!(residual_report
            .get("max_scaled_violation")
            .and_then(JsonValue::as_f64)
            .is_some());
        let families = residual_report
            .get("by_family")
            .and_then(JsonValue::as_array)
            .expect("V1 residual report must include family stats");
        assert!(families
            .iter()
            .any(|entry| entry.get("family").and_then(JsonValue::as_str)
                == Some("collocation_dynamics")));
        assert!(families
            .iter()
            .any(|entry| entry.get("family").and_then(JsonValue::as_str) == Some("kamm")));
        assert!(families
            .iter()
            .any(|entry| entry.get("family").and_then(JsonValue::as_str) == Some("power")));
        assert!(families
            .iter()
            .any(|entry| entry.get("family").and_then(JsonValue::as_str)
                == Some("section_map_jacobian")));
        assert!(families
            .iter()
            .any(|entry| entry.get("family").and_then(JsonValue::as_str)
                == Some("section_forward_progress")));
        let top_constraints = residual_report
            .get("top_constraints")
            .and_then(JsonValue::as_array)
            .expect("V1 residual report must include top constraints");
        assert!(!top_constraints.is_empty());
        assert!(top_constraints
            .iter()
            .any(|entry| entry.get("context").is_some()));
        let delta_dot_audit =
            problem.delta_dot_dynamics_audit_json(&problem.initial_guess, 8, 0, 3);
        assert_eq!(
            delta_dot_audit
                .get("schema_version")
                .and_then(JsonValue::as_str),
            Some("bike_v1_delta_dot_dynamics_audit.v1")
        );
        let delta_dot_top_rows = delta_dot_audit
            .get("top_rows")
            .and_then(JsonValue::as_array)
            .expect("V1 delta-dot audit must include top rows");
        assert!(!delta_dot_top_rows.is_empty());
        assert!(delta_dot_top_rows.iter().all(|row| row
            .get("polynomial_delta_dot_s")
            .and_then(JsonValue::as_f64)
            .is_some()));
        assert!(delta_dot_top_rows.iter().all(|row| row
            .get("dynamics_delta_dot_ds")
            .and_then(JsonValue::as_f64)
            .is_some()));
        let boundary_audit = problem.boundary_transition_audit_json(&problem.initial_guess, 8);
        assert_eq!(
            boundary_audit
                .get("schema_version")
                .and_then(JsonValue::as_str),
            Some("bike_v1_boundary_transition_audit.v1")
        );
        let boundary_top_rows = boundary_audit
            .get("top_rows")
            .and_then(JsonValue::as_array)
            .expect("V1 boundary audit must include top rows");
        assert!(!boundary_top_rows.is_empty());
        let boundary_rows = boundary_audit
            .get("rows")
            .and_then(JsonValue::as_array)
            .expect("V1 boundary audit must include all rows");
        assert_eq!(
            boundary_rows.len(),
            problem.decision_layout.dimensions.station_count
        );
        assert!(boundary_top_rows.iter().all(|row| row
            .get("ay_jump_mps2")
            .and_then(JsonValue::as_f64)
            .is_some()));
        assert!(boundary_top_rows.iter().all(|row| row
            .get("steering_torque_jump_nm")
            .and_then(JsonValue::as_f64)
            .is_some()));
    }

    #[test]
    fn bike_v1_debug_control_lowfreq_adds_steering_equality_rows() {
        let request = MintimeSolveRequestV1::parse(
            &bike_mintime_test_request_json(
                r#""solve_options": {
                    "width_opt": 0.86,
                    "bike_model_version": "v1_experimental",
                    "max_iter": 2,
                    "debug_v1_control_lowfreq_mode": "steering_torque",
                    "debug_v1_control_lowfreq_block_size": 4
                }"#,
            ),
            VehicleDynamicsModelFamily::BikeDynamics,
        )
        .unwrap();
        let base_params =
            BikeSingleTrackLeanParams::from_profile(&request.vehicle_dynamics_profile).unwrap();
        let options = BikeMintimeSolveOptions::from_request(&request).unwrap();
        let geometry_seed = build_bike_mintime_nlp_seed(&request, base_params).unwrap();
        let problem = build_bike_v1_experimental_problem(
            geometry_seed,
            BikeCountersteerLeanParamsV1::from_v05(base_params),
            options,
            BikeMintimeObjectiveWeights::from_request(&request),
            MintimeStageProgressMapping::single_stage(),
        )
        .unwrap();

        let rows = problem
            .rows
            .iter()
            .copied()
            .filter_map(|row| match row {
                BikeV1ExperimentalConstraintRow::ControlLowFrequency {
                    interval,
                    anchor_interval,
                    control_index,
                } => Some((interval, anchor_interval, control_index)),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(!rows.is_empty());
        assert!(rows
            .iter()
            .all(|(_, _, control_index)| *control_index == V1_CONTROL_STEERING_TORQUE_NM));
        assert!(rows
            .iter()
            .all(|(interval, anchor, _)| interval > anchor && interval - anchor < 4));

        let row_index = problem
            .rows
            .iter()
            .position(|row| {
                matches!(
                    row,
                    BikeV1ExperimentalConstraintRow::ControlLowFrequency { .. }
                )
            })
            .unwrap();
        assert_eq!(problem.constraint_lower_bounds[row_index], 0.0);
        assert_eq!(problem.constraint_upper_bounds[row_index], 0.0);
        let row = problem.rows[row_index];
        let BikeV1ExperimentalConstraintRow::ControlLowFrequency {
            interval,
            anchor_interval,
            control_index,
        } = row
        else {
            unreachable!();
        };
        let current_index = problem.decision_layout.control_offset(interval) + control_index;
        let anchor_index = problem.decision_layout.control_offset(anchor_interval) + control_index;
        assert_eq!(
            problem.constraint_derivative_structured(
                &problem.initial_guess,
                row_index,
                current_index
            ),
            Some(1.0)
        );
        assert_eq!(
            problem.constraint_derivative_structured(
                &problem.initial_guess,
                row_index,
                anchor_index
            ),
            Some(-1.0)
        );
    }

    #[test]
    fn bike_v1_debug_basin_trust_has_consistent_objective_gradient() {
        let request = MintimeSolveRequestV1::parse(
            &bike_mintime_test_request_json(
                r#""solve_options": {
                    "width_opt": 0.86,
                    "bike_model_version": "v1_experimental",
                    "max_iter": 2,
                    "debug_v1_basin_trust_mode": "v_heading_n_omega",
                    "debug_v1_basin_trust_weight": 0.05
                }"#,
            ),
            VehicleDynamicsModelFamily::BikeDynamics,
        )
        .unwrap();
        let base_params =
            BikeSingleTrackLeanParams::from_profile(&request.vehicle_dynamics_profile).unwrap();
        let options = BikeMintimeSolveOptions::from_request(&request).unwrap();
        assert_eq!(
            options.debug_v1_basin_trust_mode,
            BikeV1BasinTrustMode::VHeadingNOmegaZ
        );
        let geometry_seed = build_bike_mintime_nlp_seed(&request, base_params).unwrap();
        let problem = build_bike_v1_experimental_problem(
            geometry_seed,
            BikeCountersteerLeanParamsV1::from_v05(base_params),
            options,
            BikeMintimeObjectiveWeights::from_request(&request),
            MintimeStageProgressMapping::single_stage(),
        )
        .unwrap();

        assert_close(
            super::bike_v1_basin_trust_objective_s(&problem, &problem.initial_guess),
            0.0,
        );

        let mut perturbed = problem.initial_guess.clone();
        let station_offset = problem.decision_layout.state_offset(0);
        perturbed[station_offset + V1_STATE_V_MPS] += 0.4;
        perturbed[station_offset + V1_STATE_BETA_RAD] += 0.02;
        perturbed[station_offset + V1_STATE_XI_RAD] -= 0.01;
        perturbed[station_offset + V1_STATE_N_M] += 0.15;
        perturbed[station_offset + V1_STATE_OMEGA_Z_RADPS] += 0.03;

        let collocation_offset = problem.decision_layout.collocation_state_offset(0, 0);
        perturbed[collocation_offset + V1_STATE_V_MPS] += 0.2;
        perturbed[collocation_offset + V1_STATE_XI_RAD] += 0.015;

        assert!(super::bike_v1_basin_trust_objective_s(&problem, &perturbed) > 0.0);

        let dense_gradient = problem.objective_gradient_numeric(&perturbed).unwrap();
        let structured_gradient = problem
            .objective_gradient_structured_numeric(&perturbed)
            .unwrap();
        let max_gradient_delta = dense_gradient
            .iter()
            .zip(structured_gradient.iter())
            .map(|(dense, structured)| (dense - structured).abs())
            .fold(0.0, f64::max);
        assert!(
            max_gradient_delta < 1.0e-5,
            "V1 debug basin trust gradient mismatch: max delta {max_gradient_delta}"
        );
    }

    #[test]
    fn bike_v1_debug_continuation_terms_have_consistent_objective_gradient() {
        let request = MintimeSolveRequestV1::parse(
            &bike_mintime_test_request_json(
                r#""solve_options": {
                    "width_opt": 0.86,
                    "bike_model_version": "v1_experimental",
                    "max_iter": 2,
                    "penalty_n": 0.003,
                    "penalty_xi": 0.02,
                    "debug_v1_energy_guard_weight": 0.11,
                    "debug_v1_energy_guard_margin_mps": 0.5,
                    "debug_v1_active_set_guard_weight": 0.13,
                    "debug_v1_active_set_guard_margin": 0.2,
                    "debug_v1_force_loop_smooth_weight": 0.17
                }"#,
            ),
            VehicleDynamicsModelFamily::BikeDynamics,
        )
        .unwrap();
        let base_params =
            BikeSingleTrackLeanParams::from_profile(&request.vehicle_dynamics_profile).unwrap();
        let options = BikeMintimeSolveOptions::from_request(&request).unwrap();
        let geometry_seed = build_bike_mintime_nlp_seed(&request, base_params).unwrap();
        let problem = build_bike_v1_experimental_problem(
            geometry_seed,
            BikeCountersteerLeanParamsV1::from_v05(base_params),
            options,
            BikeMintimeObjectiveWeights::from_request(&request),
            MintimeStageProgressMapping::single_stage(),
        )
        .unwrap();

        assert_close(
            super::bike_v1_energy_guard_objective_s(&problem, &problem.initial_guess),
            0.0,
        );

        let mut perturbed = problem.initial_guess.clone();
        let station_offset = problem.decision_layout.state_offset(0);
        perturbed[station_offset + V1_STATE_V_MPS] -= 1.2;
        perturbed[station_offset + V1_STATE_N_M] += 0.25;
        perturbed[station_offset + V1_STATE_XI_RAD] -= 0.05;
        perturbed[station_offset + V1_STATE_PHI_RAD] =
            problem.lower_bounds[station_offset + V1_STATE_PHI_RAD] + 0.01;
        perturbed[station_offset + V1_STATE_DELTA_RAD] =
            problem.upper_bounds[station_offset + V1_STATE_DELTA_RAD] - 0.01;
        let station_offset_1 = problem.decision_layout.state_offset(1);
        perturbed[station_offset_1 + V1_STATE_N_M] -= 0.1;
        perturbed[station_offset_1 + V1_STATE_XI_RAD] += 0.03;
        let collocation_offset = problem.decision_layout.collocation_state_offset(0, 0);
        perturbed[collocation_offset + V1_STATE_V_MPS] -= 1.0;
        perturbed[collocation_offset + V1_STATE_OMEGA_Z_RADPS] =
            problem.lower_bounds[collocation_offset + V1_STATE_OMEGA_Z_RADPS] + 0.01;
        let control_offset = problem.decision_layout.control_offset(0);
        perturbed[control_offset + V1_CONTROL_STEERING_TORQUE_NM] =
            problem.upper_bounds[control_offset + V1_CONTROL_STEERING_TORQUE_NM] - 0.01;

        assert!(super::bike_v1_energy_guard_objective_s(&problem, &perturbed) > 0.0);
        assert!(super::bike_v1_active_set_guard_objective_s(&problem, &perturbed) > 0.0);
        assert!(super::bike_v1_force_loop_smooth_objective_s(&problem, &perturbed) > 0.0);

        let dense_gradient = problem.objective_gradient_numeric(&perturbed).unwrap();
        let structured_gradient = problem
            .objective_gradient_structured_numeric(&perturbed)
            .unwrap();
        let max_gradient_delta = dense_gradient
            .iter()
            .zip(structured_gradient.iter())
            .map(|(dense, structured)| (dense - structured).abs())
            .fold(0.0, f64::max);
        assert!(
            max_gradient_delta < 1.0e-5,
            "V1 debug continuation gradient mismatch: max delta {max_gradient_delta}"
        );
    }

    #[test]
    fn bike_v1_section_regularity_rejects_folded_offset_map() {
        let request = MintimeSolveRequestV1::parse(
            &bike_mintime_test_request_json(
                r#""solve_options": {
                    "width_opt": 0.86,
                    "bike_model_version": "v1_experimental",
                    "max_iter": 2,
                    "ipopt_print_level": 0
                }"#,
            ),
            VehicleDynamicsModelFamily::BikeDynamics,
        )
        .unwrap();
        let base_params =
            BikeSingleTrackLeanParams::from_profile(&request.vehicle_dynamics_profile).unwrap();
        let options = BikeMintimeSolveOptions::from_request(&request).unwrap();
        let mut geometry_seed = build_bike_mintime_nlp_seed(&request, base_params).unwrap();
        let station = 3_usize;
        let interval = station - 1;
        geometry_seed.section_dir_xy[station] = [0.0, -1.0];
        geometry_seed.section_dir_derivative_xy[station] = [1.0, 0.0];

        let problem = build_bike_v1_experimental_problem(
            geometry_seed,
            BikeCountersteerLeanParamsV1::from_v05(base_params),
            options,
            BikeMintimeObjectiveWeights::from_request(&request),
            MintimeStageProgressMapping::single_stage(),
        )
        .unwrap();

        let mut decision = problem.initial_guess.clone();
        decision[problem.decision_layout.state_offset(station)
            + crate::bike_mintime_v1::V1_STATE_N_M] = 2.2;

        let row_index = problem
            .rows
            .iter()
            .position(|row| {
                matches!(
                    row,
                    BikeV1ExperimentalConstraintRow::SectionMapJacobian {
                        sample: BikeV1ExperimentalSample::Station {
                            interval: row_interval
                        }
                    } if *row_interval == interval
                )
            })
            .expect("V1 must include station section-map Jacobian row");
        let value = problem
            .constraint_value(&decision, problem.rows[row_index])
            .unwrap();
        assert!(value < 0.0, "expected folded section map, got {value}");
        assert!(value < problem.constraint_lower_bounds[row_index]);

        let entry = problem
            .residual_entries(&decision)
            .into_iter()
            .find(|entry| entry.row_index == row_index)
            .unwrap();
        assert_eq!(entry.family, "section_map_jacobian");
        assert!(entry.bound_violation > 0.0);
        assert!(entry.scaled_violation > 0.0);
    }

    #[test]
    #[ignore = "requires local Ipopt DLL; diagnostic that V1 experimental backend reaches Ipopt"]
    fn bike_v1_experimental_reaches_ipopt_minimal_smoke() {
        let result = solve_bike_mintime_json(&bike_mintime_test_request_json(
            r#""solve_options": {
                    "width_opt": 0.86,
                    "bike_model_version": "v1_experimental",
                    "max_iter": 1,
                    "ipopt_print_level": 0
                }"#,
        ));

        match result {
            Ok(json) => {
                assert!(json.contains("rust_bike_v1_experimental_ipopt"));
                assert!(json.contains("bike_v1_experimental"));
            }
            Err(error) => {
                assert!(
                    error
                        .message
                        .contains("Ipopt bike v1 experimental solve failed")
                        || error.code == "solve.nativeBackendError",
                    "unexpected V1 smoke error: {error:?}"
                );
                assert!(
                    !error.message.contains("unsupported"),
                    "V1 experimental path should reach the Ipopt adapter, not unsupported guard"
                );
            }
        }
    }

