    #[test]
    fn bike_mintime_synthetic_curvature_fixture_matches_straight_and_circle() {
        let straight =
            super::signed_three_point_curvature_1pm([0.0, 0.0], [10.0, 0.0], [20.0, 0.0]);
        assert!(straight.abs() < 1e-12, "{straight}");

        let radius_m = 50.0;
        let angle_rad = 0.1_f64;
        let previous = [radius_m * (-angle_rad).cos(), radius_m * (-angle_rad).sin()];
        let current = [radius_m, 0.0];
        let next = [radius_m * angle_rad.cos(), radius_m * angle_rad.sin()];
        let circle = super::signed_three_point_curvature_1pm(previous, current, next);
        assert!(
            (circle - 1.0 / radius_m).abs() < 1e-12,
            "circle curvature={circle}"
        );

        let speed_mps = 20.0;
        let ay_xy_mps2 = speed_mps * speed_mps * circle;
        assert!((ay_xy_mps2 - 8.0).abs() < 1e-10, "{ay_xy_mps2}");
    }

    #[test]
    fn bike_mintime_series_uses_station_aligned_dynamics() {
        let request = MintimeSolveRequestV1::parse(
            &bike_mintime_test_request_json(r#""solve_options": {"width_opt": 0.86}"#),
            VehicleDynamicsModelFamily::BikeDynamics,
        )
        .unwrap();
        let params =
            BikeSingleTrackLeanParams::from_profile(&request.vehicle_dynamics_profile).unwrap();
        let seed = build_bike_mintime_nlp_seed(&request, params).unwrap();
        let problem = build_bike_mintime_nlp_problem_with_weights(
            seed.clone(),
            params,
            BikeMintimeSolveOptions::default(),
            BikeMintimeObjectiveWeights {
                penalty_delta: 10.0,
                penalty_f: 0.01,
                penalty_delta_dd: 0.0,
                penalty_f_dd: 0.0,
                penalty_phi_cmd_dd: 0.0,
                penalty_n: 0.0,
                penalty_xi: 0.0,
                penalty_lean_equilibrium: 0.0,
                penalty_roll_tau: 0.0,
                penalty_roll_tau_rate: 0.0,
                penalty_ay_rate: 0.0,
                penalty_phi_eq_rate: 0.0,
                penalty_v1_delta_accel: 0.0,
                penalty_v1_delta_jerk: 0.0,
                penalty_v1_steering_torque_rate: 0.0,
                steering_regularization: BikeSteeringRegularizationMode::Curvature,
            },
        );
        let mut x = seed.initial_guess.clone();
        for station in 0..seed.dimensions.station_count {
            x[super::state_offset(station) + STATE_V_MPS] = 5.0 + station as f64;
            x[super::state_offset(station) + STATE_BETA_RAD] = 0.01 * station as f64;
            x[super::state_offset(station) + STATE_OMEGA_Z_RADPS] = 0.05 + 0.01 * station as f64;
        }

        let series = problem.to_series(&x);
        let mut setup_distinguishes_shift = false;
        for station in 0..seed.dimensions.station_count {
            let station_aligned =
                super::bike_mintime_station_dynamics_from(&seed, params, &x, station).ay_mps2;
            let shifted_path = super::bike_mintime_path_dynamics_from(
                &seed,
                params,
                &x,
                station.min(seed.dimensions.interval_count - 1),
            )
            .ay_mps2;
            assert_close(series.ay_mps2[station], station_aligned);
            setup_distinguishes_shift |= (station_aligned - shifted_path).abs() > 1e-3;
        }
        assert!(
            setup_distinguishes_shift,
            "test setup should distinguish station-aligned dynamics from shifted path dynamics"
        );
    }

    #[test]
    fn bike_collocation_polynomial_dense_state_matches_collocation_nodes() {
        let request = MintimeSolveRequestV1::parse(
            &bike_mintime_test_request_json(r#""solve_options": {"width_opt": 0.86}"#),
            VehicleDynamicsModelFamily::BikeDynamics,
        )
        .unwrap();
        let params =
            BikeSingleTrackLeanParams::from_profile(&request.vehicle_dynamics_profile).unwrap();
        let seed = build_bike_mintime_nlp_seed(&request, params).unwrap();
        let mut x = seed.initial_guess.clone();
        let interval = 3;
        x[super::state_offset(interval) + STATE_V_MPS] = 11.0;
        x[super::state_offset(interval) + STATE_BETA_RAD] = 0.01;
        for point in 0..BIKE_COLLOCATION_DEGREE {
            let offset = super::collocation_state_offset(&seed, interval, point);
            x[offset + STATE_V_MPS] = 20.0 + point as f64;
            x[offset + STATE_BETA_RAD] = 0.1 + 0.01 * point as f64;
        }

        let coeffs = super::bike_legendre_collocation_coefficients_degree3();
        let start = super::bike_collocation_polynomial_state_at_tau(&seed, &x, interval, 0.0);
        assert_close(start.v_mps, 11.0);
        assert_close(start.beta_rad, 0.01);
        for point in 1..=BIKE_COLLOCATION_DEGREE {
            let reconstructed = super::bike_collocation_polynomial_state_at_tau(
                &seed,
                &x,
                interval,
                coeffs.tau[point],
            );
            let actual = super::collocation_state_from(&seed, &x, interval, point - 1);
            assert_close(reconstructed.v_mps, actual.v_mps);
            assert_close(reconstructed.beta_rad, actual.beta_rad);
        }
    }

